import React, { useState } from 'react';
import { useLedgerStore } from '../../stores/useLedgerStore';
import { useAuthStore } from '../../stores/useAuthStore';
import { Building, AlertTriangle, CheckCircle2, Clock, RefreshCw, Landmark, ArrowUpRight } from 'lucide-react';
import { toast } from 'sonner';
import { getIdToken } from '../../firebase';
import { cn } from '../../lib/utils';
import PlaidConnectButton from '../finance/PlaidConnectButton';

export default function Banking() {
  const accounts = useLedgerStore(s => s.accounts).filter(a => 
    (a.type === 'asset' && a.subtype === 'bank') ||
    a.name.toLowerCase().includes('bank') ||
    a.name.toLowerCase().includes('checking') ||
    a.name.toLowerCase().includes('savings') ||
    a.category?.toLowerCase().includes('cash') ||
    a.category?.toLowerCase().includes('bank')
  );

  const [syncingAccountId, setSyncingAccountId] = useState<string | null>(null);

  const handleSyncNow = async (accountName: string, accountId: string) => {
    setSyncingAccountId(accountId);
    try {
      const token = await getIdToken();
      const res = await fetch('/api/v1/plaid/sync', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ accountId })
      });
      const data = await res.json();
      if (res.ok && data.success) {
        toast.success(`Synchronized ${accountName} with bank feed.`);
      } else if (res.ok) {
        toast.info(data.message || 'Bank feed synced. No new transactions.');
      } else {
        toast.error(`Bank feed error: ${data.error || data.message || 'Failed to sync with institution.'}`);
      }
    } catch (err) {
      console.error('Error syncing bank feed:', err);
      toast.error(`Unable to sync bank feed for ${accountName}`);
    } finally {
      setSyncingAccountId(null);
    }
  };

  const handleSyncSuccess = () => {
    toast.success('Bank credentials saved. Transaction feed synchronized.');
  };

  return (
    <div className="h-full flex flex-col bg-[var(--color-ledger-bg)] p-6 md:p-8 overflow-auto">
      <div className="max-w-5xl mx-auto w-full space-y-8">

        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-semibold text-[var(--color-ledger-ink)] font-display tracking-tight flex items-center gap-3">
              <Landmark className="w-6 h-6 text-indigo-600" />
              Bank & Institution Connections
            </h1>
            <p className="text-sm text-[var(--color-ledger-muted)] mt-1">
              Manage your connected financial institutions, live feeds, and reconciliation pipelines.
            </p>
          </div>
          <div className="shrink-0">
            <PlaidConnectButton onSuccessSync={handleSyncSuccess} />
          </div>
        </div>

        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {accounts.map(account => (
            <div key={account.id} className="bg-white border border-[var(--color-ledger-line)] rounded-2xl p-5 shadow-xs flex flex-col">
              <div className="flex items-start justify-between mb-4">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-indigo-50 border border-indigo-100 rounded-xl flex items-center justify-center text-indigo-600">
                    <Building className="w-5 h-5" />
                  </div>
                  <div>
                    <h3 className="font-semibold text-slate-900 text-sm leading-tight">{account.name}</h3>
                    <p className="text-xs text-slate-400 font-mono mt-0.5">{account.code ? `Acct ${account.code}` : 'Bank Account'}</p>
                  </div>
                </div>

                <div className="flex items-center gap-1 text-[11px] font-bold text-emerald-600 bg-emerald-50 border border-emerald-200/60 px-2 py-0.5 rounded-full">
                  <CheckCircle2 className="w-3 h-3" /> Ready
                </div>
              </div>

              <div className="mt-auto pt-4 border-t border-slate-100 space-y-4">
                <div className="flex justify-between items-center text-xs">
                  <span className="text-slate-500 font-medium">Type</span>
                  <span className="text-slate-800 font-mono font-bold uppercase">{account.subtype || account.type || 'Asset'}</span>
                </div>
                <div className="flex gap-2">
                  <button 
                    onClick={() => handleSyncNow(account.name, account.id)}
                    disabled={syncingAccountId === account.id}
                    className="flex-1 px-3 py-2 bg-slate-900 hover:bg-black text-white text-xs font-bold rounded-xl transition-all flex items-center justify-center gap-1.5 shadow-xs disabled:opacity-50 cursor-pointer"
                  >
                    <RefreshCw className={cn("w-3.5 h-3.5", syncingAccountId === account.id && "animate-spin")} />
                    <span>{syncingAccountId === account.id ? 'Syncing...' : 'Sync Feed'}</span>
                  </button>
                </div>
              </div>
            </div>
          ))}

          {accounts.length === 0 && (
            <div className="col-span-full py-16 flex flex-col items-center justify-center text-center bg-white border border-[var(--color-ledger-line)] border-dashed rounded-3xl p-8">
              <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center mb-4">
                <Landmark className="w-7 h-7" />
              </div>
              <h3 className="text-lg font-bold text-slate-900">No Bank Connections Found</h3>
              <p className="text-slate-500 mt-1 max-w-md text-sm leading-relaxed">
                Connect your checking accounts, credit cards, or cash repositories via secure Plaid link to stream transactions automatically into your ledger.
              </p>
              <div className="mt-6">
                <PlaidConnectButton onSuccessSync={handleSyncSuccess} />
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Layers, Download, BarChart3, TrendingUp, Globe } from 'lucide-react';
import { cn } from '../../lib/utils';
import { useLedgerStore } from '../../stores/useLedgerStore';
import { IntercompanyEliminationEngine } from '../../lib/intercompanyElimination';

export default function Consolidation() {
  const transactions = useLedgerStore(s => s.transactions);
  const accounts = useLedgerStore(s => s.accounts);

  const incomeAccountIds = new Set(accounts.filter(a => a.type === 'income').map(a => a.id));
  const expenseAccountIds = new Set(accounts.filter(a => a.type === 'expense').map(a => a.id));

  const isIncomeLine = (l: any) => incomeAccountIds.has(l.accountId) || l.category?.toLowerCase().includes('income') || l.category?.toLowerCase().includes('revenue');
  const isExpenseLine = (l: any) => expenseAccountIds.has(l.accountId) || l.category?.toLowerCase().includes('expense') || l.category?.toLowerCase().includes('cogs');

  const summary = useMemo(() => {
    return IntercompanyEliminationEngine.generateConsolidatedSummary(transactions, isIncomeLine, isExpenseLine);
  }, [transactions, accounts]);

  const [activeTab, setActiveTab] = useState<'matrix' | 'adjustments'>('matrix');

  const formatCurrency = (amountCents: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 0
    }).format(amountCents / 100);
  };

  return (
    <div className="h-full flex flex-col bg-[var(--ink)] text-[var(--text)]">
      <div className="px-8 py-6 bg-[var(--surface)] border-b border-[var(--line)] text-[var(--text)] flex justify-between items-start shadow-sm">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-3 text-[var(--text)]">
            <Layers className="w-6 h-6 text-[var(--brass)]" />
            Multi-Entity Consolidation
          </h1>
          <p className="text-sm text-[var(--muted)] mt-1">
            Dynamic coordinate-based sub-ledgers with automatic intercompany transfer elimination.
          </p>
        </div>
        <div className="flex gap-3">
          <div className="bg-slate-800/80 px-3 py-1.5 rounded-xl border border-slate-700 flex items-center gap-2 text-xs font-mono text-slate-300">
            <Globe className="w-3.5 h-3.5 text-emerald-400" />
            <span>Worlds: {summary.worldStatements.length}</span>
          </div>
          <button className="h-10 px-4 bg-purple-500 text-white rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-purple-400 transition-colors" aria-label="Export Report">
            <Download className="w-4 h-4" /> Export Report
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-auto p-8">
        <div className="flex p-1 bg-[var(--surface)] border border-[var(--line)] rounded-xl shadow-sm hover:shadow-md transition-shadow duration-200 mb-6 w-max">
          {[
            { id: 'matrix', label: 'Consolidated Matrix', icon: BarChart3 },
            { id: 'adjustments', label: 'Top-Level Adjustments', icon: TrendingUp }
          ].map(tab => (
             <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={cn(
                   "px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all",
                   activeTab === tab.id ? "bg-slate-900 text-white" : "text-slate-500 hover:bg-[var(--ink)]"
                )}
             >
                <tab.icon className="w-4 h-4" /> {tab.label}
             </button>
          ))}
        </div>

        {activeTab === 'matrix' && (
          <div className="bg-[var(--surface)] border border-[var(--line)] rounded-2xl overflow-hidden shadow-sm">
            <div className="p-4 bg-[var(--ink)] border-b border-[var(--line)] text-xs font-bold text-slate-700 uppercase tracking-wider flex justify-between items-center">
              <span>Entity / World Sub-Ledgers</span>
              <span className="text-rose-600 font-mono text-[11px]">Intercompany Eliminations: {formatCurrency(summary.eliminatedTransferCents)}</span>
            </div>

            <div className="overflow-x-auto">
            <div className="divide-y divide-slate-200 min-w-[700px]">
              <div className="grid grid-cols-12 p-4 bg-slate-100/80 text-[10px] font-bold text-slate-500 uppercase tracking-wider">
                <div className="col-span-4">World / Sub-Ledger Coordinate</div>
                <div className="col-span-2 text-right">Transactions</div>
                <div className="col-span-2 text-right">Total Revenue</div>
                <div className="col-span-2 text-right">Total Expenses</div>
                <div className="col-span-2 text-right text-indigo-600">Net Income</div>
              </div>

              {summary.worldStatements.map(stmt => (
                <div key={stmt.world} className="grid grid-cols-12 p-4 items-center hover:bg-[var(--ink)] transition-colors font-mono text-sm">
                  <div className="col-span-4 font-bold font-sans text-[var(--text)] capitalize flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full bg-indigo-500"></span>
                    {stmt.world}
                  </div>
                  <div className="col-span-2 text-right text-slate-500">{stmt.transactionCount}</div>
                  <div className="col-span-2 text-right text-emerald-600">{formatCurrency(stmt.totalRevenueCents)}</div>
                  <div className="col-span-2 text-right text-slate-700">{formatCurrency(stmt.totalExpenseCents)}</div>
                  <div className={cn("col-span-2 text-right font-bold", stmt.netIncomeCents >= 0 ? "text-indigo-600" : "text-rose-600")}>
                    {formatCurrency(stmt.netIncomeCents)}
                  </div>
                </div>
              ))}

              <div className="grid grid-cols-12 p-4 items-center bg-slate-900 text-white font-mono text-sm font-bold">
                <div className="col-span-4 font-sans uppercase tracking-wider text-xs">Consolidated Group Total</div>
                <div className="col-span-2 text-right text-slate-400">{transactions.length}</div>
                <div className="col-span-2 text-right text-emerald-400">{formatCurrency(summary.consolidatedRevenueCents)}</div>
                <div className="col-span-2 text-right text-slate-300">{formatCurrency(summary.consolidatedExpenseCents)}</div>
                <div className={cn("col-span-2 text-right font-bold text-base", summary.consolidatedNetIncomeCents >= 0 ? "text-purple-300" : "text-rose-300")}>
                  {formatCurrency(summary.consolidatedNetIncomeCents)}
                </div>
              </div>
            </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { motion } from 'motion/react';
import { X } from 'lucide-react';
import React, { useState } from 'react';
import { useLedgerStore } from '../../stores/useLedgerStore';
import { format } from 'date-fns';
import { useUIStore } from '../../stores/useUIStore';

import { useAuthStore } from '../../stores/useAuthStore';

interface CurrencyConverterProps {
  isOpen?: boolean;
  onClose?: () => void;
  baseCurrency?: string;
}

export default function CurrencyConverter({ isOpen, onClose, baseCurrency }: CurrencyConverterProps) {
  const getCurrentWorkspace = useAuthStore(s => s.getCurrentWorkspace);
  const activeWorkspace = getCurrentWorkspace();
  const [isRevaluing, setIsRevaluing] = useState(false);
  const [revalResult, setRevalResult] = useState('');

  const runRevaluation = async () => {
    if (!activeWorkspace) return;
    setIsRevaluing(true);
    setRevalResult('');
    try {
      const user = useAuthStore.getState().user;
      const token = user ? await user.getIdToken() : '';
      const response = await fetch(`/api/v1/transactions/revaluation/run`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          workspaceId: activeWorkspace.id,
          targetCurrency: toCurrency
        })
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Failed to run revaluation');
      setRevalResult(data.message);
    } catch (e: any) {
      setRevalResult('Error: ' + e.message);
    } finally {
      setIsRevaluing(false);
    }
  };

  const language = useUIStore(s => s.language);
  const [amount, setAmount] = useState<number>(100);
  const [fromCurrency, setFromCurrency] = useState<string>('USD');
  const [toCurrency, setToCurrency] = useState<string>('EUR');

  const exchangeRates: Record<string, number> = {
    'USD': 1.0,
    'EUR': 0.92,
    'GBP': 0.79,
    'ILS': 3.75,
    'JPY': 151.2,
    'AUD': 1.54,
    'CAD': 1.36
  };

  const calculateConversion = () => {
    const amountInUsd = amount / (exchangeRates[fromCurrency] || 1);
    return (amountInUsd * (exchangeRates[toCurrency] || 1)).toFixed(2);
  };

  const innerContent = (
    <div className="p-6 w-full max-w-xl mx-auto bg-[var(--surface)] dark:bg-slate-900 border border-[var(--line)] dark:border-slate-800 rounded-xl shadow-sm hover:shadow-md transition-all duration-200">
      <h2 className="text-xl font-medium text-[var(--text)] dark:text-white mb-6">
        {language === 'he' ? 'המרת מטבעות' : 'Currency Converter'}
      </h2>

      <div className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-[var(--muted)] mb-1">
            {language === 'he' ? 'סכום' : 'Amount'}
          </label>
          <input
            type="number"
            value={amount}
            onChange={(e) => setAmount(Number(e.target.value))}
            className="w-full px-3 py-2 bg-[var(--surface)] border border-[var(--line)] rounded-lg text-sm text-[var(--text)]"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-[var(--muted)] mb-1">
              {language === 'he' ? 'ממטבע' : 'From'}
            </label>
            <select
              value={fromCurrency}
              onChange={(e) => setFromCurrency(e.target.value)}
              className="w-full px-3 py-2 bg-[var(--surface)] border border-[var(--line)] rounded-lg text-sm text-[var(--text)]"
            >
              {Object.keys(exchangeRates).map(c => (
                <option key={c} value={c}>{c}</option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-[var(--muted)] mb-1">
              {language === 'he' ? 'למטבע' : 'To'}
            </label>
            <select
              value={toCurrency}
              onChange={(e) => setToCurrency(e.target.value)}
              className="w-full px-3 py-2 bg-[var(--surface)] border border-[var(--line)] rounded-lg text-sm text-[var(--text)]"
            >
              {Object.keys(exchangeRates).map(c => (
                <option key={c} value={c}>{c}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="pt-4 border-t border-[var(--line)] mt-6">
          <p className="text-sm text-[var(--muted)] mb-1">
            {language === 'he' ? 'תוצאה' : 'Converted Amount'}
          </p>
          <div className="text-3xl font-medium text-[var(--text)]">
            {calculateConversion()} {toCurrency}
          </div>
        </div>
        <div className="pt-4 border-t border-[var(--line)] mt-6">
          <button 
            onClick={runRevaluation} 
            disabled={isRevaluing || !activeWorkspace}
            className="w-full px-4 py-2 bg-[var(--brass)] hover:opacity-90 text-black rounded-lg text-sm font-bold transition-colors cursor-pointer"
           aria-label="Action button">
            {isRevaluing ? 'Processing...' : (language === 'he' ? 'הפעל שערוך סוף חודש (API)' : 'Run Month-End Revaluation (API)')}
          </button>
          {revalResult && (
            <div className="mt-3 text-sm text-[var(--text)] p-3 bg-[var(--ink)] rounded border border-[var(--line)]">
              {revalResult}
            </div>
          )}
        </div>

      </div>
    </div>
  );

  if (isOpen !== undefined) {
    if (!isOpen) return null;
    return (
      <div className="fixed inset-0 z-[300] flex items-center justify-center p-4">
        <motion.div 
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={onClose}
          className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm"
        />
        <motion.div
          initial={{ opacity: 0, scale: 0.95, y: 10 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 10 }}
          className="relative w-full max-w-xl bg-[var(--surface)] dark:bg-slate-900 rounded-2xl shadow-xl border border-[var(--line)] dark:border-slate-800 overflow-hidden"
        >
          {onClose && (
            <button aria-label="Close" 
              onClick={onClose}
              className="absolute top-4 right-4 p-2 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors z-10"
            ><X size={20} /></button>
          )}
          {innerContent}
        </motion.div>
      </div>
    );
  }

  return innerContent;
}

import React, { useState, useEffect, useCallback } from 'react';
import { usePlaidLink } from 'react-plaid-link';
import { toast } from 'sonner';
import { Link2 } from 'lucide-react';
import { getIdToken } from '../../firebase';

export default function PlaidConnectButton({ onSuccessSync }: { onSuccessSync?: () => void }) {
  const [linkToken, setLinkToken] = useState<string | null>(null);

  const generateToken = useCallback(async () => {
    try {
      const idToken = await getIdToken();
      const response = await fetch('/api/v1/plaid/create_link_token', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${idToken}`
        }
      });
      const data = await response.json();
      setLinkToken(data.link_token);
    } catch (err) {
      console.error('Error generating link token:', err);
    }
  }, []);

  useEffect(() => {
    setTimeout(() => {
      generateToken();
    }, 0);
  }, [generateToken]);

  const onSuccess = useCallback(
    async (public_token: string, metadata: any) => {
      try {
        const idToken = await getIdToken();
        const response = await fetch('/api/v1/plaid/exchange_public_token', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${idToken}`
          },
          body: JSON.stringify({ public_token }),
        });
        const data = await response.json();

        if (data.success) {
          toast.success('Bank connected successfully via Plaid');
          if (onSuccessSync) onSuccessSync();
        }
      } catch (err) {
        toast.error('Failed to connect bank');
      }
    },
    [onSuccessSync]
  );

  const { open, ready } = usePlaidLink({
    token: linkToken!,
    onSuccess,
  });

  return (
    <button 
      onClick={() => open()}
      disabled={!ready}
      className="h-12 px-6 bg-slate-100 hover:bg-slate-200 border border-[var(--line)] text-[var(--text)] font-black text-[10px] uppercase tracking-widest rounded-xl transition-all shadow-sm flex items-center gap-2 active:scale-95 disabled:opacity-50"
    >
      <Link2 size={14} />
      <span>Connect Bank</span>
    </button>
  );
}

import { useLedgerStore } from '../../stores/useLedgerStore';
