import React, { useState, useRef, useEffect } from 'react';
import { 
  Sparkles, 
  ArrowRight, 
  History,
  Filter,
  BarChart3,
  Zap,
  AlertCircle
} from 'lucide-react';
import { motion } from 'motion/react';
import { aiService } from '../../services/aiService';
import { useLedgerStore } from '../../stores/useLedgerStore';
import { cn } from '../../lib/utils';
import { toast } from 'sonner';

interface AICommandCenterProps {
  isOpen: boolean;
  onClose: () => void;
  onFilter: (criteria: any) => void;
  businessContext: string;
}

export default function AICommandCenter({ isOpen, onClose, onFilter, businessContext }: AICommandCenterProps) {
  const [query, setQuery] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [history, setHistory] = useState<string[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [isOpen]);

  const runQuery = async (queryText: string) => {
    if (!queryText.trim() || isProcessing) return;

    setIsProcessing(true);
    setQuery(queryText);
    try {
      const { accounts, transactions } = useLedgerStore.getState();
      const uniqueProjects = Array.from(new Set(
        transactions
          .map((t: any) => t.projectId || t.project)
          .filter(Boolean)
      )) as string[];

      const resolved = await aiService.parseQuery(
        queryText, 
        businessContext, 
        accounts.map(a => a.name), 
        uniqueProjects
      );
      const criteria = resolved || {};

      const filter: any = {};
      if (criteria.category) filter.category = criteria.category;
      if (criteria.project) filter.project = criteria.project;
      if (criteria.minAmountCents !== undefined) filter.minAmount = criteria.minAmountCents / 100;
      if (criteria.maxAmountCents !== undefined) filter.maxAmount = criteria.maxAmountCents / 100;
      if (criteria.startDate) filter.startDate = criteria.startDate;
      if (criteria.endDate) filter.endDate = criteria.endDate;

      onFilter(filter);
      setHistory(prev => [queryText, ...prev.filter(q => q !== queryText).slice(0, 4)]);
      toast.success("Query Processing Complete", {
        description: `Applied filters based on: "${queryText}"`
      });
      onClose();
      setQuery('');
    } catch (error) {
      console.error("Command error:", error);
      toast.error("Analytical Processing Failed");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSubmit = async (e?: React.FormEvent) => {
    e?.preventDefault();
    await runQuery(query);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[700] flex items-start justify-center pt-32 px-4">
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        onClick={onClose}
        className="absolute inset-0 bg-slate-900/60 backdrop-blur-2xl"
      />

      <motion.div
        initial={{ opacity: 0, y: -40, scale: 0.98 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{ opacity: 0, y: -20, scale: 0.98 }}
        className="relative w-full max-w-4xl bg-[var(--surface)] rounded-[32px] shadow-2xl border border-[var(--line)] overflow-hidden p-2"
      >
        <div className="bg-slate-900 rounded-[32px] p-4 md:p-10 text-white relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/20 blur-[100px] pointer-events-none" />

          <form onSubmit={handleSubmit} className="mb-10 relative z-10">
            <div className="flex items-center gap-6 border-b border-white/5 pb-8 mb-8">
               <div className={cn(
                 "p-4 bg-[var(--surface)]/5 rounded-[32px] transition-all",
                 isProcessing ? "text-indigo-500 animate-spin" : "text-indigo-400 shadow-[0_0_20px_rgba(79,70,229,0.3)]"
               )}>
                 <Sparkles size={32} />
               </div>
               <div className="flex-1">
                 <input 
                   ref={inputRef}
                   type="text" 
                   value={query}
                   onChange={(e) => setQuery(e.target.value)}
                   placeholder="Enter Natural Language Query..."
                   className="w-full bg-transparent border-none text-2xl md:text-4xl font-black tracking-tighter focus:outline-none placeholder:text-white/20 font-display text-white"
                 />
                 <div className="flex items-center gap-3 mt-3">
                   <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-pulse shadow-[0_0_8px_rgba(79,70,229,0.8)]" />
                   <span className="text-[9px] font-black text-white/40 uppercase tracking-widest truncate">Analytical Engine Active</span>
                 </div>
               </div>
            </div>

            <div className="flex items-center gap-4">
              <button 
                type="submit"
                disabled={!query.trim() || isProcessing}
                className="px-8 h-14 bg-indigo-600 text-white rounded-[32px] text-[10px] font-black uppercase tracking-widest hover:bg-indigo-500 transition-all active:scale-95 disabled:opacity-20 flex items-center gap-3 shadow-[0_15px_30px_-10px_rgba(79,70,229,0.4)]"
               aria-label="Zap action">
                {isProcessing ? "Processing..." : "Run Analysis"}
                <Zap size={14} />
              </button>
              <div className="h-10 w-px bg-[var(--surface)]/10 mx-4" />
              <div className="flex items-center gap-6">
                 <button 
                   type="button" 
                   onClick={() => runQuery("Compare current period vs prior period")}
                   className="text-[10px] font-black text-white/40 hover:text-indigo-400 uppercase tracking-widest transition-colors cursor-pointer" 
                   aria-label="Compare Period"
                 >
                   Compare Period
                 </button>
                 <button 
                   type="button" 
                   onClick={() => runQuery("Scan transactions for anomalies and outliers")}
                   className="text-[10px] font-black text-white/40 hover:text-indigo-400 uppercase tracking-widest transition-colors cursor-pointer" 
                   aria-label="Anomaly Sweep"
                 >
                   Anomaly Sweep
                 </button>
              </div>
            </div>
          </form>

          <div className="grid grid-cols-2 gap-10 relative z-10">
            <div className="space-y-6">
              <h4 className="text-[10px] font-black text-white/20 uppercase tracking-widest truncate">Command History</h4>
              <div className="space-y-3">
                {history.length > 0 ? history.map((h, i) => (
                  <button 
                    key={i}
                    onClick={() => runQuery(h)}
                    className="w-full text-left p-4 rounded-[32px] bg-[var(--surface)]/5 border border-white/5 hover:bg-[var(--surface)]/10 transition-all flex items-center justify-between group cursor-pointer"
                  >
                    <span className="text-xs font-bold text-white/60 group-hover:text-white transition-colors">{h}</span>
                    <History size={14} className="text-white/20" />
                  </button>
                )) : (
                  <p className="text-[11px] font-bold text-white/20 italic">No previous executions detected.</p>
                )}
              </div>
            </div>

            <div className="space-y-6">
               <h4 className="text-[10px] font-black text-white/20 uppercase tracking-widest truncate">System Shortcuts</h4>
               <div className="grid grid-cols-1 gap-3">
                 {[
                   { label: "Analyze High-Value Outflow", icon: AlertCircle, color: 'text-rose-400' },
                   { label: "Reconcile Missing Metadata", icon: Filter, color: 'text-amber-400' },
                   { label: "Predict Q3 Growth Matrix", icon: BarChart3, color: 'text-emerald-400' }
                 ].map((item, i) => (
                   <button 
                     key={i} 
                     onClick={() => runQuery(item.label)}
                     className="flex items-center justify-between p-4 bg-[var(--surface)]/5 rounded-[32px] border border-white/5 hover:border-indigo-500/30 hover:bg-[var(--surface)]/10 transition-all group active:scale-95 cursor-pointer" 
                     aria-label={item.label}
                   >
                     <div className="flex items-center gap-4">
                       <item.icon size={16} className={item.color} />
                       <span className="text-[10px] font-black text-white/80 uppercase tracking-widest">{item.label}</span>
                     </div>
                     <ArrowRight size={14} className="text-white/20 group-hover:text-indigo-400 transition-colors" />
                   </button>
                 ))}
               </div>
            </div>
          </div>
        </div>
      </motion.div>
    </div>
  );
}

import React, { useState } from 'react';
import { motion } from 'motion/react';
import { 
  Sparkles, 
  Wand2, 
  X, 
  ArrowRight, 
  Loader2, 
  CheckCircle2,
  AlertCircle,
  BookOpen,
  Layout
} from 'lucide-react';
import { aiService } from '../../services/aiService';
import { BUSINESS_TEMPLATES } from '../../lib/businessTemplates';
import { cn } from '../../lib/utils';
import { toast } from 'sonner';

interface AICustomBlueprintProps {
  isOpen: boolean;
  onClose: () => void;
  onGenerated: (template: any) => void;
}

export default function AICustomBlueprint({ isOpen, onClose, onGenerated }: AICustomBlueprintProps) {
  const [description, setDescription] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedData, setGeneratedData] = useState<any>(null);
  const [showAllAccounts, setShowAllAccounts] = useState(false);

  const handleGenerate = async () => {
    if (!description.trim()) {
      toast.error("Please describe your business first.");
      return;
    }

    setIsGenerating(true);
    try {
      let data: any = null;

      try {
        // Attempt AI generation
        const aiResult = await aiService.process('parse-business-blueprint', { description });
        if (aiResult && aiResult.name) {
          data = aiResult;
        }
      } catch (aiError) {
        console.warn("AI generation failed, falling back to deterministic matching:", aiError);
      }

      if (!data) {
        // Fallback deterministic logic
        const lowerDesc = description.toLowerCase();
        let bestMatch = BUSINESS_TEMPLATES['saas']; // default
        let maxScore = 0;

        for (const [key, template] of Object.entries(BUSINESS_TEMPLATES)) {
          let score = 0;
          const keywords = template.name.toLowerCase().split(' ').concat(template.description.toLowerCase().split(' '));
          keywords.forEach((kw: string) => {
            if (kw.length > 3 && lowerDesc.includes(kw)) score++;
          });

          // Add specific domain keywords
          if (key === 'retail' && (lowerDesc.includes('shop') || lowerDesc.includes('store') || lowerDesc.includes('physical'))) score += 5;
          if (key === 'creative' && (lowerDesc.includes('art') || lowerDesc.includes('design') || lowerDesc.includes('freelance'))) score += 5;
          if (key === 'realestate' && (lowerDesc.includes('property') || lowerDesc.includes('rent') || lowerDesc.includes('house'))) score += 5;
          if (key === 'saas' && (lowerDesc.includes('software') || lowerDesc.includes('tech') || lowerDesc.includes('app') || lowerDesc.includes('cloud'))) score += 5;
          if (key === 'agriculture' && (lowerDesc.includes('farm') || lowerDesc.includes('crop') || lowerDesc.includes('livestock') || lowerDesc.includes('organic') || lowerDesc.includes('agriculture') || lowerDesc.includes('feed'))) score += 8;
          if (key === 'healthcare' && (lowerDesc.includes('clinic') || lowerDesc.includes('medical') || lowerDesc.includes('doctor') || lowerDesc.includes('dentist') || lowerDesc.includes('patient') || lowerDesc.includes('hospital'))) score += 8;
          if (key === 'logistics' && (lowerDesc.includes('truck') || lowerDesc.includes('freight') || lowerDesc.includes('cargo') || lowerDesc.includes('fleet') || lowerDesc.includes('delivery') || lowerDesc.includes('logistics'))) score += 8;
          if (key === 'subscription_box' && (lowerDesc.includes('subscription') || lowerDesc.includes('box') || lowerDesc.includes('recurring') || lowerDesc.includes('kit') || lowerDesc.includes('curated'))) score += 8;
          if (key === 'construction' && (lowerDesc.includes('build') || lowerDesc.includes('construct') || lowerDesc.includes('contractor') || lowerDesc.includes('heavy equipment') || lowerDesc.includes('renovate'))) score += 8;
          if (key === 'automotive' && (lowerDesc.includes('mechanic') || lowerDesc.includes('car') || lowerDesc.includes('garage') || lowerDesc.includes('auto') || lowerDesc.includes('repair') || lowerDesc.includes('vehicle'))) score += 8;
          if (key === 'renewable_energy' && (lowerDesc.includes('solar') || lowerDesc.includes('energy') || lowerDesc.includes('green') || lowerDesc.includes('utility') || lowerDesc.includes('carbon'))) score += 8;
          if (key === 'import_export' && (lowerDesc.includes('import') || lowerDesc.includes('export') || lowerDesc.includes('trade') || lowerDesc.includes('ocean') || lowerDesc.includes('cargo') || lowerDesc.includes('wholesale'))) score += 8;
          if (key === 'franchise' && (lowerDesc.includes('franchise') || lowerDesc.includes('royalty') || lowerDesc.includes('brand') || lowerDesc.includes('outlet'))) score += 8;
          if (key === 'software_agency' && (lowerDesc.includes('agency') || lowerDesc.includes('dev') || lowerDesc.includes('consulting') || lowerDesc.includes('contractor') || lowerDesc.includes('milestone'))) score += 8;

          if (key === 'enterprise_saas' && (lowerDesc.includes('enterprise') || lowerDesc.includes('global') || lowerDesc.includes('multi-product') || lowerDesc.includes('b2b') || lowerDesc.includes('multi-region') || lowerDesc.includes('scale'))) score += 10;
          if (key === 'holding_company' && (lowerDesc.includes('holding') || lowerDesc.includes('conglomerate') || lowerDesc.includes('multi-entity') || lowerDesc.includes('subsidiary') || lowerDesc.includes('portfolio') || lowerDesc.includes('parent'))) score += 10;
          if (key === 'manufacturing_multi' && (lowerDesc.includes('multi-factory') || lowerDesc.includes('supply chain') || lowerDesc.includes('global distribution') || lowerDesc.includes('multi-site') || lowerDesc.includes('international'))) score += 10;
          if (key === 'private_equity' && (lowerDesc.includes('venture') || lowerDesc.includes('vc') || lowerDesc.includes('private equity') || lowerDesc.includes('pe') || lowerDesc.includes('fund') || lowerDesc.includes('capital call'))) score += 10;

          if (score > maxScore) {
            maxScore = score;
            bestMatch = template;
          }
        }

        data = {
          name: bestMatch.name,
          description: bestMatch.description,
          industry: bestMatch.name,
          strategicAdvice: ["Based on algorithmic matching, this is the optimal structure.", "Monitor your key expense categories.", "Review income channels periodically."],
          chartOfAccounts: bestMatch.accounts.map(a => ({
             category: a.category,
             code: a.code,
             name: a.name,
             type: a.type
          })),
          dashboardSchema: { nodes: bestMatch.topology.nodes, links: bestMatch.topology.links }
        };
      }

      setGeneratedData(data);
      toast.success("Blueprint mapped successfully!");
    } catch (error) {
      console.error("Mapping Error:", error);
      toast.error("Failed to map blueprint. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleApply = () => {
    if (generatedData) {
      onGenerated(generatedData);
      onClose();
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[300] flex items-center justify-center p-4">
