import React from 'react';
import { cn } from '../../lib/utils';
import { LayoutGrid, Layers, Briefcase, BarChart3, Settings } from 'lucide-react';
import { APP_TABS, NAV_GROUPS } from '../../config/registry';
import { useUIStore } from '../../stores/useUIStore';

interface BottomNavProps {
  activeTab: string;
  onTabChange: (tabId: string) => void;
}

const GROUP_ICONS: Record<string, any> = {
  pulse: LayoutGrid,
  finance: Layers,
  operations: Briefcase,
  planning: BarChart3,
  system: Settings
};

export default function BottomNav({ activeTab, onTabChange }: BottomNavProps) {
  const isProMode = useUIStore(s => s.isProMode);
  const currentTabDef = APP_TABS.find(t => t.id === activeTab);
  const activeGroupId = currentTabDef?.groupId || 'pulse';

  const visibleGroups = ['pulse', 'finance', 'operations', 'planning'];

  return (
    <div className="lg:hidden fixed bottom-0 left-0 right-0 h-[64px] bg-[var(--surface)] border-t border-[var(--line)] flex items-center justify-around z-50 px-2 pb-[env(safe-area-inset-bottom)]">
      {visibleGroups.map(groupId => {
        const Icon = GROUP_ICONS[groupId];
        const isActive = activeGroupId === groupId;
        const firstTab = APP_TABS.find(t => t.groupId === groupId && (!t.isAdvanced || isProMode));
        const groupLabel = NAV_GROUPS[groupId]?.en;

        if (!firstTab) return null;

        return (
          <button
            key={groupId}
            onClick={() => onTabChange(firstTab.id)}
            className="flex flex-col items-center justify-center w-full h-full space-y-1 relative"
          >
            <div className={cn(
              "p-1.5 rounded-full transition-colors",
              isActive ? "bg-black/5 text-black" : "text-gray-400"
            )}>
              <Icon size={20} strokeWidth={isActive ? 2.5 : 2} />
            </div>
            <span className={cn(
              "text-[10px] font-medium transition-colors",
              isActive ? "text-black" : "text-gray-400"
            )}>
              {groupLabel}
            </span>
          </button>
        );
      })}
    </div>
  );
}

import React, { useEffect, useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { Search, Loader2, ArrowRight, FileText, User, Building, FolderKanban, Tags, DollarSign, Zap, FolderPlus, Sparkles } from 'lucide-react';
import { toast } from 'sonner';
import { SYSTEM_COMMANDS, ANALYTICAL_LENSES_REGISTRY } from '../../config/registry';
import { useUIStore } from '../../stores/useUIStore';
import { useLedgerStore } from '../../stores/useLedgerStore';
import { useAuthStore } from '../../stores/useAuthStore';
import { parseNaturalLanguageEntry, ParsedCommandIntent } from '../../lib/algorithms/nl-parser';
import { useShallow } from 'zustand/react/shallow';
import { Transaction, Project } from '../../types';
import { getLocalDateISO, resolveAccountName } from '../../lib/utils';
import { useTransactionActions } from '../../hooks/useTransactionActions';
import { useEntityOperations } from '../../hooks/useEntityOperations';
import { resolveAccountRole } from '../../lib/accountUtils';
import { isCashAccount } from '../../lib/txFilters';

interface CommandPaletteProps {
  isOpen: boolean;
  onClose: () => void;
  onAction?: (action: string, details?: any) => void;
  onQuery?: (q: string) => Promise<any>;
  recentQueries?: string[];
}

export default function CommandPalette({ isOpen, onClose, onAction }: CommandPaletteProps) {
  const [query, setQuery] = useState('');
  const [isExecuting, setIsExecuting] = useState(false);
  const language = useUIStore(state => state.language);
  const ledger = useLedgerStore(useShallow(state => ({
    transactions: state.transactions,
    projects: state.projects,
    customers: state.customers,
    vendors: state.vendors,
    accounts: state.accounts,
    invoices: state.invoices,
    bills: state.bills
  })));
  const { handleQuickAdd } = useTransactionActions();
  const { addEntity } = useEntityOperations();

  // Parse natural language intent live from search query
  const parsedIntent: ParsedCommandIntent = useMemo(() => {
    return parseNaturalLanguageEntry(query);
  }, [query]);

  // Execute Natural Language Intent
  // Execute Natural Language Intent
  const handleExecuteIntent = async () => {
    if (!parsedIntent || parsedIntent.type === 'unknown') return;
    if (parsedIntent.type === 'transaction') {
      const amountCents = parsedIntent.amountCents || 0;
      const isExpense = parsedIntent.action === 'expense';
      const cashAccount = ledger.accounts.find(a => resolveAccountRole(a) === 'cash') || ledger.accounts.find(a => isCashAccount(a)) || ledger.accounts[0];
      const categoryAccount = ledger.accounts.find(a => resolveAccountRole(a) === (isExpense ? 'expense' : 'revenue')) || ledger.accounts.find(a => a.type === (isExpense ? 'expense' : 'income')) || ledger.accounts[0];
      if (!cashAccount || !categoryAccount) {
        toast.error('Cannot post transaction: No chart of accounts available.');
        return;
      }
      const cashAccountId = cashAccount.id;
      const categoryAccountId = categoryAccount.id;
      const cashAccountName = cashAccount.name;
      const categoryAccountName = categoryAccount.name;
      await handleQuickAdd({
        date: parsedIntent.dateStr || getLocalDateISO(),
        description: parsedIntent.description || 'Natural Language Entry',
        totalAmountCents: amountCents,
        lines: [
          {
            accountId: categoryAccountId,
            accountName: categoryAccountName,
            amountCents: isExpense ? amountCents : -amountCents,
            description: parsedIntent.description || 'NL line'
          },
          {
            accountId: cashAccountId,
            accountName: cashAccountName,
            amountCents: isExpense ? -amountCents : amountCents,
            description: 'Payment settlement'
          }
        ]
      });
      setQuery('');
      onClose();
    } else if (parsedIntent.type === 'project' && parsedIntent.projectName) {
      await addEntity('projects', {
        name: parsedIntent.projectName,
        status: 'active',
        type: 'general',
        budgetCents: 0,
        dimensions: ['project'],
        description: 'Created via Omnibox Command'
      }, `✨ Created project "${parsedIntent.projectName}"`);
      setQuery('');
      onClose();
    } else if (parsedIntent.type === 'query' && parsedIntent.queryText) {
      useUIStore.getState().setFilterCriteria({ search: parsedIntent.queryText });
      useUIStore.getState().setActiveTab('transactions');
      toast.info(`Filtered ledger for "${parsedIntent.queryText}"`);
      setQuery('');
      onClose();
    }
  };

  // Map commands to the currently active UI language
  const localizedCommands = React.useMemo(() => {
    const base = SYSTEM_COMMANDS.map(cmd => ({
      id: cmd.id,
      type: 'command',
      label: cmd.label[language] || cmd.label['en'],
      category: cmd.category,
      actionId: cmd.actionId,
      payload: cmd.payload,
      icon: <ArrowRight size={16} />
    }));

    const lenses = ANALYTICAL_LENSES_REGISTRY.map((lens: any) => ({
      id: `lens-${lens.id}`,
      type: 'command',
      label: `Open: ${(lens.label && lens.label[language]) || (lens.label && lens.label['en']) || lens.name || lens.id}`,
      category: 'Calculators & Analytics',
      actionId: 'switch-tab',
      payload: { tab: 'intelligence', channel: lens.id },
      icon: <ArrowRight size={16} />
    }));

    return [...base, ...lenses];
  }, [language]);

  // Deep Omnisearch across the entire business model
  const dataResults = useMemo(() => {
    if (!query || query.length < 2) return [];

    const lowerQ = query.toLowerCase();
    const results: any[] = [];
    const searchTerms = lowerQ.split(' ').filter(t => t.length > 0);

    // Helper to check if all search terms match a string
    const match = (str?: string) => {
      if (!str) return false;
      const lower = str.toLowerCase();
      return searchTerms.every(term => lower.includes(term));
    };

    // Helper to check array of tags
    const matchArray = (arr?: string[]) => {
      if (!arr) return false;
      const str = arr.join(' ').toLowerCase();
      return searchTerms.every(term => str.includes(term));
    };

    const currentWorkspace = useAuthStore.getState().getCurrentWorkspace();
    const dimensionNodes = currentWorkspace?.dimensionNodes || [];
    const accounts = useLedgerStore.getState().accounts;

    // Check if the query matches a DimensionNode
    const matchedDimensionNodes = dimensionNodes.filter(n => 
      match(n.id) || match(n.description) || matchArray(n.aliases)
    ).map(n => n.id);

    // 1. Transactions
    ledger.transactions.forEach(t => {
      const hasMatchedDim = t.dimensions && matchedDimensionNodes.length > 0 && Object.values(t.dimensions).some(val => matchedDimensionNodes.includes(val as string));

      if (match(t.description) || matchArray(t.tags) || match(t.payee) || match(t.id) || hasMatchedDim) {
        results.push({
          id: `tx-${t.id}`,
          type: 'data',
          label: `${t.description || 'Transaction'} - ${(t.totalAmountCents / 100).toLocaleString('en-US', { style: 'currency', currency: t.currency || 'USD' })}`,
          category: `Transaction • ${t.date} ${t.tags ? '• ' + t.tags.join(', ') : ''}`,
          actionId: 'switch-tab',
          payload: { tab: 'transactions', id: t.id },
          icon: <DollarSign size={16} className="text-emerald-500 shrink-0" />
        });
      } else {
        // Search inside lines
        for (const line of t.lines) {
          const accName = resolveAccountName(accounts, line.accountId, line.accountName);
          const lineHasMatchedDim = line.dimensions && matchedDimensionNodes.length > 0 && Object.values(line.dimensions).some(val => matchedDimensionNodes.includes(val as string));
          if (match(line.description) || match(accName) || matchArray(line.tags) || match(line.project) || match(line.class) || match(line.location) || lineHasMatchedDim) {
            results.push({
              id: `tx-line-${t.id}-${line.accountId}`,
              type: 'data',
              label: `${line.description || t.description} (in ${accName})`,
              category: `Transaction Line • ${(line.amountCents / 100).toLocaleString('en-US', { style: 'currency', currency: t.currency || 'USD' })} ${line.tags ? '• ' + line.tags.join(', ') : ''}`,
              actionId: 'switch-tab',
              payload: { tab: 'transactions', id: t.id },
              icon: <FileText size={16} className="text-blue-500 shrink-0" />
            });
            break; // Don't duplicate if multiple lines match
          }
        }
      }
    });

    // 1.5. Dimension Nodes
    dimensionNodes.forEach(node => {
      if (match(node.id) || match(node.description) || matchArray(node.aliases)) {
        results.push({
          id: `dim-${node.id}`,
          type: 'data',
          label: `${node.id.toUpperCase()}: ${node.description}`,
          category: `Dimension Node • ${node.dimensionId}`,
          actionId: 'switch-tab',
          payload: { tab: 'intelligence-center' },
          icon: <FolderPlus size={16} className="text-purple-500 shrink-0" />
        });
      }
    });

    // 2. Projects / Units
    ledger.projects.forEach(p => {
      if (match(p.name) || match(p.description)) {
        results.push({
          id: `proj-${p.id}`,
          type: 'data',
          label: p.name,
          category: `Project / Unit • ${p.status}`,
          actionId: 'switch-tab',
          payload: { tab: 'projects', id: p.id },
          icon: <FolderKanban size={16} className="text-purple-500 shrink-0" />
        });
      }
    });

    // 3. Customers
    ledger.customers.forEach(c => {
      if (match(c.name) || match(c.email) || matchArray(c.tags) || match((c as any).group)) {
        results.push({
          id: `cust-${c.id}`,
          type: 'data',
          label: c.name,
          category: `Customer ${(c as any).group ? '• ' + (c as any).group : ''}`,
          actionId: 'switch-tab',
          payload: { tab: 'sales', id: c.id },
          icon: <User size={16} className="text-amber-500 shrink-0" />
        });
      }
    });

    // 4. Vendors
    ledger.vendors.forEach(v => {
      if (match(v.name) || match(v.email) || matchArray(v.tags) || match((v as any).group)) {
        results.push({
          id: `vend-${v.id}`,
          type: 'data',
          label: v.name,
          category: `Vendor ${(v as any).group ? '• ' + (v as any).group : ''}`,
          actionId: 'switch-tab',
          payload: { tab: 'expenses', id: v.id },
          icon: <Building size={16} className="text-rose-500 shrink-0" />
        });
      }
    });

    // 5. Accounts
    ledger.accounts.forEach(a => {
      if (match(a.name) || match(a.code) || match(a.category)) {
        results.push({
          id: `acc-${a.id}`,
          type: 'data',
          label: `${a.code ? a.code + ' - ' : ''}${a.name}`,
          category: `Account • ${a.type} ${a.category ? '• ' + a.category : ''}`,
          actionId: 'switch-tab',
          payload: { tab: 'ledger', accountId: a.id },
          icon: <Tags size={16} className="text-blue-500 shrink-0" />
        });
      }
    });

    // 6. Invoices
    ledger.invoices?.forEach(i => {
      if (match(i.number) || match(i.customerName) || match(i.status)) {
        results.push({
          id: `inv-${i.id}`,
          type: 'data',
          label: `Invoice ${i.number || 'Draft'} - ${(i.amountCents / 100).toLocaleString('en-US', { style: 'currency', currency: 'USD' })}`,
          category: `Invoice • ${i.customerName} • ${i.number}`,
          actionId: 'switch-tab',
          payload: { tab: 'sales', id: i.id },
          icon: <FileText size={16} className="text-emerald-500 shrink-0" />
        });
      }
    });

    // 7. Bills
    ledger.bills?.forEach(b => {
      if (match(b.number) || match(b.vendorName) || match(b.status)) {
        results.push({
          id: `bill-${b.id}`,
          type: 'data',
          label: `Bill ${b.number || 'Draft'} - ${(b.amountCents / 100).toLocaleString('en-US', { style: 'currency', currency: 'USD' })}`,
          category: `Bill • ${b.vendorName} • ${b.number}`,
          actionId: 'switch-tab',
          payload: { tab: 'purchases', id: b.id },
          icon: <FileText size={16} className="text-rose-500 shrink-0" />
        });
      }
    });

    return results.slice(0, 50); // Limit to top 50 results
  }, [query, ledger.transactions, ledger.projects, ledger.customers, ledger.vendors, ledger.accounts, ledger.invoices, ledger.bills]);

  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        if (isOpen) {
          onClose();
        } else {
          onAction?.('open-command-palette');
        }
      }
      if (e.key === 'Escape') {
        onClose();
      }
    };
    document.addEventListener('keydown', down);
    return () => document.removeEventListener('keydown', down);
  }, [isOpen, onClose, onAction]);

  useEffect(() => {
    if (!isOpen) {
      setTimeout(() => {
        setQuery('');
        setIsExecuting(false);
      }, 0);
    }
  }, [isOpen]);

  const filteredCommands = query
    ? localizedCommands.filter((command) =>
        command.label.toLowerCase().includes(query.toLowerCase())
      )
    : localizedCommands;

  const combinedResults = [...dataResults, ...filteredCommands];

  const handleSelect = async (item: any) => {
    setIsExecuting(true);
    await new Promise(r => setTimeout(r, 400));

    // Core Application Action Mappings
    if (onAction && item.actionId) {
      onAction(item.actionId, item.payload);
    }
    toast.success(`${item.label} opened`);
    setIsExecuting(false);
    onClose();
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[200] bg-gray-900/40 backdrop-blur-sm"
            onClick={onClose}
          />
          <motion.div
            initial={{ opacity: 0, scale: 0.95, y: -20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: -20 }}
            className="fixed z-[201] top-[10%] left-1/2 -translate-x-1/2 w-full max-w-3xl bg-[var(--surface)] rounded-[32px] shadow-2xl overflow-hidden border border-gray-200"
          >
            <div className="flex items-center px-6 py-5 border-b border-gray-100">
              <Search className="text-indigo-600 mr-4" size={24} />
              <input
                autoFocus
                className="flex-1 bg-transparent border-none outline-none text-gray-900 placeholder-gray-400 text-xl font-medium"
                placeholder='Type $40 gas cash, paid Maria 150, new project: Aspen, or search...'
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && parsedIntent.type !== 'unknown') {
                    e.preventDefault();
                    handleExecuteIntent();
                  }
                }}
                disabled={isExecuting}
              />
              <div className="px-2 py-1 bg-gray-100 text-gray-500 rounded text-[10px] font-mono uppercase tracking-widest hidden sm:block">
                ESC to close
              </div>
            </div>

            <div className="max-h-[60dvh] overflow-y-auto bg-[var(--ink)]">
              {parsedIntent.type !== 'unknown' && (
                <div className="p-3 bg-indigo-50/80 border-b border-indigo-100">
                  <button
                    onClick={handleExecuteIntent}
                    className="w-full flex items-center justify-between p-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl transition-all shadow-md group text-left cursor-pointer"
                   aria-label="Instant Command Execution (Press Enter) Execute">
                    <div className="flex items-center gap-3">
                      <div className="p-2.5 bg-white/20 rounded-xl">
                        {parsedIntent.type === 'project' ? <FolderPlus size={20} /> : <Zap size={20} />}
                      </div>
                      <div>
                        <p className="text-sm font-bold tracking-wide uppercase text-indigo-200">Instant Command Execution (Press Enter)</p>
                        <p className="text-base font-semibold">{parsedIntent.displaySummary}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 text-xs font-bold bg-white/20 px-3 py-1.5 rounded-lg group-hover:bg-white/30 transition-colors">
                      <span>Execute</span>
                      <ArrowRight size={14} />
                    </div>
                  </button>
                </div>
              )}

              {isExecuting ? (
                <div className="flex flex-col items-center justify-center p-16 text-gray-500">
                  <Loader2 className="animate-spin mb-4" size={32} />
                  <p className="text-base font-medium">Navigating universe...</p>
                </div>
              ) : combinedResults.length > 0 ? (
                <div className="p-3 space-y-1">
                  {combinedResults.map((item, index) => (
                    <button
                      key={item.id}
                      onClick={() => handleSelect(item)}
                      className="w-full flex items-center justify-between px-5 py-4 hover:bg-[var(--surface)] hover:shadow-sm rounded-2xl transition-all group text-left border border-transparent hover:border-[var(--line)]"
                    >
                      <div className="flex items-center gap-4 min-w-0 flex-1 mr-4">
                        <div className="p-2 bg-slate-100 rounded-lg group-hover:bg-indigo-50 group-hover:text-indigo-600 transition-colors shrink-0">
                          {item.icon}
                        </div>
                        <div className="min-w-0 flex-1">
                          <p className="text-base font-semibold text-gray-900 truncate">{item.label}</p>
                          <p className="text-xs font-medium text-gray-500 truncate">{item.category}</p>
                        </div>
                      </div>
                      <div className="opacity-100 md:opacity-0 md:group-hover:opacity-100 transition-opacity flex items-center shrink-0">
                         <span className="text-xs font-bold uppercase tracking-wider text-indigo-600 mr-2 hidden sm:inline">Jump</span>
                         <ArrowRight size={16} className="text-indigo-600 inline-block -translate-x-2 group-hover:translate-x-0 transition-all shrink-0" />
                      </div>
                    </button>
                  ))}
                </div>
              ) : query.length > 0 ? (
                <div className="p-16 text-center text-gray-500">
                  <Tags size={48} className="mx-auto mb-4 text-gray-300" />
                  <p className="text-lg font-bold text-gray-900">No dimensions matched</p>
                  <p className="text-sm font-medium mt-1">Try searching by tags, units, categories, or dollar amounts.</p>
                </div>
              ) : (
                 <div className="p-10 flex items-center justify-center opacity-50">
                    <p className="text-xs font-bold uppercase tracking-widest text-slate-400 text-center max-w-sm">
                      Amount Search Matrix active.<br/>Type any tag, location, class, or entity to instantly filter your workspace.
                    </p>
                 </div>
              )}
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
}

import React, { lazy, Suspense } from 'react';
import { toast } from 'sonner';
import { useLedgerStore } from '../../stores/useLedgerStore';
import { useAuthStore } from '../../stores/useAuthStore';

// Highly Optimized Lazy Loading of heavy overlay system modals
const CommandPalette = lazy(() => import('./CommandPalette'));
const MagicEntry = lazy(() => import('../ledger/MagicEntry'));
const QBOMigrationWizard = lazy(() => import('../migration/QBOMigrationWizard'));
const StatementImporter = lazy(() => import('../ledger/StatementImporter'));
const TemplateSelector = lazy(() => import('./TemplateSelector'));
const AICustomBlueprint = lazy(() => import('../intelligence/AICustomBlueprint'));
const AICommandCenter = lazy(() => import('../intelligence/AICommandCenter'));
const CurrencyConverter = lazy(() => import('../finance/CurrencyConverter'));
const DocumentEntanglement = lazy(() => import('../forensics/DocumentEntanglement'));
const SystemArchitecture = lazy(() => import('../platform/SystemArchitecture'));
const HealthCheckModal = lazy(() => import('../system/HealthCheckModal'));

interface CommandPortalProps {
  modals: {
    commandPalette: boolean;
    quickEntry: boolean;
    importer: boolean;
    qboMigration: boolean;
    template: boolean;
    aiBlueprint: boolean;
    commandCenter: boolean;
    converter: boolean;
    integrity: boolean;
    healthCheck: boolean;
    entanglement: boolean;
    architecture: boolean;
  };
  handlers: {
    closeCommandPalette: () => void;
    closeQuickEntry: () => void;
    closeImporter: () => void;
    closeQBOMigration: () => void;
    closeTemplate: () => void;
    closeAIBlueprint: () => void;
    closeCommandCenter: () => void;
    closeConverter: () => void;
    closeIntegrity: () => void;
    closeHealthCheck: () => void;
    closeEntanglement: () => void;
    closeArchitecture: () => void;
    handleAIQuery: (q: string) => Promise<any>;
    handleFilter: (f: any) => void;
    handleQuickAdd: (d: any) => void;
    handleImportTransactions: (t: any[]) => void;
    handleIntegrityAction: (a: string) => void;
    handleSelectTemplate: (id: string) => void;
    handleOpenAIBlueprint: () => void;
    handleSaveCurrentTemplate: () => void;
    handleApplyAITemplate: (t: any) => void;
  };
}

export default function CommandPortal({ modals, handlers }: CommandPortalProps) {
  const transactions = useLedgerStore(state => state.transactions);
  const accounts = useLedgerStore(state => state.accounts);
  const projects = useLedgerStore(state => state.projects);
  const autoRules = useLedgerStore(state => state.autoRules || []);
  const patternCache = useLedgerStore(state => state.analyticalPatternCache || {});
  const customTemplates = useLedgerStore(state => state.customTemplates || []);

  const currentWorkspaceId = useAuthStore(state => state.currentWorkspaceId);
  const workspaces = useAuthStore(state => state.workspaces);
  const currentWorkspace = workspaces.find(w => w.id === currentWorkspaceId);

  const businessContext = currentWorkspace?.description || '';
  const baseCurrency = currentWorkspace?.currency || 'USD';
  const currentTemplateId = currentWorkspace?.businessType || 'generic';

  const categories = Array.from(new Set(accounts.filter((a: any) => a.type === 'income' || a.type === 'expense').map((a: any) => a.name)));

  return (
    <Suspense fallback={null}>
      {modals.commandPalette && (
        <CommandPalette 
          isOpen={modals.commandPalette}
          onClose={handlers.closeCommandPalette}
          onQuery={handlers.handleAIQuery}
          recentQueries={[]}
        />
      )}
      {modals.quickEntry && (
        <MagicEntry 
          isOpen={modals.quickEntry} 
          onClose={handlers.closeQuickEntry} 
          onAdd={handlers.handleQuickAdd}
          categories={categories}
          accounts={accounts}
          projects={projects.map((p: any) => p.name)}
          autoRules={autoRules}
          patternCache={patternCache}
        />
      )}
      {modals.qboMigration && (
        <QBOMigrationWizard 
          isOpen={modals.qboMigration}
          onClose={handlers.closeQBOMigration}
        />
      )}
      {modals.importer && (
        <StatementImporter 
          isOpen={modals.importer}
          onClose={handlers.closeImporter}
          onImport={handlers.handleImportTransactions}
          existingTransactions={transactions}
          businessContext={businessContext}
          accounts={accounts}
          autoRules={autoRules}
          patternCache={patternCache}
        />
      )}
      {modals.aiBlueprint && (
        <AICustomBlueprint 
          isOpen={modals.aiBlueprint}
          onClose={handlers.closeAIBlueprint}
          onGenerated={handlers.handleApplyAITemplate}
        />
      )}
      {modals.template && (
        <TemplateSelector 
          isOpen={modals.template}
          onClose={handlers.closeTemplate}
          onSelect={handlers.handleSelectTemplate}
          onOpenAI={handlers.handleOpenAIBlueprint}
          currentType={currentTemplateId}
          customTemplates={customTemplates}
          onSaveCurrent={handlers.handleSaveCurrentTemplate}
        />
      )}
      {modals.commandCenter && (
        <AICommandCenter 
          isOpen={modals.commandCenter}
          onClose={handlers.closeCommandCenter}
          onFilter={handlers.handleFilter}
          businessContext={businessContext}
        />
      )}
      {modals.converter && (
        <CurrencyConverter 
          isOpen={modals.converter}
          onClose={handlers.closeConverter}
          baseCurrency={baseCurrency}
        />
      )}
      {modals.healthCheck && (
        <HealthCheckModal 
          isOpen={modals.healthCheck} 
          onClose={handlers.closeHealthCheck} 
        />
      )}
      {modals.entanglement && (
        <DocumentEntanglement 
          isOpen={modals.entanglement}
          onClose={handlers.closeEntanglement}
          onVerify={() => {
            toast.success("Document structure verified and entangled with ledger.");
            handlers.closeEntanglement();
          }}
        />
      )}
      {modals.architecture && (
        <SystemArchitecture 
          isOpen={modals.architecture}
          onClose={handlers.closeArchitecture}

          accounts={accounts}
        />
      )}
    </Suspense>
  );
}

import React from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { X, Table, Search } from 'lucide-react';
import { Transaction } from '../../types';
import { format } from 'date-fns';
import { parseLocalDate, cn } from '../../lib/utils';

interface DrillDownModalProps {
  isOpen: boolean;
  onClose: () => void;
  accountName: string;
  transactions: Transaction[];
  formatCurrency: (val: number) => string;
}

export default function DrillDownModal({ isOpen, onClose, accountName, transactions, formatCurrency }: DrillDownModalProps) {
  const [displayLimit, setDisplayLimit] = React.useState(50);
  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[600] flex items-center justify-center p-4">
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="absolute inset-0 bg-slate-900/60 backdrop-blur-md"
          />
          <motion.div
            initial={{ scale: 0.95, opacity: 0, y: 20 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.95, opacity: 0, y: 20 }}
            className="relative w-full max-w-4xl max-h-[85dvh] bg-[var(--surface)] rounded-[40px] shadow-2xl flex flex-col overflow-hidden border border-[var(--line)]"
          >
            <div className="p-4 md:p-8 border-b border-[var(--line)] flex items-center justify-between bg-[var(--surface)]/50">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-slate-900 text-white rounded-[32px] flex items-center justify-center shadow-lg shadow-ledger-ink/20">
                  <Table size={24} />
                </div>
                <div>
                  <h3 className="text-2xl font-black text-[var(--text)] tracking-tight">{accountName}</h3>
                  <p className="micro-label">Transaction Drill-Down • {transactions.length} matched events</p>
                </div>
              </div>
              <button aria-label="Close" 
                onClick={onClose}
                className="p-3 hover:bg-[var(--surface)] rounded-[32px] transition-all shadow-sm border border-transparent hover:border-[var(--line)]"
              ><X size={24} /></button>
            </div>

            <div className="flex-1 overflow-auto p-4 md:p-8 custom-scrollbar">
              <table className="w-full text-left border-separate border-spacing-y-2">
                <thead>
                  <tr className="micro-label text-slate-500">
                    <th className="pb-4 pl-4 font-black">Date</th>
                    <th className="pb-4 font-black">Description</th>
                    <th className="pb-4 text-right pr-4 font-black">Impact</th>
                  </tr>
                </thead>
                <tbody>
                  {transactions.slice(0, displayLimit).map((tx) => {
                    const matchedLine = tx.lines?.find(l => l.accountName === accountName || l.accountId === accountName);
                    const line = matchedLine || tx.lines?.[0];
                    const amount = matchedLine ? matchedLine.amountCents : tx.totalAmountCents;

                    return (
                      <tr key={tx.id} className="group hover:bg-[var(--ink)] transition-all rounded-[32px] overflow-hidden">
                        <td className="py-4 pl-4 text-xs font-black text-slate-500 font-mono rounded-l-2xl border-y border-l border-[var(--line)] group-hover:border-slate-300">
                          {tx.date ? format(parseLocalDate(tx.date), 'MMM dd, yyyy') : 'N/A'}
                        </td>
                        <td className="py-4 text-sm font-bold text-[var(--text)] border-y border-[var(--line)] group-hover:border-slate-300">
                           <div className="flex flex-col">
                             <span>{tx.description}</span>
                             {tx.payee && <span className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">{tx.payee}</span>}
                           </div>
                        </td>
                        <td className={cn(
                          "py-4 text-right pr-4 font-black font-mono border-y border-r border-[var(--line)] group-hover:border-slate-300 rounded-r-2xl",
                          amount >= 0 ? "text-emerald-600" : "text-rose-600"
                        )}>
                          {amount >= 0 ? '+' : ''}{formatCurrency(amount)}
                        </td>
                      </tr>
                    );
                  })}
                  {transactions.length > displayLimit && (
                    <tr>
                      <td colSpan={3} className="py-6 text-center border border-dashed border-[var(--line)] rounded-[32px]">
                        <button 
                          onClick={() => setDisplayLimit(prev => prev + 50)}
                          className="px-6 py-2 bg-[var(--surface)] hover:bg-[var(--ink)] text-indigo-600 font-bold text-xs uppercase tracking-widest rounded-xl transition-all cursor-pointer"
                        >
                          Load Next 50 (Showing {displayLimit} of {transactions.length})
                        </button>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>

              {transactions.length === 0 && (
                <div className="py-20 text-center space-y-4">
                  <div className="w-16 h-16 bg-[var(--surface)] rounded-[32px] flex items-center justify-center text-slate-300 mx-auto">
                    <Search size={32} />
                  </div>
                  <p className="text-sm text-slate-500 font-medium italic">No underlying transactions found for this period.</p>
                </div>
              )}
            </div>

            <div className="p-4 md:p-8 border-t border-[var(--line)] bg-[var(--surface)]/30">
               <div className="flex items-center justify-between">
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">End of Drill-Down View</p>
                  <button onClick={onClose} className="btn-secondary" aria-label="Close Report">Close Report</button>
               </div>
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}

import React from 'react';
import { Menu, Search, Sun, Moon, Plus, Compass, ShieldCheck } from 'lucide-react';
import QuickCreateMenu from './QuickCreateMenu';
import { useAuthStore } from '../../stores/useAuthStore';
import { useUIStore } from '../../stores/useUIStore';

interface HeaderProps {
  onLogout?: () => void;
  onLoginPrompt?: () => void;
}

const Header = React.memo(function Header({ onLogout, onLoginPrompt }: HeaderProps) {
  const user = useAuthStore(state => state.user);
  const currentWorkspaceId = useAuthStore(state => state.currentWorkspaceId);
