export default Ledger;

import React, { useState, useEffect } from 'react';
import { aiService } from '../../services/aiService';
import { useLedgerStore } from '../../stores/useLedgerStore';
import { parseNaturalLanguageEntry } from '../../lib/algorithms/nl-parser';
import { Check, Wand2, Receipt, Camera, X, Loader2, Edit2 } from 'lucide-react';
import { parseReceiptOCR } from '../../lib/algorithms/receipt-capture';
import { useTransactionActions } from '../../hooks/useTransactionActions';
import { toast } from 'sonner';
import { getLocalDateISO } from '../../lib/utils';
import { resolveAccountRole } from '../../lib/accountUtils';
import { isCashAccount } from '../../lib/txFilters';
import AsyncButton from '../ui/AsyncButton';

export default function MagicEntry({ isOpen, onClose, onAdd }: any) {
  const [isAiParsing, setIsAiParsing] = useState(false);
  const [text, setText] = useState('');
  const [parsed, setParsed] = useState<any>(null);
  const [receiptMode, setReceiptMode] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const { handleQuickAdd, handleParseReceipt } = useTransactionActions();

  const isModal = isOpen !== undefined;

  const handleParse = (val: string) => {
    setText(val);
    if (val.length < 5) {
      setParsed(null);
    }
  };

  useEffect(() => {
    if (text.length < 5) return;
    const timer = setTimeout(async () => {
      setIsAiParsing(true);
      try {
        const { accounts, projects } = useLedgerStore.getState();
        const catNames = accounts.map(a => a.name);
        const projNames = projects.map(p => p.name) || [];
        const resultArr = await aiService.parseMagicEntry(text, catNames, accounts, projNames);
        if (resultArr && resultArr.length > 0) {
          const r = resultArr[0];
          setParsed({
            action: r.amountCents < 0 ? 'expense' : 'revenue',
            amount: Math.abs(r.amountCents),
            description: r.description,
            method: r.dimensions?.account || 'Default',
            dateStr: r.date
          });
        } else {
          const fallback = parseNaturalLanguageEntry(text);
          setParsed({
            action: fallback.action,
            amount: fallback.amountCents || 0,
            description: fallback.description,
            method: fallback.method,
            dateStr: fallback.dateStr
          });
        }
      } catch (e) {
        const fallback = parseNaturalLanguageEntry(text);
        setParsed({
            action: fallback.action,
            amount: fallback.amountCents || 0,
            description: fallback.description,
            method: fallback.method,
            dateStr: fallback.dateStr
        });
      } finally {
        setIsAiParsing(false);
      }
    }, 800);
    return () => clearTimeout(timer);
  }, [text]);

  const handleUploadReceipt = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    // Call it normally as a hook if we can, but since this is inside a component, we can destructure it at the top level.
    if (handleParseReceipt) {
      await handleParseReceipt(file);
      if (onClose) onClose();
    }
  };

  const handleSave = async () => {
    if (!parsed) return;
    if (onAdd) {
       onAdd({
         description: parsed.description,
         amount: parsed.amount,
         date: parsed.dateStr,
         type: parsed.action
       });
    } else {
       const { accounts } = useLedgerStore.getState();
       const actionType = parsed.action || 'expense';
       const isExp = actionType === 'expense';
       const targetAcc = accounts.find(a => resolveAccountRole(a) === (isExp ? 'expense' : 'revenue')) || accounts.find(a => a.type === (isExp ? 'expense' : 'income')) || accounts[0];
       const cashAcc = accounts.find(a => resolveAccountRole(a) === 'cash') || accounts.find(a => isCashAccount(a)) || accounts[0];

       if (!targetAcc || !cashAcc) {
         toast.error('Cannot post transaction: No chart of accounts available.');
         return;
       }

       const amt = Math.abs(parsed.amount || 0);
       await handleQuickAdd({
         description: parsed.description || 'Natural Language Entry',
         totalAmountCents: amt,
         date: parsed.dateStr || getLocalDateISO(),
         type: actionType,
         lines: [
           {
             accountId: targetAcc.id,
             accountName: parsed.description || targetAcc.name,
             amountCents: isExp ? amt : -amt
           },
           {
             accountId: cashAcc.id,
             accountName: cashAcc.name,
             amountCents: isExp ? -amt : amt
           }
         ]
       });
       toast.success('Transaction saved to General Ledger!');
    }
    setText('');
    setParsed(null);
    setReceiptMode(false);
    setIsEditing(false);
    if (onClose) onClose();
  };

  const content = (
    <div className="p-6 space-y-6">
      <div className="relative">
        <input 
          autoFocus
          className="w-full text-lg py-6 pl-12 pr-32 rounded-xl border border-[var(--line)] bg-[var(--panel)] text-[var(--text)] shadow-sm focus:outline-none focus:ring-2 focus:ring-[var(--brass)] focus:border-[var(--brass)] placeholder:text-[var(--faint)]"
          placeholder="e.g., paid $40 gas cash yesterday"
          value={text}
          onChange={(e) => handleParse(e.target.value)}
        />
        {isAiParsing ? <Loader2 className="absolute left-4 top-1/2 -translate-y-1/2 text-[var(--brass)] w-5 h-5 animate-spin" /> : <Wand2 className="absolute left-4 top-1/2 -translate-y-1/2 text-[var(--brass)] w-5 h-5" />}
        <label className="absolute right-2 top-1/2 -translate-y-1/2 text-[var(--muted)] hover:text-[var(--text)] hover:bg-[var(--elevated)] px-3 py-2 rounded-lg font-medium text-sm flex items-center transition-colors cursor-pointer">
          <Camera className="w-4 h-4 mr-2" /> Snap Receipt
          <input type="file" accept="image/*" className="hidden" onChange={handleUploadReceipt} />
        </label>
      </div>

      {parsed && (
        <div className="mt-8 bg-[var(--panel)] border border-[var(--line)] rounded-xl p-6">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-semibold text-[var(--muted)] uppercase tracking-wider">We understood:</h3>
          </div>
          {isEditing ? (
            <div className="grid grid-cols-2 gap-y-4 gap-x-8">
              <div>
                <p className="text-xs text-[var(--faint)] mb-1">Amount ($)</p>
                <input 
                  type="number" 
                  step="0.01"
                  className="w-full bg-[var(--surface)] border border-[var(--line)] rounded p-2 text-sm focus:outline-none focus:border-[var(--brass)] text-[var(--text)]"
                  value={(parsed.amount / 100).toFixed(2)}
                  onChange={(e) => setParsed({...parsed, amount: Math.round(parseFloat(e.target.value || '0') * 100)})}
                />
              </div>
              <div>
                <p className="text-xs text-[var(--faint)] mb-1">Action</p>
                <select 
                  className="w-full bg-[var(--surface)] border border-[var(--line)] rounded p-2 text-sm focus:outline-none focus:border-[var(--brass)] text-[var(--text)]"
                  value={parsed.action}
                  onChange={(e) => setParsed({...parsed, action: e.target.value})}
                >
                  <option value="expense">Expense (Out)</option>
                  <option value="revenue">Revenue (In)</option>
                </select>
              </div>
              <div>
                <p className="text-xs text-[var(--faint)] mb-1">Method</p>
                <input 
                  type="text" 
                  className="w-full bg-[var(--surface)] border border-[var(--line)] rounded p-2 text-sm focus:outline-none focus:border-[var(--brass)] text-[var(--text)]"
                  value={parsed.method}
                  onChange={(e) => setParsed({...parsed, method: e.target.value})}
                />
              </div>
              <div>
                <p className="text-xs text-[var(--faint)] mb-1">Date</p>
                <input 
                  type="date" 
                  className="w-full bg-[var(--surface)] border border-[var(--line)] rounded p-2 text-sm focus:outline-none focus:border-[var(--brass)] text-[var(--text)]"
                  value={parsed.dateStr}
                  onChange={(e) => setParsed({...parsed, dateStr: e.target.value})}
                />
              </div>
              <div className="col-span-2">
                <p className="text-xs text-[var(--faint)] mb-1">Description / Category</p>
                <input 
                  type="text" 
                  className="w-full bg-[var(--surface)] border border-[var(--line)] rounded p-2 text-sm focus:outline-none focus:border-[var(--brass)] text-[var(--text)]"
                  value={parsed.description}
                  onChange={(e) => setParsed({...parsed, description: e.target.value})}
                />
              </div>
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-y-4 gap-x-8">
              <div>
                <p className="text-xs text-[var(--faint)] mb-1">Amount</p>
                <p className={`text-xl font-bold ${parsed.action === 'expense' ? 'text-[var(--neg)]' : 'text-[var(--pos)]'}`}>
                  ${Math.abs(parsed.amount / 100).toFixed(2)} {parsed.action === 'expense' ? 'Out' : 'In'}
                </p>
              </div>
              <div>
                <p className="text-xs text-[var(--faint)] mb-1">Method</p>
                <p className="text-lg font-medium text-[var(--text)]">{parsed.method}</p>
              </div>
              <div>
                <p className="text-xs text-[var(--faint)] mb-1">Description / Category</p>
                <p className="text-lg font-medium text-[var(--text)] capitalize">{parsed.description || 'General'}</p>
              </div>
              <div>
                <p className="text-xs text-[var(--faint)] mb-1">Date</p>
                <p className="text-lg font-medium text-[var(--text)]">{parsed.dateStr}</p>
              </div>
            </div>
          )}

          <div className="mt-6 flex flex-col sm:flex-row gap-3">
            {!isEditing ? (
              <button 
                className="w-full sm:w-1/3 bg-[var(--surface)] border border-[var(--line)] text-[var(--text)] font-medium py-3 px-4 rounded-xl transition-colors hover:bg-[var(--elevated)] shadow-sm flex items-center justify-center"
                onClick={() => setIsEditing(true)}
              >
                <Edit2 className="w-4 h-4 mr-2" /> Edit Details
              </button>
            ) : (
              <button 
                className="w-full sm:w-1/3 bg-[var(--surface)] border border-[var(--line)] text-[var(--text)] font-medium py-3 px-4 rounded-xl transition-colors hover:bg-[var(--elevated)] shadow-sm flex items-center justify-center"
                onClick={() => setIsEditing(false)}
              >
                Done Editing
              </button>
            )}
            <AsyncButton 
              className="w-full sm:flex-1 bg-[var(--brass)] text-black font-bold py-3 px-4 rounded-xl flex items-center justify-center transition-opacity hover:opacity-90 shadow-md"
              onClick={handleSave}
              loadingText="Saving..."
            >
              <Check className="w-4 h-4 mr-2" /> Looks Right - Save It
            </AsyncButton>
          </div>
        </div>
      )}

      <div className="flex flex-wrap gap-2 justify-center pt-4">
        <span className="text-xs text-[var(--muted)]">Try typing:</span>
        <span className="text-xs bg-[var(--surface)] border border-[var(--line)] text-[var(--text)] px-2 py-0.5 rounded cursor-pointer hover:bg-[var(--elevated)]" onClick={() => handleParse("earned $1500 client retainer check today")}>earned $1500 client retainer check today</span>
        <span className="text-xs bg-[var(--surface)] border border-[var(--line)] text-[var(--text)] px-2 py-0.5 rounded cursor-pointer hover:bg-[var(--elevated)]" onClick={() => handleParse("paid $80 lunch card yesterday")}>paid $80 lunch card yesterday</span>
      </div>
    </div>
  );

  if (isOpen === false) return null;

  if (isModal) {
    return (
      <div className="fixed inset-0 z-[300] flex items-center justify-center p-4">
        <div role="button" tabIndex={0} className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={onClose} />
        <div className="relative w-full max-w-2xl bg-[var(--surface)] rounded-2xl shadow-2xl border border-[var(--line)] overflow-hidden">
          <div className="flex items-center justify-between p-6 border-b border-[var(--line)]">
            <div>
              <h2 className="text-2xl font-bold tracking-tight">Magic Entry</h2>
              <p className="text-slate-500">Just type what happened. No debit/credit knowledge required.</p>
            </div>
            {onClose && (
              <button aria-label="Close" onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full text-slate-500"><X className="w-5 h-5" /></button>
            )}
          </div>
          {content}
        </div>
      </div>
    );
  }

  // Full page view
  return (
    <div className="p-6 max-w-2xl mx-auto space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Magic Entry</h1>
        <p className="text-slate-500">Just type what happened. No debit/credit knowledge required.</p>
      </div>
      <div className="bg-[var(--surface)] rounded-xl shadow-sm border border-[var(--line)] overflow-hidden">
        {content}
      </div>
    </div>
  );
}

import React, { useMemo, useState } from 'react';
import { useLedgerStore } from '../../stores/useLedgerStore';
import { useAuthStore } from '../../stores/useAuthStore';
import { CheckCircle2, Circle, AlertTriangle, ArrowRight, BookOpen, Lock, ShieldCheck, Download } from 'lucide-react';
import { motion } from 'motion/react';
import { formatCurrency } from '../../lib/utils';
import { Transaction } from '../../types';
import { toast } from 'sonner';
import * as XLSX from 'xlsx';

import AsyncButton from '../ui/AsyncButton';

export default function MonthEndCloseView() {
  const transactions = useLedgerStore(s => s.transactions) || [];
  const accounts = useLedgerStore(s => s.accounts) || [];
  const bankLines = useLedgerStore(s => s.bankLines) || [];
  const invoices = useLedgerStore(s => s.invoices) || [];
  const bills = useLedgerStore(s => s.bills) || [];
  const user = useAuthStore(s => s.user);
  const userWorkspaces = useAuthStore(s => s.workspaces) || [];
  const currentWorkspaceId = useAuthStore(s => s.currentWorkspaceId);

  const currentWorkspace = userWorkspaces.find(w => w.id === currentWorkspaceId);
  const currency = currentWorkspace?.currency || 'USD';

  // State
  const [nowMs] = useState(() => Date.now());
  const [selectedMonth, setSelectedMonth] = useState(() => {
    const d = new Date();
    d.setMonth(d.getMonth() - 1);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
  });

  const [isClosing, setIsClosing] = useState(false);
  const [closedPeriods, setClosedPeriods] = useState<string[]>([]);

  const stats = useMemo(() => {
    const periodTx = transactions.filter(t => !t.deletedAt && t.status !== 'void' && (t.date || '').startsWith(selectedMonth));
    const periodBankLines = bankLines.filter(l => (l.date || '').startsWith(selectedMonth));

    const uncategorizedCount = periodTx.filter(t => 
      t.lines?.some(l => !l.accountId || l.accountId === 'uncategorized' || l.accountName === 'Uncategorized')
    ).length;

    const unreconciledBankLines = periodBankLines.filter(l => l.status === 'pending' || !l.matchedTransactionId).length;
    // Vacuously reconciled if zero pending lines in bank feed
    const isReconciled = unreconciledBankLines === 0;

    // Trial balance net calculation across cumulative ledger up to month end
    let tbNet = 0;
    const cumulativeTx = transactions.filter(t => !t.deletedAt && t.status !== 'void' && (t.date || '') <= `${selectedMonth}-31`);
    cumulativeTx.forEach(t => {
      t.lines?.forEach(l => {
        tbNet += l.amountCents || 0;
      });
    });
    const tbIsZero = Math.abs(tbNet) === 0;

    // Anomalies
    const flaggedTx = periodTx.filter(t => t.status === 'flagged').length;

    // Invoices and Bills over 60 days overdue
    const aged60Ms = nowMs - 60 * 24 * 60 * 60 * 1000;
    const oldInvoices = invoices.filter(inv => inv.status !== 'paid' && inv.status !== 'void' && inv.dueDate && new Date(inv.dueDate).getTime() < aged60Ms).length;
    const oldBills = bills.filter(b => b.status !== 'paid' && b.status !== 'void' && b.dueDate && new Date(b.dueDate).getTime() < aged60Ms).length;
    const oldUnpaid = oldInvoices + oldBills;

    return {
      uncategorizedCount,
      unreconciledBankLines,
      isReconciled,
      tbIsZero,
      flaggedTx,
      oldUnpaid,
      periodBankLinesCount: periodBankLines.length
    };
  }, [transactions, bankLines, invoices, bills, selectedMonth]);

  const checklist = [
    {
      id: 'import',
      title: 'Bank Accounts Imported',
      desc: stats.periodBankLinesCount > 0 ? `Imported ${stats.periodBankLinesCount} bank lines this period.` : 'No bank feed activity (manual entry mode).',
      status: 'done' as const
    },
    {
      id: 'uncategorized',
      title: 'Categorize Transactions',
      desc: stats.uncategorizedCount === 0 ? 'All transactions categorized.' : `${stats.uncategorizedCount} transactions missing category.`,
      status: stats.uncategorizedCount === 0 ? ('done' as const) : ('pending' as const)
    },
    {
      id: 'reconcile',
      title: 'Bank Reconciliation',
      desc: stats.periodBankLinesCount === 0 ? 'No bank feed items to reconcile.' : stats.isReconciled ? 'All bank lines reconciled.' : `${stats.unreconciledBankLines} lines pending match.`,
      status: stats.isReconciled ? ('done' as const) : ('pending' as const)
    },
    {
      id: 'trial-balance',
      title: 'Trial Balance Verification',
      desc: stats.tbIsZero ? 'Debits equal credits (nets to zero).' : 'Trial balance is out of balance!',
      status: stats.tbIsZero ? ('done' as const) : ('error' as const)
    },
    {
      id: 'anomalies',
      title: 'Anomaly Resolution',
      desc: stats.flaggedTx === 0 ? 'No unresolved anomalies.' : `${stats.flaggedTx} anomalies need review.`,
      status: stats.flaggedTx === 0 ? ('done' as const) : ('warning' as const)
    },
    {
      id: 'ar-ap',
      title: 'Aging Review',
      desc: stats.oldUnpaid === 0 ? 'No severely aged receivables or payables.' : `${stats.oldUnpaid} unpaid items > 60 days old.`,
      status: stats.oldUnpaid === 0 ? ('done' as const) : ('warning' as const)
    }
  ];

  const totalSteps = checklist.length;
  const completedSteps = checklist.filter(c => c.status === 'done').length;
  const isReady = completedSteps === totalSteps;

  const handleExportAccountantPackage = () => {
    try {
      const toastId = toast.loading('Compiling accountant package workbook...');

      const periodTx = transactions.filter(t => !t.deletedAt && t.status !== 'void' && (t.date || '').startsWith(selectedMonth));
      const cumulativeTx = transactions.filter(t => !t.deletedAt && t.status !== 'void' && (t.date || '') <= `${selectedMonth}-31`);

      const wb = XLSX.utils.book_new();

      // 1. Cumulative Trial Balance Sheet
      const accountMap: Record<string, { code: string; name: string; type: string; debitCents: number; creditCents: number }> = {};
      accounts.forEach(a => {
        accountMap[a.id] = {
          code: a.code || '',
          name: a.name,
          type: a.type,
          debitCents: 0,
          creditCents: 0
        };
      });

      cumulativeTx.forEach(t => {
        t.lines?.forEach(l => {
          const acc = accountMap[l.accountId] || {
            code: '',
            name: l.accountName || l.accountId || 'Unassigned',
            type: 'expense',
            debitCents: 0,
            creditCents: 0
          };
          if (l.amountCents > 0) {
            acc.debitCents += l.amountCents;
          } else {
            acc.creditCents += Math.abs(l.amountCents);
          }
          accountMap[l.accountId] = acc;
        });
      });

      const tbHeaders = ['Account Code', 'Account Name', 'Type', 'Cumulative Debits ($)', 'Cumulative Credits ($)', 'Net Balance ($)'];
      const tbRows = Object.values(accountMap).map(a => [
        a.code,
        a.name,
        a.type.toUpperCase(),
        (a.debitCents / 100).toFixed(2),
        (a.creditCents / 100).toFixed(2),
        ((a.debitCents - a.creditCents) / 100).toFixed(2)
      ]);
      const wsTB = XLSX.utils.aoa_to_sheet([tbHeaders, ...tbRows]);
      XLSX.utils.book_append_sheet(wb, wsTB, "Trial Balance");

      // 2. General Ledger / Transactions
      const glHeaders = ['Date', 'Transaction ID', 'Description', 'Account Name', 'Type', 'Status', 'Amount ($)'];
      const glRows = periodTx.flatMap(t => 
        (t.lines && t.lines.length > 0 ? t.lines : [{ accountName: 'General', accountId: '', amountCents: t.totalAmountCents }]).map(l => [
          t.date,
          t.id,
          t.description,
          l.accountName || l.accountId || 'General',
          t.type || 'actual',
          t.status,
          ((l.amountCents || t.totalAmountCents || 0) / 100).toFixed(2)
        ])
      );
      const wsGL = XLSX.utils.aoa_to_sheet([glHeaders, ...glRows]);
      XLSX.utils.book_append_sheet(wb, wsGL, "General Ledger");

      // 3. Open Invoices (A/R)
      const invHeaders = ['Invoice #', 'Customer Name', 'Issue Date', 'Due Date', 'Status', 'Total ($)'];
      const invRows = invoices.map(i => [
        i.number,
        i.customerName,
        i.date,
        i.dueDate,
        i.status,
        ((i.totalCents || i.amountCents || 0) / 100).toFixed(2)
      ]);
      const wsInv = XLSX.utils.aoa_to_sheet([invHeaders, ...invRows]);
      XLSX.utils.book_append_sheet(wb, wsInv, "Invoices (AR)");

      // 4. Open Bills (A/P)
      const billHeaders = ['Bill #', 'Vendor Name', 'Issue Date', 'Due Date', 'Status', 'Amount ($)'];
      const billRows = bills.map(b => [
        b.number,
        b.vendorName,
        b.date,
        b.dueDate,
        b.status,
        ((b.amountCents || 0) / 100).toFixed(2)
      ]);
      const wsBills = XLSX.utils.aoa_to_sheet([billHeaders, ...billRows]);
      XLSX.utils.book_append_sheet(wb, wsBills, "Bills (AP)");

      // Write file
      const fileName = `Accountant_Package_${selectedMonth}_${new Date().toISOString().slice(0, 10)}.xlsx`;
      XLSX.writeFile(wb, fileName);
      toast.success(`Accountant Package exported: ${fileName}`, { id: toastId });
    } catch (err: any) {
      console.error('Failed to export accountant package:', err);
      toast.error('Failed to export accountant package workbook.');
    }
  };

  const handleClosePeriod = async () => {
    if (!user || !currentWorkspaceId) return;
    setIsClosing(true);
    try {
      const isFiscalYearEnd = selectedMonth.endsWith('-12');
      const token = await user.getIdToken();
      const res = await fetch('/api/v1/transactions/close-month', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          workspaceId: currentWorkspaceId,
          month: selectedMonth,
          isFiscalYearEnd
        })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to close period');

      setClosedPeriods(prev => [...prev, selectedMonth]);
      toast.success(data.message || `Period ${selectedMonth} locked.`);
    } catch (err: any) {
      toast.error(`Failed to lock period: ${err?.message || 'Error'}`);
    } finally {
      setIsClosing(false);
    }
  };

  const monthEndDate = `${selectedMonth}-28`;
  const isClosed = (currentWorkspace?.lockDate && currentWorkspace.lockDate >= monthEndDate) || closedPeriods.includes(selectedMonth);

  return (
    <div className="h-full flex flex-col bg-[var(--color-ledger-bg)]">
      <div className="flex-1 overflow-auto p-6 md:p-8">
        <div className="max-w-4xl mx-auto space-y-8">

          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-semibold text-[var(--color-ledger-ink)] font-display tracking-tight flex items-center gap-3">
                <ShieldCheck className="w-6 h-6 text-emerald-500" />
                Month-End Close
              </h1>
              <p className="text-sm text-[var(--color-ledger-muted)] mt-1">
                Verify ledgers, snapshot balances, and lock the period.
              </p>
            </div>
            <input 
              type="month" 
              value={selectedMonth}
              onChange={(e) => setSelectedMonth(e.target.value)}
              className="bg-white border border-[var(--color-ledger-line)] rounded-lg px-4 py-2 text-sm focus:outline-none focus:border-indigo-500 shadow-sm"
            />
          </div>

          <div className="bg-white rounded-2xl border border-[var(--color-ledger-line)] overflow-hidden shadow-sm">
            <div className="p-6 border-b border-[var(--color-ledger-line)] flex items-center justify-between bg-slate-50">
              <div>
                <h2 className="text-lg font-medium text-[var(--color-ledger-ink)]">
                  Close Checklist — {new Date(`${selectedMonth}-01`).toLocaleString('default', { month: 'long', year: 'numeric' })}
                </h2>
                <div className="flex items-center gap-3 mt-2">
                  <div className="flex-1 w-48 h-2 bg-slate-200 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-emerald-500 transition-all duration-500"
                      style={{ width: `${(completedSteps / totalSteps) * 100}%` }}
                    />
                  </div>
                  <span className="text-sm font-medium text-slate-500">
                    {completedSteps} of {totalSteps} complete
                  </span>
                </div>
              </div>
              <div className="flex items-center gap-3 flex-wrap">
                <button 
                  onClick={handleExportAccountantPackage}
                  className="px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-lg flex items-center gap-2 font-medium hover:bg-slate-50 transition-colors shadow-sm text-sm cursor-pointer"
                >
                  <BookOpen className="w-4 h-4 text-indigo-600" /> Export Accountant Package (.xlsx)
                </button>
                {isClosed ? (
                  <div className="px-4 py-2 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-lg flex items-center gap-2 font-medium text-sm">
                    <Lock className="w-4 h-4" /> Period Locked
                  </div>
                ) : (
                  <AsyncButton
                    disabled={!isReady || isClosing}
                    onClick={handleClosePeriod}
                    loadingText="Locking Period..."
                    className={`px-6 py-2.5 rounded-xl font-medium transition-all shadow-sm flex items-center gap-2 ${
                      isReady 
                        ? 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-indigo-200' 
                        : 'bg-slate-100 text-slate-400 cursor-not-allowed'
                    }`}
                  >
                    Close Month
                    {!isClosing && <ArrowRight className="w-4 h-4" />}
                  </AsyncButton>
                )}
              </div>
            </div>

            <div className="divide-y divide-[var(--color-ledger-line)]">
              {checklist.map((item, idx) => (
                <motion.div 
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.05 }}
                  key={item.id} 
                  className="p-5 flex items-start gap-4 hover:bg-slate-50 transition-colors"
                >
                  <div className="mt-0.5">
                    {item.status === 'done' && <CheckCircle2 className="w-6 h-6 text-emerald-500" />}
                    {item.status === 'pending' && <Circle className="w-6 h-6 text-slate-300" />}
                    {item.status === 'warning' && <AlertTriangle className="w-6 h-6 text-amber-500" />}
                    {item.status === 'error' && <AlertTriangle className="w-6 h-6 text-rose-500" />}
                  </div>
                  <div className="flex-1">
                    <h3 className={`font-medium ${item.status === 'done' ? 'text-slate-600' : 'text-slate-900'}`}>
                      {item.title}
                    </h3>
                    <p className={`text-sm mt-1 ${item.status === 'error' ? 'text-rose-600' : 'text-slate-500'}`}>
                      {item.desc}
                    </p>
                  </div>
                  {item.status !== 'done' && (
                    <button className="text-sm font-medium text-indigo-600 hover:text-indigo-700 hover:bg-indigo-50 px-3 py-1.5 rounded-lg transition-colors">
                      Review
                    </button>
                  )}
                </motion.div>
              ))}
            </div>
          </div>

        </div>
      </div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Transaction } from '../../types';
import { 
  Table as TableIcon, 
  Search, 
  Download, 
  ChevronDown, 
  ChevronRight,
  Calculator,
  Grid3X3,
  ListCollapse,
  Plus,
  ExternalLink,
  Calendar
} from 'lucide-react';
import { toast } from 'sonner';
import { formatDecimal, cn, formatCurrency, sanitizeCsvCell, resolveAccountName } from '../../lib/utils';
import { isPostable } from '../../lib/txFilters';
import { getLineDimension, DEFAULT_WORKSPACE_DIMENSIONS } from '../../lib/dimensionUtils';
import { useAuthStore } from '../../stores/useAuthStore';
import { useLedgerStore } from '../../stores/useLedgerStore';
import DrillDownModal from '../layout/DrillDownModal';

interface PivotSheetProps {
  transactions: Transaction[];
  isEmbedded?: boolean;
}

type GroupBy = string; // Dynamic dimension ID or 'month' | 'payee'
type PivotMode = 'flat' | 'matrix';
type PeriodFilter = 'all' | 'this_year' | 'last_year' | 'this_quarter' | 'this_month' | 'custom';

export default function PivotSheet({ transactions, isEmbedded = false }: PivotSheetProps) {
  const currentWorkspace = useAuthStore(s => s.getCurrentWorkspace());
  const accounts = useLedgerStore(s => s.accounts);
  const activeDimensions = useMemo(() => {
    const custom = currentWorkspace?.dimensions || DEFAULT_WORKSPACE_DIMENSIONS;
    const baseIds = custom.map(d => ({ id: d.id, name: d.name }));
    return [
      ...baseIds,
      { id: 'month', name: 'Month' },
      { id: 'payee', name: 'Payee' }
    ];
  }, [currentWorkspace]);

  const [pivotMode, setPivotMode] = useState<PivotMode>('flat');
  const [rowDim, setRowDim] = useState<GroupBy>('category');
  const [colDim, setColDim] = useState<GroupBy>('month');
  const [groupBy, setGroupBy] = useState<GroupBy>('category');
  const [searchTerm, setSearchTerm] = useState('');
  const [period, setPeriod] = useState<PeriodFilter>('all');
  const [customStartDate, setCustomStartDate] = useState('');
  const [customEndDate, setCustomEndDate] = useState('');
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());
  const [drillDownTarget, setDrillDownTarget] = useState<{ title: string; transactions: Transaction[] } | null>(null);

  const toggleGroup = (groupId: string) => {
    const newExpanded = new Set(expandedGroups);
    if (newExpanded.has(groupId)) {
      newExpanded.delete(groupId);
    } else {
      newExpanded.add(groupId);
    }
    setExpandedGroups(newExpanded);
  };

  // Compute active date boundaries
  const { startDate, endDate } = useMemo(() => {
    const now = new Date();
    const y = now.getFullYear();
    const m = now.getMonth();

    if (period === 'this_year') {
      return { startDate: `${y}-01-01`, endDate: `${y}-12-31` };
    }
    if (period === 'last_year') {
      return { startDate: `${y - 1}-01-01`, endDate: `${y - 1}-12-31` };
    }
    if (period === 'this_month') {
      const lastDay = new Date(y, m + 1, 0).getDate();
      return { 
        startDate: `${y}-${String(m + 1).padStart(2, '0')}-01`, 
        endDate: `${y}-${String(m + 1).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}` 
      };
    }
    if (period === 'this_quarter') {
      const qStartMonth = Math.floor(m / 3) * 3;
      const qEndMonth = qStartMonth + 2;
      const lastDay = new Date(y, qEndMonth + 1, 0).getDate();
      return {
        startDate: `${y}-${String(qStartMonth + 1).padStart(2, '0')}-01`,
        endDate: `${y}-${String(qEndMonth + 1).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`
      };
    }
    if (period === 'custom') {
      return { startDate: customStartDate, endDate: customEndDate };
    }
    return { startDate: '', endDate: '' };
  }, [period, customStartDate, customEndDate]);

  // Scoped & Postable transactions
  const scopedTransactions = useMemo(() => {
    return transactions.filter(t => {
      if (!isPostable(t)) return false;
      if (startDate && t.date < startDate) return false;
      if (endDate && t.date > endDate) return false;
      return true;
    });
  }, [transactions, startDate, endDate]);

  // Helper code to map a Transaction/Line to a group key representation
  const getLineDimensionValue = (t: Transaction, line: any, dim: GroupBy): string => {
    if (dim === 'payee') {
      return t.payee || t.description || 'Direct Entry';
    }
    if (dim === 'month') {
      if (!t.date) return 'Unknown Date';
      return t.date.substring(0, 7); // ISO YYYY-MM
    }
    if (dim === 'account' || dim === 'accountId') {
      return resolveAccountName(accounts, line?.accountId, line?.accountName) || 'Unassigned';
    }

    const lineVal = line ? getLineDimension(line, t, dim) : 'Unassigned';
    return lineVal || 'Unassigned';
  };

  const formatDimensionDisplay = (dim: GroupBy, key: string): string => {
    if (dim === 'month' && /^\d{4}-\d{2}$/.test(key)) {
      const [year, month] = key.split('-');
      const d = new Date(Number(year), Number(month) - 1, 1);
      return d.toLocaleString('default', { month: 'short', year: 'numeric' });
    }
    return key;
  };

  // 1. FLAT MODE COMPILATION (Line-accurate Aggregation)
  const groupedData = useMemo(() => {
    const groups: Record<string, { total: number, items: Transaction[], lineCount: number }> = {};
    const seenTxInGroup: Record<string, Set<string>> = {};

    scopedTransactions.forEach(t => {
      const txRate = t.exchangeRate || 1;
      const linesToProcess = (t.lines && t.lines.length > 0) 
        ? t.lines 
        : [{ accountId: '', accountName: '', amountCents: t.totalAmountCents, description: t.description }];

      linesToProcess.forEach(line => {
        const key = getLineDimensionValue(t, line, groupBy);

        if (searchTerm && 
            !key.toLowerCase().includes(searchTerm.toLowerCase()) && 
            !t.description.toLowerCase().includes(searchTerm.toLowerCase()) &&
            !(t.payee || '').toLowerCase().includes(searchTerm.toLowerCase())) {
          return;
        }

        const convertedCents = Math.round((line.amountCents || 0) * txRate);

        if (!groups[key]) {
          groups[key] = { total: 0, items: [], lineCount: 0 };
          seenTxInGroup[key] = new Set();
        }
        groups[key].total += convertedCents;
        groups[key].lineCount += 1;

        if (!seenTxInGroup[key].has(t.id)) {
          seenTxInGroup[key].add(t.id);
          groups[key].items.push(t);
        }
      });
    });

    return Object.entries(groups).sort((a, b) => Math.abs(b[1].total) - Math.abs(a[1].total));
  }, [scopedTransactions, groupBy, searchTerm, accounts]);

  // 2. CROSS-TAB MATRIX MODE COMPILATION
  const matrixData = useMemo(() => {
    if (pivotMode !== 'matrix') {
      return { rows: [], cols: [], cells: {}, cellItems: {}, rowTotals: {}, rowItems: {}, colTotals: {}, colItems: {}, allItems: [], grandTotal: 0 };
    }

    const cells: Record<string, Record<string, number>> = {};
    const cellItems: Record<string, Record<string, Transaction[]>> = {};
    const seenCellTxs: Record<string, Record<string, Set<string>>> = {};
    const rowTotals: Record<string, number> = {};
    const rowItems: Record<string, Transaction[]> = {};
    const seenRowTxs: Record<string, Set<string>> = {};
    const colTotals: Record<string, number> = {};
    const colItems: Record<string, Transaction[]> = {};
    const seenColTxs: Record<string, Set<string>> = {};
    const allItems: Transaction[] = [];
    const seenAllTxs = new Set<string>();
    let grandTotal = 0;

    const rowKeys = new Set<string>();
    const colKeys = new Set<string>();

    scopedTransactions.forEach(t => {
      const txRate = t.exchangeRate || 1;
      const linesToProcess = (t.lines && t.lines.length > 0) 
        ? t.lines 
        : [{ accountId: '', accountName: '', amountCents: t.totalAmountCents, description: t.description }];

      linesToProcess.forEach(line => {
        const rKey = getLineDimensionValue(t, line, rowDim);
        const cKey = getLineDimensionValue(t, line, colDim);

        if (searchTerm && 
            !rKey.toLowerCase().includes(searchTerm.toLowerCase()) && 
            !cKey.toLowerCase().includes(searchTerm.toLowerCase()) &&
            !t.description.toLowerCase().includes(searchTerm.toLowerCase())) {
          return;
        }

        rowKeys.add(rKey);
        colKeys.add(cKey);

        const convertedCents = Math.round((line.amountCents || 0) * txRate);

        if (!cells[rKey]) cells[rKey] = {};
        if (!cells[rKey][cKey]) cells[rKey][cKey] = 0;
        cells[rKey][cKey] += convertedCents;

        if (!cellItems[rKey]) cellItems[rKey] = {};
        if (!cellItems[rKey][cKey]) cellItems[rKey][cKey] = [];
        if (!seenCellTxs[rKey]) seenCellTxs[rKey] = {};
        if (!seenCellTxs[rKey][cKey]) seenCellTxs[rKey][cKey] = new Set();
        if (!seenCellTxs[rKey][cKey].has(t.id)) {
          seenCellTxs[rKey][cKey].add(t.id);
          cellItems[rKey][cKey].push(t);
        }

        rowTotals[rKey] = (rowTotals[rKey] || 0) + convertedCents;
        if (!rowItems[rKey]) rowItems[rKey] = [];
        if (!seenRowTxs[rKey]) seenRowTxs[rKey] = new Set();
        if (!seenRowTxs[rKey].has(t.id)) {
          seenRowTxs[rKey].add(t.id);
          rowItems[rKey].push(t);
        }

        colTotals[cKey] = (colTotals[cKey] || 0) + convertedCents;
        if (!colItems[cKey]) colItems[cKey] = [];
        if (!seenColTxs[cKey]) seenColTxs[cKey] = new Set();
        if (!seenColTxs[cKey].has(t.id)) {
          seenColTxs[cKey].add(t.id);
          colItems[cKey].push(t);
        }

        if (!seenAllTxs.has(t.id)) {
          seenAllTxs.add(t.id);
          allItems.push(t);
        }
        grandTotal += convertedCents;
      });
    });

    const sortedRows = Array.from(rowKeys).sort((a, b) => Math.abs(rowTotals[b] || 0) - Math.abs(rowTotals[a] || 0));

    // Alphanumeric ISO sort (e.g. YYYY-MM is chronological in every locale)
    const sortedCols = Array.from(colKeys).sort((a, b) => a.localeCompare(b));

    return {
      rows: sortedRows,
      cols: sortedCols,
      cells,
      cellItems,
      rowTotals,
      rowItems,
      colTotals,
      colItems,
      allItems,
      grandTotal
    };

  }, [scopedTransactions, pivotMode, rowDim, colDim, searchTerm, accounts]);

  return (
    <div className={cn(
      "flex flex-col h-full bg-[var(--surface)] animate-fadeIn text-left",
      isEmbedded ? "p-0 border-0 shadow-none rounded-[32px]" : "border border-[var(--line)] rounded-[32px] overflow-hidden shadow-2xl"
    )}>
      {/* Spreadsheet Controller Topbar */}
      <div className="border-b border-[var(--line)] bg-[var(--ink)]/70 p-5 space-y-4">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
             <div className="p-2 bg-slate-900 text-white rounded-xl">
                <TableIcon size={16} />
             </div>
             <div>
                <h3 className="text-sm font-bold text-[var(--text)] uppercase tracking-tight leading-none">Spreadsheet Pivot Matrix</h3>
                <p className="text-[9.5px] text-slate-400 font-mono tracking-tight mt-1">Cross-tabulation & Dimension Aggregator</p>
             </div>
          </div>

          <div className="flex flex-wrap items-center gap-3">
              {/* Period Filter */}
              <div className="flex items-center gap-1.5 bg-[var(--panel)] border border-[var(--line)] rounded-xl px-2 py-1">
                 <Calendar size={12} className="text-slate-400" />
                 <select
                   aria-label="Filter period"
                   value={period}
                   onChange={(e) => setPeriod(e.target.value as PeriodFilter)}
                   className="bg-transparent text-[9.5px] font-bold uppercase tracking-wider text-[var(--text)] outline-none cursor-pointer"
                 >
                   <option value="all">All Dates</option>
                   <option value="this_year">This Year</option>
                   <option value="last_year">Last Year</option>
                   <option value="this_quarter">This Quarter</option>
                   <option value="this_month">This Month</option>
                   <option value="custom">Custom Range</option>
                 </select>
                 {period === 'custom' && (
                   <div className="flex items-center gap-1 ml-1 border-l border-[var(--line)] pl-1.5">
                     <input
                       type="date"
                       aria-label="Start date"
                       value={customStartDate}
                       onChange={(e) => setCustomStartDate(e.target.value)}
                       className="bg-[var(--surface)] border border-[var(--line)] rounded px-1.5 py-0.5 text-[9px] font-mono outline-none"
                     />
                     <span className="text-[9px] text-slate-400">to</span>
                     <input
                       type="date"
                       aria-label="End date"
                       value={customEndDate}
                       onChange={(e) => setCustomEndDate(e.target.value)}
                       className="bg-[var(--surface)] border border-[var(--line)] rounded px-1.5 py-0.5 text-[9px] font-mono outline-none"
                     />
                   </div>
                 )}
              </div>

              {/* Mode Selector */}
              <div className="flex p-0.5 bg-[var(--panel)] border border-[var(--line)] rounded-xl shrink-0">
                 <button
                   type="button"
                   onClick={() => setPivotMode('flat')}
                   className={cn(
                     "flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[9.5px] font-bold uppercase tracking-wider transition-all cursor-pointer",
                     pivotMode === 'flat' ? "bg-[var(--brass)] text-black shadow-3xs" : "text-[var(--muted)] hover:text-[var(--text)]"
                   )}
                 >
                   <ListCollapse size={11} />
                   <span>Flat View</span>
                 </button>
                 <button
                   type="button"
                   onClick={() => setPivotMode('matrix')}
                   className={cn(
                     "flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[9.5px] font-bold uppercase tracking-wider transition-all cursor-pointer",
                     pivotMode === 'matrix' ? "bg-[var(--brass)] text-black shadow-3xs" : "text-[var(--muted)] hover:text-[var(--text)]"
                   )}
                 >
                   <Grid3X3 size={11} />
                   <span>Cross-Tab Matrix</span>
                 </button>
              </div>

              {/* Export Data Button */}
              <button 
                type="button"
                onClick={() => {
                  if (scopedTransactions.length === 0) {
                    toast.error("No transactions to export in this scope.");
                    return;
                  }
                  const headers = ['Date', 'Transaction ID', 'Description', 'Payee', 'Account', 'Amount (USD)'];
                  const rows = scopedTransactions.flatMap(t => {
                    const lines = (t.lines && t.lines.length > 0) 
                      ? t.lines 
                      : [{ accountId: '', accountName: '', amountCents: t.totalAmountCents }];
                    return lines.map(l => [
                      t.date,
                      t.id,
                      `"${t.description.replace(/"/g, '""')}"`,
                      `"${(t.payee || '').replace(/"/g, '""')}"`,
                      `"${resolveAccountName(accounts, l.accountId, l.accountName).replace(/"/g, '""')}"`,
                      formatDecimal(Math.round((l.amountCents || 0) * (t.exchangeRate || 1)))
                    ]);
                  });
                  const csvString = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
                  const blob = new Blob([csvString], { type: 'text/csv;charset=utf-8;' });
                  const url = URL.createObjectURL(blob);
                  const link = document.createElement('a');
                  link.href = url;
                  link.download = `pivot_export_${new Date().toISOString().split('T')[0]}.csv`;
                  link.click();
                  URL.revokeObjectURL(url);
                }}
