      ['', '', '', ''],
      [labels.netLabel.toUpperCase(), (data.netIncome || 0) / 100, isComp ? (prevData?.netIncome || 0) / 100 : '', '']
    ];

    const ws = XLSX.utils.aoa_to_sheet(rows);
