  const projectProfitability = React.useMemo(() => {
    const projectData: Record<string, { income: number, expense: number, net: number, name: string, transactionsCount: number }> = {};

    transactions.forEach(t => {
      if (!isPostable(t)) return;

      t.lines?.forEach(l => {
        const pId = l.project || t.projectId || 'General Topology';
        if (!projectData[pId]) {
          projectData[pId] = { income: 0, expense: 0, net: 0, name: pId, transactionsCount: 0 };
        }
        const amt = lineAmount(l, t);
        const accName = (l.accountName || '').toLowerCase();
        const catName = (typeof l.category === 'string' ? l.category : '').toLowerCase();

        const isRev = accName.includes('income') || accName.includes('revenue') || catName.includes('revenue') || catName.includes('income');
        const isExp = accName.includes('expense') || accName.includes('cost') || accName.includes('cogs') || catName.includes('expense') || catName.includes('cost');

        if (isRev) {
          const incomeDelta = -amt; // Revenue is credit normal
          projectData[pId].income += incomeDelta;
          projectData[pId].net += incomeDelta;
          projectData[pId].transactionsCount += 1;
        } else if (isExp) {
          const expDelta = amt; // Expense is debit normal
          projectData[pId].expense += expDelta;
          projectData[pId].net -= expDelta;
          projectData[pId].transactionsCount += 1;
        }
      });
    });

    let results = Object.values(projectData).sort((a, b) => b.net - a.net);
    if (filterMode === 'high-yield') {
      results = results.filter(r => r.income > 0 && r.net / r.income > 0.4);
    } else if (filterMode === 'loss') {
      results = results.filter(r => r.net < 0);
    }

    return results;
  }, [transactions, filterMode]);

  const totalIncome = projectProfitability.reduce((sum, p) => sum + p.income, 0);
  const totalExpense = projectProfitability.reduce((sum, p) => sum + p.expense, 0);
  const totalNet = totalIncome - totalExpense;

  const chartData = projectProfitability.map(p => ({
    name: p.name.length > 15 ? p.name.substring(0, 15) + '...' : p.name,
    income: p.income / 100,
    expense: p.expense / 100,
    net: p.net / 100,
    margin: p.income > 0 ? (p.net / p.income) * 100 : 0
  })).slice(0, showAllChart ? undefined : 10);

  return (
    <div className="space-y-8 pb-20">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div>
           <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.4em] mb-2 block">Project Matrix</span>
           <h2 className="text-3xl md:text-5xl font-black text-[var(--text)] uppercase italic tracking-tighter leading-none">Profitability Engine</h2>
        </div>
        <div className="flex items-center gap-3">
           {['all', 'high-yield', 'loss'].map((mode) => (
             <button
               key={mode}
               onClick={() => setFilterMode(mode as any)}
               className={cn(
                 "px-6 py-2.5 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all",
                 filterMode === mode ? "bg-slate-900 text-white shadow-lg" : "bg-[var(--surface)] text-slate-500 hover:bg-[var(--ink)] border border-[var(--line)]"
               )}
             >
               {mode.replace('-', ' ')}
             </button>
           ))}
        </div>
      </div>

      {/* KPI Row */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
         {[
           { label: 'Total Global Income', val: formatCurrency(totalIncome), color: 'text-indigo-600', icon: TrendingUp },
           { label: 'Total Energy Expense', val: formatCurrency(totalExpense), color: 'text-rose-500', icon: Zap },
           { label: 'Net System Amount', val: formatCurrency(totalNet), color: 'text-emerald-500', icon: Activity },
           { label: 'Overall Margin Resonance', val: totalIncome > 0 ? `${((totalNet / totalIncome) * 100).toFixed(1)}%` : '0%', color: 'text-purple-500', icon: BrainCircuit },
         ].map((kpi, idx) => (
           <div key={idx} className="bg-[var(--surface)] p-6 rounded-[32px] border border-[var(--line)] shadow-sm relative overflow-hidden group hover:border-slate-300 transition-all">
             <div className="absolute top-0 right-0 p-6 opacity-10 group-hover:opacity-20 transition-opacity">
                <kpi.icon size={48} className={kpi.color} />
             </div>
             <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-2">{kpi.label}</p>
             <h3 className={cn("text-3xl font-mono font-light tracking-tight", kpi.color)}>{kpi.val}</h3>
           </div>
         ))}
      </div>

      {/* Advanced Charting */}
      {chartData.length > 0 && (
        <div className="bg-[var(--surface)] p-8 rounded-[32px] border border-[var(--line)] shadow-sm">
           <div className="flex justify-between items-center mb-8">
             <div>
                <h3 className="text-sm font-black text-[var(--text)] uppercase tracking-widest">{showAllChart ? 'All Projects Vector Analysis' : 'Top 10 Vector Analysis'}</h3>
                <p className="text-[10px] font-medium text-slate-500 uppercase tracking-widest mt-1">Income vs Expense vs Net Margin</p>
             </div>
             <div className="flex items-center gap-2">
               {projectProfitability.length > 10 && (
                 <button 
                   onClick={() => setShowAllChart(!showAllChart)}
                   className="px-4 py-2 text-[10px] font-bold uppercase tracking-widest rounded-xl bg-[var(--ink)] hover:bg-slate-200 border border-[var(--line)] transition-all cursor-pointer text-[var(--text)]"
                 >
                   {showAllChart ? 'Show Top 10' : `Show All (${projectProfitability.length})`}
                 </button>
               )}
               <button className="w-10 h-10 flex items-center justify-center rounded-full bg-[var(--ink)] text-slate-500 hover:bg-slate-100 transition-all" aria-label="Maximize2 action">
                  <Maximize2 size={16} />
               </button>
             </div>
           </div>

           <div className="h-[400px] w-full">
             <ResponsiveContainer width="100%" height="100%">
               <ComposedChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
                 <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                 <XAxis 
                   dataKey="name" 
                   axisLine={false}
                   tickLine={false}
                   tick={{ fontSize: 10, fill: '#64748b', fontWeight: 600 }}
                   dy={10}
                 />
                 <YAxis 
                   yAxisId="left"
                   axisLine={false}
                   tickLine={false}
                   tick={{ fontSize: 10, fill: '#64748b', fontFamily: 'monospace' }}
                   tickFormatter={(value) => `$${value.toLocaleString()}`}
                 />
                 <YAxis 
                   yAxisId="right"
                   orientation="right"
                   axisLine={false}
                   tickLine={false}
                   tick={{ fontSize: 10, fill: '#64748b', fontFamily: 'monospace' }}
                   tickFormatter={(value) => `${value}%`}
                 />
                 <Tooltip 
                   cursor={{ fill: '#f8fafc' }}
                   contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 25px rgba(0,0,0,0.1)', padding: '16px' }}
                   itemStyle={{ fontSize: '12px', fontWeight: 600, fontFamily: 'monospace' }}
                   labelStyle={{ fontSize: '10px', fontWeight: 900, textTransform: 'uppercase', letterSpacing: '2px', color: '#0f172a', marginBottom: '8px' }}
                   formatter={(value: number, name: string) => [
                     name === 'margin' ? `${value.toFixed(1)}%` : `$${value.toLocaleString()}`, 
                     name.toUpperCase()
                   ]}
                 />
                 <Legend wrapperStyle={{ fontSize: '10px', fontWeight: 600, textTransform: 'uppercase' }} />
                 <Bar yAxisId="left" dataKey="income" fill="#3b82f6" radius={[4, 4, 0, 0]} maxBarSize={40} name="Flux Income" />
                 <Bar yAxisId="left" dataKey="expense" fill="#ef4444" radius={[4, 4, 0, 0]} maxBarSize={40} name="Energy Expense" />
                 <Line yAxisId="right" type="monotone" dataKey="margin" stroke="#8b5cf6" strokeWidth={3} dot={{ r: 4, fill: '#8b5cf6', strokeWidth: 2, stroke: '#fff' }} name="Margin Resonance %" />
               </ComposedChart>
             </ResponsiveContainer>
           </div>
        </div>
      )}

      {/* Data Table */}
      <div className="bg-[var(--surface)] rounded-[32px] border border-[var(--line)] shadow-sm overflow-hidden">
        <div className="p-6 md:p-8 border-b border-[var(--line)] flex items-center justify-between bg-[var(--ink)]/50">
          <div>
            <h3 className="text-sm font-black text-[var(--text)] uppercase tracking-widest">Project Ledger Engine</h3>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-1">Real-time vector synchronization</p>
          </div>
          <button className="px-4 py-2 bg-[var(--surface)] border border-[var(--line)] rounded-xl text-[10px] font-bold uppercase tracking-widest text-slate-600 hover:bg-[var(--ink)] flex items-center gap-2 transition-all" aria-label="Export Node">
            <Download size={14} /> Export Node
          </button>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse min-w-[800px]">
            <thead>
              <tr className="bg-[var(--ink)]/80 border-b border-[var(--line)]">
                <th className="px-8 py-4 text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">Project Node</th>
                <th className="px-8 py-4 text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] text-right">Transactions</th>
                <th className="px-8 py-4 text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] text-right">Flux Income</th>
                <th className="px-8 py-4 text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] text-right">Energy Expense</th>
                <th className="px-8 py-4 text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] text-right">Net Amount</th>
                <th className="px-8 py-4 text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] text-right">Yield Resonance</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100/50">
              {projectProfitability.map((p, idx) => (
                <tr key={idx} className="hover:bg-[var(--ink)]/50 transition-all group">
                  <td className="px-8 py-5">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 bg-slate-100 rounded-[32px] border border-[var(--line)] flex items-center justify-center text-slate-500 group-hover:bg-slate-900 group-hover:text-white transition-all transform group-hover:rotate-6">
                        <Compass size={18} />
                      </div>
                      <div>
                        <span className="font-bold text-[var(--text)] tracking-tight">{p.name}</span>
                        <p className="text-[9px] font-mono text-slate-400 mt-1 uppercase tracking-widest">Active Node</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-right font-mono text-slate-600 font-bold text-xs">{p.transactionsCount}</td>
                  <td className="px-8 py-5 text-right font-mono text-indigo-600 font-bold text-sm">{formatCurrency(p.income)}</td>
                  <td className="px-8 py-5 text-right font-mono text-rose-500/80 font-bold text-sm">{formatCurrency(p.expense)}</td>
                  <td className="px-8 py-5 text-right font-mono font-black text-[var(--text)] text-sm">{formatCurrency(p.net)}</td>
                  <td className="px-8 py-5 text-right">
                    <span className={cn(
                      "px-3 py-1.5 rounded-xl text-[10px] font-bold uppercase tracking-widest shadow-sm border",
                      p.income > 0 ? (p.net / p.income > 0.3 ? "bg-slate-900/10 text-indigo-600 border-indigo-600/20" : "bg-orange-500/10 text-orange-600 border-orange-500/20") : "bg-slate-100 text-slate-500 border-[var(--line)]"
                    )}>
                      {p.income > 0 ? `${((p.net / p.income) * 100).toFixed(1)}%` : '0%'}
                    </span>
                  </td>
                </tr>
              ))}
              {projectProfitability.length === 0 && (
                <tr>
                   <td colSpan={6} className="px-8 py-16 text-center">
                     <div className="flex flex-col items-center justify-center text-slate-400">
                        <Filter size={32} className="mb-4 opacity-50" />
                        <p className="text-sm font-bold uppercase tracking-widest">No Projects Match Filter</p>
                     </div>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import { useLedgerStore } from '../../stores/useLedgerStore';
import { useAuthStore } from '../../stores/useAuthStore';
import { useTransactionActions } from '../../hooks/useTransactionActions';
import React, { useState, useMemo, useEffect } from 'react';
import { 
  ArrowLeftRight, 
  Sparkles, 
  Search, 
  AlertCircle, 
  ArrowRight,
  ShieldCheck,
  Zap,
  RefreshCw,
  Link as LinkIcon,
  X,
  Check,
  Loader2,
  Lock,
  History,
  Info,
  Layers,
  Maximize2
} from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';
import { parseLocalDate, cn, formatCurrency, resolveAccountName } from '../../lib/utils';
import { resolveAccountRole } from '../../lib/accountUtils';
import { Transaction, BankStatementLine, ChartAccount, User } from '../../types';
import { format } from 'date-fns';
import { 
  jaroWinklerSimilarity, 
  findGlobalOptimalMatch 
} from '../../lib/algorithms';
import { toast } from 'sonner';
import { isPostable } from '../../lib/txFilters';



import AsyncButton from '../ui/AsyncButton';

export default function Reconciliation() {
  const user = useAuthStore((s: any) => s.user);
  const workspaceId = useAuthStore((s: any) => s.currentWorkspaceId);
  const transactions = useLedgerStore((s: any) => s.transactions);
  const bankLines = useLedgerStore((s: any) => s.bankLines || []);
  const accounts = useLedgerStore((s: any) => s.accounts);
  const txActions = useTransactionActions();
  const onMatch = txActions.handleReconcileMatch;
  const onIgnore = txActions.handleReconcileIgnore;
  const onAddFromBank = txActions.handleReconcileCreate;
  const onAutoReconcile = txActions.handleAutoReconcile;
  const onUndoMatch = txActions.handleReconcileUndo;
  const [selectedBankId, setSelectedBankId] = useState<string | null>(null);
  const [selectedLedgerId, setSelectedLedgerId] = useState<string | null>(null);
  const [showAutoConfirm, setShowAutoConfirm] = useState(false);
  const [matchToleranceCents, setMatchToleranceCents] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAutoReconciling, setIsAutoReconciling] = useState(false);

  // Tab view: pending matching streams vs synchronized matched history logs
  const [viewMode, setViewMode] = useState<'pending' | 'history'>('pending');

  // Custom filter states
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedAccountId, setSelectedAccountId] = useState<string>('all');

  // Granular checkable state for the smart auto-alignment bulk modal
  const [selectedBatchIds, setSelectedBatchIds] = useState<Record<string, boolean>>({});

  const safeBankLines = Array.isArray(bankLines) ? bankLines : [];
  const safeTransactions = Array.isArray(transactions) ? transactions : [];
  const safeAccounts = Array.isArray(accounts) ? accounts : [];

  const cashAccounts = useMemo(() => safeAccounts.filter(a => resolveAccountRole(a) === 'cash'), [safeAccounts]);

  // Active pending statement lines
  const unmatchedBankLines = useMemo(() => {
    return safeBankLines.filter(line => line.status === 'pending' && (selectedAccountId === 'all' || !line.accountId || line.accountId === selectedAccountId));
  }, [safeBankLines, selectedAccountId]);

  // Synchronized matched statement lines (History)
  const matchedBankLines = useMemo(() => {
    return safeBankLines.filter(line => line.status === 'matched' && (selectedAccountId === 'all' || !line.accountId || line.accountId === selectedAccountId));
  }, [safeBankLines, selectedAccountId]);

  // Uncleared internal ledger transactions (excluding void and reconciled)
  const unclearedLedgerTransactions = useMemo(() => {
    return safeTransactions.filter(tx => {
      if (!isPostable(tx) || tx.status === 'reconciled') return false;
      if (selectedAccountId !== 'all') {
        const touchesAccount = tx.lines?.some((l: any) => l.accountId === selectedAccountId);
        if (!touchesAccount) return false;
      }
      return true;
    });
  }, [safeTransactions, selectedAccountId]);

  // AI/Heuristic dynamic suggestion index maps
  const aiSuggestionsMap = useMemo(() => {
    if (unmatchedBankLines.length === 0 || unclearedLedgerTransactions.length === 0) return [];

    const sourceItems = unmatchedBankLines.map(btx => {
      const scoreMap = new Map<string, number>();

      unclearedLedgerTransactions.forEach(ltx => {
        // Sign direction validation for cash account movement
        const cashLines = ltx.lines?.filter((l: any) => {
          const acc = safeAccounts.find(a => a.id === l.accountId);
          return acc && resolveAccountRole(acc) === 'cash';
        }) || [];
        const cashDelta = cashLines.reduce((s: number, l: any) => s + l.amountCents, 0);

        // Disallow matching positive bank deposits with negative cash outflows and vice versa
        if (cashDelta !== 0 && Math.sign(cashDelta) !== Math.sign(btx.amountCents)) {
          return;
        }

        let score = 0;

        // Exact Amount Match (High Weight)
        if (Math.abs(ltx.totalAmountCents) === Math.abs(btx.amountCents)) {
          score += 100;
        } else if (Math.abs(Math.abs(ltx.totalAmountCents) - Math.abs(btx.amountCents)) <= matchToleranceCents) {
          score += 30; // Near match / tiny difference
        }

        // Description Similarity (Jaro-Winkler)
        const descSimilarity = jaroWinklerSimilarity(btx.description, ltx.description, user?.uid);
        score += descSimilarity * 65;

        // Date Proximity
        const bDate = parseLocalDate(btx.date).getTime();
        const lDate = parseLocalDate(ltx.date).getTime();
        if (!isNaN(bDate) && !isNaN(lDate)) {
          const dayDiff = Math.abs(bDate - lDate) / (1000 * 60 * 60 * 24);
          if (dayDiff === 0) score += 30;
          else if (dayDiff <= 3) score += 18;
          else if (dayDiff <= 7) score += 8;
        }

        // Require similarity > 0.3 or dateDiff <= 2 to prevent pure amount-only false positives
        const bDateMs = parseLocalDate(btx.date).getTime();
        const lDateMs = parseLocalDate(ltx.date).getTime();
        const dDiff = (!isNaN(bDateMs) && !isNaN(lDateMs)) ? Math.abs(bDateMs - lDateMs) / (1000 * 60 * 60 * 24) : 99;

        if (score > 115 && (descSimilarity >= 0.3 || dDiff <= 2)) { // Threshold for considering it a strong match candidate
          scoreMap.set(ltx.id, score);
        }
      });

      return { id: btx.id, scoreMap };
    });

    return sourceItems;
  }, [unmatchedBankLines, unclearedLedgerTransactions, user?.uid, matchToleranceCents, safeAccounts]);

  const optimizedMatches = useMemo(() => {
     if (!aiSuggestionsMap || !Array.isArray(aiSuggestionsMap)) return new Map();

     const relevantTargets = new Set<string>();
     aiSuggestionsMap.forEach(item => {
        for (const key of item.scoreMap.keys()) relevantTargets.add(key);
     });

     return findGlobalOptimalMatch(aiSuggestionsMap, Array.from(relevantTargets));
  }, [aiSuggestionsMap]);

  // Initialize checkboxes for smart bulk matching modal when it opens
  useEffect(() => {
    if (showAutoConfirm) {
      const state: Record<string, boolean> = {};
      unmatchedBankLines.forEach(btx => {
        if (optimizedMatches.get(btx.id)) {
          state[btx.id] = true;
        }
      });
      setTimeout(() => setSelectedBatchIds(state), 0);
    }
  }, [showAutoConfirm, unmatchedBankLines, optimizedMatches]);

  // Execute confirmation for selected batch elements
  const executeSelectedBatchMatches = async () => {
    setIsProcessing(true);
    let matchedCount = 0;

    // Filter only those selected by checkboxes
    const pairsToMatch = unmatchedBankLines.map(btx => {
        const ltxId = optimizedMatches.get(btx.id);
        const isChecked = selectedBatchIds[btx.id];
        return { bankId: btx.id, ledgerId: ltxId, isChecked };
    }).filter(p => p.ledgerId && p.isChecked);

    if (pairsToMatch.length === 0) {
        toast.info("No alignment nodes selected for integration.");
        setIsProcessing(false);
        return;
    }

    try {
        for (const pair of pairsToMatch) {
           await onMatch(pair.bankId, pair.ledgerId!);
           matchedCount++;
        }
        toast.success(`Synapses Active: Successfully integrated ${matchedCount} verified bonds.`);
        setShowAutoConfirm(false);
    } catch(err:any) {
        toast.error("Could not complete reconciliation cycle.", {
          description: `Please try again. (${err?.message || 'Network sync error'})`
        });
    } finally {
        setIsProcessing(false);
    }
  };

  const handleAutoReconcile = async () => {
    setIsAutoReconciling(true);
    try {
       await onAutoReconcile();
       toast.success("Autonomous batch matching complete!");
    } catch (e: any) {
        toast.error("Could not complete batch alignment.", {
          description: `Please try again. (${e?.message || 'Network sync error'})`
        });
    } finally {
       setIsAutoReconciling(false);
    }
  };

  // Revert / Undo a confirmed reconciliation link
  const handleUndoAlignment = async (bankLineId: string, matchedTxId?: string) => {
    if (!onUndoMatch) {
      toast.error("Reversion interface not enabled on this workspace container.");
      return;
    }

    setIsProcessing(true);
    try {
      await onUndoMatch(bankLineId, matchedTxId);
    } catch (e: any) {
      toast.error("Failed to break alignment link: " + e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const selectedBankLine = useMemo(() => {
    if (viewMode === 'pending') {
      return unmatchedBankLines.find(b => b.id === selectedBankId);
    } else {
      return matchedBankLines.find(b => b.id === selectedBankId);
    }
  }, [unmatchedBankLines, matchedBankLines, selectedBankId, viewMode]);

  const selectedLedgerTx = useMemo(() => {
    if (viewMode === 'pending') {
      return unclearedLedgerTransactions.find(l => l.id === selectedLedgerId);
    } else {
      const matchTxId = selectedBankLine?.matchedTransactionId;
      return safeTransactions.find(tx => tx.id === matchTxId);
    }
  }, [unclearedLedgerTransactions, safeTransactions, selectedLedgerId, selectedBankLine, viewMode]);

  // DUAL-VERIFIER ALIGNMENT MATRIX METRICS
  const checkSimilarity = useMemo(() => {
    if (!selectedBankLine || !selectedLedgerTx) return { textScore: 0, dateDiff: 0, amountDiff: 0, overall: 0 };

    // Description similarity
    const textScore = Math.round(jaroWinklerSimilarity(selectedBankLine.description, selectedLedgerTx.description, user?.uid) * 100);

    // Date Difference
    const bDate = parseLocalDate(selectedBankLine.date).getTime();
    const lDate = parseLocalDate(selectedLedgerTx.date).getTime();
    let dateDiff = 99;
    if (!isNaN(bDate) && !isNaN(lDate)) {
      dateDiff = Math.abs(bDate - lDate) / (1000 * 60 * 60 * 24);
    }

    // Amount difference
    const amountDiff = Math.abs(selectedBankLine.amountCents) - Math.abs(selectedLedgerTx.totalAmountCents);

    // Compute heuristic overall probability
    let overall = 0;
    if (amountDiff === 0) overall += 50;
    else if (Math.abs(amountDiff) < 100) overall += 25; // negligible difference

    overall += Math.max(0, 40 - (dateDiff * 8)); // Date penalty
    overall += (textScore * 0.1); // text likeness

    return {
      textScore,
      dateDiff,
      amountDiff,
      overall: Math.min(100, Math.round(overall))
    };
  }, [selectedBankLine, selectedLedgerTx, user?.uid]);

  // Filter pending feeds
  const filteredBankFeed = useMemo(() => {
    const list = viewMode === 'pending' ? unmatchedBankLines : matchedBankLines;
    if (!searchQuery) return list;
    return list.filter(b => 
      b.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      b.amountCents.toString().includes(searchQuery)
    );
  }, [unmatchedBankLines, matchedBankLines, searchQuery, viewMode]);

  const filteredLedgerEntries = useMemo(() => {
    if (!searchQuery) return unclearedLedgerTransactions;
    return unclearedLedgerTransactions.filter(l => 
      l.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      l.totalAmountCents.toString().includes(searchQuery)
    );
  }, [unclearedLedgerTransactions, searchQuery]);

  return (
    <div className="flex flex-col h-full bg-[var(--surface)] overflow-hidden min-h-0 flex-1 rounded-2xl border border-[var(--line)] shadow-sm">

      {/* Workspace Header Dashboard */}
