                  onClick={() => { setSelectedBankId(null); setSelectedLedgerId(null); }}
                  className="px-6 py-3 text-[10px] font-black uppercase tracking-[0.2em] text-white/30 hover:text-white transition-colors cursor-pointer w-full sm:w-auto"
                >
                  Deselect Node Links
                </button>

                <div className="flex items-center gap-3 w-full sm:w-auto justify-end">
                  {viewMode === 'pending' ? (
                    <button 
                      onClick={() => {
                        onMatch(selectedBankId!, selectedLedgerId!);
                        setSelectedBankId(null);
                        setSelectedLedgerId(null);
                      }}
                      className="px-8 h-12 bg-emerald-600 text-white rounded-xl font-black text-[11px] uppercase tracking-[0.2em] flex items-center justify-center gap-3 hover:bg-emerald-500 transition-all cursor-pointer shadow-lg shadow-emerald-900/30 w-full sm:w-auto"
                    >
                      <ShieldCheck size={18} />
                      Assert Match Verification
                    </button>
                  ) : (
                    <AsyncButton 
                      onClick={() => handleUndoAlignment(selectedBankLine!.id, selectedBankLine!.matchedTransactionId)}
                      loadingText="Unbinding..."
                      className="px-8 h-12 bg-rose-600 text-white rounded-xl font-black text-[11px] uppercase tracking-[0.2em] flex items-center justify-center gap-3 hover:bg-rose-500 transition-all cursor-pointer shadow-lg shadow-rose-900/30 w-full sm:w-auto"
                    >
                      <X size={18} />
                      Unbind & Reopen Vector
                    </AsyncButton>
                  )}
                </div>
              </div>

            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {selectedBankId && !selectedLedgerId && viewMode === 'pending' && (
          <motion.div 
            initial={{ y: 50, opacity: 0, x: '-50%' }}
            animate={{ y: 0, opacity: 1, x: '-50%' }}
            exit={{ y: 50, opacity: 0, x: '-50%' }}
            className="fixed bottom-20 lg:bottom-10 left-1/2 -translate-x-1/2 w-full max-w-xl z-[80] px-4 md:px-6"
          >
            <div className="bg-zinc-950 text-white p-5 rounded-[32px] border border-white/10 shadow-3xl flex items-center justify-between gap-4">
               <div className="flex items-center gap-3 pl-2">
                  <span className="relative flex h-2.5 w-2.5">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-emerald-500"></span>
                  </span>
                  <span className="text-xs font-bold text-zinc-400">Select internal General Ledger node to match sequence</span>
               </div>
               <button 
                 onClick={async () => {
                     const statementItem = selectedBankLine;
                     if (statementItem) {
                       await onAddFromBank(statementItem);
                       setSelectedBankId(null);
                     }
                 }}
                 className="px-5 py-2.5 bg-[var(--surface)]/10 hover:bg-[var(--surface)]/20 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all cursor-pointer border border-white/10 hover:border-white/20 shadow-sm whitespace-nowrap"
               >
                 Synthesize Record
               </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* SMART BATCH VERIFICATION CHECKBOX MODAL */}
      <AnimatePresence>
         {showAutoConfirm && Array.from(optimizedMatches.values()).length > 0 && (
             <>
               <div role="button" tabIndex={0} className="fixed inset-0 bg-slate-900/50 backdrop-blur-md z-[150]" onClick={() => setShowAutoConfirm(false)} />
               <motion.div 
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.95 }}
                  className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full max-w-4xl z-[200] bg-[var(--surface)] rounded-[32px] p-6 md:p-8 shadow-[0_45px_110px_-15px_rgba(0,0,0,0.55)] border border-[var(--line)] overflow-hidden flex flex-col max-h-[85dvh]"
               >
                  <div className="flex flex-col md:flex-row items-start md:items-center justify-between border-b border-[var(--line)] pb-5 gap-4">
                    <div className="flex items-center gap-3">
                       <Zap size={24} className="text-amber-500 fill-amber-500" />
                       <div>
                         <h3 className="text-xl font-black uppercase tracking-tight text-[var(--text)]">
                            Cognitive Alignments Panel
                         </h3>
                         <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Select synapses to reconcile at once. Toggle individual checkboxes or apply bulk verification instantly.</p>
                       </div>
                    </div>
                    {/* Header check/uncheck shortcuts */}
                    <div className="flex items-center gap-2">
                      <button 
                        onClick={() => {
                          const state: Record<string, boolean> = {};
                          unmatchedBankLines.forEach(b => { if (optimizedMatches.get(b.id)) state[b.id] = true; });
                          setSelectedBatchIds(state);
                        }} 
                        className="text-[9px] font-black px-2.5 py-1.5 bg-slate-100 text-slate-600 hover:bg-slate-200 uppercase tracking-widest rounded-lg transition-all cursor-pointer"
                      >
                        Select All
                      </button>
                      <button 
                        onClick={() => setSelectedBatchIds({})} 
                        className="text-[9px] font-black px-2.5 py-1.5 bg-slate-100 text-slate-600 hover:bg-slate-200 uppercase tracking-widest rounded-lg transition-all cursor-pointer"
                      >
                        Deselect All
                      </button>
                    </div>
                  </div>

                  {/* Checklist matching pairs items list structure */}
                  <div className="py-5 overflow-y-auto custom-scrollbar flex-1 space-y-3.5 my-3">
                     {unmatchedBankLines.filter(tx => optimizedMatches.get(tx.id)).map(btx => {
                        const matchedLtxId = optimizedMatches.get(btx.id);
                        const matchedLtx = unclearedLedgerTransactions.find(t => t.id === matchedLtxId);
                        if (!matchedLtx) return null;

                        const isChecked = !!selectedBatchIds[btx.id];

                        return (
                           <div role="button" tabIndex={0} 
                             key={btx.id} 
                             onClick={() => setSelectedBatchIds(prev => ({ ...prev, [btx.id]: !prev[btx.id] }))}
                             className={cn(
                               "flex items-center gap-4 p-4 rounded-xl border transition-all cursor-pointer",
                               isChecked ? "border-emerald-200 bg-emerald-50/20" : "border-slate-150 bg-[var(--ink)]/50 opacity-60 hover:opacity-100 hover:border-slate-300"
                             )}
                           >
                              {/* Stateful Row Checkbox wrapper */}
                              <div className="shrink-0 flex items-center justify-center">
                                 <div className={cn(
                                   "w-5.5 h-5.5 rounded-lg border flex items-center justify-center transition-all",
                                   isChecked ? "bg-emerald-600 border-emerald-600 text-white" : "bg-[var(--surface)] border-slate-300"
                                 )}>
                                    {isChecked && <Check size={12} strokeWidth={3} />}
                                 </div>
                              </div>

                              <div className="flex-1 grid grid-cols-1 md:grid-cols-11 gap-4 items-center overflow-hidden">
                                {/* Bank Item info */}
                                <div className="md:col-span-5 overflow-hidden">
                                   <span className="text-[8px] uppercase tracking-widest font-black text-slate-400 block mb-0.5">Physical Inflow Node</span>
                                   <p className="font-bold text-[var(--text)] truncate text-sm">{btx.description}</p>
                                   <p className="text-[10px] font-semibold text-slate-500 font-mono mt-0.5">{btx.date} • {formatCurrency(btx.amountCents)}</p>
                                </div>

                                {/* Flow indicator status line */}
                                <div className="hidden md:flex justify-center text-emerald-500">
                                    <ArrowRight size={16} />
                                </div>

                                {/* Mapped registry internal record item info */}
                                <div className="md:col-span-5 overflow-hidden text-right">
                                   <span className="text-[8px] uppercase tracking-widest font-black text-slate-400 block mb-0.5">Assigned Target record</span>
                                   <p className="font-bold text-[var(--text)] truncate text-sm">{matchedLtx.description}</p>
                                   <p className="text-[10px] font-semibold text-slate-500 font-mono mt-0.5">{matchedLtx.date} • {formatCurrency(matchedLtx.totalAmountCents)}</p>
                                   {Math.abs(btx.amountCents) !== Math.abs(matchedLtx.totalAmountCents) && (
                                     <span className="text-[9px] text-amber-600 font-bold uppercase tracking-wider block mt-1 bg-amber-50/50 inline-block px-1.5 py-0.5 rounded border border-amber-200">
                                       Diff: {formatCurrency(Math.abs(Math.abs(btx.amountCents) - Math.abs(matchedLtx.totalAmountCents)))}
                                     </span>
                                   )}

                                </div>
                              </div>
                           </div>
                        );
                     })}
                  </div>

                  {/* Batch validation button stripe */}
                  <div className="border-t pt-5 flex items-center justify-between shrink-0">
                     <button onClick={() => setShowAutoConfirm(false)} className="px-6 py-3 font-bold text-xs uppercase tracking-widest text-slate-500 hover:text-[var(--text)] transition-colors cursor-pointer">
                        Dismiss alignments panel
                     </button>
                     <button 
                        onClick={executeSelectedBatchMatches} 
                        disabled={isProcessing} 
                        className="bg-emerald-600 hover:bg-emerald-500 cursor-pointer transition-all text-white px-8 h-12 rounded-xl font-black uppercase text-xs tracking-widest flex items-center gap-2.5 disabled:opacity-50"
                      aria-label="Apply Checked Synapses Now ( )">
                        {isProcessing ? <Loader2 size={16} className="animate-spin" /> : <ShieldCheck size={16} />} 
                        Apply Checked Synapses Now ({Object.values(selectedBatchIds).filter(Boolean).length})
                     </button>
                  </div>
               </motion.div>
             </>
         )}
      </AnimatePresence>
    </div>
  );
}

import { useLedgerStore } from '../../stores/useLedgerStore';
import { TruthEngine } from '../../modules/integrity/TruthEngine';
import React,
 { useState, useMemo } from 'react';
import { Transaction, ChartAccount } from '../../types';
import { motion, AnimatePresence } from 'motion/react';
import { 
  RefreshCw, 
  CheckCircle2, 
  AlertCircle,
  X,
  ChevronRight,
  ChevronLeft,
  Search,
  CheckSquare,
  Sparkles
} from 'lucide-react';
import { parseLocalDate, cn } from '../../lib/utils';
import { format } from 'date-fns';
import { toast } from 'sonner';

interface ReconciliationWizardProps {
  isOpen: boolean;
  onClose: () => void;
  accounts: ChartAccount[];
  onComplete: (data: any) => Promise<void> | void;
  formatCurrency: (val: number) => string;
}

export default function ReconciliationWizard({ isOpen, onClose, accounts, onComplete, formatCurrency }: ReconciliationWizardProps) {
  const transactions = useLedgerStore(state => state.transactions || []);
  const reconciliations = useLedgerStore(state => state.reconciliations || []);

  const [step, setStep] = useState(1);
  const [selectedAccount, setSelectedAccount] = useState<string>('');
  const [statementDate, setStatementDate] = useState(format(new Date(), 'yyyy-MM-dd'));
  const [endingBalance, setEndingBalance] = useState<string>('0');
  const [reconciledIds, setReconciledIds] = useState<string[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isFinalizing, setIsFinalizing] = useState(false);

  const account = useMemo(() => accounts.find(a => a.name === selectedAccount || a.id === selectedAccount), [accounts, selectedAccount]);

  const lastReconciliation = useMemo(() => {
    if (!account) return null;
    const list = (reconciliations || []).filter(r => r.accountId === account.id || r.accountName === account.name);
    list.sort((a, b) => (b.statementDate || '').localeCompare(a.statementDate || ''));
    return list[0] || null;
  }, [reconciliations, account]);

  const beginningBalance = useMemo(() => {
    if (lastReconciliation && typeof lastReconciliation.statementBalanceCents === 'number') {
      return lastReconciliation.statementBalanceCents;
    }
    return account?.openingBalanceCents || account?.balanceCents || 0;
  }, [lastReconciliation, account]);

  const safeParseCents = (val: string): number => {
    if (!val || !val.trim()) return 0;
    try {
      let clean = val.trim();
      if (clean.startsWith('(') && clean.endsWith(')')) {
        clean = '-' + clean.slice(1, -1);
      }
      clean = clean.replace(/[$,]/g, '');
      return TruthEngine.parseAmountToCents(clean || '0');
    } catch {
      return 0;
    }
  };

  const filteredTransactions = useMemo(() => {
    if (!selectedAccount || !account) return [];
    return (transactions || []).filter(t => 
      !t.deletedAt &&
      t.status !== 'reconciled' &&
      t.status !== 'void' &&
      !t.clearedAt &&
      t.date <= statementDate &&
      t.lines?.some(l => l.accountId === account.id || l.accountName === account.name) && 
      (t.description.toLowerCase().includes(searchTerm.toLowerCase()) || t.totalAmountCents.toString().includes(searchTerm))
    ).map(t => ({
      ...t,
      // For reconciliation, we care about the amount specifically for the selected account
      relevantAmountCents: t.lines?.find(l => l.accountId === account.id || l.accountName === account.name)?.amountCents || 0
    }));
  }, [selectedAccount, account, statementDate, searchTerm, transactions]);

  const stats = useMemo(() => {
    const cleared = filteredTransactions
      .filter(t => reconciledIds.includes(t.id))
      .reduce((sum, t) => sum + t.relevantAmountCents, 0);

    const targetBalance = safeParseCents(endingBalance);
    const currentBalance = beginningBalance + cleared;
    const difference = targetBalance - currentBalance;

    return { cleared, beginningBalance, targetBalance, currentBalance, difference };
  }, [filteredTransactions, reconciledIds, beginningBalance, endingBalance]);

  const handleToggle = (id: string) => {
    setReconciledIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleAutoMatch = () => {
    const targetAmountCents = safeParseCents(endingBalance);
    const needed = targetAmountCents - beginningBalance;

    // Greedy matching algorithm for exact amounts
    const matches: string[] = [];
    let matchedSum = 0;

    // Sort by amount to try and find combinations
    const sorted = [...filteredTransactions].sort((a, b) => Math.abs(b.relevantAmountCents) - Math.abs(a.relevantAmountCents));

    sorted.forEach(t => {
      if (Math.abs(matchedSum + t.relevantAmountCents - needed) < Math.abs(matchedSum - needed) || 
          Math.abs(matchedSum + t.relevantAmountCents) <= Math.abs(needed)) {
        matches.push(t.id);
        matchedSum += t.relevantAmountCents;
      }
    });

    setReconciledIds(matches);
    toast.success(`Auto-matched ${matches.length} transactions based on statement balance.`);
  };

  const handleFinalize = async () => {
    if (Math.abs(stats.difference) > 0.01) {
      toast.error('Difference must be zero to finalize reconciliation.');
      return;
    }

    setIsFinalizing(true);
    try {
      await onComplete({
        accountId: account?.id,
        accountName: selectedAccount,
        statementDate,
        statementBalanceCents: stats.targetBalance,
        reconciledIds,
        timestamp: new Date().toISOString()
      });
      onClose();
    } catch (err) {
      console.error('Finalization error:', err);
    } finally {
      setIsFinalizing(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[300] flex items-center justify-center p-4">
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        onClick={onClose}
        className="absolute inset-0 bg-zinc-900/60 backdrop-blur-md"
      />

      <motion.div
        initial={{ opacity: 0, scale: 0.95, y: 20 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.95, y: 20 }}
        className="relative w-full max-w-5xl bg-[var(--ink)] rounded-[40px] shadow-2xl border border-[var(--line)] overflow-hidden flex flex-col max-h-[90dvh]"
      >
        {/* Header */}
        <div className="p-4 md:p-10 border-b border-[var(--line)] flex items-center justify-between bg-[var(--ink)]/30">
          <div className="flex items-center gap-6">
            <div className="w-16 h-16 bg-indigo-600 text-white rounded-[32px] flex items-center justify-center border border-indigo-600/20 shadow-lg shadow-ledger-accent/10">
              <RefreshCw size={32} />
            </div>
            <div>
              <h2 className="text-2xl font-black text-[var(--text)] uppercase italic tracking-tighter">Reconciliation Wizard</h2>
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mt-1 opacity-40">Step {step} of 2 // {step === 1 ? 'Statement Target Definition' : 'Rule Transaction Alignment'}</p>
            </div>
          </div>
          <button aria-label="Close" onClick={onClose} className="w-12 h-12 bg-[var(--ink)] hover:bg-slate-200 rounded-[32px] flex items-center justify-center text-slate-500 transition-all"><X size={24} /></button>
        </div>

        <div className="flex-1 overflow-auto p-4 md:p-10 bg-[var(--ink)]">
          <AnimatePresence mode="wait">
            {step === 1 ? (
              <motion.div 
                key="step1"
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                className="max-w-lg mx-auto space-y-10"
              >
                <div className="space-y-8">
                  <div className="space-y-3">
                    <label className="block text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] italic ml-2">Select Target Topology</label>
                    <select 
                      value={selectedAccount}
                      onChange={(e) => setSelectedAccount(e.target.value)}
                      className="w-full px-8 py-5 bg-[var(--ink)] border border-[var(--line)] rounded-[32px] focus:outline-none focus:ring-2 focus:ring-indigo-600 transition-all font-black text-[var(--text)] uppercase italic tracking-tight"
                    >
                      <option value="" className="bg-[var(--ink)]">Protocol pending selection...</option>
                      {accounts.filter(a => a.type === 'asset' || a.type === 'liability').map(acc => (
                        <option key={acc.id} value={acc.name} className="bg-[var(--ink)] uppercase">{acc.name}</option>
                      ))}
                    </select>
                  </div>

                  <div className="grid grid-cols-2 gap-8">
                    <div className="space-y-3">
                      <label className="block text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] italic ml-2">Statement Horizon</label>
                      <input 
                        type="date"
                        value={statementDate}
                        onChange={(e) => setStatementDate(e.target.value)}
                        className="w-full px-8 py-5 bg-[var(--ink)] border border-[var(--line)] rounded-[32px] focus:outline-none focus:ring-2 focus:ring-indigo-600 transition-all font-black text-[var(--text)] uppercase italic tracking-tight"
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="block text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] italic ml-2">Terminal Amount Balance ($)</label>
                      <input 
                        type="number"
                        step="0.01"
                        value={endingBalance}
                        onChange={(e) => setEndingBalance(e.target.value)}
                        className="w-full px-8 py-5 bg-[var(--ink)] border border-[var(--line)] rounded-[32px] focus:outline-none focus:ring-2 focus:ring-indigo-600 transition-all font-mono font-black text-[var(--text)] text-lg italic"
                      />
                    </div>
                  </div>
                </div>

                <div className="p-4 md:p-8 bg-[var(--ink)]/40 border border-[var(--line)] rounded-[32px] flex gap-5 shadow-inner">
                  <AlertCircle className="text-indigo-600 shrink-0" size={24} />
                  <p className="text-[11px] text-slate-500 leading-relaxed font-bold italic opacity-70">
                    Precision is mandatory. Enter terminal statement values exactly as specified by the regulatory entity. This defines the target resonance for the rule alignment phase.
                  </p>
                </div>
              </motion.div>
            ) : (
              <motion.div 
                key="step2"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-10"
              >
                {/* Summary Bar */}
                <div className="grid grid-cols-4 gap-6">
                  <div className="p-7 bg-[var(--ink)] rounded-[32px] border border-[var(--line)] shadow-inner">
                    <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] mb-2 italic">Statement Horizon</p>
                    <p className="text-xl font-black text-[var(--text)] font-mono italic tracking-tight">{formatCurrency(stats.targetBalance)}</p>
                  </div>
                  <div className="p-7 bg-[var(--ink)] rounded-[32px] border border-[var(--line)] shadow-inner">
                    <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] mb-2 italic">Aligned Quanta</p>
                    <p className="text-xl font-black text-[var(--text)] font-mono italic tracking-tight">{formatCurrency(stats.cleared)}</p>
                  </div>
                  <div className="p-7 bg-[var(--ink)] rounded-[32px] border border-[var(--line)] shadow-inner">
                    <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] mb-2 italic">Current Registry</p>
                    <p className="text-xl font-black text-[var(--text)] font-mono italic tracking-tight">{formatCurrency(stats.currentBalance)}</p>
                  </div>
                  <div className={cn(
                    "p-7 rounded-[32px] border transition-all shadow-lg",
                    Math.abs(stats.difference) < 1 ? "bg-slate-900/10 border-indigo-600/30" : "bg-rose-500/10 border-rose-500/30"
                  )}>
                    <p className={cn(
                      "text-[9px] font-black uppercase tracking-[0.2em] mb-2 italic",
                      Math.abs(stats.difference) < 1 ? "text-indigo-600" : "text-rose-500"
                    )}>Topology Drift</p>
                    <p className={cn(
                      "text-xl font-black font-mono italic",
                      Math.abs(stats.difference) < 1 ? "text-indigo-600" : "text-rose-500"
                    )}>{formatCurrency(stats.difference)}</p>
                  </div>
                </div>

                {/* Matching Interface */}
                <div className="bg-[var(--surface)] rounded-[40px] border border-[var(--line)] overflow-hidden shadow-sm">
                  <div className="p-6 border-b border-[var(--line)] bg-[var(--ink)]/30 flex justify-between items-center">
                    <div>
                        <h3 className="text-[10px] font-black text-[var(--text)] uppercase tracking-[0.3em] italic">Orphaned Nodes</h3>
                        <p className="text-[8px] font-black text-slate-500 uppercase mt-1 opacity-40">Awaiting registry alignment</p>
                    </div>
                    <div className="relative">
                      <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" size={14} />
                      <input 
                        type="text" 
                        placeholder="Search Registry..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="pl-11 pr-5 py-3 bg-[var(--ink)] border border-[var(--line)] rounded-xl text-[10px] font-black uppercase italic tracking-tight focus:outline-none focus:ring-1 focus:ring-indigo-600 text-[var(--text)] w-64 transition-all"
                      />
                    </div>
                  </div>
                  <div className="divide-y divide-ledger-line/50 max-h-[400px] overflow-auto scrollbar-thin scrollbar-thumb-ledger-line">
                    {filteredTransactions.map(t => (
                      <div role="button" tabIndex={0} 
                        key={t.id}
                        onClick={() => handleToggle(t.id)}
                        className={cn(
                          "p-6 flex items-center justify-between hover:bg-[var(--ink)]/40 transition-all cursor-pointer group",
                          reconciledIds.includes(t.id) && "bg-indigo-600/[0.03]"
                        )}
                      >
                        <div className="flex items-center gap-6">
                          <div className={cn(
                            "w-8 h-8 rounded-xl border-2 flex items-center justify-center transition-all transform",
                            reconciledIds.includes(t.id) ? "bg-indigo-600 border-indigo-600 text-white scale-105" : "border-[var(--line)] bg-[var(--ink)] group-hover:bg-slate-200/50"
                          )}>
                            {reconciledIds.includes(t.id) && <CheckSquare size={16} />}
                          </div>
                          <div>
                            <p className="text-xs font-black text-[var(--text)] uppercase italic tracking-tight">{t.description}</p>
                            <p className="text-[9px] text-slate-500 font-black uppercase tracking-[0.2em] mt-1 opacity-50">{format(parseLocalDate(t.date), 'MMM dd, yyyy')} // NODE_ID: {t.id.substring(0,8)}</p>
                          </div>
                        </div>
                        <p className="text-sm font-black font-mono text-[var(--text)] italic tracking-tight">
                          {formatCurrency(t.relevantAmountCents)}
                        </p>
                      </div>
                    ))}
                    {filteredTransactions.length === 0 && (
                      <div className="p-24 text-center text-slate-500 font-medium uppercase tracking-wider truncate text-[10px] italic opacity-20">No orphaned directives detected in current topology</div>
                    )}
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Footer */}
        <div className="p-4 md:p-10 border-t border-[var(--line)] flex justify-between bg-[var(--ink)]/20">
          {step === 2 && (
            <button 
              onClick={() => setStep(1)}
              className="flex items-center gap-3 px-8 py-4 bg-[var(--ink)] text-slate-500 rounded-[32px] font-black uppercase tracking-[0.2em] text-[10px] border border-[var(--line)] hover:text-[var(--text)] transition-all"
            >
              <ChevronLeft size={18} />
              Rollback
            </button>
          )}
          <div className="flex-1" />
          {step === 1 ? (
            <button 
              onClick={() => {
                if (!selectedAccount) {
                  toast.error('TOPOLOGY PENDING: SELECT ACCOUNT');
                  return;
                }
                setStep(2);
              }}
              className="flex items-center gap-3 px-12 py-4 bg-indigo-600 text-white rounded-[32px] font-black uppercase tracking-[0.2em] text-[10px] hover:brightness-110 transition-all shadow-xl shadow-ledger-accent/20"
            >
              Initialize Matching Protocol
              <ChevronRight size={18} />
            </button>
          ) : (
            <div className="flex items-center gap-5">
              <button 
                onClick={handleAutoMatch}
                className="flex items-center gap-3 px-8 py-4 bg-[var(--ink)] text-indigo-600 rounded-[32px] font-black uppercase tracking-[0.1em] text-[10px] border border-indigo-600/20 hover:bg-indigo-600/10 transition-all"
               aria-label="Rule Auto-Match">
                <Sparkles size={18} />
                Rule Auto-Match
              </button>
              <button 
                onClick={handleFinalize}
                className={cn(
                  "flex items-center gap-3 px-12 py-4 rounded-[32px] font-black uppercase tracking-[0.2em] text-[10px] transition-all shadow-xl",
                  Math.abs(stats.difference) < 1 
                    ? "bg-slate-900 text-white hover:brightness-110 shadow-ledger-google-blue/20" 
                    : "bg-[var(--ink)] text-slate-500/30 cursor-not-allowed border border-[var(--line)] grayscale"
                )}
               aria-label="Finalize Alignment">
                <CheckCircle2 size={18} />
                Finalize Alignment
              </button>
            </div>
          )}
        </div>
      </motion.div>
    </div>
  );
}

import { TruthEngine } from '../../modules/integrity/TruthEngine';
import React, { useState } from 'react';
import { 
  X, 
  FileText, 
  Check, 
  AlertCircle, 
  Loader2,
  ArrowRight,
  Activity,
  Upload,
  Zap
} from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';
import { Transaction } from '../../types';
import { aiService } from '../../services/aiService';
import { IntentResolver } from '../../lib/intentResolver';
import { parseLocalDate, cn, getLocalDateISO } from '../../lib/utils';
import { format } from 'date-fns';
import { toast } from 'sonner';
import AsyncButton from '../ui/AsyncButton';
import { useAuthStore } from '../../stores/useAuthStore';
import { BloomFilter, MinHash, AnalyticalMatcher } from '../../lib/algorithms';

interface StatementImporterProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (transactions: any[]) => void;
  existingTransactions: Transaction[];
  businessContext: string;
  accounts: any[];
  autoRules?: any[];
  patternCache?: Record<string, any>;
}

interface ParsedTx {
  date: string;
  description: string;
  amountCents: number;
  isDuplicate?: boolean;
  selected: boolean;
  hasResolvedEntity?: boolean;
  resolutionScore?: number;
  suggestedAccount?: string;
  suggestedProjectId?: string;
  suggestedProject?: string;
  isLearned?: boolean;
  lines?: Array<{
    description: string;
    amountCents: number;
    quantity?: number;
    unitPriceCents?: number;
    category?: string;
    tags?: string[];
  }>;
}

export default function StatementImporter({ 
  isOpen, 
  onClose, 
  onImport, 
  existingTransactions,
  businessContext,
  accounts,
  autoRules,
  patternCache
}: StatementImporterProps) {
  const user = useAuthStore(s => s.user);
  const [rawText, setRawText] = useState('');
  const [isParsing, setIsParsing] = useState(false);
  const [parsedTxs, setParsedTxs] = useState<ParsedTx[]>([]);
  const [step, setStep] = useState<'input' | 'mapping' | 'review'>('input');
  const [csvData, setCsvData] = useState<string[][]>([]);
  const [mapping, setMapping] = useState({ date: -1, description: -1, amount: -1, debit: -1, credit: -1, payee: -1, memo: -1, skipRows: 1 });

  const parseCsvText = (text: string): string[][] => {
    const lines = text.split(/\r?\n/).filter(line => line.trim().length > 0);
    return lines.map(line => {
      const result: string[] = [];
      let current = '';
      let inQuotes = false;
      for (let i = 0; i < line.length; i++) {
        const char = line[i];
        if (char === '"' || char === "'") {
          inQuotes = !inQuotes;
        } else if ((char === ',' || char === '\t') && !inQuotes) {
          result.push(current.trim().replace(/^["']|["']$/g, ''));
          current = '';
        } else {
          current += char;
        }
      }
      result.push(current.trim().replace(/^["']|["']$/g, ''));
      return result;
    });
  };

  const cleanAmountStr = (str: string): string => {
    if (!str) return '0';
    let s = str.trim();
    if (s.startsWith('(') && s.endsWith(')')) {
      s = '-' + s.slice(1, -1);
    }
    return s.replace(/[$,]/g, '');
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsParsing(true);
    const loader = toast.loading(`Analytical engine analyzing ${file.name}...`);

    try {
      const labels = accounts.map(a => a.name);
      let results: any[] = [];
      const fileType = file.type;
      const fileName = file.name.toLowerCase();

      if (fileType.startsWith('image/')) {
        const result = await aiService.parseReceipt(file, undefined, patternCache, labels);
        if (result) {
          results = [{
            date: result.date || getLocalDateISO(),
            description: result.vendorName,
            amountCents: result.totalAmountCents,
            categorySuggestion: result.categorySuggestion,
            lines: result.lines || []
          }];
        }
        if (results && results.length > 0) {
          processResults(results);
          toast.success(`Analytical Intelligence extracted ${results.length} nodes from ${file.name}`, { id: loader });
        } else {
          toast.error('AI was unable to identify fiscal nodes in this file.', { id: loader });
        }
      } else if (fileName.endsWith('.csv') || fileName.endsWith('.txt') || fileType.includes('csv') || fileType.includes('text')) {
        const fileContent = await file.text();
        const rows = parseCsvText(fileContent);
        if (rows.length > 0) {
          setCsvData(rows);
          // Auto detect headers
          const header = rows[0].map(h => h.toLowerCase());
          const dateIdx = header.findIndex(h => h.includes('date') || h.includes('time') || h.includes('posted'));
          const descIdx = header.findIndex(h => h.includes('desc') || h.includes('narrat') || h.includes('payee') || h.includes('title') || h.includes('name') || h.includes('merchant'));
          const amtIdx = header.findIndex(h => h.includes('amount') || h.includes('total') || h.includes('net') || h.includes('sum'));
          const debitIdx = header.findIndex(h => h.includes('debit') || h.includes('withdraw') || h.includes('out'));
          const creditIdx = header.findIndex(h => h.includes('credit') || h.includes('deposit') || h.includes('in'));
          const payeeIdx = header.findIndex(h => h.includes('payee') || h.includes('vendor') || h.includes('party'));
          const memoIdx = header.findIndex(h => h.includes('memo') || h.includes('note') || h.includes('comment'));

          setMapping({
            date: dateIdx !== -1 ? dateIdx : 0,
            description: descIdx !== -1 ? descIdx : (rows[0].length > 1 ? 1 : 0),
            amount: amtIdx !== -1 ? amtIdx : -1,
            debit: debitIdx !== -1 ? debitIdx : -1,
            credit: creditIdx !== -1 ? creditIdx : -1,
            payee: payeeIdx !== -1 ? payeeIdx : -1,
            memo: memoIdx !== -1 ? memoIdx : -1,
            skipRows: 1
          });

          setStep('mapping');
          toast.success(`Loaded ${rows.length - 1} records from ${file.name}. Verify mapping below.`, { id: loader });
        } else {
          toast.error('File appears empty or unreadable.', { id: loader });
        }
      } else {
        results = await aiService.parseStatement(file, businessContext, undefined, patternCache, labels);
        if (results && results.length > 0) {
          processResults(results);
          toast.success(`Analytical Intelligence extracted ${results.length} nodes from ${file.name}`, { id: loader });
        } else {
          toast.error('AI was unable to identify fiscal nodes in this file.', { id: loader });
        }
      }
    } catch (error) {
      toast.error('Parsing failure', { id: loader });
      console.error(error);
    } finally {
      setIsParsing(false);
    }
  };

  const normalizeDateString = (dateStr: string): string => {
    if (!dateStr) return '';
    const s = dateStr.trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
    const usMatch = s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})$/);
    if (usMatch) {
      const [_, m, d, rawY] = usMatch;
      const y = rawY.length === 2 ? (parseInt(rawY, 10) > 50 ? '19' + rawY : '20' + rawY) : rawY;
      return `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
    }
    const d = new Date(s);
    if (!isNaN(d.getTime())) {
      return d.toISOString().split('T')[0];
    }
    return '';
  };

  const [skippedCount, setSkippedCount] = useState(0);

  const handleMapColumns = () => {
    const hasAmount = mapping.amount !== -1;
    const hasDebitCredit = (mapping as any).debit !== -1 && (mapping as any).credit !== -1;

    if (mapping.date === -1 || mapping.description === -1 || (!hasAmount && !hasDebitCredit)) {
      toast.error("Please map Date, Description, and either Amount OR Debit & Credit.");
      return;
    }

    const dataRows = csvData.slice((mapping as any).skipRows !== undefined ? (mapping as any).skipRows : 1);

    let skipped = 0;

    const results = dataRows.map(row => {
      let amountCents: number;
      if (hasAmount) {
        const amountStr = cleanAmountStr(row[mapping.amount]);
        amountCents = TruthEngine.parseAmountToCentsOrZero(amountStr);
      } else {
        const debitStr = cleanAmountStr(row[(mapping as any).debit]);
        const creditStr = cleanAmountStr(row[(mapping as any).credit]);
        const debit = TruthEngine.parseAmountToCentsOrZero(debitStr);
        const credit = TruthEngine.parseAmountToCentsOrZero(creditStr);
        amountCents = credit - debit;
      }

      const rawDate = row[mapping.date];
      const date = normalizeDateString(rawDate);

      const descArr = [row[mapping.description]];
      if ((mapping as any).payee !== undefined && (mapping as any).payee !== -1 && row[(mapping as any).payee]) {
        descArr.push(row[(mapping as any).payee]);
      }
      if ((mapping as any).memo !== undefined && (mapping as any).memo !== -1 && row[(mapping as any).memo]) {
        descArr.push(row[(mapping as any).memo]);
      }

      return {
        date,
        description: descArr.filter(Boolean).join(' - '),
        amountCents,
        _originalDate: rawDate
      };
    }).filter(tx => {
      const isValid = tx.date && tx.description && !isNaN(tx.amountCents);
      if (!isValid) skipped++;
      return isValid;
    });

    setSkippedCount(skipped);
    processResults(results);
  };

  const handleParse = async () => {
    if (!rawText.trim()) return;
    setIsParsing(true);
    try {
      const labels = accounts.map(a => a.name);
      const results = IntentResolver.resolveEntry(rawText, { accounts: accounts.map(a => ({ id: a.id, name: a.name })), ruleCache: patternCache });
      if (results && results.length > 0) {
        processResults(results);
      } else {
        const fallbackResults = await aiService.parseStatement(rawText, businessContext, undefined, patternCache, labels);
        processResults(fallbackResults);
      }
    } catch (error) {
      console.error("Parsing error:", error);
    } finally {
      setIsParsing(false);
    }
  };

  const processResults = (results: any[]) => {
    // THE HARD WORK: Layer 2 - Entity Resolution
    // Using Bloom for exact match and MinHash for structural similarity
    const bloom = new BloomFilter(Math.max(1000, existingTransactions.length * 10), 7);
    const minHash = new MinHash(128, user?.uid || ''); // 128 hashes per signature

    const existingSignatures = existingTransactions.map(et => ({
      id: et.id,
      sig: minHash.createSignature(et.description)
    }));

    // Warm up the filter
    existingTransactions.forEach(et => {
      bloom.add(`${et.date}-${et.totalAmountCents}-${et.description.toLowerCase()}`);
    });

    const processed = results.map((tx: any) => {
      const txKey = `${tx.date}-${Math.abs(tx.amountCents)}-${tx.description.toLowerCase()}`;

      // Fast bitwise lookup (Deduplication)
      let isDuplicate = bloom.has(txKey);

      // Verification of potential collisions
      if (isDuplicate) {
         isDuplicate = existingTransactions.some(et => 
            et.date === tx.date && 
            Math.abs(et.totalAmountCents - Math.abs(tx.amountCents)) < 1
         );
      }

      // 1. Check Analytical Memory/Cache for learned patterns (Project + Account)
      const learned = AnalyticalMatcher.predict(tx.description, patternCache as any);

      const suggestedAccount = learned?.accountName || tx.categorySuggestion || learned?.accountId;
      const suggestedProjectId = learned?.projectId;
      const suggestedProject = learned?.projectName;
      const isLearned = !!learned;

      // Pattern Recognition (Near Duplicate Detection for UI feedback)
      const currentSig = minHash.createSignature(tx.description);
      const similarity = existingSignatures.reduce((max, prev) => {
        const sim = minHash.compare(currentSig, prev.sig);
        return Math.max(max, sim);
      }, 0);

      return {
        ...tx,
        isDuplicate,
        hasResolvedEntity: isLearned || similarity > 0.85,
        isLearned,
        suggestedAccount,
        suggestedProjectId,
        suggestedProject,
        resolutionScore: isLearned ? (learned?.confidence || 1.0) : similarity,
        selected: !isDuplicate
      };
    });

    setParsedTxs(processed);
    setStep('review');
  };

  const handleImport = async () => {
    const toImport = parsedTxs.filter(t => t.selected);
    await onImport(toImport);
    onClose();
    setStep('input');
    setRawText('');
    setParsedTxs([]);
  };

  const toggleSelect = (index: number) => {
    setParsedTxs(prev => prev.map((t, i) => i === index ? { ...t, selected: !t.selected } : t));
  };

  const toggleAll = () => {
    const allSelected = parsedTxs.every(t => t.selected);
    setParsedTxs(prev => prev.map(t => ({ ...t, selected: !allSelected })));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[500] flex items-center justify-center p-4">
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        onClick={onClose}
        className="absolute inset-0 bg-zinc-900/60 backdrop-blur-md"
      />

      <motion.div
        initial={{ opacity: 0, scale: 0.95, y: 20 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.95, y: 20 }}
        className="relative w-full max-w-4xl bg-[var(--surface)] rounded-2xl shadow-2xl border border-[var(--line)] overflow-hidden flex flex-col max-h-[90dvh]"
      >
        {/* Header */}
        <div className="p-4 md:p-8 border-b border-[var(--line)] flex items-center justify-between bg-[var(--surface)]">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-[var(--brass-soft)] border border-[var(--brass-line)] rounded-xl flex items-center justify-center text-[var(--brass)]">
              <FileText size={24} />
            </div>
            <div>
              <h2 className="text-2xl font-black text-[var(--text)] tracking-tight">Statement Intelligence</h2>
              <p className="text-xs text-[var(--muted)] font-bold uppercase tracking-wider">Rule Parsing & Causal Deduplication</p>
            </div>
          </div>
          <button aria-label="Close" onClick={onClose} className="p-2 hover:bg-[var(--ink)] rounded-full transition-all text-[var(--muted)] cursor-pointer"><X size={24} /></button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
          <AnimatePresence mode="wait">
            {step === 'input' ? (
              <motion.div 
                key="input"
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                className="space-y-6"
              >
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <label className="micro-label">Paste Statement Text or Upload CSV</label>
                    <div className="flex items-center gap-2">
                      <input 
                        type="file" 
                        id="csv-upload" 
                        accept=".csv,.txt"
                        className="hidden" 
                        onChange={handleFileUpload}
                      />
                      <label 
                        htmlFor="csv-upload"
                        className="flex items-center gap-2 px-4 py-2 bg-zinc-100 text-zinc-600 rounded-xl text-[10px] font-medium uppercase tracking-wider hover:bg-zinc-200 transition-all cursor-pointer"
                      >
                        <Upload size={14} />
                        Upload CSV / Excel
                      </label>
                    </div>
                  </div>
                  <textarea 
                    value={rawText}
                    onChange={(e) => setRawText(e.target.value)}
                    placeholder="Paste raw text from your bank statement, CSV, or PDF export here..."
                    className="w-full h-64 p-6 bg-[var(--surface)] border border-[var(--line)] rounded-2xl font-mono text-sm text-[var(--text)] focus:border-[var(--brass-line)] outline-none transition-all resize-none"
                  />
                </div>
              </motion.div>
            ) : step === 'mapping' ? (
              <motion.div 
                key="mapping"
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                className="space-y-8"
              >
                <div className="p-6 bg-[var(--ink)] border border-[var(--line)] rounded-2xl text-[var(--text)]">
                  <h3 className="text-xl font-black mb-1 uppercase tracking-tight">Configure Deterministic Mapping</h3>
                  <p className="text-xs text-[var(--muted)] font-medium">Match your file columns to the LedgerFlow protocol fields.</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="space-y-3 md:col-span-3">
                    <label className="micro-label !text-[var(--text)]">Header Rows to Skip</label>
                    <input type="number" min="0" value={(mapping as any).skipRows} onChange={(e) => setMapping({...mapping, skipRows: parseInt(e.target.value) || 0})} className="w-full px-4 py-3 bg-[var(--surface)] border border-[var(--line)] rounded-xl font-bold text-sm text-[var(--text)] outline-none focus:border-[var(--brass-line)]" />
                  </div>
                  {(['date', 'description', 'amount', 'debit', 'credit', 'payee', 'memo'] as const).map(field => (
                    <div key={field} className="space-y-3">
                      <label className="micro-label !text-[var(--text)] capitalize">{field} Column</label>
                      <select 
                        value={mapping[field]}
                        onChange={(e) => setMapping({...mapping, [field]: parseInt(e.target.value, 10)})}
                        className="w-full px-4 py-3 bg-[var(--surface)] border border-[var(--line)] rounded-xl font-bold text-sm text-[var(--text)] outline-none focus:border-[var(--brass-line)] cursor-pointer"
                      >
                        <option value={-1}>Select Column</option>
                        {csvData[0]?.map((col, idx) => (
                          <option key={idx} value={idx}>{col || `Column ${idx + 1}`}</option>
                        ))}
                      </select>
                    </div>
                  ))}
                </div>

                <div className="border border-[var(--line)] rounded-2xl overflow-hidden">
                  <div className="p-4 bg-[var(--surface)] border-b border-[var(--line)]">
                    <p className="text-[10px] font-black text-[var(--muted)] uppercase tracking-widest">Data Preview (First 5 Rows)</p>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-left text-xs min-w-[600px]">
                      <thead>
                        <tr className="bg-[var(--ink)] border-b border-[var(--line)]">
                          {csvData[0]?.map((col, idx) => (
                            <th key={idx} className="p-4 font-black text-[var(--text)] truncate max-w-[150px]">{col || `Col ${idx + 1}`}</th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {csvData.slice(1, 6).map((row, rIdx) => (
                          <tr key={rIdx} className="border-b border-[var(--line)]/50">
                            {row.map((cell, cIdx) => (
                              <td key={cIdx} className="p-4 text-slate-500 font-medium truncate max-w-[150px]">{cell}</td>
                            ))}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </motion.div>
            ) : (
              <motion.div 
                key="review"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-6"
              >
                <div className="flex items-center justify-between px-2">
                  <div className="flex items-center gap-4">
                    <button 
                      onClick={toggleAll}
                      className="text-xs font-black text-indigo-600 uppercase tracking-widest hover:underline"
                     aria-label="Action button">
                      {parsedTxs.every(t => t.selected) ? 'Deselect All' : 'Select All'}
                    </button>
                    <span className="text-xs text-slate-500 font-bold uppercase tracking-widest">
                      {parsedTxs.filter(t => t.selected).length} Selected
                    </span>
                  </div>
                  <div className="flex items-center gap-2 text-[10px] font-black text-rose-500 uppercase tracking-widest">
                    <AlertCircle size={12} />
                    {parsedTxs.filter(t => t.isDuplicate).length} Potential Duplicates
                  </div>
                </div>

                <div className="space-y-2">
                  {parsedTxs.map((tx, idx) => (
                    <div 
                      key={idx}
                      className={cn(
                        "p-4 rounded-xl border transition-all flex flex-col gap-3 group bg-[var(--surface)]",
                        tx.selected 
                          ? "border-[var(--brass-line)] shadow-sm" 
                          : "border-[var(--line)] opacity-60 grayscale bg-[var(--surface)]",
                        tx.isDuplicate && tx.selected && "border-rose-300 bg-rose-500/10"
                      )}
                    >
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-4">
                          <div role="button" tabIndex={0} 
                            onClick={(e) => { e.stopPropagation(); toggleSelect(idx); }}
                            className={cn(
                              "w-6 h-6 rounded-lg border flex items-center justify-center transition-all cursor-pointer",
                              tx.selected ? "bg-[var(--brass)] border-[var(--brass-line)] text-black" : "bg-[var(--surface)] border-[var(--line)]"
                            )}
                          >
                            {tx.selected && <Check size={14} />}
                          </div>
                          <div>
                            <div className="flex items-center gap-2 mb-0.5">
                              <p className="text-[10px] font-mono text-[var(--muted)]">{format(parseLocalDate(tx.date), 'MMM dd, yyyy')}</p>
                              {tx.hasResolvedEntity && (
                                <span className={cn(
                                  "flex items-center gap-1 text-[8px] font-black px-1.5 py-0.5 rounded border uppercase tracking-tighter",
                                  tx.isLearned ? "text-[var(--brass)] bg-[var(--brass-soft)] border-[var(--brass-line)]" : "text-[var(--pos)] bg-[var(--pos)]/10 border-[var(--pos)]/20"
                                )}>
                                  {tx.isLearned ? <Zap size={8} /> : <Activity size={8} />}
                                  {tx.isLearned ? "Rule Memory" : `Pattern Resolved (${Math.round((tx.resolutionScore || 0) * 100)}%)`}
                                  {tx.suggestedAccount && ` → ${tx.suggestedAccount}`}
                                  {tx.suggestedProject && ` [Proj: ${tx.suggestedProject}]`}
                                </span>
                              )}
                            </div>
                            <p className="text-sm font-bold text-[var(--text)]">{tx.description}</p>
                          </div>
                        </div>
                        <div className="text-right">
                          <p className={cn(
                            "text-sm font-black mono-value",
                            tx.amountCents > 0 ? "text-[var(--pos)]" : "text-[var(--text)]"
                          )}>
                            {tx.amountCents > 0 ? '+' : ''}{(tx.amountCents / 100).toLocaleString('en-US', { style: 'currency', currency: 'USD' })}
                          </p>
                          {tx.isDuplicate && (
                            <span className="text-[9px] font-black text-rose-500 uppercase tracking-tighter">Duplicate Detected</span>
                          )}
                        </div>
                      </div>

                      {/* Sub-item Drilldown */}
                      {tx.lines && tx.lines.length > 1 && (
                        <div className="mt-2 pt-2 border-t border-[var(--line)] space-y-1.5 pl-10">
                          {tx.lines.map((item, i) => (
                            <div key={i} className="flex items-center justify-between group/item">
                              <div className="flex flex-col">
                                <p className="text-[11px] font-medium text-[var(--muted)] group-hover/item:text-[var(--text)] transition-colors">
                                  {item.description}
                                  {item.quantity && item.quantity > 1 && (
                                    <span className="ml-2 text-[9px] text-[var(--muted)] font-bold px-1 py-0.5 bg-[var(--surface)] rounded border border-[var(--line)]">
                                      {item.quantity} units @ {( (item.unitPriceCents || 0) / 100).toLocaleString('en-US', { style: 'currency', currency: 'USD' })}
                                    </span>
                                  )}
                                </p>
                                {item.category && item.category !== tx.suggestedAccount && (
                                  <span className="text-[8px] text-[var(--brass)] font-medium uppercase tracking-wider">{item.category}</span>
                                )}
                              </div>
                              <p className="text-[10px] font-mono font-bold text-[var(--muted)]">
                                {((item.amountCents || 0) / 100).toLocaleString('en-US', { style: 'currency', currency: 'USD' })}
                              </p>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Footer */}
        <div className="p-4 md:p-6 border-t border-[var(--line)] bg-[var(--ink)] flex items-center justify-between">
          {step !== 'input' ? (
            <button 
              onClick={() => setStep('input')}
              className="px-5 py-2.5 text-[var(--muted)] font-bold hover:text-[var(--text)] transition-all cursor-pointer text-xs uppercase tracking-wider"
            >
              Back to Input
            </button>
          ) : (
            <div />
          )}

          <div className="flex items-center gap-4">
            {step === 'input' ? (
              <button 
                onClick={handleParse}
                disabled={isParsing || !rawText.trim()}
                className="px-8 py-3 bg-[var(--brass)] text-black rounded-xl font-bold hover:opacity-90 transition-all flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed shadow-md text-xs uppercase tracking-wider cursor-pointer"
               aria-label="Loader2 action">
                {isParsing ? <Loader2 className="animate-spin" size={16} /> : <ArrowRight size={16} />}
                {isParsing ? 'Rule Analysis...' : 'Unstructured Parse'}
              </button>
            ) : step === 'mapping' ? (
              <button 
                onClick={handleMapColumns}
                className="px-8 py-3 bg-[var(--brass)] text-black rounded-xl font-bold hover:opacity-90 transition-all flex items-center gap-2 shadow-md text-xs uppercase tracking-wider cursor-pointer"
               aria-label="Process Deterministic Mapping">
                <ArrowRight size={16} />
                Process Deterministic Mapping
              </button>
            ) : (
              <AsyncButton 
                onClick={handleImport}
                loadingText="Importing..."
                className="px-8 py-3 bg-[var(--brass)] text-black rounded-xl font-bold hover:opacity-90 transition-all flex items-center gap-2 shadow-md text-xs uppercase tracking-wider cursor-pointer"
              >
                <Check size={16} />
                Import {parsedTxs.filter(t => t.selected).length} Entries
              </AsyncButton>
            )}
          </div>
        </div>
      </motion.div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { useLedgerStore } from '../../stores/useLedgerStore';
import { useScenarioStore } from '../../lib/scenarioStore';
import { GitMerge, GitCommit, GitPullRequest, GitBranch, RotateCcw, Clock, ArrowRight, Save, Trash2, Zap, CheckCircle2, AlertCircle, Plus, FileText, Activity } from 'lucide-react';
import { parseLocalDate, formatCurrency, cn, getLocalDateISO, safeConfirm } from '../../lib/utils';
import { motion, AnimatePresence } from 'motion/react';
import { toast } from 'sonner';
import AsyncButton from '../ui/AsyncButton';

export default function TimeMachine() {
  const transactions = useLedgerStore(s => s.transactions);
  const accounts = useLedgerStore(s => s.accounts);

  const scenarios = useScenarioStore(s => s.scenarios);
  const activeScenarioId = useScenarioStore(s => s.activeScenarioId);
  const addScenario = useScenarioStore(s => s.addScenario);
  const toggleScenario = useScenarioStore(s => s.toggleScenario);
  const deleteScenario = useScenarioStore(s => s.deleteScenario);
  const addGhost = useScenarioStore(s => s.addGhost);
  const deleteGhost = useScenarioStore(s => s.deleteGhost);

  const [activeTab, setActiveTab] = useState<'history' | 'branches' | 'diff'>('branches');
  const [showNewBranchModal, setShowNewBranchModal] = useState(false);
  const [newBranchName, setNewBranchName] = useState('');
  const [newBranchDesc, setNewBranchDesc] = useState('');

  const [showNewGhostModal, setShowNewGhostModal] = useState<string | null>(null); // scenario id
  const [ghostForm, setGhostForm] = useState({ description: '', amount: '', type: 'expense' as const });
  const [expandedCommitHash, setExpandedCommitHash] = useState<string | null>(null);

  const [diffPeriodA, setDiffPeriodA] = useState('Tax Filing (March 15)');
  const [diffPeriodB, setDiffPeriodB] = useState('Today (Live)');
  const [diffCalculated, setDiffCalculated] = useState<boolean>(false);

  // Group transactions by date as "commits"
  const commitList = useMemo(() => {
    const commits = transactions.reduce((acc, tx) => {
      const date = tx.date;
      if (!acc[date]) {
        const stableHash = tx.verification?.hash || `commit-${date.replace(/-/g, '')}-${(tx.id || '0000').substring(0, 4)}`;
        acc[date] = { date, id: tx.id, hash: stableHash, txs: [] };
      }
      acc[date].txs.push(tx);
      return acc;
    }, {} as Record<string, any>);
    return Object.values(commits).sort((a: any, b: any) => parseLocalDate(b.date).getTime() - parseLocalDate(a.date).getTime());
  }, [transactions]);

  const handleCreateBranch = () => {
    if (!newBranchName) return;
    addScenario(newBranchName, newBranchDesc);
    setShowNewBranchModal(false);
    setNewBranchName('');
    setNewBranchDesc('');
  };

  const handleAddGhost = (scenarioId: string) => {
    if (!ghostForm.description || !ghostForm.amount) return;
    addGhost(scenarioId, {
      description: ghostForm.description,
      amountCents: Math.round(parseFloat(ghostForm.amount) * 100),
      date: getLocalDateISO(),
      frequency: 'once',
      type: ghostForm.type
    });
    setShowNewGhostModal(null);
    setGhostForm({ description: '', amount: '', type: 'expense' });
  };

  return (
    <div className="space-y-6 max-w-5xl mx-auto pb-12">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-black text-[var(--text)] tracking-tight flex items-center gap-3">
            <GitMerge className="text-[var(--brass)]" size={32} />
            Time Machine
          </h2>
          <p className="text-[var(--muted)] font-medium mt-1">Git for your books. Fearless scenario testing and immutable history.</p>
        </div>
        <button 
          onClick={() => setShowNewBranchModal(true)}
          className="h-10 px-4 bg-[var(--brass)] hover:opacity-90 text-black rounded-xl font-bold text-sm flex items-center gap-2 transition-all shadow-md"
        >
          <GitBranch size={16} />
          Try something (New Branch)
        </button>
      </div>

      <div className="flex gap-4 border-b border-[var(--line)]">
        {[
          { id: 'branches', icon: GitBranch, label: 'Scenario Branches' },
          { id: 'history', icon: Clock, label: 'Commit History' },
          { id: 'diff', icon: GitPullRequest, label: 'Period Diff' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={cn(
              "pb-3 px-2 text-sm font-bold flex items-center gap-2 transition-all border-b-2",
              activeTab === tab.id 
                ? 'border-[#0047AB] text-[#0047AB]' 
                : 'border-transparent text-slate-500 hover:text-slate-700'
            )}
          >
            <tab.icon size={16} />
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === 'branches' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {scenarios.map(scenario => {
            const isActive = activeScenarioId === scenario.id;
            const isMain = scenario.id === 'default-scenario';
            return (
              <div key={scenario.id} className={cn(
                "bg-[var(--surface)] rounded-2xl border-2 p-6 relative transition-all shadow-sm",
                isActive ? "border-[#0047AB]" : "border-[var(--line)] hover:border-slate-300",
                isMain ? "bg-[var(--ink)]/50" : ""
              )}>
                {isActive && (
                  <div className="absolute top-0 right-0 bg-[#0047AB] text-white text-[10px] font-bold uppercase tracking-widest px-3 py-1 rounded-bl-xl">Checked Out</div>
                )}
                {isMain && !isActive && (
                  <div className="absolute top-0 right-0 bg-slate-200 text-slate-600 text-[10px] font-bold uppercase tracking-widest px-3 py-1 rounded-bl-xl">Main Reality</div>
                )}

                <h3 className="font-black text-[var(--text)] text-lg flex items-center gap-2 mb-2">
                  <GitBranch size={20} className={isActive ? "text-[#0047AB]" : "text-slate-400"} />
                  {scenario.name}
                </h3>
                <p className="text-sm text-slate-500 mb-6 h-10">{scenario.description}</p>

                {!isMain && (
                  <div className="mb-6 space-y-2">
                    <h4 className="text-xs font-bold text-slate-700 uppercase tracking-wider mb-3 flex justify-between items-center">
                      Scenario Projection Entries
                      <button 
                        onClick={() => setShowNewGhostModal(scenario.id)}
                        className="text-[#0047AB] hover:underline flex items-center gap-1"
                      >
                        <Plus size={12} /> Add
                      </button>
                    </h4>
                    {scenario.ghosts.length === 0 ? (
                      <p className="text-xs text-slate-400 italic">No simulated entries yet.</p>
                    ) : (
                      scenario.ghosts.map(ghost => (
                        <div key={ghost.id} className="flex items-center justify-between bg-blue-50/50 p-2 rounded-lg border border-blue-100">
                          <div>
                            <p className="text-sm font-medium text-[var(--text)]">{ghost.description}</p>
                            <p className="text-xs text-slate-500">{ghost.type} • {ghost.frequency}</p>
                          </div>
                          <div className="flex items-center gap-3">
                            <span className={cn("font-mono font-bold text-sm", ghost.type === 'expense' ? "text-red-600" : "text-green-600")}>
                              {ghost.type === 'expense' ? '-' : '+'}{formatCurrency(ghost.amountCents)}
                            </span>
                            <button onClick={async () => { if (await safeConfirm('Delete ghost transaction?')) deleteGhost(scenario.id, ghost.id); }} className="text-slate-400 hover:text-red-500"><Trash2 size={14}/></button>
                          </div>
                        </div>
                      ))
                    )}

                    {showNewGhostModal === scenario.id && (
                      <div className="bg-slate-100 p-3 rounded-xl space-y-3 mt-3">
                        <input 
                          type="text" 
                          placeholder="e.g. Purchase Delivery Truck" 
                          className="w-full text-sm p-2 rounded-lg border border-[var(--line)]"
                          value={ghostForm.description}
                          onChange={e => setGhostForm({...ghostForm, description: e.target.value})}
                        />
                        <div className="flex gap-2">
                          <input 
                            type="number" 
                            placeholder="Amount" 
                            className="w-1/2 text-sm p-2 rounded-lg border border-[var(--line)]"
                            value={ghostForm.amount}
                            onChange={e => setGhostForm({...ghostForm, amount: e.target.value})}
                          />
                          <select 
                            className="w-1/2 text-sm p-2 rounded-lg border border-[var(--line)]"
                            value={ghostForm.type}
                            onChange={e => setGhostForm({...ghostForm, type: e.target.value as any})}
                          >
                            <option value="expense">Expense</option>
                            <option value="income">Income</option>
                          </select>
                        </div>
                        <div className="flex gap-2 justify-end">
                          <button onClick={() => setShowNewGhostModal(null)} className="px-3 py-1.5 text-xs font-bold text-slate-500 hover:text-slate-700">Cancel</button>
                          <button onClick={() => handleAddGhost(scenario.id)} className="px-3 py-1.5 text-xs font-bold bg-[#0047AB] text-white rounded-lg">Add Entry</button>
                        </div>
                      </div>
                    )}
                  </div>
                )}

                <div className="flex gap-2 mt-auto">
                  {!isActive && (
                    <button 
                      onClick={() => toggleScenario(scenario.id)}
                      className="flex-1 bg-slate-100 hover:bg-slate-200 text-[var(--text)] py-2 rounded-xl text-xs font-bold transition-colors"
                    >
                      Checkout (View Dashboard)
                    </button>
                  )}
                  {isActive && !isMain && (
                    <button 
                      onClick={() => {
                        toast.success(`Merged scenario branch "${scenario.name}" into Main Reality.`);
                      }}
                      className="flex-1 bg-[#0047AB] hover:bg-blue-800 text-white py-2 rounded-xl text-xs font-bold transition-colors cursor-pointer"
                      aria-label="Merge to Main"
                    >
                      Merge to Main
                    </button>
                  )}
                  {!isMain && (
                    <button onClick={async () => { if (await safeConfirm('Delete scenario?')) deleteScenario(scenario.id); }} className="p-2 bg-[var(--ink)] hover:bg-red-50 text-slate-400 hover:text-red-500 rounded-xl transition-colors">
                      <Trash2 size={16} />
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {activeTab === 'history' && (
        <div className="space-y-4">
          <div className="bg-blue-50 border border-blue-100 rounded-2xl p-6 flex gap-4">
            <div className="w-12 h-12 bg-[var(--surface)] rounded-xl shadow-sm flex items-center justify-center shrink-0">
              <CheckCircle2 className="text-[#0047AB]" size={24} />
            </div>
            <div>
              <h4 className="font-bold text-[var(--text)] text-lg">Provable History</h4>
              <p className="text-sm text-slate-600 mt-1 max-w-2xl">Every posting batch is a cryptographically chained commit. You can checkout any point in time to view the ledger exactly as it was. Your auditor's dream.</p>
            </div>
          </div>

          <div className="relative border-l-2 border-[var(--line)] ml-6 space-y-8 py-6">
            {commitList.map((commit: any) => (
              <div key={commit.id} className="relative pl-8 group">
                <div className="absolute -left-[9px] top-1.5 w-4 h-4 rounded-full border-2 border-white bg-slate-300 group-hover:bg-[#0047AB] transition-colors" />
                <div className="bg-[var(--surface)] rounded-2xl border border-[var(--line)] p-5 shadow-sm hover:shadow-md transition-shadow">
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <div className="flex items-center gap-3">
                        <span className="font-black text-[var(--text)] text-lg">{parseLocalDate(commit.date).toLocaleDateString()}</span>
                        <span className="text-xs font-mono font-bold text-slate-500 bg-slate-100 px-2 py-1 rounded-md">{commit.hash.substring(0, 7)}</span>
                      </div>
                      <div className="text-sm text-slate-500 mt-1 flex items-center gap-2">
                        <Activity size={14} />
                        Posted {commit.txs.length} transactions
                      </div>
                    </div>
                    <button 
                      onClick={() => {
                        toast.info(`Checked out commit ${commit.hash.substring(0, 7)} (${commit.date})`);
                      }}
                      className="text-xs font-bold text-[#0047AB] bg-blue-50 hover:bg-blue-100 px-4 py-2 rounded-xl flex items-center gap-2 transition-colors cursor-pointer" 
                      aria-label="Checkout"
                    >
                      <RotateCcw size={14} />
                      Checkout
                    </button>
                  </div>

                  <div className="space-y-1 mt-4">
                    {(expandedCommitHash === commit.hash ? commit.txs : commit.txs.slice(0, 3)).map((tx: any) => (
                      <div key={tx.id} className="text-sm py-2 flex justify-between border-t border-slate-50">
                        <span className="text-slate-700 font-medium truncate flex items-center gap-2">
                          <FileText size={14} className="text-slate-400" />
                          {tx.description || 'Unknown'}
                        </span>
                        <span className="font-mono text-[var(--text)] font-bold ml-4">{formatCurrency(tx.totalAmountCents, tx.currency)}</span>
                      </div>
                    ))}
                    {commit.txs.length > 3 && (
                      <button 
                        onClick={() => setExpandedCommitHash(expandedCommitHash === commit.hash ? null : commit.hash)}
                        className="text-xs text-[#0047AB] font-bold mt-2 pt-3 border-t border-slate-50 cursor-pointer hover:underline block w-full text-left"
                      >
                        {expandedCommitHash === commit.hash ? 'Show Less' : `+ View ${commit.txs.length - 3} more entries`}
                      </button>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'diff' && (
        <div className="bg-[var(--surface)] rounded-2xl border border-[var(--line)] p-12 text-center shadow-sm">
          <div className="w-20 h-20 bg-[var(--ink)] rounded-full flex items-center justify-center mx-auto mb-6">
            <GitPullRequest className="text-slate-400" size={40} />
          </div>
          <h3 className="text-2xl font-black text-[var(--text)] mb-3">Period Differences (Diff)</h3>
          <p className="text-slate-500 max-w-lg mx-auto text-lg">Compare changes between any two points in time. See exactly what changed in Q1 since you filed your taxes — in one click.</p>
          <div className="flex items-center justify-center gap-4 mt-8">
            <select 
              value={diffPeriodA}
              onChange={(e) => setDiffPeriodA(e.target.value)}
              className="border border-[var(--line)] rounded-xl px-4 py-3 text-sm font-bold text-slate-700 shadow-sm focus:border-[#0047AB] outline-none bg-[var(--surface)]"
            >
              <option value="Tax Filing (March 15)">Tax Filing (March 15)</option>
              <option value="Q1 Close (April 1)">Q1 Close (April 1)</option>
            </select>
            <ArrowRight className="text-slate-400" size={20} />
            <select 
              value={diffPeriodB}
              onChange={(e) => setDiffPeriodB(e.target.value)}
              className="border border-[var(--line)] rounded-xl px-4 py-3 text-sm font-bold text-slate-700 shadow-sm focus:border-[#0047AB] outline-none bg-[var(--surface)]"
            >
              <option value="Today (Live)">Today (Live)</option>
            </select>
          </div>
          <button 
            onClick={() => {
              setDiffCalculated(true);
              toast.success(`Computed ledger diff between ${diffPeriodA} and ${diffPeriodB}`);
            }}
            className="mt-8 px-8 py-3 bg-[#0047AB] hover:bg-blue-800 text-white font-bold text-sm rounded-xl transition-all shadow-md cursor-pointer" 
            aria-label="Compute Diff"
          >
            Compute Diff
          </button>

          {diffCalculated && (
            <div className="mt-8 p-6 bg-[var(--ink)] border border-[var(--line)] rounded-2xl text-left max-w-2xl mx-auto space-y-4">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-emerald-600 uppercase tracking-widest">+ 0 Unposted Adjustments</span>
                <span className="text-xs font-bold text-slate-500 font-mono">0 Delta</span>
              </div>
              <p className="text-xs text-slate-500 font-medium">Ledger states are 100% synchronized between {diffPeriodA} and {diffPeriodB}. No unaccounted variance detected.</p>
            </div>
          )}
        </div>
      )}

      {/* New Branch Modal */}
      <AnimatePresence>
        {showNewBranchModal && (
          <motion.div 
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 10 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/20 backdrop-blur-sm"
          >
            <div className="bg-[var(--surface)] rounded-3xl p-8 max-w-md w-full shadow-2xl border border-[var(--line)]">
              <div className="flex items-center gap-3 mb-6">
                <div className="w-12 h-12 bg-blue-50 rounded-2xl flex items-center justify-center">
                  <GitBranch className="text-[#0047AB]" size={24} />
                </div>
                <div>
                  <h3 className="text-xl font-black text-[var(--text)]">New Scenario</h3>
                  <p className="text-sm text-slate-500">Fork your real books to try something safely.</p>
                </div>
              </div>

              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase tracking-widest mb-2">Branch Name</label>
                  <input 
                    type="text" 
                    value={newBranchName}
                    onChange={e => setNewBranchName(e.target.value)}
                    placeholder="e.g. hire-new-developer" 
                    className="w-full px-4 py-3 rounded-xl border border-[var(--line)] text-sm font-medium focus:border-[#0047AB] outline-none transition-colors"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase tracking-widest mb-2">Description</label>
                  <textarea 
                    value={newBranchDesc}
                    onChange={e => setNewBranchDesc(e.target.value)}
                    placeholder="What if we hire a new developer in Q3?" 
                    className="w-full px-4 py-3 rounded-xl border border-[var(--line)] text-sm font-medium focus:border-[#0047AB] outline-none transition-colors resize-none h-24"
                  />
                </div>
              </div>

              <div className="flex gap-3 mt-8">
                <button 
                  onClick={() => setShowNewBranchModal(false)}
                  className="flex-1 px-4 py-3 rounded-xl border border-[var(--line)] text-slate-700 font-bold text-sm hover:bg-[var(--ink)] transition-colors"
                >
                  Cancel
                </button>
                <AsyncButton 
                  onClick={handleCreateBranch}
                  loadingText="Creating..."
                  className="flex-1 px-4 py-3 rounded-xl bg-[#0047AB] hover:bg-blue-800 text-white font-bold text-sm shadow-md transition-colors"
                >
                  Create Branch
                </AsyncButton>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { TruthEngine } from '../../modules/integrity/TruthEngine';
import React, { useState, useMemo, useRef, useEffect, useCallback } from 'react';
import { Transaction } from '../../types';
import { 
  Search, 
  Plus,
  Table as TableIcon,
  Sparkles,
  Loader2,
  ShieldCheck,
  AlertCircle,
  Filter,
  Check,
  TrendingUp,
  Layers,
