import { useLedgerStore } from '../../stores/useLedgerStore';
import { useAuthStore } from '../../stores/useAuthStore';
import { TruthEngine } from '../../modules/integrity/TruthEngine';
import React, { useState, useMemo } from 'react';
import { 
  Target, 
  Plus, 
  Trash2, 
  Edit2,
  AlertCircle,
  DollarSign,
  Activity,
  ShieldCheck,
  Zap,
  ArrowUpRight,
  Layers
} from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';
import { Budget, Transaction, ChartAccount } from '../../types';
import { cn, formatCurrency, getLocalDateISO, safeConfirm } from '../../lib/utils';
import { addDoc, collection, deleteDoc, doc, updateDoc } from 'firebase/firestore';
import { db } from '../../firebase';
import { toast } from 'sonner';
import AsyncButton from '../ui/AsyncButton';



export default function BudgetManager() {
  const user = useAuthStore((s: any) => s.user);
  const currentWorkspaceId = useLedgerStore((s: any) => s.currentWorkspaceId);
  const budgets = useLedgerStore((s: any) => s.budgets);
  const transactions = useLedgerStore((s: any) => s.transactions);
  const accounts = useLedgerStore((s: any) => s.accounts);
  const [isAdding, setIsAdding] = useState(false);
  const [editingBudget, setEditingBudget] = useState<string | null>(null);
  const [newBudget, setNewBudget] = useState({
    targetId: '',
    targetType: 'account' as const,
    amountCents: 0,
    period: 'monthly',
    startDate: getLocalDateISO()
  });

  const handleAddBudget = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentWorkspaceId) {
      toast.error('Workspace context missing');
      return;
    }
    try {
      if (editingBudget) {
        await updateDoc(doc(db, 'budgets', editingBudget), {
          targetId: newBudget.targetId,
          amountCents: newBudget.amountCents,
          period: newBudget.period,
          startDate: newBudget.startDate || getLocalDateISO(),
          updatedAt: new Date().toISOString()
        });
        toast.success('Objective Updated');
      } else {
        await addDoc(collection(db, 'budgets'), {
          ...newBudget,
          workspaceId: currentWorkspaceId,
          uid: user?.uid || "",
          createdAt: new Date().toISOString()
        });
        toast.success('Objective Synchronized');
      }
      setIsAdding(false);
      setEditingBudget(null);
      setNewBudget({
        targetId: '',
        targetType: 'account',
        amountCents: 0,
        period: 'monthly',
        startDate: getLocalDateISO()
      });
    } catch (error) {
      toast.error('Could not save budget objective. Please try again.');
    }
  };

  const budgetAnalysis = useMemo(() => {
    return budgets.map((budget: any) => {
      const targetLower = (budget.targetId || '').toLowerCase();
      // Find matching account ID or name
      const matchingAccount = accounts.find((a: any) => 
        a.id === budget.targetId || 
        (a.name || '').toLowerCase() === targetLower || 
        (a.code || '').toLowerCase() === targetLower
      );

      const actualCents = transactions.reduce((sum: number, t: any) => {
        if (t.status === 'void' || t.status === 'deleted') return sum;
        const lines = t.lines?.filter((l: any) => 
          l.accountId === budget.targetId || 
          (matchingAccount && l.accountId === matchingAccount.id) ||
          (l.accountName || '').toLowerCase() === targetLower
        ) || [];
        return sum + lines.reduce((s: number, l: any) => s + Math.max(0, l.amountCents || 0), 0);
      }, 0);

      const variance = budget.amountCents - actualCents;
      const percentUsed = budget.amountCents > 0 ? (actualCents / budget.amountCents) * 100 : 0;

      return {
        ...budget,
        actualCents,
        variance,
        percentUsed
      };
    });
  }, [budgets, transactions, accounts]);

  return (
    <div className="space-y-12">
      {/* Rule Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
        <div>
          <div className="flex items-center gap-2 text-[10px] font-black text-indigo-600 uppercase tracking-widest truncate mb-4">
            <Target size={14} />
            Resource Allocation Matrix
          </div>
          <h2 className="text-3xl md:text-5xl font-black text-[var(--text)] tracking-tighter">Budget Protocol</h2>
          <p className="text-slate-500 font-medium text-lg mt-2 italic opacity-60">Strategic variance analysis and predictive consumption monitoring.</p>
        </div>

        <button 
          onClick={() => setIsAdding(true)}
          className="flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-[32px] text-xs font-medium uppercase tracking-wider hover:bg-slate-900/90 transition-all shadow-2xl"
        >
          <Plus size={18} />
          Define Target
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        {budgetAnalysis.map((b: any) => {
          const isOver = b.percentUsed > 100;
          const isWarning = b.percentUsed > 85 && b.percentUsed <= 100;

          return (
            <motion.div 
              key={b.id}
              whileHover={{ y: -5 }}
              className="ledger-card p-4 md:p-8 rounded-[32px] relative overflow-hidden group border border-[var(--line)] hover:border-indigo-600/20 transition-all"
            >
              <div className="absolute technical-grid inset-0 opacity-5 pointer-events-none" />

              <div className="flex items-center justify-between mb-8 relative z-10">
                <div className="w-14 h-14 bg-slate-900 rounded-[32px] flex items-center justify-center text-white border border-white/5 shadow-2xl">
                  <Activity size={28} />
                </div>
                <div className="flex items-center gap-2">
                  {isOver ? (
                    <div className="px-4 py-1.5 bg-rose-50 text-rose-700 border border-rose-200 rounded-xl text-[9px] font-medium uppercase tracking-wider flex items-center gap-2">
                      <AlertCircle size={12} />
                      Critical Limit
                    </div>
                  ) : isWarning ? (
                    <div className="px-4 py-1.5 bg-amber-50 text-amber-700 border border-amber-200 rounded-xl text-[9px] font-medium uppercase tracking-wider flex items-center gap-2">
                      <Zap size={12} />
                      Warning Alert
                    </div>
                  ) : (
                    <div className="px-4 py-1.5 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-xl text-[9px] font-medium uppercase tracking-wider flex items-center gap-2">
                      <ShieldCheck size={12} />
                      Stable Allocation
                    </div>
                  )}
                  <button 
                    onClick={() => {
                      setNewBudget({
                        targetId: b.targetId,
                        targetType: b.targetType as 'account',
                        amountCents: b.amountCents,
                        period: b.period,
                        startDate: b.startDate || getLocalDateISO()
                      });
                      setEditingBudget(b.id);
                      setIsAdding(true);
                    }}
                    className="p-2 text-slate-500 hover:text-indigo-600 transition-colors opacity-100 md:opacity-0 md:group-hover:opacity-100"
                  >
                    <Edit2 size={16} />
                  </button>
                  <button 
                    onClick={async () => { if (await safeConfirm('Delete budget?')) { await deleteDoc(doc(db, 'budgets', b.id)); toast.success('Budget deleted'); } }}
                    className="p-2 text-slate-500 hover:text-rose-500 transition-colors opacity-100 md:opacity-0 md:group-hover:opacity-100"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>

              <div className="space-y-2 relative z-10">
                 <h3 className="text-2xl font-black text-[var(--text)] tracking-tight uppercase italic truncate">{b.targetId}</h3>
                 <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] opacity-40">{b.period} Allocation</p>
              </div>

              <div className="mt-8 space-y-6 relative z-10">
                <div className="flex justify-between items-end">
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest opacity-50 mb-1">Consumption Flow</span>
                    <span className="text-2xl font-black text-[var(--text)] font-mono tracking-tighter">{formatCurrency(b.actualCents)}</span>
                  </div>
                  <div className="flex flex-col items-end">
                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest opacity-50 mb-1">Cap Magnitude</span>
                    <span className="text-sm font-bold text-slate-500 font-mono">{formatCurrency(b.amountCents)}</span>
                  </div>
                </div>

                <div className="relative h-4 bg-[var(--ink)] rounded-full overflow-hidden border border-[var(--line)]">
                  <motion.div 
                    initial={{ width: 0 }}
                    animate={{ width: `${Math.min(b.percentUsed, 100)}%` }}
                    transition={{ duration: 1, ease: "easeOut" }}
                    className={cn(
                      "absolute inset-y-0 left-0 transition-colors",
                      isOver ? "bg-rose-500 shadow-[0_0_15px_#f43f5e]" : 
                      isWarning ? "bg-amber-500 shadow-[0_0_15px_#f59e0b]" : 
                      "bg-indigo-600 shadow-[0_0_15px_#10b981]"
                    )}
                  />
                </div>

                <div className="flex justify-between items-center text-[10px] font-medium uppercase tracking-wider">
                  <span className={cn(
                    isOver ? "text-rose-600" : isWarning ? "text-amber-600" : "text-emerald-600"
                  )}>
                    {b.percentUsed.toFixed(1)}% Capacity Utilization
                  </span>
                  <span className="text-slate-500 opacity-40">
                    {b.variance > 0 ? `Forensic Buffer: ${formatCurrency(b.variance)}` : 'Cap Threshold Breached'}
                  </span>
                </div>
              </div>

              <div className="mt-8 pt-6 border-t border-[var(--line)] flex justify-between items-center relative z-10">
                 <div className="flex items-center gap-2">
                    <Layers size={14} className="text-slate-500 opacity-30" />
                    <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest opacity-30">Analytical Snapshot Matrix</span>
                 </div>
                 <button 
                   onClick={() => {
                     setNewBudget({
                       targetId: b.targetId,
                       targetType: b.targetType as 'account',
                       amountCents: b.amountCents,
                       period: b.period,
                       startDate: b.startDate || getLocalDateISO()
                     });
                     setEditingBudget(b.id);
                     setIsAdding(true);
                   }}
                   className="w-10 h-10 bg-[var(--ink)] rounded-xl flex items-center justify-center text-slate-500 hover:text-[var(--text)] hover:bg-[var(--surface)] transition-all border border-[var(--line)] group-hover:scale-110" 
                   aria-label="Edit budget objective"
                 >
                    <ArrowUpRight size={18} />
                 </button>
              </div>
            </motion.div>
          );
        })}

        {budgets.length === 0 && (
          <div className="col-span-full py-32 text-center bg-[var(--surface)] rounded-[32px] border border-dashed border-[var(--line)] relative overflow-hidden group">
            <div className="absolute technical-grid inset-0 opacity-5 pointer-events-none" />
            <div className="relative z-10 flex flex-col items-center gap-6">
              <div className="w-24 h-24 bg-slate-200/20 rounded-[32px] flex items-center justify-center text-slate-500/30">
                <Target size={48} />
              </div>
              <div className="space-y-2">
