      )}

      {/* Bulk Synchronization Progress Success Modal */}
      <AnimatePresence>
        {showBulkSuccess && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center z-[250] p-4">
