import { useLedgerStore } from '../../stores/useLedgerStore';
import React,
 { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { Project, Transaction } from '../../types';
import { cn, formatCurrency } from '../../lib/utils';
import { GripVertical, CheckCircle, Target, Users, PlayCircle, Clock, Archive } from 'lucide-react';

interface ProjectPipelineProps {
  projects: Project[];

  onUpdateProject: (id: string, updates: Partial<Project>) => Promise<void>;
}

type PipelineStage = 'planning' | 'in_progress' | 'review' | 'completed' | 'archived';

const STAGES: { id: PipelineStage; label: string; icon: React.ElementType; color: string; borderColor: string }[] = [
  { id: 'planning', label: 'Planning', icon: Target, color: 'bg-slate-100 text-slate-700', borderColor: 'border-[var(--line)]' },
  { id: 'in_progress', label: 'In Progress', icon: PlayCircle, color: 'bg-indigo-100 text-indigo-700', borderColor: 'border-indigo-200' },
  { id: 'review', label: 'Review', icon: Clock, color: 'bg-amber-100 text-amber-700', borderColor: 'border-amber-200' },
  { id: 'completed', label: 'Completed', icon: CheckCircle, color: 'bg-emerald-100 text-emerald-700', borderColor: 'border-emerald-200' },
  { id: 'archived', label: 'Archived', icon: Archive, color: 'bg-stone-100 text-stone-700', borderColor: 'border-stone-200' }
];

export default function ProjectPipeline({ projects, onUpdateProject }: ProjectPipelineProps) {
  const transactions = useLedgerStore(state => state.transactions || []);

  const [draggedProjectId, setDraggedProjectId] = useState<string | null>(null);
  const [dragOverStage, setDragOverStage] = useState<string | null>(null);

  const handleDragStart = (e: React.DragEvent, id: string) => {
    e.dataTransfer.setData('text/plain', id);
    setDraggedProjectId(id);
  };

  const handleDragOver = (e: React.DragEvent, stageId: string) => {
    e.preventDefault();
    setDragOverStage(stageId);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOverStage(null);
  };

  const handleDrop = async (e: React.DragEvent, stageId: string) => {
    e.preventDefault();
    const id = e.dataTransfer.getData('text');
    setDragOverStage(null);
    setDraggedProjectId(null);

    const proj = projects.find(p => p.id === id);
    if (!proj || proj.pipelineStage === stageId) return;

    let newStatus: Project['status'];
    if (stageId === 'completed') newStatus = 'completed';
    else if (stageId === 'archived') newStatus = 'archived';
    else newStatus = 'active';

    await onUpdateProject(proj.id, { pipelineStage: stageId as PipelineStage, status: newStatus });
  };

  const grouped = useMemo(() => {
    const map: Record<PipelineStage, Project[]> = {
      planning: [],
      in_progress: [],
      review: [],
      completed: [],
      archived: []
    };

    projects.forEach(p => {
      const stage = p.pipelineStage || (p.status === 'completed' ? 'completed' : p.status === 'archived' ? 'archived' : 'planning');
      if (map[stage]) map[stage].push(p);
      else map['planning'].push(p);
    });

    Object.keys(map).forEach(key => {
      map[key as PipelineStage].sort((a, b) => (b.budgetCents || 0) - (a.budgetCents || 0));
    });

    return map;
  }, [projects]);

  const projectStats = useMemo(() => {
    const stats: Record<string, { actualCents: number, budgetCents: number, incomeCents: number, expenseCents: number }> = {};

    projects.forEach(p => {
      const projectTransactions = (transactions || []).filter(t => t.lines?.some(l => l.project === p.id));
      let income = 0;
      let expense = 0;

      projectTransactions.forEach(t => {
        t.lines?.filter(l => l.project === p.id).forEach(l => {
          const accName = (l.accountName || '').toLowerCase();
          if (accName.includes('income') || accName.includes('revenue')) {
            income += Math.abs(l.amountCents);
          } else if (accName.includes('expense') || accName.includes('cost')) {
            expense += Math.abs(l.amountCents);
          }
        });
      });

      stats[p.id] = {
        actualCents: income - expense,
        budgetCents: p.budgetCents,
        incomeCents: income,
        expenseCents: expense
      };
    });

    return stats;
  }, [projects, transactions]);

  return (
    <div className="flex gap-4 overflow-x-auto min-h-[700px] pb-8 custom-scrollbar pt-6">
      {STAGES.map((stage) => {
        const stageProjects = grouped[stage.id];
        const totalBudget = stageProjects.reduce((sum, p) => sum + (p.budgetCents || 0), 0);

        return (
          <div 
            key={stage.id} 
            className={cn(
              "flex-1 min-w-[340px] max-w-[380px] flex flex-col h-full rounded-[32px] border p-4 transition-all duration-300 relative",
              dragOverStage === stage.id ? "bg-slate-100 border-indigo-300 ring-4 ring-indigo-50" : "bg-[var(--ink)]/50 border-[var(--line)]/60"
            )}
            onDragOver={(e) => handleDragOver(e, stage.id)}
            onDragLeave={handleDragLeave}
            onDrop={(e) => handleDrop(e, stage.id)}
          >
            {/* Stage Header */}
            <div className="flex items-center justify-between mb-4 px-2">
              <div className="flex items-center gap-3">
                <div className={cn("w-10 h-10 rounded-[32px] flex items-center justify-center border shadow-xs transition-transform hover:scale-105", stage.color, stage.borderColor)}>
                  <stage.icon size={18} className="opacity-90" />
                </div>
                <div>
                  <h3 className="font-bold text-[var(--text)] tracking-tight">{stage.label}</h3>
                  <p className="text-[10px] font-medium uppercase tracking-wider text-slate-400 mt-0.5">{stageProjects.length} Projects</p>
                </div>
              </div>
            </div>

            <div className="px-2 mb-4 space-y-1">
              <div className="flex justify-between items-end">
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Total Budget</span>
                <span className="font-mono font-black text-[var(--text)] tracking-tighter">{formatCurrency(totalBudget)}</span>
              </div>
            </div>

            {/* Cards Area */}
            <div className="flex-1 space-y-4 relative overflow-y-auto pr-2 custom-scrollbar pb-20">
              <AnimatePresence>
                {stageProjects.map((project) => {
                  const stats = projectStats[project.id];
                  const progress = stats.budgetCents > 0 ? (stats.expenseCents / stats.budgetCents) * 100 : 0;

                  return (
                  <motion.div
                    layout
                    layoutId={project.id}
                    key={project.id}
                    draggable
                    onDragStart={(e: any) => handleDragStart(e, project.id!)}
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.9 }}
                    className={cn(
                      "bg-[var(--surface)] border rounded-[32px] p-5 cursor-grab active:cursor-grabbing hover:shadow-xl transition-all group relative overflow-hidden",
                      draggedProjectId === project.id ? "opacity-50 border-slate-300 border-dashed" : "border-[var(--line)]/80 shadow-sm hover:border-slate-300"
                    )}
                  >
                    <div className="flex items-start justify-between mb-4">
                      <div>
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">{project.type}</p>
                        <h4 className="font-black text-[var(--text)] leading-tight">{project.name}</h4>
                      </div>
                      <GripVertical size={14} className="text-slate-300 opacity-100 md:opacity-0 md:group-hover:opacity-100 transition-opacity" />
                    </div>

                    <div className="pt-4 border-t border-[var(--line)] space-y-3">
                      <div className="flex items-end justify-between">
                        <div className="space-y-1">
                          <p className="text-[8px] font-bold uppercase tracking-wider text-slate-400">Budget</p>
                          <p className="text-xs font-bold text-[var(--text)] font-mono">
                            {formatCurrency(stats.budgetCents)}
                          </p>
                        </div>
                        <div className="text-right">
                           <p className="text-[8px] font-bold uppercase tracking-wider text-slate-400">Spent</p>
                          <span className="text-xs font-black font-mono tracking-tighter text-slate-600">
                            {formatCurrency(stats.expenseCents)}
                          </span>
                        </div>
                      </div>

                      {/* Progress representation */}
                      <div className="h-1 w-full bg-slate-100 rounded-full overflow-hidden">
                        <div 
                          className={cn(
                            "h-full rounded-full transition-all",
                            progress > 100 ? "bg-rose-500" : progress > 75 ? "bg-amber-500" : "bg-emerald-500"
                          )}
                          style={{ width: `${Math.min(progress, 100)}%` }}
                        />
                      </div>
                      <div className="flex justify-between items-center text-[9px] font-medium uppercase tracking-wider text-slate-400">
                         <span>{progress.toFixed(0)}% Used</span>
                         <div className="flex items-center gap-1"><Users size={10} /> {(project.splitRules || []).length || 1} Mbrs</div>
                      </div>
                    </div>
                  </motion.div>
                )})}
              </AnimatePresence>

              {/* Empty state for the column */}
              {stageProjects.length === 0 && (
                <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center justify-center text-center opacity-40 w-full h-full pointer-events-none">
                   <div className="w-12 h-12 bg-slate-100 rounded-[32px] border-2 border-[var(--line)] border-dashed flex items-center justify-center mb-3">
                     <stage.icon size={20} className="text-slate-400" />
                   </div>
                   <p className="text-[10px] font-medium uppercase tracking-wider text-slate-500">Drop Here</p>
                </div>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { User } from 'firebase/auth';
import { Project, Transaction, Budget, Vendor } from '../../types';
import { 
  BrainCircuit,
  Pencil,
  Plus, 
  Search, 
  FolderKanban, 
  Trash2,
  Target,
  Users,
  BookOpen,
  DollarSign,
  BarChart3,
  Calendar,
  LayoutDashboard,
  List
} from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';
import { cn, safeConfirm, parseAmountToCents } from '../../lib/utils';
import { resolveAccountRole } from '../../lib/accountUtils';
import AsyncButton from '../ui/AsyncButton';
import { toast } from 'sonner';
import ProjectPipeline from './ProjectPipeline';

import { useAuthStore } from '../../stores/useAuthStore';
import { useLedgerStore } from '../../stores/useLedgerStore';
import { useCommandDispatcher } from '../../hooks/useSystemContext';
import { useEntityOperations } from '../../hooks/useEntityOperations';

export default function Projects() {
  const user = useAuthStore(s => s.user);
  const projects = useLedgerStore(s => s.projects);
  const transactions = useLedgerStore(s => s.transactions);
  const accounts = useLedgerStore(s => s.accounts);
  const bills = useLedgerStore(s => s.bills);
  const budgets = useLedgerStore(s => s.budgets);
  const vendors = useLedgerStore(s => s.vendors);
  const { handleAction: onAction } = useCommandDispatcher();
  const { addEntity, updateEntity, deleteEntity } = useEntityOperations();
  const onAdd = (data: any) => addEntity('projects', data);
  const onUpdate = (id: string, data: any) => updateEntity('projects', id, data);
  const onDelete = (id: string) => deleteEntity('projects', id);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeSubTab, setActiveSubTab] = useState<'pipeline' | 'list'>('pipeline');
  const [isNewProjectModalOpen, setIsNewProjectModalOpen] = useState(false);
  const [editingProject, setEditingProject] = useState<Project | null>(null);
  const [loading, setLoading] = useState(false);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);

  const [newProject, setNewProject] = useState<Partial<Project>>({
    name: '',
    description: '',
    type: 'general',
    status: 'active',
    budgetCents: 0
  });

  const handleAddProject = async () => {
    if (!newProject.name || !onAdd) return;
    setLoading(true);
    try {
      await onAdd({
        ...newProject,
        uid: user?.uid || "",
        createdAt: new Date().toISOString()
      });
      setIsNewProjectModalOpen(false);
      setNewProject({
        name: '',
        description: '',
        type: 'general',
        status: 'active',
        budgetCents: 0
      });
      toast.success('Project initialized successfully');
    } catch (err) {
      toast.error('Failed to initialize project');
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateProject = async () => {
    if (!editingProject || !onUpdate) return;
    setLoading(true);
    try {
      await onUpdate(editingProject.id, editingProject);
      setEditingProject(null);
      toast.success('Project updated successfully');
    } catch (err) {
      toast.error('Failed to update project');
    } finally {
      setLoading(false);
    }
  };

  const isProjectLine = (l: any, p: Project) => {
    if (!l || !p) return false;
    return l.project === p.id || 
           l.project === p.name || 
           l.dimensions?.project === p.id || 
           l.dimensions?.project === p.name;
  };

  const isProjectTx = (t: Transaction, p: Project) => {
    if (!t || !p) return false;
    return t.projectId === p.id || 
           t.project === p.id || 
           t.project === p.name || 
           (t.lines && t.lines.some(l => isProjectLine(l, p)));
  };

  const handleDeleteProject = async (id: string) => {
    if (!onDelete) return;
    const project = projects.find(p => p.id === id);
    if (!project) return;

    const referencingTxs = transactions.filter(t => isProjectTx(t, project));
    const referencingBills = (bills || []).filter(b => b.projectId === id || b.metadata?.projectId === id);

    let confirmMsg = 'Are you sure you want to delete this project?';
    if (referencingTxs.length > 0 || referencingBills.length > 0) {
      confirmMsg = `Warning: ${referencingTxs.length} transaction(s) and ${referencingBills.length} bill(s) reference "${project.name}". Deleting this project will unlink these financial records. Do you still wish to proceed?`;
    }

    if (!safeConfirm(confirmMsg)) return;
    try {
      await onDelete(id);
      if (selectedProjectId === id) setSelectedProjectId(null);
      toast.success('Project deleted successfully');
    } catch (err) {
      toast.error('Deletion failed');
    }
  };

  const filteredProjects = useMemo(() => {
    return projects.filter(p => {
      const term = searchTerm.toLowerCase();
      if (!term) return true;
      const searchStr = `${p.name || ''} ${p.description || ''} ${p.tags?.join(' ') || ''} ${p.metadata ? JSON.stringify(p.metadata) : ''}`.toLowerCase();
      return searchStr.includes(term);
    });
  }, [projects, searchTerm]);

  const projectStats = useMemo(() => {
    const stats: Record<string, { actualCents: number, budgetCents: number, incomeCents: number, expenseCents: number }> = {};
    const accountsMap = new Map(accounts.map(a => [a.id, a]));

    projects.forEach(p => {
      const projectTransactions = transactions.filter(t => isProjectTx(t, p));
      let income = 0;
      let expense = 0;

      projectTransactions.forEach(t => {
        const matchingLines = t.lines?.filter(l => isProjectLine(l, p) || t.projectId === p.id) || [];
        matchingLines.forEach(l => {
          const acc = accountsMap.get(l.accountId);
          const role = resolveAccountRole(acc);
          const accName = (l.accountName || acc?.name || '').toLowerCase();
          const amt = l.amountCents || 0;

          if (role === 'revenue' || acc?.type === 'income' || acc?.type === 'revenue') {
            // Revenue in double-entry is negative (credit)
            income += amt < 0 ? -amt : amt;
          } else if (role === 'expense' || role === 'cogs' || acc?.type === 'expense' || acc?.type === 'cost_of_goods') {
            // Expense in double-entry is positive (debit)
            expense += amt > 0 ? amt : -amt;
          } else if (accName.includes('income') || accName.includes('revenue') || accName.includes('sales')) {
            income += Math.abs(amt);
          } else if (accName.includes('expense') || accName.includes('cost') || accName.includes('cogs')) {
            expense += Math.abs(amt);
          }
        });
      });

      stats[p.id] = {
        actualCents: income - expense,
        budgetCents: p.budgetCents || 0,
        incomeCents: income,
        expenseCents: expense
      };
    });

    return stats;
  }, [projects, transactions, accounts]);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('en-US', { 
      style: 'currency', 
      currency: 'USD',
      minimumFractionDigits: 2
    }).format(val / 100);

  const selectedProject = useMemo(() => 
    projects.find(p => p.id === selectedProjectId), 
  [projects, selectedProjectId]);

  const projectVendors = useMemo(() => {
    if (!selectedProjectId) return [];
    const selectedP = projects.find(p => p.id === selectedProjectId);
    if (!selectedP) return [];

    const vendorIds = new Set<string>();

    transactions.forEach(t => {
      if (isProjectTx(t, selectedP)) {
        if (t.metadata?.vendorId) {
          vendorIds.add(t.metadata.vendorId);
        }
        if (t.payee) {
          const matched = vendors.find(v => v.name.toLowerCase() === t.payee?.toLowerCase());
          if (matched) vendorIds.add(matched.id);
        }
      }
    });

    (bills || []).forEach(b => {
      if (b.projectId === selectedProjectId || b.metadata?.projectId === selectedProjectId) {
        if (b.vendorId) vendorIds.add(b.vendorId);
      }
    });

    return vendors.filter(v => vendorIds.has(v.id));
  }, [selectedProjectId, projects, transactions, bills, vendors]);

  return (
    <div className="space-y-6 max-w-[1600px] mx-auto pb-12">
      {/* Header with brand gold backdrop */}
      <div className="relative overflow-hidden bg-gradient-to-r from-[var(--brass-soft)] via-[var(--surface)]/40 to-[var(--panel)] p-6 rounded-2xl border border-[var(--brass-line)]/50 shadow-sm">
        <div className="absolute -top-16 -left-16 w-56 h-56 bg-[var(--brass)] opacity-10 rounded-full blur-3xl hidden md:block pointer-events-none" />
        <div className="relative z-10 flex flex-col lg:flex-row lg:items-center justify-between gap-6">
          <div>
            <div className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-[var(--brass-soft)] border border-[var(--brass-line)]/60 text-[10px] font-mono text-[var(--brass)] font-semibold mb-2 shadow-xs">
              <FolderKanban size={12} />
              DIMENSIONAL COST ARCHITECTURE
            </div>
            <h1 className="text-2xl sm:text-3xl font-bold text-[var(--text)] tracking-tight">Project & Initiative Tracking</h1>
            <p className="text-xs text-[var(--muted)] font-medium mt-1">Initiative performance management paired with multi-rule split protocol tracing.</p>
          </div>

          <div className="flex flex-wrap items-center gap-3 shrink-0">
            <div className="flex items-center bg-[var(--surface)]/80 p-1 rounded-xl border border-[var(--line)] shadow-inner backdrop-blur-sm">
              <button
                onClick={() => setActiveSubTab('pipeline')}
                className={cn(
                  "px-3 py-1.5 rounded-lg text-xs font-semibold uppercase tracking-wider transition-all gap-1.5 flex items-center cursor-pointer",
                  activeSubTab === 'pipeline' 
                    ? "bg-gradient-to-r from-[var(--brass)] via-[#e5be6b] to-[var(--brass)] text-black font-bold shadow-sm" 
                    : "text-[var(--muted)] hover:text-[var(--text)]"
                )}
              >
                 <LayoutDashboard size={13} /> Board
              </button>
              <button
                onClick={() => setActiveSubTab('list')}
                className={cn(
                  "px-3 py-1.5 rounded-lg text-xs font-semibold uppercase tracking-wider transition-all gap-1.5 flex items-center cursor-pointer",
                  activeSubTab === 'list' 
                    ? "bg-gradient-to-r from-[var(--brass)] via-[#e5be6b] to-[var(--brass)] text-black font-bold shadow-sm" 
                    : "text-[var(--muted)] hover:text-[var(--text)]"
                )}
              >
                <List size={13} /> List
              </button>
            </div>
            <div className="relative group">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[var(--muted)] group-focus-within:text-[var(--brass)] transition-colors" size={14} />
              <input 
                type="text"
                placeholder="Search projects or tags..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-9 pr-4 py-2 bg-[var(--surface)] border border-[var(--line)] rounded-xl text-xs focus:outline-none focus:border-[var(--brass-line)] focus:ring-1 focus:ring-[var(--brass)] transition-all w-52 sm:w-60 text-[var(--text)] placeholder:text-[var(--faint)] font-medium"
              />
            </div>
            <button 
              onClick={() => setIsNewProjectModalOpen(true)}
              className="h-9 px-4 bg-gradient-to-r from-[var(--brass)] via-[#e5be6b] to-[var(--brass)] text-black hover:opacity-95 rounded-xl text-xs font-bold transition-all active:scale-95 flex items-center gap-1.5 shadow-md hover:shadow-lg cursor-pointer"
            >
              <Plus size={15} />
              Initialize Project
            </button>
          </div>
        </div>
      </div>

      {activeSubTab === 'pipeline' ? (
         <ProjectPipeline 
           projects={filteredProjects}
           onUpdateProject={async (id, data) => { if (onUpdate) await onUpdate(id, data); }}
         />
      ) : (
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        {/* Project List */}
        <div className="xl:col-span-2 space-y-3">
          {filteredProjects.map((project) => {
            const stats = projectStats[project.id];
            const progress = stats.budgetCents > 0 ? (stats.expenseCents / stats.budgetCents) * 100 : 0;

            return (
              <motion.div 
                key={project.id}
                layoutId={project.id}
                onClick={() => setSelectedProjectId(project.id)}
                className={cn(
                  "p-5 rounded-xl border transition-all cursor-pointer group relative overflow-hidden",
                  selectedProjectId === project.id 
                    ? "bg-slate-900 border-slate-950 text-white shadow-xs" 
                    : "bg-[var(--surface)] border-[var(--line)]/80 hover:border-slate-300 text-[var(--text)] shadow-3xs"
                )}
              >
                {selectedProjectId === project.id && (
                  <div className="absolute inset-0 technical-grid opacity-10 pointer-events-none" />
                )}

                  <div className="flex items-start justify-between mb-4 relative z-10">
                    <div className="flex items-center gap-4">
                      <div className={cn(
                        "w-10 h-10 rounded-lg flex items-center justify-center transition-all",
                        selectedProjectId === project.id ? "bg-[var(--surface)]/10" : "bg-slate-100 border border-[var(--line)]/40"
                      )}>
                        <FolderKanban size={18} className={selectedProjectId === project.id ? "text-orange-300" : "text-slate-600"} />
                      </div>
                      <div dir="auto">
                        <h3 className="font-bold text-sm tracking-tight">{project.name}</h3>
                        <div className="flex items-center gap-1.5 mt-1">
                          <span className={cn("px-1.5 py-0.5 rounded text-[8px] font-bold uppercase tracking-wider", selectedProjectId === project.id ? "bg-[var(--surface)]/10 text-white" : "bg-slate-100 text-slate-600")}>
                            {project.type}
                          </span>
                          <span className={cn("px-1.5 py-0.5 rounded text-[8px] font-bold uppercase tracking-wider border", selectedProjectId === project.id ? "border-white/10 text-white/80" : "border-[var(--line)] text-slate-400")}>
                            {project.status}
                          </span>
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-4">
                      <div className="flex items-center gap-1 bg-[var(--surface)]/5 p-0.5 rounded-lg border border-slate-250/10">
                        <button 
                          onClick={(e) => {
                            e.stopPropagation();
                            setEditingProject(project);
                          }}
                          className={cn(
                            "p-1.5 rounded-md transition-all",
                            selectedProjectId === project.id ? "text-white/80 hover:text-white hover:bg-[var(--surface)]/10" : "text-slate-400 hover:text-[var(--text)] hover:bg-[var(--ink)]"
                          )}
                        >
                          <Pencil size={12} />
                        </button>
                        <AsyncButton 
                          onClick={async () => {
                            handleDeleteProject(project.id);
                          }}
                          className={cn(
                            "p-1.5 rounded-md transition-all",
                            selectedProjectId === project.id ? "text-white/80 hover:text-red-400 hover:bg-[var(--surface)]/10" : "text-slate-400 hover:text-rose-600 hover:bg-rose-50/50"
                          )}
                        >
                          <Trash2 size={12} />
                        </AsyncButton>
                      </div>
                      <div className="text-right">
                        <p className={cn("text-[9px] font-bold uppercase tracking-wider mb-0.5", selectedProjectId === project.id ? "text-white/60" : "text-slate-400")}>Net Impact</p>
                        <p className={cn("text-base font-bold font-mono tracking-tight", stats.actualCents < 0 ? (selectedProjectId === project.id ? "text-rose-300" : "font-semibold text-rose-700") : (selectedProjectId === project.id ? "text-emerald-300" : "font-semibold text-emerald-700"))}>
                          {formatCurrency(stats.actualCents)}
                        </p>
                      </div>
                    </div>
                  </div>

                <div className="grid grid-cols-3 gap-4 mb-4 relative z-10 pt-2 border-t border-[var(--line)]/10">
                  <div className="space-y-0.5">
                    <p className={cn("text-[8px] font-bold uppercase tracking-wider", selectedProjectId === project.id ? "text-white/60" : "text-slate-400")}>Allocated</p>
                    <p className="font-semibold font-mono text-xs">{formatCurrency(stats.budgetCents)}</p>
                  </div>
                  <div className="space-y-0.5">
                    <p className={cn("text-[8px] font-bold uppercase tracking-wider", selectedProjectId === project.id ? "text-white/60" : "text-slate-400")}>Cost Burn</p>
                    <p className="font-semibold font-mono text-xs">{formatCurrency(stats.expenseCents)}</p>
                  </div>
                  <div className="space-y-0.5">
                    <p className={cn("text-[8px] font-bold uppercase tracking-wider", selectedProjectId === project.id ? "text-white/60" : "text-slate-400")}>Usage</p>
                    <p className="font-semibold font-mono text-xs">{progress.toFixed(1)}%</p>
                  </div>
                </div>

                {/* Progress Bar */}
                <div className={cn("h-1 w-full rounded-full overflow-hidden relative z-10", selectedProjectId === project.id ? "bg-[var(--surface)]/10" : "bg-slate-100")}>
                  <motion.div 
                    initial={{ width: 0 }}
                    animate={{ width: `${Math.min(progress, 100)}%` }}
                    className={cn(
                      "h-full rounded-full",
                      selectedProjectId === project.id 
                        ? "bg-[var(--surface)]" 
                        : (progress > 90 ? "bg-rose-500" : progress > 70 ? "bg-amber-500" : "bg-slate-900")
                    )}
                  />
                </div>
              </motion.div>
            );
          })}
        </div>

        {/* Project Detail Sidebar */}
        <div className="space-y-4">
          <AnimatePresence mode="wait">
            {selectedProject ? (
              <motion.div 
                key={selectedProject.id}
                initial={{ opacity: 0, scale: 0.98 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.98 }}
                className="bg-[var(--surface)] rounded-xl border border-[var(--line)]/80 shadow-3xs p-5 relative overflow-hidden"
              >
                <div className="absolute inset-0 technical-grid opacity-[0.01] pointer-events-none" />
                <div className="relative z-10">
                  <div className="flex items-center justify-between mb-4 pb-2 border-b border-[var(--line)]">
                    <div>
                      <h4 className="text-xs font-bold uppercase tracking-widest text-slate-400">Collaborators</h4>
                      <h3 className="text-sm font-black text-[var(--text)] tracking-tight mt-0.5">{selectedProject.name}</h3>
                    </div>
                    <div className="w-8 h-8 bg-[var(--ink)] border border-[var(--line)]/60 rounded-lg flex items-center justify-center">
                      <Users size={14} className="text-slate-500" />
                    </div>
                  </div>

                  <div className="space-y-2">
                    {projectVendors.length > 0 ? projectVendors.map(vendor => (
                      <div key={vendor.id} className="flex items-center justify-between p-3 bg-[var(--ink)] rounded-xl border border-[var(--line)]/60 hover:border-slate-300 transition-all">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-lg bg-slate-900 flex items-center justify-center text-white font-black text-xs shadow-3xs">
                            {vendor.name[0]}
                          </div>
                          <div>
                            <p className="text-xs font-bold text-[var(--text)]">{vendor.name}</p>
                            <p className="text-[8px] text-[var(--muted)] uppercase tracking-wider font-bold">{vendor.type}</p>
                          </div>
                        </div>
                        <div className="text-right">
                          <p className="text-xs font-bold font-mono text-[var(--text)] col-span-1">
                            {formatCurrency(
                              transactions.filter(t => 
                                selectedProject && isProjectTx(t, selectedProject) && 
                                (t.metadata?.vendorId === vendor.id || t.payee?.toLowerCase() === vendor.name.toLowerCase())
                              ).reduce((sum, t) => sum + Math.abs(t.totalAmountCents), 0)
                            )}
                          </p>
                          <p className="text-[8px] text-[var(--muted)] uppercase tracking-wider">Settled</p>
                        </div>
                      </div>
                    )) : (
                      <div className="text-center py-10 bg-[var(--ink)]/50 rounded-xl border border-dashed border-[var(--line)]">
                        <div className="w-10 h-10 bg-[var(--ink)] border border-[var(--line)] rounded-lg flex items-center justify-center mx-auto mb-3 opacity-60">
                          <BrainCircuit size={18} className="text-[var(--muted)]" />
                        </div>
                        <p className="text-[10px] font-bold text-[var(--muted)] uppercase tracking-wider">No active project members</p>
                      </div>
                    )}
                  </div>

                  <div className="mt-5 pt-4 border-t border-[var(--line)]">
                    <div className="flex items-center gap-2 mb-3">
                      <div className="w-1.5 h-4 bg-[var(--brass)] rounded-full" />
                      <h3 className="text-xs font-bold uppercase tracking-wider text-[var(--text)]">Split Tranches</h3>
                    </div>

                    <div className="space-y-3">
                      {selectedProject.splitRules?.map((rule, idx) => (
                        <div key={idx} className="space-y-1">
                          <div className="flex items-center justify-between">
                            <span className="text-[10px] font-semibold text-[var(--muted)]">{rule.partnerName}</span>
                            <span className="text-[10px] font-bold font-mono text-[var(--text)]">{rule.percentage}%</span>
                          </div>
                          <div className="h-1 w-full bg-[var(--line)] rounded-full overflow-hidden">
                            <div className="h-full bg-[var(--brass)]" style={{ width: `${rule.percentage}%` }} />
                          </div>
                        </div>
                      ))}
                      {!selectedProject.splitRules?.length && (
                        <p className="text-[10px] text-slate-400 font-bold italic">No split allocations configured.</p>
                      )}
                    </div>
                  </div>

                  <div className="mt-6 pt-4 border-t border-[var(--line)]">
                    <button className="w-full h-10 bg-slate-900 hover:bg-slate-800 text-white rounded-xl font-bold uppercase tracking-wider text-[9px] transition-all flex items-center justify-center gap-2 shadow-3xs cursor-pointer" aria-label="Generate Brief">
                      <BarChart3 size={12} className="text-slate-300" />
                      Generate Brief
                    </button>
                  </div>
                </div>
              </motion.div>
            ) : (
              <div className="bg-slate-100/30 rounded-xl border border-dashed border-[var(--line)] p-4 md:p-8 text-center h-full flex flex-col items-center justify-center">
