import { TruthEngine } from '../../modules/integrity/TruthEngine';
import React, { useState } from 'react';
import { X, Plus, Trash2, Save, CreditCard, Sparkles } from 'lucide-react';
import { motion } from 'motion/react';
import { Bill, Vendor, ChartAccount } from '../../types';
import { format } from 'date-fns';
import { toast } from 'sonner';
import { useLedgerStore } from '../../stores/useLedgerStore';
import AsyncButton from '../ui/AsyncButton';

interface BillModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (bill: Partial<Bill>) => void;
  vendors: Vendor[];
  accounts: ChartAccount[];
}

export default function BillModal({ isOpen, onClose, onSave, vendors = [], accounts = [] }: BillModalProps) {
  // Ensure we have arrays even if props were passed as null
  const safeVendors = Array.isArray(vendors) ? vendors : [];
  const safeAccounts = Array.isArray(accounts) ? accounts.filter(a => a?.type === 'expense' || a?.type === 'cost_of_goods' || a?.type === 'asset') : [];

  const storeBills = useLedgerStore(s => s.bills) || [];
  const storeTransactions = useLedgerStore(s => s.transactions) || [];
  const [autofillNotice, setAutofillNotice] = useState<string | null>(null);

  const [bill, setBill] = useState<Partial<Bill>>(() => ({
    number: `BILL-${Date.now().toString().slice(-6)}`,
    date: format(new Date(), 'yyyy-MM-dd'),
    dueDate: format(new Date(), 'yyyy-MM-dd'),
    status: 'pending',
    amountCents: 0
  }));

  const [splits, setSplits] = useState<Array<{ id: string, amountCents: number, accountId: string, description: string }>>([
    { id: crypto.randomUUID(), amountCents: 0, accountId: '', description: '' }
  ]);

  const [memo, setMemo] = useState('');
  const [attachments, setAttachments] = useState<File[]>([]);

  const total = splits.reduce((sum, split) => sum + split.amountCents, 0);

  const handleVendorSelect = (vendorId: string) => {
    const vend = safeVendors.find(v => v.id === vendorId);
    setBill(prev => ({ ...prev, vendorId, vendorName: vend?.name }));
    setAutofillNotice(null);

    if (!vendorId) return;

    // Look for last used account for this vendor from previous bills
    let foundAccountId = '';
    let foundDesc = '';

    const prevBill = storeBills.find(b => b.vendorId === vendorId && b.splits && b.splits.length > 0 && b.splits[0].accountId);
    if (prevBill && prevBill.splits?.[0]?.accountId) {
      foundAccountId = prevBill.splits[0].accountId;
      foundDesc = prevBill.splits[0].description || '';
    } else {
      // Look in transaction history
      const prevTx = storeTransactions.find(t => 
        (((t as any).vendorId === vendorId || (t.metadata as any)?.vendorId === vendorId) || (vend && t.description?.toLowerCase().includes(vend.name.toLowerCase()))) &&
        t.lines && t.lines.length > 0
      );
      if (prevTx && prevTx.lines) {
        const matchingLine = prevTx.lines.find(l => accounts.some(a => a.id === l.accountId && (a.type === 'expense' || a.type === 'cost_of_goods'))) || prevTx.lines[0];
        if (matchingLine) {
          foundAccountId = matchingLine.accountId;
          foundDesc = prevTx.description || '';
        }
      }
    }

    if (foundAccountId) {
      const targetAcc = accounts.find(a => a.id === foundAccountId);
      setSplits(prev => {
        const next = [...prev];
        if (next.length > 0) {
          next[0] = {
            ...next[0],
            accountId: foundAccountId,
            description: next[0].description || foundDesc || `${vend?.name || 'Vendor'} expense`
          };
        }
        return next;
      });
      if (targetAcc) {
        setAutofillNotice(`Auto-filled account: ${targetAcc.name}`);
        toast.info(`⚡ Auto-filled account "${targetAcc.name}" from previous ${vend?.name || 'vendor'} history.`);
      }
    }
  };

  const handleAction = async (e: React.FormEvent, actionStatus: string) => {
    e.preventDefault();
    if (!bill.vendorId) {
      toast.error('Please select a vendor');
      return;
    }

    if (attachments.length > 0) {
      toast.success(`${attachments.length} file(s) attached`);
    }

    await onSave({
      ...bill,
      status: actionStatus as any,
      amountCents: total,
      splits,
      metadata: {
        memo,
        hasAttachments: attachments.length > 0
      }
    });
  };

  const handleSubmit = (e: React.FormEvent) => handleAction(e, bill.status || 'pending');

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setAttachments([...attachments, ...Array.from(e.target.files)]);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[600] flex items-center justify-center p-4">
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        onClick={onClose}
        className="absolute inset-0 bg-zinc-900/40 backdrop-blur-sm"
      />

      <motion.div
        initial={{ opacity: 0, scale: 0.95, y: 20 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.95, y: 20 }}
        className="relative w-full max-w-4xl bg-[var(--surface)] rounded-[40px] shadow-2xl border border-[var(--line)] overflow-hidden flex flex-col max-h-[90dvh]"
      >
        <div className="p-4 md:p-8 border-b border-[var(--line)] flex items-center justify-between bg-[var(--ink)]/50">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-zinc-900 text-white rounded-[32px] flex items-center justify-center shadow-xl shadow-zinc-900/20">
              <CreditCard size={24} />
            </div>
            <div>
              <h3 className="text-2xl font-black text-[var(--text)] tracking-tight">Record New Bill</h3>
              <p className="text-xs text-zinc-500 font-bold uppercase tracking-widest">Purchases & Payables</p>
            </div>
          </div>
          <button aria-label="Close" onClick={onClose} className="p-2 hover:bg-zinc-100 rounded-full transition-colors text-zinc-400"><X size={24} /></button>
        </div>

        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 custom-scrollbar">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <label className="micro-label">Vendor</label>
                {autofillNotice && (
                  <span className="text-[10px] font-bold text-amber-600 bg-amber-50 px-2 py-0.5 rounded-full flex items-center gap-1 border border-amber-200">
                    <Sparkles size={10} /> Auto-filled
                  </span>
                )}
              </div>
              <select 
                required
                value={bill.vendorId || ''}
                onChange={(e) => handleVendorSelect(e.target.value)}
                className="w-full px-5 py-3.5 bg-[var(--ink)] border border-[var(--line)] rounded-[32px] focus:ring-2 focus:ring-zinc-900 outline-none font-bold"
              >
                <option value="">Select Vendor</option>
                {safeVendors.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="micro-label">Bill Number</label>
              <input 
                type="text"
                required
                value={bill.number}
                onChange={(e) => setBill({ ...bill, number: e.target.value })}
                className="w-full px-5 py-3.5 bg-[var(--ink)] border border-[var(--line)] rounded-[32px] focus:ring-2 focus:ring-zinc-900 outline-none font-mono font-bold"
              />
            </div>
            <div className="space-y-2">
              <label className="micro-label">Status</label>
              <select 
                value={bill.status}
                onChange={(e) => setBill({ ...bill, status: e.target.value as any })}
                className="w-full px-5 py-3.5 bg-[var(--ink)] border border-[var(--line)] rounded-[32px] focus:ring-2 focus:ring-zinc-900 outline-none font-bold"
              >
                <option value="pending">Pending</option>
                <option value="unpaid">Unpaid</option>
                <option value="paid">Paid</option>
                <option value="overdue">Overdue</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="micro-label">Bill Date</label>
              <input 
                type="date"
                required
                value={bill.date}
                onChange={(e) => setBill({ ...bill, date: e.target.value })}
                className="w-full px-5 py-3.5 bg-[var(--ink)] border border-[var(--line)] rounded-[32px] focus:ring-2 focus:ring-zinc-900 outline-none font-bold"
              />
            </div>
            <div className="space-y-2">
              <label className="micro-label">Due Date</label>
              <input 
                type="date"
                required
                value={bill.dueDate}
                onChange={(e) => setBill({ ...bill, dueDate: e.target.value })}
                className="w-full px-5 py-3.5 bg-[var(--ink)] border border-[var(--line)] rounded-[32px] focus:ring-2 focus:ring-zinc-900 outline-none font-bold"
              />
            </div>
          </div>

          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h4 className="micro-label">Expense Allocation</h4>
              <button 
                type="button"
                onClick={() => setSplits([...splits, { id: crypto.randomUUID(), amountCents: 0, accountId: '', description: '' }])}
                className="flex items-center gap-2 px-4 py-2 bg-zinc-100 text-zinc-600 rounded-xl text-[10px] font-medium uppercase tracking-wider hover:bg-zinc-200 transition-all"
              >
                <Plus size={14} />
                Add Split
              </button>
            </div>

            <div className="space-y-3">
              {splits.map((split, idx) => (
                <div key={split.id} className="grid grid-cols-12 gap-4 items-end bg-[var(--ink)] p-4 rounded-[32px] border border-[var(--line)]">
                  <div className="col-span-5 space-y-1">
                    <label className="text-[10px] font-bold text-zinc-400 uppercase">Description</label>
                    <input 
                      type="text"
                      value={split.description}
                      onChange={(e) => {
                        const newSplits = [...splits];
                        newSplits[idx].description = e.target.value;
                        setSplits(newSplits);
                      }}
                      placeholder="What was this for?"
                      className="w-full px-4 py-2 bg-[var(--surface)] border border-[var(--line)] rounded-xl outline-none focus:ring-2 focus:ring-zinc-900"
                    />
                  </div>
                  <div className="col-span-3 space-y-1">
                    <label className="text-[10px] font-bold text-zinc-400 uppercase">Expense Account</label>
                    <select 
                      value={split.accountId}
                      onChange={(e) => {
                        const newSplits = [...splits];
                        newSplits[idx].accountId = e.target.value;
                        setSplits(newSplits);
                      }}
                      className="w-full px-4 py-2 bg-[var(--surface)] border border-[var(--line)] rounded-xl outline-none focus:ring-2 focus:ring-zinc-900"
                    >
                      <option value="">Select Account</option>
                      {safeAccounts.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                    </select>
                  </div>
                  <div className="col-span-3 space-y-1">
                    <label className="text-[10px] font-bold text-zinc-400 uppercase">Amount ($)</label>
                    <input 
                      type="number"
                      step="0.01"
                      value={split.amountCents / 100}
                      onChange={(e) => {
                        const newSplits = [...splits];
                        newSplits[idx].amountCents = TruthEngine.parseAmountToCents(e.target.value || '0');
                        setSplits(newSplits);
                      }}
                      className="w-full px-4 py-2 bg-[var(--surface)] border border-[var(--line)] rounded-xl outline-none focus:ring-2 focus:ring-zinc-900 font-mono"
                    />
                  </div>
                  <div className="col-span-1 pb-1">
                    <button 
                      type="button"
                      onClick={() => setSplits(splits.filter((_, i) => i !== idx))}
                      className="p-2 text-zinc-300 hover:text-rose-500 transition-colors"
                    >
                      <Trash2 size={18} />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 border-t border-[var(--line)] pt-8 mt-8">
            <div className="space-y-4">
              <div className="space-y-2">
                <label className="micro-label">Internal Memo</label>
                <textarea 
                  value={memo}
                  onChange={(e) => setMemo(e.target.value)}
                  placeholder="Notes about this bill..."
                  className="w-full px-4 py-3 bg-[var(--ink)] border border-[var(--line)] rounded-xl focus:ring-2 focus:ring-zinc-900 outline-none resize-none h-24"
                />
              </div>
            </div>
            <div className="space-y-4">
              <div className="space-y-2">
                <label className="micro-label">Attachments & Receipts</label>
                <div className="flex items-center gap-4">
                   <label className="cursor-pointer flex items-center justify-center w-full px-4 py-3 bg-[var(--ink)] border-2 border-dashed border-zinc-300 rounded-xl hover:bg-zinc-100 transition-colors">
                     <span className="text-xs font-bold text-zinc-500 uppercase tracking-widest">Select Files</span>
                     <input type="file" multiple className="hidden" onChange={handleFileUpload} />
                   </label>
                </div>
                {attachments.length > 0 && (
                  <div className="flex flex-wrap gap-2 mt-2">
                     {attachments.map((f, i) => (
                       <span key={i} className="px-2 py-1 bg-zinc-100 text-zinc-600 text-xs rounded-lg">{f.name}</span>
                     ))}
                  </div>
                )}
              </div>
            </div>
          </div>
        </form>

        <div className="p-4 md:p-8 border-t border-[var(--line)] bg-[var(--ink)]/50 flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="flex flex-col w-full sm:w-auto">
            <span className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest">Total Bill Amount</span>
            <span className="text-3xl font-black text-[var(--text)] font-mono">
              {(total / 100).toLocaleString('en-US', { style: 'currency', currency: 'USD' })}
            </span>
          </div>
          <div className="flex flex-wrap items-center justify-end gap-3 w-full sm:w-auto">
            <button 
              type="button"
              onClick={onClose}
              className="px-6 py-3.5 bg-[var(--surface)] border border-[var(--line)] text-zinc-600 rounded-[32px] font-medium uppercase tracking-wider text-[10px] hover:bg-[var(--ink)] transition-all"
             aria-label="Cancel">
              Cancel
            </button>
            <AsyncButton 
              type="button"
              onClick={(e) => handleAction(e, 'draft')}
              loadingText="Saving..."
              className="px-6 py-3.5 bg-zinc-100 text-zinc-700 rounded-[32px] font-medium uppercase tracking-wider text-[10px] hover:bg-zinc-200 transition-all flex items-center gap-2"
            >
              Save Draft
            </AsyncButton>
            <AsyncButton 
              type="submit"
              onClick={(e) => handleAction(e, 'pending')}
              loadingText="Saving..."
              className="px-6 py-3.5 bg-zinc-900 text-white rounded-[32px] font-medium uppercase tracking-wider text-[10px] hover:bg-zinc-800 transition-all shadow-lg flex items-center gap-2"
            >
              <Save size={16} />
              Save & Close
            </AsyncButton>
            <AsyncButton 
              type="button"
              onClick={(e) => handleAction(e, 'approved')}
              loadingText="Approving..."
              className="px-6 py-3.5 bg-emerald-600 text-white rounded-[32px] font-medium uppercase tracking-wider text-[10px] hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-600/20 flex items-center gap-2"
            >
              Approve Bill
            </AsyncButton>
          </div>
        </div>
      </motion.div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { User } from 'firebase/auth';
import { Bill, Vendor, ChartAccount } from '../../types';
import { 
  Plus, 
  Search, 
  Users,
  Filter,
  Download,
  Clock,
  AlertCircle,
  Calendar,
  Zap,
  Activity,
  ShieldCheck,
  Package,
  TrendingDown,
  Trash2
} from 'lucide-react';
import { toast } from 'sonner';
import { motion } from 'motion/react';
import { parseLocalDate, cn, formatCurrency } from '../../lib/utils';
import { resolveAccountRole } from '../../lib/accountUtils';
import { format, differenceInDays, addDays, startOfDay } from 'date-fns';

import BillModal from './BillModal';
import VendorModal from './VendorModal';



import { useAuthStore } from '../../stores/useAuthStore';
import { useLedgerStore } from '../../stores/useLedgerStore';
import { useEntityOperations } from '../../hooks/useEntityOperations';

export default function Purchases() {
  const user = useAuthStore(s => s.user);
  const bills = useLedgerStore(s => s.bills);
  const vendors = useLedgerStore(s => s.vendors);
  const accounts = useLedgerStore(s => s.accounts);
  const transactions = useLedgerStore(s => s.transactions);
  const { addEntity, updateEntity } = useEntityOperations();

  const vendorBalances = useMemo(() => {
    const map: Record<string, number> = {};
    (bills || []).forEach(b => {
      if (b.vendorId && b.status !== 'paid' && b.status !== 'void') {
        map[b.vendorId] = (map[b.vendorId] || 0) + (b.amountCents || 0);
      }
    });

    // Transaction-based AP matching
    if (transactions) {
      transactions.forEach(tx => {
        if (tx.status === 'void') return;

        let apAmount = 0;
        tx.lines.forEach(l => {
          const acc = accounts?.find(a => a.id === l.accountId);
          if (acc && (resolveAccountRole(acc) === 'ap' || (acc.type === 'liability' && acc.name.toLowerCase().includes('payable')))) {
            apAmount += Math.abs(l.amountCents);
          }
        });

        if (apAmount > 0) {
          const matchedVend = vendors?.find(v => tx.payee?.toLowerCase() === v.name.toLowerCase() || tx.description?.toLowerCase().includes(v.name.toLowerCase()));
          if (matchedVend) {
            map[matchedVend.id] = (map[matchedVend.id] || 0) + apAmount;
          }
        }
      });
    }

    return map;
  }, [bills, transactions, vendors, accounts]);
  const onAddBill = (data: any) => { if (data.id) { const { id, ...updates } = data; return updateEntity('bills', id, updates); } return addEntity('bills', data); };
  const onUpdateBill = (id: string, updates: any) => updateEntity('bills', id, updates);
  const onAddVendor = (data: any) => { if (data.id) { const { id, ...updates } = data; return updateEntity('vendors', id, updates); } return addEntity('vendors', data); };
  const [activeSubTab, setActiveSubTab] = useState<'bills' | 'vendors' | 'pipeline'>('pipeline');
  const [isBillModalOpen, setIsBillModalOpen] = useState(false);
  const [isVendorModalOpen, setIsVendorModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const agingBuckets = useMemo(() => {
    const today = startOfDay(new Date());
    const buckets = {
      current: 0,
      overdue: 0,
      due30: 0,
      due60: 0,
      due90: 0
    };

    bills.forEach(bill => {
      if (bill.status === 'paid' || bill.status === 'void') return;

      const dueDate = parseLocalDate(bill.dueDate);
      const daysDiff = differenceInDays(dueDate, today);

      if (daysDiff < 0) buckets.overdue += bill.amountCents;
      else if (daysDiff <= 30) buckets.due30 += bill.amountCents;
      else if (daysDiff <= 60) buckets.due60 += bill.amountCents;
      else buckets.due90 += bill.amountCents;

      buckets.current += bill.amountCents;
    });

    return buckets;
  }, [bills]);

  const timelineData = useMemo(() => {
    const today = startOfDay(new Date());
    const days = Array.from({ length: 30 }, (_, i) => addDays(today, i));

    return days.map(day => {
      const dayBills = bills.filter(b => 
        b.status !== 'paid' && 
        format(parseLocalDate(b.dueDate), 'yyyy-MM-dd') === format(day, 'yyyy-MM-dd')
      );
      return {
        date: day,
        amountCents: dayBills.reduce((sum, b) => sum + b.amountCents, 0),
        count: dayBills.length
      };
    });
  }, [bills]);

  const filteredBills = useMemo(() => {
    return bills.filter(b => {
      const term = searchTerm.toLowerCase();
      if (!term) return true;
      const vendor = vendors?.find(v => v.id === b.vendorId);
      const searchStr = `${b.vendorName || ''} ${b.number || ''} ${b.tags?.join(' ') || ''} ${b.metadata ? JSON.stringify(b.metadata) : ''} ${vendor?.tags?.join(' ') || ''} ${vendor?.metadata ? JSON.stringify(vendor.metadata) : ''}`.toLowerCase();
      return searchStr.includes(term);
    }).sort((a, b) => parseLocalDate(a.dueDate).getTime() - parseLocalDate(b.dueDate).getTime());
  }, [bills, vendors, searchTerm]);

  const getStatusColor = (status: Bill['status']) => {
    switch (status) {
      case 'paid': return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case 'unpaid': 
      case 'pending':
        return 'bg-amber-50 text-amber-700 border-amber-200';
      case 'overdue': return 'bg-rose-50 text-rose-700 border-rose-200';
      default: return 'bg-[var(--ink)] text-zinc-650 border-[var(--line)]';
    }
  };

  return (
    <div className="space-y-8 pb-20">
      {/* Rule Header with brand gold backdrop */}
      <div className="relative overflow-hidden bg-gradient-to-r from-[var(--brass-soft)] via-[var(--surface)]/40 to-[var(--panel)] p-6 rounded-2xl border border-[var(--brass-line)]/50 shadow-sm">
        <div className="absolute -top-16 -left-16 w-56 h-56 bg-[var(--brass)] opacity-10 rounded-full blur-3xl hidden md:block pointer-events-none" />
        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div>
            <div className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-[var(--brass-soft)] border border-[var(--brass-line)]/60 text-[10px] font-mono text-[var(--brass)] font-semibold mb-2 shadow-xs">
              <TrendingDown size={12} />
              ACCOUNTS PAYABLE & EXPENSES
            </div>
            <h1 className="text-2xl sm:text-3xl font-bold text-[var(--text)] tracking-tight">Bills & Vendor Liabilities</h1>
            <p className="text-xs text-[var(--muted)] font-medium mt-1">Manage supplier bills, expense accruals, and cash outflow schedules.</p>
          </div>

          <div className="flex flex-wrap items-center gap-3 shrink-0">
            <div className="flex items-center bg-[var(--surface)]/80 p-1 rounded-xl border border-[var(--line)] shadow-inner backdrop-blur-sm">
              <button 
                onClick={() => setActiveSubTab('bills')}
                className={cn(
                  "px-3.5 py-1.5 rounded-lg text-xs font-semibold transition-all cursor-pointer",
                  activeSubTab === 'bills' 
                    ? "bg-gradient-to-r from-[var(--brass)] via-[#e5be6b] to-[var(--brass)] text-black font-bold shadow-sm" 
                    : "text-[var(--muted)] hover:text-[var(--text)]"
                )}
              >
                Bills & AP
              </button>
              <button 
                onClick={() => setActiveSubTab('vendors')}
                className={cn(
                  "px-3.5 py-1.5 rounded-lg text-xs font-semibold transition-all cursor-pointer",
                  activeSubTab === 'vendors' 
                    ? "bg-gradient-to-r from-[var(--brass)] via-[#e5be6b] to-[var(--brass)] text-black font-bold shadow-sm" 
                    : "text-[var(--muted)] hover:text-[var(--text)]"
                )}
              >
                Vendors & Suppliers
              </button>
            </div>
            <button 
              onClick={() => activeSubTab === 'bills' ? setIsBillModalOpen(true) : setIsVendorModalOpen(true)}
              className="flex items-center gap-1.5 px-4 py-2 bg-gradient-to-r from-[var(--brass)] via-[#e5be6b] to-[var(--brass)] text-black rounded-xl text-xs font-bold hover:opacity-95 transition-all shadow-md hover:shadow-lg cursor-pointer active:scale-95"
            >
              <Plus size={15} />
              {activeSubTab === 'bills' ? 'Add Bill' : 'Add Vendor'}
            </button>
          </div>
        </div>
      </div>

      {/* Psychological Header: Aging Buckets */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5">
        <motion.div 
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="p-5 bg-[var(--panel)] rounded-2xl border border-[var(--line)] shadow-sm relative overflow-hidden group"
        >
          <div className="absolute technical-grid inset-0 opacity-5 pointer-events-none" />
          <p className="text-[10px] font-mono uppercase tracking-widest text-rose-500 font-semibold mb-3 relative z-10">Critical Overdue</p>
          <p className="text-2xl sm:text-3xl font-mono font-bold text-rose-600 tracking-tight relative z-10">{formatCurrency(agingBuckets.overdue)}</p>
          <div className="mt-3 flex items-center gap-2 text-xs font-mono text-[var(--muted)] relative z-10">
             <AlertCircle size={12} />
             Immediate Disbursement Priority
          </div>
        </motion.div>

        <motion.div 
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="p-5 bg-[var(--panel)] rounded-2xl border border-[var(--line)] shadow-sm relative overflow-hidden group"
        >
          <div className="absolute technical-grid inset-0 opacity-5 pointer-events-none" />
          <p className="text-[10px] font-mono uppercase tracking-widest text-amber-500 font-semibold mb-3 relative z-10">Short-Term (30d)</p>
          <p className="text-2xl sm:text-3xl font-mono font-bold text-amber-600 tracking-tight relative z-10">{formatCurrency(agingBuckets.due30)}</p>
          <div className="mt-3 flex items-center gap-2 text-xs font-mono text-[var(--muted)] relative z-10">
             <Activity size={12} />
             Operational Outflow Expected
          </div>
        </motion.div>

        <motion.div 
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="p-5 bg-[var(--panel)] rounded-2xl border border-[var(--line)] shadow-sm relative overflow-hidden group"
        >
          <div className="absolute technical-grid inset-0 opacity-5 pointer-events-none" />
          <p className="text-[10px] font-mono uppercase tracking-widest text-[var(--muted)] font-semibold mb-3 relative z-10">Mid-Term (30-60d)</p>
          <p className="text-2xl sm:text-3xl font-mono font-bold text-[var(--text)] tracking-tight relative z-10">{formatCurrency(agingBuckets.due60)}</p>
          <div className="mt-3 flex items-center gap-2 text-xs font-mono text-[var(--muted)] relative z-10">
             <Clock size={12} />
             Liquidity Forecast Cluster
          </div>
        </motion.div>

        <motion.div 
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="p-5 bg-[var(--panel)] rounded-2xl border border-[var(--brass-line)] shadow-sm relative overflow-hidden group bg-gradient-to-b from-[var(--brass-soft)] to-[var(--panel)]"
        >
          <div className="absolute technical-grid inset-0 opacity-5 pointer-events-none" />
          <p className="text-[10px] font-mono uppercase tracking-widest text-[var(--muted)] font-semibold mb-3 relative z-10">Total Aggregate Payable</p>
          <p className="text-2xl sm:text-3xl font-mono font-bold text-[var(--text)] tracking-tight relative z-10">{formatCurrency(agingBuckets.current)}</p>
          <div className="mt-3 flex items-center gap-2 text-xs font-mono text-[var(--muted)] relative z-10">
             <ShieldCheck size={12} className="text-[var(--brass)]" />
             Verified System Liability
          </div>
        </motion.div>
      </div>

      {/* Timeline Visualization */}
      <div className="p-6 bg-[var(--panel)] border border-[var(--line)] rounded-2xl shadow-sm relative overflow-hidden group">
        <div className="absolute technical-grid inset-0 opacity-[0.02] pointer-events-none" />
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-[var(--surface)] border border-[var(--line)] rounded-xl flex items-center justify-center text-[var(--brass)] shadow-xs">
              <Calendar size={20} />
            </div>
            <div>
              <h3 className="text-lg font-bold text-[var(--text)] tracking-tight">Disbursement Horizon</h3>
              <p className="text-xs text-[var(--muted)]">30-Day Predictive Cash Outflow Map</p>
            </div>
          </div>
        </div>

        <div className="flex gap-3 overflow-x-auto pb-2 custom-scrollbar">
          {timelineData.map((day, i) => (
            <motion.div 
              key={i}
              whileHover={{ y: -2 }}
              className={cn(
                "flex-shrink-0 w-20 flex flex-col items-center gap-2 p-3 rounded-xl transition-all relative overflow-hidden",
                day.amountCents > 0 
                  ? "bg-[var(--brass-soft)] border border-[var(--brass-line)] text-[var(--text)] shadow-xs" 
                  : "bg-[var(--surface)] border border-[var(--line)] text-[var(--muted)] opacity-60"
              )}
            >
              <span className={cn(
                "text-[10px] font-mono uppercase font-semibold",
                day.amountCents > 0 ? "text-[var(--brass)]" : "text-[var(--muted)]"
              )}>{format(day.date, 'EEE')}</span>
              <span className="text-base font-mono font-bold">{format(day.date, 'dd')}</span>
              {day.amountCents > 0 ? (
                <div className="flex flex-col items-center pt-1 border-t border-[var(--brass-line)]/40 w-full mt-1">
                  <span className="text-[10px] font-mono font-bold text-[var(--text)]">
                    ${(day.amountCents / 100).toLocaleString(undefined, { maximumFractionDigits: 0 })}
                  </span>
                </div>
              ) : (
                <div className="w-full pt-4 mt-2 border-t border-[var(--line)] flex justify-center">
                   <div className="w-1 h-1 bg-slate-200 rounded-full" />
                </div>
              )}
            </motion.div>
          ))}
        </div>
      </div>

      <div className="flex items-center justify-between pb-4 border-b border-[var(--line)]">
        <div className="relative group max-w-md w-full">
          <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-indigo-600 transition-colors" size={20} />
          <input 
            type="text" 
            placeholder="Search bills by vendor, number, tags, or metadata..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-14 pr-6 py-4 bg-[var(--surface)] border border-[var(--line)] rounded-[32px] focus:outline-none focus:ring-2 focus:ring-indigo-600/20 focus:bg-[var(--surface)] transition-all text-sm font-bold text-[var(--text)] placeholder:text-slate-500/40 shadow-sm"
          />
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={() => {
              toast.info("Filter applied: Showing all active bills");
            }}
            className="p-4 bg-[var(--surface)] border border-[var(--line)] rounded-[32px] text-slate-500 hover:text-[var(--text)] hover:bg-[var(--surface)] transition-all cursor-pointer" 
            aria-label="Filter action"
            title="Filter Bills"
          >
            <Filter size={20} />
          </button>
          <button 
            onClick={() => {
              const csvLines = [
                'Bill ID,Vendor,Issue Date,Due Date,Amount Cents,Status',
                ...(bills || []).map(b => `${b.id},"${b.vendorId || ''}",${b.issueDate},${b.dueDate},${b.amountCents},${b.status}`)
              ];
              const blob = new Blob([csvLines.join('\n')], { type: 'text/csv' });
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `bills_export_${new Date().toISOString().slice(0,10)}.csv`;
              a.click();
              URL.revokeObjectURL(url);
              toast.success("Exported bills CSV");
            }}
            className="p-4 bg-[var(--surface)] border border-[var(--line)] rounded-[32px] text-slate-500 hover:text-[var(--text)] hover:bg-[var(--surface)] transition-all cursor-pointer" 
            aria-label="Download action"
            title="Download CSV"
          >
            <Download size={20} />
          </button>
        </div>
      </div>

      {/* Modals */}
      <BillModal 
        isOpen={isBillModalOpen}
        onClose={() => setIsBillModalOpen(false)}
        onSave={(bill) => {
          onAddBill(bill);
          setIsBillModalOpen(false);
        }}
        vendors={vendors}
        accounts={accounts}
      />
      <VendorModal 
        isOpen={isVendorModalOpen}
        onClose={() => setIsVendorModalOpen(false)}
        onSave={(vend) => {
          onAddVendor(vend);
          setIsVendorModalOpen(false);
        }}
      />



      {activeSubTab === 'bills' && (
        <div className="ledger-card p-1 rounded-[32px] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full border-collapse min-w-[700px]">
              <thead>
                <tr className="text-left border-b border-[var(--line)]/50">
                  <th className="p-4 md:p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] whitespace-nowrap">Liability Node</th>
                  <th className="p-4 md:p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] whitespace-nowrap">Supplier</th>
                  <th className="p-4 md:p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] whitespace-nowrap">Timestamp</th>
                  <th className="p-4 md:p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] whitespace-nowrap">Maturity</th>
                  <th className="p-4 md:p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] text-right">Magnitude</th>
                  <th className="p-4 md:p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] text-center">State</th>
                  <th className="p-4 md:p-8 w-10"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-ledger-line/30">
                {filteredBills.map((bill) => (
                  <tr key={bill.id} className="group hover:bg-[var(--ink)]/30 transition-all cursor-pointer">
                    <td className="p-4 md:p-8 font-mono font-bold text-slate-500 group-hover:text-[var(--text)] transition-colors">{bill.number}</td>
                    <td className="p-4 md:p-8">
                       <div className="flex flex-col">
                          <span className="font-black text-[var(--text)] text-base tracking-tight">{bill.vendorName}</span>
                          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-1 opacity-50">KYB Verified</span>
                       </div>
                    </td>
                    <td className="p-4 md:p-8">
                       <span className="font-bold text-[var(--text)]">{bill.date ? format(parseLocalDate(bill.date), 'MMM dd, yyyy') : 'N/A'}</span>
                    </td>
                    <td className="p-4 md:p-8">
                      <div className="flex flex-col">
                        <span className={cn(
                          "font-bold text-[var(--text)]",
                          bill.status === 'overdue' && "text-rose-600"
                        )}>
                          {bill.dueDate ? format(parseLocalDate(bill.dueDate), 'MMM dd, yyyy') : 'N/A'}
                        </span>
                        {bill.status === 'unpaid' && (
                          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-1 opacity-50">
                            {differenceInDays(parseLocalDate(bill.dueDate), new Date())} T-Days Left
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="p-4 md:p-8 text-right font-black font-mono text-[var(--text)] text-lg tracking-tighter">
                      {formatCurrency(bill.amountCents || 0)}
                    </td>
                    <td className="p-4 md:p-8">
                      <div className="flex justify-center">
                        <span className={cn(
                          "px-4 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-[0.2em] border shadow-sm",
                          getStatusColor(bill.status)
                        )}>
                          {bill.status}
                        </span>
                      </div>
