                  </td>
                  <td className="py-3.5 px-4 text-right font-mono text-orange-700">
                    {item.days61To90Cents > 0 ? formatCurrency(item.days61To90Cents) : '-'}
                  </td>
                  <td className="py-3.5 px-4 text-right font-mono font-bold text-rose-600">
                    {item.days90PlusCents > 0 ? formatCurrency(item.days90PlusCents) : '-'}
                  </td>
                  <td className="py-3.5 px-5 text-right font-mono font-bold text-slate-900">
