                )}
              </div>
            </div>

            {/* Document Management Section */}
            <div className="bg-[var(--ink)]/50 p-4 rounded-[32px] border border-zinc-150 space-y-3">
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="text-xs font-bold text-[var(--text)] uppercase tracking-wider flex items-center gap-1.5">
                    <FileText size={13} className="text-zinc-500" /> Source Documents & Receipts
                  </h4>
                  <p className="text-[10px] text-zinc-400">Attach underlying evidence for this specific vector node.</p>
                </div>
                <label className="flex items-center gap-1 px-3 py-1 bg-[var(--surface)] hover:bg-zinc-100 text-[var(--text)] border border-[var(--line)] text-[11px] font-bold rounded-lg transition-all cursor-pointer">
                  <Plus size={12} />
                  <span>Attach Document</span>
                  <input
                    type="file"
                    className="hidden"
                    accept="image/*,application/pdf"
                    multiple
                    disabled={isLocked}
                    onChange={(e) => {
                      if (!e.target.files) return;
                      const files = Array.from(e.target.files);

                      files.forEach(file => {
                        const reader = new FileReader();
                        reader.readAsDataURL(file);
                        reader.onload = () => {
                          setFileUrls(prev => [...prev, reader.result as string]);
                        };
                      });
                    }}
                  />
                </label>
              </div>

              {fileUrls.length > 0 && (
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mt-3">
                  {fileUrls.map((url, i) => (
                    <div key={i} className="relative group rounded-xl border border-[var(--line)] overflow-hidden bg-[var(--surface)] h-24 flex items-center justify-center">
                      {url.startsWith('data:image') ? (
                        <img src={url} alt="Attached receipt" className="w-full h-full object-cover opacity-90 group-hover:opacity-100 transition-opacity" />
                      ) : (
                        <div className="flex flex-col items-center gap-1 text-zinc-400">
                          <FileText size={24} />
                          <span className="text-[9px] uppercase font-bold tracking-widest">Document</span>
                        </div>
                      )}

                      {!isLocked && (
                        <button 
                          onClick={() => setFileUrls(prev => prev.filter((_, index) => index !== i))}
                          className="absolute top-1 right-1 p-1 bg-red-500/80 hover:bg-red-500 text-white rounded-md opacity-100 md:opacity-0 md:group-hover:opacity-100 transition-opacity"
                        >
                          <Trash2 size={12} />
                        </button>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>

          </div>

          {/* Actions footer */}
          <div className="px-6 py-4 bg-[var(--ink)] border-t border-[var(--line)] flex items-center justify-end gap-3 shrink-0">
            <button
              onClick={onClose}
              type="button"
              className="px-4 py-2 hover:bg-zinc-100 rounded-xl text-xs font-semibold text-zinc-500 hover:text-[var(--text)] transition-colors"
             aria-label="Cancel">
              Cancel
            </button>
            <AsyncButton
              onClick={handleSave}
              disabled={isLocked}
              loadingText="Recording..."
              className="px-5 py-2 bg-zinc-900 hover:bg-zinc-800 text-white rounded-xl text-xs font-bold transition-all shadow-md shadow-zinc-800/15 disabled:opacity-50"
            >
              Record synchronized changes
            </AsyncButton>
          </div>

        </motion.div>
      </div>
    </AnimatePresence>
  );
}

import React from 'react';
import { Transaction } from '../../types';
import { format } from 'date-fns';
import { 
  Zap,
  RotateCcw,
  AlertCircle,
  Columns,
  Sparkles,
  Copy,
  Lock,
  Edit3,
  BrainCircuit
} from 'lucide-react';
import { parseLocalDate, resolveAccountName, cn } from '../../lib/utils';
import { isInflow } from '../../lib/txFilters';
import { useLedgerStore } from '../../stores/useLedgerStore';
import AsyncButton from '../ui/AsyncButton';

const HighlightMatch = ({ text, match }: { text: string; match?: string }) => {
  if (!match) return <>{text}</>;
  const parts = text.split(new RegExp(`(${match})`, 'gi'));
  return (
    <>
      {parts.map((p, i) =>
        p.toLowerCase() === match.toLowerCase() ? (
          <mark key={i} className="bg-yellow-200 text-yellow-900 rounded-[2px] px-0.5 font-bold">{p}</mark>
        ) : (
          <span key={i}>{p}</span>
        )
      )}
    </>
  );
};

interface TransactionRowProps {
  tx: Transaction & { balanceCents: number };
  isSelected: boolean;
  isSetA: boolean;
  isSetB: boolean;
  isFocused: boolean;
  isEven: boolean;
  focusedField: string | null;
  onToggleSelection: (id: string) => void;
  onVoid: (id: string) => Promise<void> | void;
  onUpdate?: (id: string, updates: Partial<Transaction>) => void;
  onSelect?: (id: string) => void;
  onCreateRule: (tx: Transaction) => void;
  onProjectClick: (projectName: string) => void;
  onSplit: (id: string) => void;
  onDuplicate?: (id: string) => void;
  onToggleFlag?: (id: string) => void;
  onEditDetails?: (tx: Transaction) => void;
  formatCurrency: (cents: number) => string;
  isProMode?: boolean;
  isCompactMode?: boolean;
  isMobileGrid?: boolean;
  isTabletGrid?: boolean;
  dateFormat?: string;
  gridColumns: string;
  anomaly?: { score: number, reason: string };
  internalConflict?: { type: string, message: string };
  searchTerm?: string;
}

const TransactionRow = React.memo(({
  tx,
  isSelected,
  isSetA,
  isSetB,
  isFocused,
  isEven,
  focusedField,
  onToggleSelection,
  onVoid,
  onUpdate,
  onSelect,
  onCreateRule,
  onProjectClick,
  onSplit,
  onDuplicate,
  onToggleFlag,
  onEditDetails,
  formatCurrency,
  isProMode = false,
  isCompactMode = false,
  isMobileGrid = false,
  isTabletGrid = false,
  dateFormat = 'MMM dd, yyyy',
  gridColumns,
  anomaly,
  internalConflict,
  searchTerm
}: TransactionRowProps) => {
  const isPrivacyMode = useLedgerStore(state => state.isPrivacyMode);
  const accounts = useLedgerStore(state => state.accounts);
  const lockDate = useLedgerStore(state => state.lockDate);
  const isLocked = !!(lockDate && tx.date <= lockDate) || !!tx.isLocked;
  const displayTx = tx;

  const [isEditingDesc, setIsEditingDesc] = React.useState(false);
  const [editDraft, setEditDraft] = React.useState<string | null>(null);
  const descValue = editDraft !== null ? editDraft : displayTx.description;

  const handleDescSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    e?.stopPropagation();
    setIsEditingDesc(false);
    if (editDraft !== null && editDraft !== displayTx.description && !isLocked && onUpdate) {
      onUpdate(tx.id, { description: editDraft });
    }
    setEditDraft(null);
  };

  return (
    <div className="flex flex-col w-full h-full relative group/row">
      <div role="button" tabIndex={0} 
        onClick={() => onSelect?.(tx.id)}
        className={cn(
          "grid w-full h-full items-center transition-all border-b border-[var(--line)] cursor-pointer relative",
          tx.type === 'reversal' && "bg-rose-50/5",
          tx.type === 'adjustment' && "bg-amber-50/5",
          (anomaly || internalConflict) && "bg-indigo-600/[0.03]",
          isSetA && "bg-amber-50/10",
          isSetB && "bg-emerald-50/10",
