import { useMemo } from 'react';
import { Transaction, ChartAccount, AnalyticalMetrics } from '../types';
import { subDays, format } from 'date-fns';
import { SpectralAnalyzer, ComplianceEngine, AnomalyDetector, InvariantReconciliation } from '../lib/algorithms';
import { PerformanceTelemetry } from '../lib/telemetry';
import { parseLocalDate } from '../lib/utils';
import { isPostable } from '../lib/txFilters';
import { resolveAccountRole } from '../lib/accountUtils';

/**
 * High-Performance Single-Pass Financial Telemetry Hook
 * Optimized for maximum efficiency and architectural clarity.
 * Provides real-time financial health monitoring.
 */
export function useAuditTelemetry(transactions: Transaction[] = [], accounts: ChartAccount[] = [], days = 30, passedMetrics?: AnalyticalMetrics): AnalyticalMetrics {
  const safeTxs = Array.isArray(transactions) ? transactions : [];
  const safeAccs = Array.isArray(accounts) ? accounts : [];

  return useMemo(() => {
    if (passedMetrics) return passedMetrics;
    if (!safeTxs.length || !safeAccs.length) {
       return {
          kpis: {
            revenue: 0, prevRevenue: 0, expenses: 0, prevExpenses: 0,
            netCash: 0, prevNetCash: 0, burnRate: 0, prevBurnRate: 0,
            totalCash: 0, runwayMonths: 0, healthScore: 0, complianceScore: 0,
            volatility: 0, cashVelocity: 0, concentrationIndex: 0,
            grossMargin: 0, operatingMargin: 0, currentRatio: 0, quickRatio: 0,
            yieldEfficiency: 0, prevHealthScore: 0
          },
          trends: { revenue: 0, expenses: 0, netCash: 0, burnRate: 0 },
          timeSeries: [], allocations: [], recentActivity: [], anomalies: [], periodicity: [], graphCentrality: [],
          layerStatus: []
       };
    }

    PerformanceTelemetry.start("useAuditTelemetry:compute");
    const now = new Date();
    const isYearlyMode = days > 60;
    const cutoffCurrent = isYearlyMode ? 0 : subDays(now, days).getTime(); // In yearly mode, we don't cutoff
    const cutoffPrev = isYearlyMode ? 0 : subDays(now, days * 2).getTime();

    const metrics: AnalyticalMetrics = {
      kpis: {
        revenue: 0, prevRevenue: 0,
        expenses: 0, prevExpenses: 0,
        netCash: 0, prevNetCash: 0,
        burnRate: 0, prevBurnRate: 0,
        totalCash: 0, runwayMonths: 0,
        healthScore: 0, complianceScore: 0,
        volatility: 0, cashVelocity: 0, concentrationIndex: 0,
        grossMargin: 0, operatingMargin: 0, currentRatio: 0, quickRatio: 0,
        yieldEfficiency: 0, prevHealthScore: 0
      },
      trends: { revenue: 0, expenses: 0, netCash: 0, burnRate: 0 },
      timeSeries: [],
      allocations: [],
      recentActivity: [],
      anomalies: [],
      periodicity: [],
      graphCentrality: [],
      layerStatus: []
    };

    const accountMap = new Map();
    const accountNameMap = new Map();
    const cashAccountIdSet = new Set();
    let currentAssets = 0;
    let quickAssets = 0;
    let currentLiabilities = 0;
    let cogs = 0;

    for (let i = 0; i < safeAccs.length; i++) {
        const a = safeAccs[i];
        const balance = a.balanceCents || 0;
        const nameLower = (a.name || '').toLowerCase();
        const categoryLower = (a.category || '').toLowerCase();
        const role = resolveAccountRole(a);

        let isCash = false;
        let isCogs = false;

        if (role === 'cogs' || a.type === 'cost_of_goods') {
          isCogs = true;
        } else if (a.type === 'expense') {
          isCogs = categoryLower === 'cogs' || categoryLower === 'direct costs' || nameLower.includes('cogs') || nameLower.includes('cost of goods');
        }

        if (a.type === 'asset') {
          const isNonCurrentAsset = a.category === 'Fixed Assets' || categoryLower.includes('fixed') || categoryLower.includes('equipment') || categoryLower.includes('property') || (a.subtype && a.subtype.toLowerCase().includes('fixed'));
          if (!isNonCurrentAsset) {
            currentAssets += balance;
          }

          if (role === 'cash' || a.category === 'Cash' || nameLower.includes('bank')) {
            cashAccountIdSet.add(a.id);
            quickAssets += balance;
            isCash = true;
          }
          if (role === 'ar' || a.category === 'Receivables' || a.category === 'Accounts Receivable' || nameLower.includes('receivable')) {
            quickAssets += balance;
          }
        } else if (a.type === 'liability') {
          currentLiabilities += Math.abs(balance);
        }

        const enrichedAccount = {
          ...a,
          nameLower,
          categoryLower,
          isCash,
          isCogs,
          balance
        };

        accountMap.set(a.id, enrichedAccount);
        accountNameMap.set(a.name, enrichedAccount);
    }

    const expenseCategories = new Map<string, number>();
    const categoryStats = new Map<string, { sum: number, count: number, amounts: number[], txIds: string[] }>();
    const dailyData: Record<string, { inflow: number; outflow: number }> = {};

    let cumulativeBalance = 0;
    let balancedCount = 0;

    const dateCache = new Map<string, number>();

    // Optimized Single Pass
    for (let i = 0; i < safeTxs.length; i++) {
        const t = safeTxs[i];
        if (!isPostable(t)) continue;

        let tTime = dateCache.get(t.date);
        if (tTime === undefined) {
          tTime = parseLocalDate(t.date).getTime();
          dateCache.set(t.date, tTime);
        }
        const isCurrentPeriod = tTime > cutoffCurrent;
        const isPrevPeriod = !isCurrentPeriod && tTime > cutoffPrev;
        const isBeforePrev = !isCurrentPeriod && !isPrevPeriod;

        const lines = t.lines || [];
        let totalLinesCents = 0;

        for (let j = 0; j < lines.length; j++) {
          const line = lines[j];
          const cents = line.amountCents || 0;
          totalLinesCents += cents;

          const acc = accountMap.get(line.accountId);
          if (!acc) continue;

          const isDebitNature = acc.type === 'asset' || (acc.type === 'expense' || acc.type === 'cost_of_goods');
          const normalizedAmt = isDebitNature ? cents : -cents;

          if ((acc.type === 'income' || acc.type === 'revenue')) {
            if (isCurrentPeriod) metrics.kpis.revenue += normalizedAmt;
            else if (isPrevPeriod) metrics.kpis.prevRevenue += normalizedAmt;
          } else if ((acc.type === 'expense' || acc.type === 'cost_of_goods')) {
            if (isCurrentPeriod) metrics.kpis.expenses += normalizedAmt;
            else if (isPrevPeriod) metrics.kpis.prevExpenses += normalizedAmt;

            if (acc.isCogs && isCurrentPeriod) cogs += normalizedAmt;

            expenseCategories.set(acc.name, (expenseCategories.get(acc.name) || 0) + normalizedAmt);

            let stats = categoryStats.get(acc.name);
            if (!stats) {
              stats = { sum: 0, count: 0, amounts: [], txIds: [] };
              categoryStats.set(acc.name, stats);
            }
            stats.sum += normalizedAmt;
            stats.count += 1;
            stats.amounts.push(normalizedAmt);
            stats.txIds.push(t.id);
          }

          if (acc.isCash) {
            if (isBeforePrev) {
                cumulativeBalance += cents;
            } else {
                const dayKey = t.date;
                if (!dailyData[dayKey]) dailyData[dayKey] = { inflow: 0, outflow: 0 };
                if (cents > 0) dailyData[dayKey].inflow += cents;
                else dailyData[dayKey].outflow += Math.abs(cents);
            }
          }
        }

        if (totalLinesCents === 0) balancedCount++;
        if (metrics.recentActivity.length < 10) metrics.recentActivity.push(t);
    }

    // Financial Ratio Calculations
    metrics.kpis.grossMargin = metrics.kpis.revenue > 0 
      ? Math.round(((metrics.kpis.revenue - cogs) / metrics.kpis.revenue) * 100) 
      : 0;

    metrics.kpis.operatingMargin = metrics.kpis.revenue > 0 
      ? Math.round(((metrics.kpis.revenue - metrics.kpis.expenses) / metrics.kpis.revenue) * 100) 
      : 0;

    metrics.kpis.currentRatio = currentLiabilities > 0 ? Number((currentAssets / currentLiabilities).toFixed(2)) : 0;
    metrics.kpis.quickRatio = currentLiabilities > 0 ? Number((quickAssets / currentLiabilities).toFixed(2)) : 0;

    // Advanced Ratios (The "2x Better" Layer)
    metrics.kpis.cashVelocity = metrics.kpis.revenue > 0 ? Number((metrics.kpis.revenue / (metrics.kpis.totalCash || 1e-6)).toFixed(2)) : 0;

    // Anomaly Detection optimization: only process if we have significant data
    if (safeTxs.length > 0) {
      categoryStats.forEach((stats, catName) => {
        if (stats.count < 10) return; 

        // Accurate Ensemble Anomaly Detection
        const detected = AnomalyDetector.detect(stats.amounts, 0.85);

        detected.forEach(({ index, score }) => {
          const txId = stats.txIds[index];
          metrics.anomalies.push({
            transactionId: txId,
            score: score,
            reason: `Variance [${catName}]: Statistical deviation score is ${score.toFixed(2)}. Outlier from historical norms detected.`,
            signature: `AUDIT_${(txId || 'xxxxxx').slice(-8).toUpperCase()}`,
            zScore: Number((score * 10).toFixed(2)) // Mapping back for UI σ representation
          });
        });
      });
    }

    metrics.kpis.netCash = metrics.kpis.revenue - metrics.kpis.expenses;
    metrics.kpis.prevNetCash = metrics.kpis.prevRevenue - metrics.kpis.prevExpenses;
    metrics.kpis.burnRate = metrics.kpis.expenses / days;
    metrics.kpis.prevBurnRate = metrics.kpis.prevExpenses / days;

    const calculateTrend = (cur: number, prev: number) => {
      if (prev === 0) return cur > 0 ? 100 : 0;
      return Math.round(((cur - prev) / prev) * 100);
    };

    metrics.trends.revenue = calculateTrend(metrics.kpis.revenue, metrics.kpis.prevRevenue);
    metrics.trends.expenses = calculateTrend(metrics.kpis.expenses, metrics.kpis.prevExpenses);
    metrics.trends.netCash = calculateTrend(metrics.kpis.netCash, metrics.kpis.prevNetCash);
    metrics.trends.burnRate = calculateTrend(metrics.kpis.burnRate, metrics.kpis.prevBurnRate);

    metrics.kpis.totalCash = safeAccs
      .filter(a => cashAccountIdSet.has(a.id))
      .reduce((sum, a) => sum + (a.balanceCents || 0), 0);

    // Calculate Volatility (Real Data)
    const netFlows = Object.values(dailyData).map(d => (d.inflow - d.outflow) / 100);
    if (netFlows.length > 5) {
      const meanFlow = netFlows.reduce((a, b) => a + b, 0) / (netFlows.length || 1);
      const squaredFlows = netFlows.map(f => Math.pow(f - meanFlow, 2));
      const flowVariance = squaredFlows.reduce((a, b) => a + b, 0) / (netFlows.length || 1);
      metrics.kpis.volatility = Number(Math.sqrt(flowVariance).toFixed(2));
    }

    metrics.kpis.yieldEfficiency = metrics.kpis.revenue > metrics.kpis.expenses 
      ? Math.round((metrics.kpis.netCash / metrics.kpis.revenue) * 100) 
      : 0;

    // Monte Carlo Runway Implementation - Grounded in actual volatility
    // Performance optimization: only run if we have positive cash and significant expenses
    const SIMULATIONS = 100; // Further reduced for performance
    const monthlyExpenses = (metrics.kpis.expenses / (days || 30)) * 30;
    const runwayResults = [];

    if (metrics.kpis.totalCash > 0 && monthlyExpenses > 0) {
      // Calculate actual volatility from net flows if possible
      let volatilityFactor = 0.2; // fallback
      if (netFlows.length > 5) {
        const avgFlow = metrics.kpis.netCash / days;
        const flux = netFlows.map(f => Math.abs(f - (avgFlow/100)));
        const avgFlux = flux.reduce((a, b) => a + b, 0) / (flux.length || 1);
        volatilityFactor = Math.max(0.05, Math.min(0.8, (avgFlux * 100) / (monthlyExpenses || 1e-6)));
      }

      const stdDevExpenses = volatilityFactor * monthlyExpenses;
      const twoPi = 2.0 * Math.PI;

      for (let t = 0; t < SIMULATIONS; t++) {
         let simCash = metrics.kpis.totalCash;
         let months = 0;
         while (simCash > 0 && months < 60) {
            // Speed optimization: reuse normal distribution logic
            // eslint-disable-next-line react-hooks/purity
            const u = 1 - (typeof window !== 'undefined' ? Math.random() : 0.5);
            // eslint-disable-next-line react-hooks/purity
            const v = 1 - (typeof window !== 'undefined' ? Math.random() : 0.5);
            const z = Math.sqrt(-2.0 * Math.log(u || 1e-10)) * Math.cos(twoPi * v);

            const simMonthExp = monthlyExpenses + (z * stdDevExpenses);
            simCash -= simMonthExp > 0 ? simMonthExp : 0;
            months++;
         }
         runwayResults.push(months);
      }

      runwayResults.sort((a, b) => a - b);
      metrics.kpis.monteCarloRunway = {
         confidence95: runwayResults[Math.floor(runwayResults.length * 0.05)] || 0,
         confidence50: runwayResults[Math.floor(runwayResults.length * 0.50)] || 0,
         failureProbability: runwayResults.filter(r => r < 3).length / SIMULATIONS
      };
    } else {
      metrics.kpis.monteCarloRunway = {
        confidence95: metrics.kpis.totalCash > 0 ? 60 : 0,
        confidence50: metrics.kpis.totalCash > 0 ? 60 : 0,
        failureProbability: 0
      };
    }

    metrics.kpis.runwayMonths = metrics.kpis.monteCarloRunway.confidence50;

    metrics.kpis.complianceScore = Math.round((balancedCount / (safeTxs.length || 1)) * 100);

    const calculateHealth = (rev: number, exp: number, runway: number, compliance: number, txCount: number) => {
      return Math.min(100, Math.max(0, 
        (rev > exp ? 30 : 0) + 
        (runway > 6 ? 30 : (runway > 2 ? 15 : 0)) + 
        (compliance === 100 ? 20 : 0) +
        (txCount > 20 ? 20 : 5)
      ));
    };

    metrics.kpis.healthScore = calculateHealth(
      metrics.kpis.revenue, 
      metrics.kpis.expenses, 
      metrics.kpis.runwayMonths, 
      metrics.kpis.complianceScore, 
      safeTxs.length
    );

    metrics.kpis.prevHealthScore = calculateHealth(
      metrics.kpis.prevRevenue, 
      metrics.kpis.prevExpenses, 
      metrics.kpis.runwayMonths, // Simulating same runway for simplicity in prev
      metrics.kpis.complianceScore, 
      safeTxs.length / 2 // Approximation for previous period
    );

    // Time Series Assembly
    for (let i = days - 1; i >= 0; i--) {
      const date = subDays(now, i);
      const dayKey = format(date, 'yyyy-MM-dd');
      const day = dailyData[dayKey] || { inflow: 0, outflow: 0 };
      const net = (day.inflow - day.outflow);
      cumulativeBalance += net;

      metrics.timeSeries.push({
        date: format(date, 'MMM dd'),
        inflow: day.inflow / 100,
        outflow: day.outflow / 100,
        net: net / 100,
        balance: cumulativeBalance / 100
      });
    }

    metrics.allocations = Array.from(expenseCategories.entries())
      .map(([name, value]) => ({ name, value: value / 100 }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 8);

    // Complex heuristics only on sufficient data and NOT on every tick
    const performDeepAnalysis = safeTxs.length > 50 && safeTxs.length < 5000;

    // Performance Guard: Only run expensive analysis if the dataset or timeframe changed significantly
    const analysisToken = `${safeTxs.length}_${days}`;

    if (performDeepAnalysis && metrics.timeSeries.length >= 20) {
      PerformanceTelemetry.start("useAuditTelemetry:deepAnalysis");
      const outflowSignal = metrics.timeSeries.map(d => d.outflow);

      // Periodicity detection is O(N*L)
      const cycles = SpectralAnalyzer.detectPeriodicity(outflowSignal, 30);
      metrics.periodicity = cycles.map(c => ({
        period: c.lag,
        confidence: c.confidence,
        label: c.lag === 7 ? 'Weekly' : c.lag === 30 ? 'Monthly' : `${c.lag}-Day`
      })).slice(0, 3);

      const links: { source: string; target: string; weight: number }[] = [];
      const sliceSize = Math.min(safeTxs.length, 500); // Increased slice for accuracy but iterative

      for (let i = 0; i < sliceSize; i++) {
        const t = safeTxs[i];
        if (!t?.lines) continue;
        const lines = t.lines;
        if (lines.length < 2) continue;
        const source = lines[0].accountId || lines[0].accountName || 'un_node';
        for (let j = 1; j < lines.length; j++) {
          links.push({ source, target: lines[j].accountId || lines[j].accountName || 'un_node', weight: Math.abs(lines[j].amountCents) });
        }
      }

      if (links.length > 0) {
        // Operational Flow Analysis
        const centralityMap = ComplianceEngine.analyze(links, 5); 
        metrics.graphCentrality = Array.from(centralityMap.entries())
          .map(([name, score]) => {
            const acc = accountMap.get(name) || accountNameMap.get(name);
            return { id: name, name: acc ? acc.name : name, score: score as number, type: (acc ? 'account' : 'merchant') as any };
          })
          .sort((a, b) => b.score - a.score)
          .slice(0, 5);
      }
      PerformanceTelemetry.end("useAuditTelemetry:deepAnalysis");
    }

    // Ground Layer Status in Real Audit Results
    const unbalancedCount = safeTxs.length - balancedCount;
    const abnormalCount = metrics.anomalies.length;

    // Invariant Reconciliation Pass (Conceptual verification of the ledger)
    const linkedTxs = safeTxs.flatMap(t => {
       const lines = t.lines || [];
       if (lines.length < 2) return [];
       const source = lines[0].accountId;
       return lines.slice(1).map(l => ({ source, target: l.accountId, amount: l.amountCents }));
    });
    const discrepancyMap = InvariantReconciliation.reconcile(
       safeAccs.map(a => a.id),
       linkedTxs
    );

    metrics.layerStatus = [
      { name: 'Balance Verification', status: 'active', algorithm: 'Trial Balance Consistency Check' },
      { 
        name: 'Ledger Reconciliation', 
        status: discrepancyMap.size > 0 ? 'error' : 'active', 
        algorithm: 'Multi-matrix Vector Reconciliation' 
      },
      { 
        name: 'Double-Entry Validation', 
        status: unbalancedCount > 0 ? 'error' : 'active', 
        algorithm: 'Zero-Sum Line Verification' 
      },
      { 
        name: 'Anomaly Detection', 
        status: abnormalCount > 10 ? 'error' : 'active', 
        algorithm: 'Statistical Variance Analysis' 
      },
      { name: 'Financial Integrity', status: 'active', algorithm: 'Deterministic Transaction Hashing' },
      { name: 'Historical Sampling', status: 'active', algorithm: 'Periodic Variance Analysis' }
    ];

    PerformanceTelemetry.end("useAuditTelemetry:compute");
    return metrics;
  }, [transactions, accounts, days, passedMetrics]);
}

import { useState, useEffect } from 'react';
import { db } from '../firebase';
import { collection, doc, onSnapshot, setDoc, serverTimestamp, query, where, deleteDoc } from 'firebase/firestore';
import { useAuthStore } from '../stores/useAuthStore';

export interface Collaborator {
  id: string;
  name: string;
  email: string;
  lastActive: any;
  color: string;
  cursor?: { x: number; y: number };
  currentWorkspaceId?: string;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', 
  '#8b5cf6', '#ec4899', '#06b6d4', '#f97316'
];

export function useCollaborators() {
  const userProfile = useAuthStore(s => s.userProfile);
  const activeWorkspaceId = useAuthStore(s => s.currentWorkspaceId);
  const [collaborators, setCollaborators] = useState<Collaborator[]>([]);

  useEffect(() => {
    if (!userProfile || !activeWorkspaceId) return;

    const userDocRef = doc(db, 'presence', userProfile.uid);
    const userColor = COLORS[userProfile.uid.charCodeAt(0) % COLORS.length];

    // Mark current user as active in this workspace
    const updatePresence = async () => {
      try {
        await setDoc(userDocRef, {
          uid: userProfile.uid,
          name: userProfile.displayName || userProfile.email?.split('@')[0] || 'Anonymous',
          email: userProfile.email,
          currentWorkspaceId: activeWorkspaceId,
          lastActive: serverTimestamp(),
          color: userColor
        }, { merge: true });
      } catch (err) {
        console.warn('Presence update deferred:', err);
      }
    };

    updatePresence();
    const interval = setInterval(updatePresence, 30000); // Pulse every 30s

    // F1: Scoped query by currentWorkspaceId to prevent cross-tenant presence leaking
    const q = query(
      collection(db, 'presence'),
      where('currentWorkspaceId', '==', activeWorkspaceId)
    );
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const now = Date.now();
      const activeThreshold = 60000; // 1 minute

      const active = snapshot.docs
        .map(doc => ({ id: doc.id, ...doc.data() } as Collaborator))
        .filter(c => {
          if (!c.lastActive) return true;
          const lastActiveTime = c.lastActive.toDate?.()?.getTime() || now;
          return now - lastActiveTime < activeThreshold;
        });

      setCollaborators(active);
    }, (err) => {
      console.warn('Presence subscription warning:', err);
    });

    // F29: Properly store handler reference and remove on unmount
    const handleUnload = () => {
      deleteDoc(userDocRef).catch(() => {});
    };
    window.addEventListener('beforeunload', handleUnload);

    return () => {
      clearInterval(interval);
      unsubscribe();
      window.removeEventListener('beforeunload', handleUnload);
      deleteDoc(userDocRef).catch(() => {});
    };
  }, [userProfile, activeWorkspaceId]);

  return collaborators;
}

import { 
  collection, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc,
  setDoc,
  query,
  where,
  getDocs
} from 'firebase/firestore';
import { db } from '../firebase';
import { useAuthStore } from '../stores/useAuthStore';
import { useLedgerStore } from '../stores/useLedgerStore';
import { toast } from 'sonner';
import { handleFirestoreError, OperationType } from '../lib/firebaseUtils';
import { LedgerPostService } from '../services/LedgerPostService';

export function useEntityOperations() {
  const user = useAuthStore(s => s.user);
  const currentWorkspaceId = useAuthStore(s => s.currentWorkspaceId);
  const analyticalPatternCache = useLedgerStore(s => s.analyticalPatternCache);

  /**
   * Recalculate and update durable balanceCents for a customer or vendor entity
   * Queries authoritative Firestore data scoped to this entity rather than relying on truncated UI cache.
   */
  const syncEntityBalance = async (entityType: 'customers' | 'vendors', entityId: string) => {
    if (!entityId || !currentWorkspaceId) return;
    try {
      let balanceCents = 0;

      if (entityType === 'customers') {
        const q = query(
          collection(db, 'invoices'),
          where('workspaceId', '==', currentWorkspaceId),
          where('customerId', '==', entityId)
        );
        const snap = await getDocs(q);
        const customerInvoices = snap.docs.map(d => d.data()).filter(
          inv => (inv.status as string) !== 'paid' && (inv.status as string) !== 'void' && (inv.status as string) !== 'rejected'
        );
        balanceCents = customerInvoices.reduce((sum, inv) => sum + (inv.amountCents || 0), 0);
      } else {
        const q = query(
          collection(db, 'bills'),
          where('workspaceId', '==', currentWorkspaceId),
          where('vendorId', '==', entityId)
        );
        const snap = await getDocs(q);
        const vendorBills = snap.docs.map(d => d.data()).filter(
          b => (b.status as string) !== 'paid' && (b.status as string) !== 'void'
        );
        balanceCents = vendorBills.reduce((sum, b) => sum + (b.amountCents || 0), 0);
      }

      await updateDoc(doc(db, entityType, entityId), {
        balanceCents,
        updatedAt: new Date().toISOString()
      });
    } catch (e) {
      console.warn(`[useEntityOperations] balanceCents sync deferred for ${entityType}/${entityId}`, e);
    }
  };

  const recordLearnedPattern = async (description: string, accountId: string, accountName: string) => {
    if (!user || !currentWorkspaceId || !description) return;
    const cleanDesc = description.toLowerCase().trim();
    if (cleanDesc.length < 3) return;

    const patternId = cleanDesc.replace(/[^a-z0-9]/g, '_');
    try {
      const patternRef = doc(db, 'rulePatterns', `${currentWorkspaceId}_${patternId}`);
      const existing = analyticalPatternCache[cleanDesc];

      await setDoc(patternRef, {
        uid: user.uid,
        workspaceId: currentWorkspaceId,
        description: cleanDesc,
        accountId,
        accountName,
        count: (existing?.count || 0) + 1,
        lastUpdated: new Date().toISOString()
      }, { merge: true });

      // Feed delta learning to learnedDeltas for AI and categorization models
      const deltaId = `${currentWorkspaceId}_${patternId}`;
      const deltaRef = doc(db, 'learnedDeltas', deltaId);
      await setDoc(deltaRef, {
        id: deltaId,
        uid: user.uid,
        workspaceId: currentWorkspaceId,
        apiKeyId: "human_web_console",
        description: cleanDesc.slice(0, 500),
        category: (accountName || "General").slice(0, 100),
        timestamp: new Date().toISOString()
      }, { merge: true });
    } catch (e) {
      console.warn("Soft learning deferred", e);
    }
  };

  const addEntity = async (path: string, data: any, successMsg?: string) => {
    if (!user || !currentWorkspaceId) return;
    try {
      const docId = doc(collection(db, path)).id;
      const finalData = {
        ...data,
        id: docId,
        uid: user.uid,
        workspaceId: currentWorkspaceId,
        createdAt: new Date().toISOString()
      };

      if (path === 'invoices') {
        await LedgerPostService.postInvoiceLedger(docId, finalData, currentWorkspaceId, user.uid, { collection: path, docId, action: 'create', data: finalData });
        if (finalData.customerId) {
          syncEntityBalance('customers', finalData.customerId);
        }
      } else if (path === 'bills') {
        await LedgerPostService.postBillLedger(docId, finalData, currentWorkspaceId, user.uid, { collection: path, docId, action: 'create', data: finalData });
        if (finalData.vendorId) {
          syncEntityBalance('vendors', finalData.vendorId);
        }
      } else {
        await setDoc(doc(db, path, docId), finalData);
      }

      // LEARNING: If we added something with a description and a category, learn it.
      if (data.description || data.vendorName || data.customerName) {
        const desc = data.description || data.vendorName || data.customerName;
        // Check for lines or direct category fields
        if (data.lines && data.lines.length > 0) {
          const mainLine = data.lines[0];
          if (mainLine.accountId && mainLine.accountName && mainLine.accountName !== 'Uncategorized') {
            recordLearnedPattern(desc, mainLine.accountId, mainLine.accountName);
          }
        } else if (data.categoryId && data.categoryName) {
           recordLearnedPattern(desc, data.categoryId, data.categoryName);
        }
      }

      if (successMsg) toast.success(successMsg);

      return doc(db, path, docId);
    } catch (error) {
      handleFirestoreError(error, OperationType.CREATE, path);
    }
  };

  const sendInvoiceEmail = async (id: string, invoiceData: any) => {
    if (!currentWorkspaceId) return false;
    const customers = useLedgerStore.getState().customers || [];
    const customer = customers.find(c => c.id === invoiceData.customerId);
    const toEmail = invoiceData.metadata?.sentTo || customer?.email;

    if (!toEmail || toEmail.trim() === '' || toEmail === 'customer@example.com') {
      toast.error('Cannot send invoice email: Customer has no valid email address on file.');
      return false;
    }

    try {
      const res = await fetch(`/api/v1/invoices/${id}/send`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          workspaceId: currentWorkspaceId,
          toEmail,
          subject: invoiceData.metadata?.emailSubject || `Invoice ${invoiceData.number || id}`,
          body: invoiceData.metadata?.emailBody || 'Please find your invoice attached.'
        })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Invoice email sent successfully to ${toEmail}.`);
        if (data.invoiceUrl) {
          navigator.clipboard.writeText(data.invoiceUrl);
          toast.info('Payment link copied to clipboard: ' + data.invoiceUrl);
        }
        return true;
      } else {
        toast.error(data.error || 'Failed to send invoice email.');
        return false;
      }
    } catch (err) {
      console.error('Failed to send invoice email:', err);
      toast.error('Failed to send invoice email.');
      return false;
    }
  };

  const updateEntity = async (path: string, id: string, updates: any, successMsg?: string) => {
    try {
      const finalData = {
        ...updates,
        updatedAt: new Date().toISOString()
      };

      // Post to ledger if it's an invoice or a bill
      if (path === 'invoices' && updates.status === 'sent') {
        const existingInvoice: any = useLedgerStore.getState().invoices.find(i => i.id === id) || {};
        const mergedData = { ...existingInvoice, ...finalData };
        if (existingInvoice?.status !== 'sent' || updates.forceSend) {
          sendInvoiceEmail(id, mergedData);
        }
      }


      if (path === 'invoices' && user && currentWorkspaceId) {
        const existingInvoice = useLedgerStore.getState().invoices.find(i => i.id === id) || {};
        const mergedData = { ...existingInvoice, ...finalData };
        await LedgerPostService.postInvoiceLedger(id, mergedData, currentWorkspaceId, user.uid, { collection: path, docId: id, action: 'update', data: finalData });
        const targetCustId = mergedData.customerId || finalData.customerId;
        if (targetCustId) {
          syncEntityBalance('customers', targetCustId);
        }
      } else if (path === 'bills' && user && currentWorkspaceId) {
        const existingBill = useLedgerStore.getState().bills.find(b => b.id === id) || {};
        const mergedData = { ...existingBill, ...finalData };
        await LedgerPostService.postBillLedger(id, mergedData, currentWorkspaceId, user.uid, { collection: path, docId: id, action: 'update', data: finalData });
        const targetVendId = mergedData.vendorId || finalData.vendorId;
        if (targetVendId) {
          syncEntityBalance('vendors', targetVendId);
        }
      } else {
        await updateDoc(doc(db, path, id), finalData);
      }

      if (successMsg) toast.success(successMsg);
    } catch (error) {
      handleFirestoreError(error, OperationType.UPDATE, `${path}/${id}`);
    }
  };

  const deleteEntity = async (path: string, id: string, successMsg?: string) => {
    try {
      if (path === 'invoices' && currentWorkspaceId) {
        const existingInvoice = useLedgerStore.getState().invoices.find(i => i.id === id);
        await LedgerPostService.deletePostings(id, 'invoiceId', currentWorkspaceId, { collection: path, docId: id, action: 'delete' });
        if (existingInvoice?.customerId) {
          syncEntityBalance('customers', existingInvoice.customerId);
        }
      } else if (path === 'bills' && currentWorkspaceId) {
        const existingBill = useLedgerStore.getState().bills.find(b => b.id === id);
        await LedgerPostService.deletePostings(id, 'billId', currentWorkspaceId, { collection: path, docId: id, action: 'delete' });
        if (existingBill?.vendorId) {
          syncEntityBalance('vendors', existingBill.vendorId);
        }
      } else {
        await deleteDoc(doc(db, path, id));
      }

      if (successMsg) toast.success(successMsg);
    } catch (error) {
      handleFirestoreError(error, OperationType.DELETE, `${path}/${id}`);
    }
  };

  return { addEntity, updateEntity, deleteEntity, sendInvoiceEmail };
}

import { parseLocalDate } from '../lib/utils';
import { useState, useMemo, useCallback } from 'react';
import { useAuthStore } from '../stores/useAuthStore';
import { useLedgerStore } from '../stores/useLedgerStore';
import { ChartAccount, Transaction } from '../types';
import { toast } from 'sonner';
import { isPostable, isOpenInvoice, isOpenBill, lineAmount, isRevenueAccount, isExpenseAccount, calculateTransactionImpact } from '../lib/txFilters';
import { resolveAccountRole } from '../lib/accountUtils';

export function useFinancialReporting() {
  const currentWorkspaceId = useAuthStore(s => s.currentWorkspaceId);
  const transactions = useLedgerStore(s => s.transactions);
  const accounts = useLedgerStore(s => s.accounts);
  const invoices = useLedgerStore(s => s.invoices);
  const bills = useLedgerStore(s => s.bills);
  const [loading, setLoading] = useState(false);
  const [apiReports, setApiReports] = useState<any>({ pl: null, aging: null, agingAP: null, cashFlow: null });

  const fetchPL = useCallback(async (startDate?: string, endDate?: string) => {
    if (!currentWorkspaceId) return;
    setLoading(true);
    try {
      const user = useAuthStore.getState().user;
      if (!user) return;

      let url = `/api/v1/reports/pl?workspaceId=${currentWorkspaceId}`;
      if (startDate) url += `&startDate=${startDate}`;
      if (endDate) url += `&endDate=${endDate}`;

      const token = await user.getIdToken();
      const response = await fetch(url, {
         headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await response.json();
      if (data.status === 'success') {
         setApiReports((prev: any) => ({ ...prev, pl: data.data }));
      }
    } catch (e: any) {
      toast.error('Failed to fetch P&L');
    } finally {
      setLoading(false);
    }
  }, [currentWorkspaceId]);

  const fetchAging = useCallback(async (type: 'ar' | 'ap') => {
    if (!currentWorkspaceId) return;
    setLoading(true);

    try {
      const rawItems = type === 'ar' ? invoices : bills;
      const items = rawItems.filter(item => type === 'ar' ? isOpenInvoice(item) : isOpenBill(item));
      const now = new Date();

      const aging = {
        current: 0,
        "1-30": 0,
        "31-60": 0,
        "61-90": 0,
        "90+": 0,
        total: 0
      };

      items.forEach((item: any) => {
        const dueDate = parseLocalDate(item.dueDate);
        const diffDays = Math.floor((now.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24));
        const amount = item.amountCents || item.totalCents || 0;

        if (diffDays <= 0) aging.current += amount;
        else if (diffDays <= 30) aging["1-30"] += amount;
        else if (diffDays <= 60) aging["31-60"] += amount;
        else if (diffDays <= 90) aging["61-90"] += amount;
        else aging["90+"] += amount;

        aging.total += amount;
      });

      setApiReports((prev: any) => ({ ...prev, [type === 'ar' ? 'aging' : 'agingAP']: aging }));
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  }, [currentWorkspaceId, invoices, bills]);

  const fetchCashFlow = useCallback(async () => {
    if (!currentWorkspaceId) return;
    setLoading(true);

    try {
      const cashFlow = {
        operating: { total: 0, items: [] as any[] },
        investing: { total: 0, items: [] as any[] },
        financing: { total: 0, items: [] as any[] },
        netChange: 0
      };

      transactions.filter(isPostable).forEach((tx: any) => {
        const accountMap = new Map(accounts.map(a => [a.id, a]));
        tx.lines?.forEach((line: any) => {
          const acc = accountMap.get(line.accountId);
          if (!acc) return;

          const role = resolveAccountRole(acc);
          const amt = lineAmount(line, tx);

          if (isRevenueAccount(acc)) cashFlow.operating.total -= amt;
          if (isExpenseAccount(acc)) cashFlow.operating.total -= amt;

          if (role === 'ar' || acc.category === 'Receivables' || acc.category === 'Receivable') cashFlow.operating.total -= amt;
          if (role === 'ap' || acc.category === 'Payables' || acc.category === 'Payable') cashFlow.operating.total += amt;

          if (acc.category === 'Fixed Assets' || acc.category === 'Fixed Asset') {
            cashFlow.investing.total -= amt;
            cashFlow.investing.items.push({ name: tx.description, amount: -amt });
          }

          if (acc.type === 'equity' || acc.category === 'Debt' || acc.category === 'Long Term Liability') {
            cashFlow.financing.total += amt;
            cashFlow.financing.items.push({ name: tx.description, amount: amt });
          }
        });
      });

      cashFlow.netChange = cashFlow.operating.total + cashFlow.investing.total + cashFlow.financing.total;

      setApiReports((prev: any) => ({ ...prev, cashFlow }));
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  }, [currentWorkspaceId, accounts, transactions]);

  // Combined reports object
  const reports = useMemo(() => {
    // Local calculation for immediate feedback
    let localIncome = 0;
    let localExpenses = 0;
    const accountMap = new Map(accounts.map(a => [a.id, a]));

    transactions.filter(isPostable).forEach((t: Transaction) => {
      const impact = calculateTransactionImpact(t, accountMap);
      if (impact > 0) localIncome += impact;
      else if (impact < 0) localExpenses += Math.abs(impact);
    });

    return {
      ...apiReports,
      local: { income: localIncome, expenses: localExpenses, netIncome: localIncome - localExpenses }
    };
  }, [transactions, accounts, apiReports]);

  return { reports, loading, fetchPL, fetchAging, fetchCashFlow };
}

import { useMemo } from 'react';
import { Transaction, FilterCriteria, ChartAccount } from '../types';
import { LedgerEngine } from '../kernel/ledger/LedgerEngine';
import { useScenarioStore } from '../lib/scenarioStore';
import { useAuthStore } from '../stores/useAuthStore';
import { useSavedViewsStore } from '../stores/useSavedViewsStore';
import { addDays, addWeeks, addMonths, addYears, format } from 'date-fns';
import { parseLocalDate } from '../lib/utils';
import { TransactionQueryEngine } from '../lib/TransactionQueryEngine';

export function useLedgerComputation(
  transactions: Transaction[] = [], 
  filterCriteria: FilterCriteria | null = null, 
  searchTerm: string = '', 
  accounts: ChartAccount[] = [],
  sortConfig?: { key: string, direction: 'asc' | 'desc' } | null
) {
  const user = useAuthStore(s => s.user);
  const currentWorkspace = useAuthStore(s => s.getCurrentWorkspace());
  const dimensionNodes = currentWorkspace?.dimensionNodes || [];

  const scenarios = useScenarioStore(state => state.scenarios);
  const activeScenarioId = useScenarioStore(state => state.activeScenarioId);
  const activeScenario = Array.isArray(scenarios) ? scenarios.find(s => s.id === activeScenarioId) : null;

  const views = useSavedViewsStore(s => s.views);
  const activeViewId = useSavedViewsStore(s => s.activeViewId);
  const activeView = views.find(v => v.id === activeViewId);

  // Materialize Ghost Transactions into actual ledger entries for simulation
  const expandedTransactions = useMemo(() => {
    if (!activeScenario || !activeScenario.ghosts.length) return transactions;

    const materializedGhosts: Transaction[] = [];
    const horizonEndDate = addDays(new Date(), 365); // Simulate up to 1 year ahead
    const cachedCashAcc = accounts.find(a => a.type === 'asset' || a.category?.toLowerCase() === 'cash') || { id: 'ghost-asset-offset', name: 'Simulated Cash Offset' };

    activeScenario.ghosts.filter(g => g.isActive).forEach(ghost => {
      let currentDate = parseLocalDate(ghost.date);

      const createGhost = (date: Date) => {
        const mainLineAmount = ghost.type === 'income' ? -ghost.amountCents : ghost.amountCents; // Neg for Credit (Income source), Pos for Debit (Expense dest)
        const offsetLineAmount = -mainLineAmount; // Pos for Debit (Cash increase), Neg for Credit (Cash decrease)

        return {
          id: `ghost-${ghost.id}-${format(date, 'yyyyMMdd')}`,
          uid: 'system',
          workspaceId: 'simulation',
          date: format(date, 'yyyy-MM-dd'),
          description: `[GHOST] ${ghost.description}`,
          totalAmountCents: Math.abs(ghost.amountCents || 0),
          currency: 'USD',
          status: 'pending',
          type: 'forecast',
          isCleared: false,
          project: 'Simulation',
          lines: [
            {
              accountId: 'ghost-acc',
              accountName: ghost.type === 'income' ? 'Simulated Income' : 'Simulated Expense',
              amountCents: mainLineAmount,
            },
            {
              accountId: cachedCashAcc.id,
              accountName: cachedCashAcc.name,
              amountCents: offsetLineAmount,
            }
          ],
          createdAt: new Date().toISOString(),
          metadata: { isGhost: true }
        } as Transaction;
      };

      if (ghost.frequency === 'once') {
        materializedGhosts.push(createGhost(currentDate));
      } else {
        while (currentDate <= horizonEndDate) {
          materializedGhosts.push(createGhost(currentDate));
          if (ghost.frequency === 'daily') currentDate = addDays(currentDate, 1);
          else if (ghost.frequency === 'weekly') currentDate = addWeeks(currentDate, 1);
          else if (ghost.frequency === 'monthly') currentDate = addMonths(currentDate, 1);
          else if (ghost.frequency === 'quarterly') currentDate = addMonths(currentDate, 3);
          else if (ghost.frequency === 'yearly') currentDate = addYears(currentDate, 1);
          else break;
        }
      }
    });

    return [...transactions, ...materializedGhosts];
  }, [transactions, activeScenario]);

  // O(1) Lookup Maps for financial entities
  const accountMap = useMemo(() => new Set(accounts.map(a => a.id)), [accounts]);

  // Pre-sort expanded transactions. Done once per filter change.
  const sortedExpandedTransactions = useMemo(() => {
    // High-Stability sorting with tie-breakers for consistent rendering
    return [...expandedTransactions].sort((a, b) => {
      if (!a || !b) return 0;

      if (sortConfig) {
        let valA: any;
        let valB: any;

        switch (sortConfig.key) {
          case 'date': {
            valA = a.date;
            valB = b.date;
            break;
          }
          case 'amount':
            valA = Number(a.totalAmountCents) || 0;
            valB = Number(b.totalAmountCents) || 0;
            break;
          case 'description':
            valA = (a.description || '').toLowerCase();
            valB = (b.description || '').toLowerCase();
            break;
          case 'category':
            valA = (a.lines?.[0]?.accountName || '').toLowerCase();
            valB = (b.lines?.[0]?.accountName || '').toLowerCase();
            break;
          case 'project':
            valA = (a.project || '').toLowerCase();
            valB = (b.project || '').toLowerCase();
            break;
          case 'class':
            valA = (a.lines?.[0]?.class || '').toLowerCase();
            valB = (b.lines?.[0]?.class || '').toLowerCase();
            break;
          case 'type':
            valA = (a.type || '').toLowerCase();
            valB = (b.type || '').toLowerCase();
            break;
          case 'status':
            valA = (a.status || '').toLowerCase();
            valB = (b.status || '').toLowerCase();
            break;
          default:
            valA = (a as any)[sortConfig.key];
            valB = (b as any)[sortConfig.key];
        }

        if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
        if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
      }

      // Default fallback sorting
      if (a.date > b.date) return -1;
      if (a.date < b.date) return 1;

      const aTime = (a as any).createdAt || a.id;
      const bTime = (b as any).createdAt || b.id;
      if (aTime > bTime) return -1;
      if (aTime < bTime) return 1;
      return 0;
    });
  }, [expandedTransactions, sortConfig]);

  // Pre-normalize for speed
  const normalized = useMemo(() => LedgerEngine.normalize(sortedExpandedTransactions), [sortedExpandedTransactions]);

  // True O(1) Reverse Index for Dimension Lookup (Performance Optimization for 100k+ scaling)
  const reverseDimensionIndex = useMemo(() => {
    const idx = new Map<string, Set<string>>();
    for (let i = 0; i < normalized.length; i++) {
      const t = normalized[i];
      if (t.dimensions) {
        for (const nodeId of Object.values(t.dimensions)) {
          if (!idx.has(nodeId as string)) idx.set(nodeId as string, new Set());
          idx.get(nodeId as string)!.add(t.id);
        }
      }
      if (t.lines) {
        for (const line of t.lines) {
          if (line.dimensions) {
            for (const nodeId of Object.values(line.dimensions)) {
              if (!idx.has(nodeId as string)) idx.set(nodeId as string, new Set());
              idx.get(nodeId as string)!.add(t.id);
            }
          }
        }
      }
    }
    return idx;
  }, [normalized]);

  const thresholds = useMemo(() => {
    if (normalized.length === 0) return { avg: 0, totalVolume: 0, percentiles: { top10: 0, top25: 0, bottom10: 0 } };

    const totalVolume = normalized.reduce((acc, t) => acc + t._normalized.absAmount, 0);
    const avg = totalVolume / (normalized.length || 1);

    const amounts = normalized.map(t => t._normalized.absAmount).sort((a, b) => b - a);
    return {
      avg,
      totalVolume,
      percentiles: {
        top10: amounts[Math.floor(amounts.length * 0.1)] || 0,
        top25: amounts[Math.floor(amounts.length * 0.25)] || 0,
        bottom10: amounts[Math.floor(amounts.length * 0.9)] || 0,
      }
    };
  }, [normalized]);

  const smartFilteredTransactions = useMemo(() => {
    return TransactionQueryEngine.query({
      normalized,
      filterCriteria,
      searchTerm,
      accounts,
      activeView,
      dimensionNodes,
      reverseDimensionIndex,
      thresholds,
      userUid: user?.uid
    });
  }, [normalized, filterCriteria, searchTerm, accounts, activeView, dimensionNodes, reverseDimensionIndex, thresholds, user?.uid]);

  const chronologicalRunningBalances = useMemo(() => {
    // Chronologically compute historical running balance for every transaction to ensure mathematical stability.
    // Done once per transaction load, massively improving rendering & filtering performance for 50,000+ inputs.
    const chronologicalTxs = [...transactions].sort((a, b) => {
      if (a.date < b.date) return -1;
      if (a.date > b.date) return 1;
      const aTime = (a as any).createdAt || a.id;
      const bTime = (b as any).createdAt || b.id;
      if (aTime < bTime) return -1;
      if (aTime > bTime) return 1;
      return 0;
    });

    const runningBalanceMap = new Map<string, number>();
    let currentSum = 0;
    for (let i = 0; i < chronologicalTxs.length; i++) {
      const t = chronologicalTxs[i];
      currentSum += (t.totalAmountCents || 0);
      runningBalanceMap.set(t.id, currentSum);
    }
    return runningBalanceMap;
  }, [transactions]);

  const transactionsWithBalance = useMemo(() => {
    return smartFilteredTransactions.map(t => {
      const balance = chronologicalRunningBalances.get(t.id) ?? 0;
      return { ...t, balanceCents: balance };
    });
  }, [smartFilteredTransactions, chronologicalRunningBalances]);

  const stats = useMemo(() => {
    let totalExposure = 0;
    let discrepancies = 0;
    const conflicts = new Map<string, { type: string, message: string }>();

    for (const t of smartFilteredTransactions) {
      totalExposure += Math.abs(t.totalAmountCents);

      const auditErrors = LedgerEngine.auditTransaction(t, accountMap);
      if (auditErrors.length > 0) {
        discrepancies++;
        conflicts.set(t.id, { 
          type: 'audit_fail', 
          message: auditErrors.join('; ')
        });
      }
    }

    return { 
      totalExposure, 
      count: smartFilteredTransactions.length, 
      discrepancies, 
      conflicts,
      totalValues: {
        sum: smartFilteredTransactions.reduce((acc, t) => acc + (t.totalAmountCents || 0), 0)
      }
    };
  }, [smartFilteredTransactions, accounts]);

  return { smartFilteredTransactions, transactionsWithBalance, stats, conflicts: stats.conflicts };
}

import { useEffect } from 'react';
import { 
  collection, 
  query, 
  where, 
  onSnapshot, 
  doc, 
  setDoc,
  limit,
  orderBy
} from 'firebase/firestore';
import { db } from '../firebase';
import { useLedgerStore } from '../stores/useLedgerStore';
import { useAuthStore } from '../stores/useAuthStore';
import { useUIStore } from '../stores/useUIStore';
import { 
  Transaction, 
  ChartAccount, 
  JournalEntry, 
  Project, 
  Budget, 
  Vendor, 
  Customer, 
  Invoice, 
  Bill, 
  InventoryItem, 
  FixedAsset, 
  RecurringTransaction, 
  Employee, 
  PayRun, 
  TaxRate,
  Workspace,
  CustomTemplate,
  UserProfile
} from '../types';

import { handleFirestoreError, OperationType } from '../lib/firebaseUtils';

import { safeAsync } from "../lib/utils";
import { fetchSnapshotBridge, useSnapshotBridge } from "./useSnapshotBridge";


export function useLedgerData() {
  const user = useAuthStore(s => s.user);
  const currentWorkspaceId = useAuthStore(s => s.currentWorkspaceId);
  const setWorkspaces = useAuthStore(s => s.setWorkspaces);
  const setCurrentWorkspaceId = useAuthStore(s => s.setCurrentWorkspaceId);
  const setUserProfile = useAuthStore(s => s.setUserProfile);
  useSnapshotBridge();


  // 1. Workspaces
  useEffect(() => {
    if (!user) return;
    const q = query(collection(db, 'workspaces'), where('uid', '==', user.uid));
    return onSnapshot(q, async (snapshot) => {
      const fetched = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Workspace));
      setWorkspaces(fetched);

      if (fetched.length === 0 && user) {
        // Create Default Workspace
        const defaultWorkspace: Partial<Workspace> = {
          uid: user.uid,
          name: 'Personal Workspace',
          businessType: 'personal',
          createdAt: new Date().toISOString(),
          currency: 'USD'
        };
        await safeAsync(
          setDoc(doc(collection(db, 'workspaces')), defaultWorkspace),
          OperationType.CREATE,
          'workspaces',
          { userId: user.uid }
        );
      } else if (fetched.length > 0) {
        // Validation: Ensure current selection is still valid
        const isCurrentValid = fetched.some(w => w.id === currentWorkspaceId);
        if (!currentWorkspaceId || !isCurrentValid) {
          setCurrentWorkspaceId(fetched[0].id);
        }
      }
    }, (err) => handleFirestoreError(err, OperationType.LIST, 'workspaces'));
  }, [user, currentWorkspaceId, setCurrentWorkspaceId, setWorkspaces]);

  // 2. User Profile
  useEffect(() => {
    if (!user) return;
    return onSnapshot(doc(db, 'users', user.uid), async (snap) => {
      if (snap.exists()) {
        const data = snap.data() as UserProfile;
        setUserProfile(data);
      } else {
        const profileData: UserProfile = {
          uid: user.uid,
          email: user.email || '',
          role: 'client', // Default new users to 'client' role; admin elevated via backend or owner logic
          createdAt: new Date().toISOString()
        };
        await safeAsync(
          setDoc(doc(db, 'users', user.uid), profileData),
          OperationType.CREATE,
          `users/${user.uid}`
        );
        setUserProfile(profileData);
      }
    }, (err) => handleFirestoreError(err, OperationType.GET, `users/${user.uid}`));
  }, [user, setUserProfile]);

  // Sync workspace-level settings (currency, lockDate, and matchingThreshold) to the ledger store
  const workspaces = useAuthStore(state => state.workspaces);
  const baseCurrency = useLedgerStore(state => state.baseCurrency);
  const lockDate = useLedgerStore(state => state.lockDate);
  const matchingThreshold = useLedgerStore(state => state.matchingThreshold);
  const setBaseCurrency = useLedgerStore(state => state.setBaseCurrency);
  const setLockDate = useLedgerStore(state => state.setLockDate);
  const setMatchingThreshold = useLedgerStore(state => state.setMatchingThreshold);

  useEffect(() => {
    const currentWorkspace = workspaces.find(w => w.id === currentWorkspaceId);
    if (currentWorkspace) {
      const targetCurrency = currentWorkspace.currency || 'USD';
      const targetLockDate = currentWorkspace.lockDate || null;
      const targetThreshold = typeof currentWorkspace.matchingThreshold === 'number' ? currentWorkspace.matchingThreshold : 0.85;
      if (baseCurrency !== targetCurrency) {
        setBaseCurrency(targetCurrency);
      }
      if (lockDate !== targetLockDate) {
        setLockDate(targetLockDate);
      }
      if (matchingThreshold !== targetThreshold) {
        setMatchingThreshold(targetThreshold);
      }
    }
  }, [currentWorkspaceId, workspaces, baseCurrency, lockDate, matchingThreshold, setBaseCurrency, setLockDate, setMatchingThreshold]);

  // Main Entities (Workspace Scoped)
  useEffect(() => {
    if (!user || !currentWorkspaceId) return;

    // Clear data immediately to prevent ghosting between workspaces
    useLedgerStore.setState({
      transactions: [],
      accounts: [],
      journalEntries: [],
      projects: [],
      budgets: [],
      vendors: [],
      customers: [],
      invoices: [],
      bills: [],
      inventory: [],
      assets: [],
      recurring: [],
      employees: [],
      payRuns: [],
      taxRates: [],
      runningBalances: {
        totalIncome: 0,
        totalExpense: 0,
        totalBalance: 0,
        projectMetrics: {},
        categoryMetrics: {}
      }
    });


    // DATA BRIDGE: Fetch snapshot for immediate "big math" rendering on new devices
    fetchSnapshotBridge(currentWorkspaceId).then((data: any) => {
      if (data && useLedgerStore.getState().transactions.length === 0) {
        useLedgerStore.setState({
          runningBalances: {
            ...useLedgerStore.getState().runningBalances,
            totalIncome: Number(data.totalIncome || 0),
            totalExpense: Number(data.totalExpense || 0),
            totalBalance: Number(data.totalBalance || 0)
          }
        });
      }
    });

    const filter = [
      where('workspaceId', '==', currentWorkspaceId)
    ];
    const { setIsSyncing } = useUIStore.getState();

    // Track pending writes across all active listeners
    const pendingWritesMap = new Map<string, boolean>();
    const updateGlobalSyncStatus = () => {
      const isAnyPending = Array.from(pendingWritesMap.values()).some(v => v);
      setIsSyncing(isAnyPending);
    };

    // Batch updates to the store to prevent rapid-fire re-renders
    let pendingUpdates: Partial<any> = {};
    let updateTimer: any = null;

    const scheduleUpdate = (key: string, data: any, hasPendingWrites: boolean) => {
      pendingUpdates[key] = data;
      pendingWritesMap.set(key, hasPendingWrites);
      updateGlobalSyncStatus();

      if (updateTimer) clearTimeout(updateTimer);
      // Increased window for high-volume logs and history to prevent UI lockup
      const debounceMs = (key === 'auditLogs' || key === 'bankLines') ? 500 : 100;

      updateTimer = setTimeout(() => {
        const updatesToApply: any = { ...pendingUpdates };
        pendingUpdates = {};
        updateTimer = null;

        Object.entries(updatesToApply).forEach(([k, value]) => {
          const setterName = `set${k.charAt(0).toUpperCase() + k.slice(1)}`;
          const store = useLedgerStore.getState() as any;
          if (store[setterName]) {
            store[setterName](value);
          }
        });
      }, debounceMs);
    };

    const criticalListeners = [
      onSnapshot(query(collection(db, 'transactions'), ...filter, orderBy('date', 'desc')), (snap) => {
        useLedgerStore.getState().setIsDataTruncated(false);
        scheduleUpdate('transactions', snap.docs.map(d => ({ id: d.id, ...d.data() } as Transaction)), snap.metadata.hasPendingWrites);
      }, (err) => handleFirestoreError(err, OperationType.LIST, 'transactions')),
      onSnapshot(query(collection(db, 'chartAccounts'), ...filter), (snap) => {
        scheduleUpdate('accounts', snap.docs.map(d => ({ id: d.id, ...d.data() } as ChartAccount)), snap.metadata.hasPendingWrites);
      }, (err) => handleFirestoreError(err, OperationType.LIST, 'chartAccounts')),
      onSnapshot(query(collection(db, 'projects'), ...filter), (snap) => {
        scheduleUpdate('projects', snap.docs.map(d => ({ id: d.id, ...d.data() } as Project)), snap.metadata.hasPendingWrites);
      }, (err) => handleFirestoreError(err, OperationType.LIST, 'projects')),
      onSnapshot(query(collection(db, 'rulePatterns'), ...filter), (snap) => {
        const cache: Record<string, any> = {};
        snap.docs.forEach(d => {
          const data = d.data();
          cache[(data.description || '').toLowerCase().trim()] = data;
        });
        useLedgerStore.getState().setAnalyticalPatternCache(cache);
      }, (err) => handleFirestoreError(err, OperationType.LIST, 'rulePatterns')),
    ];

    const isCurrent = { active: true };
    const allUnsubs = [...criticalListeners];

    // Defer non-critical listeners to prioritize initial paint and dashboard readiness
    const secondaryTimer = setTimeout(() => {
      if (!isCurrent.active) return;
      const secondaryUnsubs = [
        onSnapshot(query(collection(db, 'budgets'), ...filter), (snap) => {
          scheduleUpdate('budgets', snap.docs.map(d => ({ id: d.id, ...d.data() } as Budget)), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'budgets')),
        onSnapshot(query(collection(db, 'vendors'), ...filter), (snap) => {
          scheduleUpdate('vendors', snap.docs.map(d => ({ id: d.id, ...d.data() } as Vendor)), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'vendors')),
        onSnapshot(query(collection(db, 'customers'), ...filter), (snap) => {
          scheduleUpdate('customers', snap.docs.map(d => ({ id: d.id, ...d.data() } as Customer)), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'customers')),
        onSnapshot(query(collection(db, 'invoices'), ...filter, orderBy('date', 'desc'), limit(2000)), (snap) => {
          scheduleUpdate('invoices', snap.docs.map(d => ({ id: d.id, ...d.data() } as Invoice)), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'invoices')),
        onSnapshot(query(collection(db, 'bills'), ...filter, orderBy('date', 'desc'), limit(2000)), (snap) => {
          scheduleUpdate('bills', snap.docs.map(d => ({ id: d.id, ...d.data() } as Bill)), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'bills')),
        onSnapshot(query(collection(db, 'inventory'), ...filter), (snap) => {
          scheduleUpdate('inventory', snap.docs.map(d => ({ id: d.id, ...d.data() } as InventoryItem)), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'inventory')),
        onSnapshot(query(collection(db, 'assets'), ...filter), (snap) => {
          scheduleUpdate('assets', snap.docs.map(d => ({ id: d.id, ...d.data() } as FixedAsset)), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'assets')),
        onSnapshot(query(collection(db, 'recurring'), ...filter), (snap) => {
          scheduleUpdate('recurring', snap.docs.map(d => ({ id: d.id, ...d.data() } as RecurringTransaction)), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'recurring')),
        onSnapshot(query(collection(db, 'employees'), ...filter), (snap) => {
          scheduleUpdate('employees', snap.docs.map(d => ({ id: d.id, ...d.data() } as Employee)), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'employees')),
        onSnapshot(query(collection(db, 'payRuns'), ...filter), (snap) => {
          scheduleUpdate('payRuns', snap.docs.map(d => ({ id: d.id, ...d.data() } as PayRun)), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'payRuns')),
        onSnapshot(query(collection(db, 'taxRates'), ...filter), (snap) => {
          scheduleUpdate('taxRates', snap.docs.map(d => ({ id: d.id, ...d.data() } as TaxRate)), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'taxRates')),
        onSnapshot(query(collection(db, 'customTemplates'), where('uid', '==', user.uid)), (snap) => {
          scheduleUpdate('customTemplates', snap.docs.map(d => ({ id: d.id, ...d.data() } as CustomTemplate)), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'customTemplates')),
        onSnapshot(query(collection(db, 'auditLogs'), ...filter, orderBy('timestamp', 'desc'), limit(500)), (snap) => {
          scheduleUpdate('auditLogs', snap.docs.map(d => ({ id: d.id, ...d.data() })), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'auditLogs')),
        onSnapshot(query(collection(db, 'partners'), ...filter), (snap) => {
          scheduleUpdate('partners', snap.docs.map(d => ({ id: d.id, ...d.data() })), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'partners')),
        onSnapshot(query(collection(db, 'reconciliations'), ...filter), (snap) => {
          scheduleUpdate('reconciliations', snap.docs.map(d => ({ id: d.id, ...d.data() })), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'reconciliations')),
        onSnapshot(query(collection(db, 'autoRules'), ...filter), (snap) => {
          scheduleUpdate('autoRules', snap.docs.map(d => ({ id: d.id, ...d.data() })), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'autoRules')),
        onSnapshot(query(collection(db, 'bankLines'), ...filter, orderBy('date', 'desc'), limit(2000)), (snap) => {
          scheduleUpdate('bankLines', snap.docs.map(d => ({ id: d.id, ...d.data() })), snap.metadata.hasPendingWrites);
        }, (err) => handleFirestoreError(err, OperationType.LIST, 'bankLines')),
      ];
      allUnsubs.push(...secondaryUnsubs);
    }, 500);

    return () => {
      isCurrent.active = false;
      allUnsubs.forEach(unsub => unsub());
      clearTimeout(secondaryTimer);
      if (updateTimer) clearTimeout(updateTimer);
    };
  }, [user, currentWorkspaceId]);

  return null;
}

import { useCallback } from 'react';
import React from 'react';
import { useUIStore } from '../stores/useUIStore';
import { SYSTEM_GLOSSARY } from '../config/registry';

/**
 * Enterprise Lexicon Translation Hook
 * Handles localization and hot-swappable live overrides for any text card, title, or label.
 */
export function useLexicon() {
  const language = useUIStore(state => state.language);
  const lexiconOverrides = useUIStore(state => state.lexiconOverrides);

  const t = useCallback((key: string, defaultVal?: string): string => {
    // 1. Check live user overrides first
    if (lexiconOverrides[key] && lexiconOverrides[key][language]) {
      return lexiconOverrides[key][language];
    }

    // 2. Resolve from central vocabulary registry
    const registryEntry = SYSTEM_GLOSSARY[key];
    if (registryEntry) {
      return registryEntry[language] || registryEntry['en'] || key;
    }

    // 3. Fallback to inline default
    return defaultVal || key;
  }, [language, lexiconOverrides]);

  return { t, language };
}

interface LexiconTextProps {
  cardKey: string;
  defaultVal: string;
  className?: string;
  as?: 'span' | 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'div';
}

/**
 * Self-Aware Copy Component
 * Renders simple localized copy dynamically from the central glossary.
 */
export const LexiconText: React.FC<LexiconTextProps> = ({
  cardKey,
  defaultVal,
  className = '',
  as = 'span'
}) => {
  const { t } = useLexicon();
  const textValue = t(cardKey, defaultVal);
  const Tag = as;

  return <Tag className={className}>{textValue}</Tag>;
};

import { useState, useEffect } from 'react';

interface BeforeInstallPromptEvent extends Event {
  readonly platforms: string[];
  readonly userChoice: Promise<{
    outcome: 'accepted' | 'dismissed';
    platform: string;
  }>;
  prompt(): Promise<void>;
}

export function usePWAInstall() {
  const [deferredPrompt, setDeferredPrompt] = useState<BeforeInstallPromptEvent | null>(null);
  const [isInstallable, setIsInstallable] = useState(false);
  const [isInstalled, setIsInstalled] = useState(() => {
    return typeof window !== 'undefined' && (
      window.matchMedia('(display-mode: standalone)').matches || 
      (navigator as any).standalone === true
    );
  });

  useEffect(() => {

    const handleBeforeInstallPrompt = (e: Event) => {
      // Prevent the mini-infobar from appearing on mobile
      e.preventDefault();
      // Stash the event so it can be triggered later.
      setDeferredPrompt(e as BeforeInstallPromptEvent);
      setIsInstallable(true);
    };

    const handleAppInstalled = () => {
      setIsInstallable(false);
      setIsInstalled(true);
      setDeferredPrompt(null);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    window.addEventListener('appinstalled', handleAppInstalled);

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
      window.removeEventListener('appinstalled', handleAppInstalled);
    };
  }, []);

  const promptInstall = async () => {
    if (!deferredPrompt) return;

    // Show the install prompt
    deferredPrompt.prompt();

    // Wait for the user to respond to the prompt
    const { outcome } = await deferredPrompt.userChoice;

    if (outcome === 'accepted') {
      setIsInstallable(false);
      setIsInstalled(true);
    }

    // We've used the prompt, and can't use it again, throw it away
    setDeferredPrompt(null);
  };

  return { isInstallable, isInstalled, promptInstall };
}

import { useEffect } from "react";
import { repository } from "../services/repository";
import { useLedgerStore } from "../stores/useLedgerStore";
import { useAuthStore } from "../stores/useAuthStore";

export function useSnapshotBridge() {
  const currentWorkspaceId = useAuthStore(s => s.currentWorkspaceId);
  const user = useAuthStore(s => s.user);
  const balances = useLedgerStore(state => state.runningBalances);
  const hasTransactions = useLedgerStore(state => state.transactions.length > 0);

  // 1. Save data bridge snapshot debounced
  useEffect(() => {
    if (!currentWorkspaceId || !user || !hasTransactions) return;

    const timeoutId = setTimeout(() => {

      // We only save the top-level big math totals
      repository.createDoc("ledgerSnapshots", {
        totalIncome: balances.totalIncome.toString(),
        totalExpense: balances.totalExpense.toString(),
        totalBalance: balances.totalBalance.toString(),
        updatedAt: new Date().toISOString(), uid: user.uid, workspaceId: currentWorkspaceId
      }, currentWorkspaceId).catch(console.error);
    }, 10000); // 10 second debounce to minimize writes

    return () => clearTimeout(timeoutId);
  }, [balances.totalBalance, currentWorkspaceId, user]);

  return { bridgeLoaded: hasTransactions };
}

export async function fetchSnapshotBridge(workspaceId: string) {
  if (!workspaceId) return null;
  try {
    const data = await repository.getDoc("ledgerSnapshots", workspaceId);
    if (data) {
      return data;
    }
  } catch(e) {
    console.warn("Bridge missing:", e);
  }
  return null;
}

import { useCallback } from 'react';
import { toast } from 'sonner';
import { db, auth } from '../firebase';
import { doc, writeBatch, collection, addDoc, setDoc } from 'firebase/firestore';
import { signOut } from 'firebase/auth';
import { useAuthStore } from '../stores/useAuthStore';
import { useLedgerStore } from '../stores/useLedgerStore';
import { useUIStore } from '../stores/useUIStore';
import { BUSINESS_TEMPLATES } from '../lib/businessTemplates';
