export function useSystemActions() {
  const user = useAuthStore(s => s.user);
  const currentWorkspaceId = useAuthStore(s => s.currentWorkspaceId);
  const currentWorkspace = useAuthStore(s => s.workspaces.find(w => w.id === s.currentWorkspaceId));

  const handleLoginPrompt = useCallback(() => {
    useAuthStore.getState().setIsGuest(false);
  }, []);

  const handleLogout = useCallback(() => {
    useAuthStore.getState().setIsGuest(false);
    localStorage.removeItem('ledgerflow_use_sandbox_mode');
    localStorage.removeItem('ledgerflow_identity_email');
    localStorage.removeItem('ledgerflow_identity_name');

    useAuthStore.getState().setUser(null);
    if (typeof useLedgerStore.getState().resetStore === 'function') {
      useLedgerStore.getState().resetStore();
    } else {
      useLedgerStore.setState({ 
        transactions: [], 
        accounts: [], 
        journalEntries: []
      });
    }

    signOut(auth).catch(() => {});
    toast.success('Returned to login screen');
  }, []);

  const handleApplyAITemplate = useCallback(async (customBlueprint: any) => {
    if (!user || !currentWorkspaceId || !customBlueprint) return;
    const loader = toast.loading(`Initiating AI ledger structural transformation...`);
    try {
      const batch = writeBatch(db);
      batch.update(doc(db, 'workspaces', currentWorkspaceId), {
        businessType: customBlueprint.id || 'ai_custom',
        analyticalTopology: customBlueprint.dashboardSchema || customBlueprint.topology
      });
      const hasTransactions = useLedgerStore.getState().transactions.length > 0;
      if (!hasTransactions) {
        const currentAccounts = useLedgerStore.getState().accounts;
        if (currentAccounts.length > 0) {
          currentAccounts.forEach(acc => {
            if (acc.id) batch.delete(doc(db, 'chartAccounts', acc.id));
          });
        }
        const accountsToMap = customBlueprint.chartOfAccounts || customBlueprint.accounts || [];
        accountsToMap.forEach((acc: any) => {
          const accRef = doc(collection(db, 'chartAccounts'));
          batch.set(accRef, {
            ...acc,
            uid: user.uid,
            workspaceId: currentWorkspaceId,
            balanceCents: 0,
            isArchived: false,
            createdAt: new Date().toISOString()
          });
        });
      } else {
        const accountsToMap = customBlueprint.chartOfAccounts || customBlueprint.accounts || [];
        accountsToMap.forEach((acc: any) => {
          const exists = useLedgerStore.getState().accounts.some((a: any) => a.name.toLowerCase() === acc.name.toLowerCase());
          if (!exists) {
            const accRef = doc(collection(db, 'chartAccounts'));
            batch.set(accRef, {
              ...acc,
              uid: user.uid,
              workspaceId: currentWorkspaceId,
              balanceCents: 0,
              isArchived: false,
              createdAt: new Date().toISOString()
            });
          }
        });
      }
      await batch.commit();
      toast.success('AI Ledger Template applied successfully.', { id: loader });
      useUIStore.getState().setAIBlueprintOpen(false);
      useUIStore.getState().setTemplateSelectorOpen(false);
      useUIStore.getState().setActiveTab('intelligence');
    } catch (error: any) {
      toast.error(`Transformation Failed: ${error.message}`, { id: loader });
    }
  }, [user, currentWorkspaceId]);

  const handleSelectTemplate = useCallback(async (templateId: string) => {
    if (!user || !currentWorkspaceId) return;
    const template = BUSINESS_TEMPLATES[templateId];
    if (!template) return;
    const loader = toast.loading(`Initiating ledger structural transformation...`);
    try {
      const batch = writeBatch(db);
      batch.update(doc(db, 'workspaces', currentWorkspaceId), {
        businessType: templateId,
        analyticalTopology: template.topology
      });
      const hasTransactions = useLedgerStore.getState().transactions.length > 0;
      if (!hasTransactions) {
        const currentAccounts = useLedgerStore.getState().accounts;
        if (currentAccounts.length > 0) {
          currentAccounts.forEach(acc => {
            if (acc.id) batch.delete(doc(db, 'chartAccounts', acc.id));
          });
        }
        template.accounts.forEach((acc: Partial<ChartAccount>) => {
          const accRef = doc(collection(db, 'chartAccounts'));
          batch.set(accRef, {
            ...acc,
            uid: user.uid,
            workspaceId: currentWorkspaceId,
            balanceCents: 0,
            createdAt: new Date().toISOString()
          });
        });
      } else {
        const currentAccounts = useLedgerStore.getState().accounts;
        const existingCodes = new Set(currentAccounts.map(a => a.code));
        const existingNames = new Set(currentAccounts.map(a => (a.name || '').toLowerCase().trim()));
        template.accounts.forEach((acc: Partial<ChartAccount>) => {
          if (!acc.code) return;
          const isCodeDuplicate = existingCodes.has(acc.code);
          const isNameDuplicate = acc.name ? existingNames.has(acc.name.toLowerCase().trim()) : false;
          if (!isCodeDuplicate && !isNameDuplicate) {
            const accRef = doc(collection(db, 'chartAccounts'));
            batch.set(accRef, {
              ...acc,
              uid: user.uid,
              workspaceId: currentWorkspaceId,
              balanceCents: 0,
              createdAt: new Date().toISOString()
            });
          }
        });
      }
      await batch.commit();
      useUIStore.getState().setTemplateSelectorOpen(false);
      useUIStore.getState().setActiveTab('ledger');
      toast.success(`STRUCTURE SET TO ${(template.name || 'UNKNOWN').toUpperCase()}`, { id: loader });
    } catch (e) {
      console.error("Template transformation aborted:", e);
      toast.error('SETUP FAILED', { id: loader });
    }
  }, [user, currentWorkspaceId]);

  const handleSaveCurrentTemplate = useCallback(async () => {
    if (!user || !currentWorkspaceId || !currentWorkspace) return;
    const name = window.prompt("Enter template name:", `${currentWorkspace.name} Clone`);
    if (!name) return;
    try {
      await addDoc(collection(db, 'customTemplates'), {
        name,
        industry: currentWorkspace.businessType || 'generic',
        accounts: useLedgerStore.getState().accounts.map(a => ({ code: a.code, name: a.name, type: a.type, category: a.category })),
        analyticalTopology: currentWorkspace.analyticalTopology || {},
        uid: user.uid,
        createdAt: new Date().toISOString()
      });
      toast.success('TEMPLATE SAVED');
    } catch (e) {
      toast.error('SNAPSHOT FAILED');
    }
  }, [user, currentWorkspaceId, currentWorkspace]);

  const handleCreateWorkspace = useCallback(async () => {
    if (!user) return;
    const name = window.prompt("Enter new workspace name:", "New Workspace");
    if (!name) return;
    try {
      const workspaceRef = doc(collection(db, 'workspaces'));
      const newWorkspace = {
        id: workspaceRef.id,
        uid: user.uid,
        name: name,
        type: 'business',
        currency: 'USD',
        businessType: 'generic',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };
      await setDoc(workspaceRef, newWorkspace);
      useAuthStore.getState().setCurrentWorkspaceId(workspaceRef.id);
      useUIStore.getState().setTemplateSelectorOpen(true);
      toast.success(`Workspace '${name}' created! Please choose an architectural template.`);
    } catch (e) {
      console.error(e);
      toast.error('Failed to create workspace');
    }
  }, [user]);

  return {
    handleLoginPrompt,
    handleLogout,
    handleApplyAITemplate,
    handleSelectTemplate,
    handleSaveCurrentTemplate,
    handleCreateWorkspace
  };
}

import { useCallback, useMemo } from 'react';
import { toast } from 'sonner';
import { useAuthStore } from '../stores/useAuthStore';
import { useLedgerStore } from '../stores/useLedgerStore';
import { useUIStore } from '../stores/useUIStore';
import { useEntityOperations } from './useEntityOperations';
import { useTransactionActions } from './useTransactionActions';
import { useFinancialReporting } from './useFinancialReporting';
import { useAIActions } from './useAIActions';
import { useAuditTelemetry } from './useAuditTelemetry';
import { VIEW_COMPONENTS, APP_TABS } from '../config/registry';

export function useCommandDispatcher() {
  const setQuickEntryOpen = useUIStore(state => state.setQuickEntryOpen);
  const setImporterOpen = useUIStore(state => state.setImporterOpen);
  const setCommandPaletteOpen = useUIStore(state => state.setCommandPaletteOpen);
  const setTemplateSelectorOpen = useUIStore(state => state.setTemplateSelectorOpen);
  const setConverterOpen = useUIStore(state => state.setConverterOpen);
  const setIntegrityOpen = useUIStore(state => state.setIntegrityOpen);
  const setGuideOpen = useUIStore(state => state.setGuideOpen);
  const setCommandCenterOpen = useUIStore(state => state.setCommandCenterOpen);
  const setActiveTab = useUIStore(state => state.setActiveTab);
  const setFilterCriteria = useUIStore(state => state.setFilterCriteria);
  const activeTab = useUIStore(state => state.activeTab);
  const { updateEntity } = useEntityOperations();

  const txActions = useTransactionActions();
  const aiActions = useAIActions();

  const handleAction = useCallback((action: string, details?: any) => {
    const actionMap: Record<string, () => void> = {
      'open-converter': () => setConverterOpen(true),
      'open-integrity': () => setIntegrityOpen(true),
      'open-health-check': () => useUIStore.getState().setHealthCheckOpen(true),
      'open-guide': () => setGuideOpen(true),
      'open-command-palette': () => setCommandPaletteOpen(true),
      'quick-entry': () => setQuickEntryOpen(true),
      'new-entry': () => setQuickEntryOpen(true),
      'bulk-repair-ledger': () => txActions.handleBulkRepair(details?.transactions || []),
      'update': () => updateEntity(details?.entityType, details?.id, details?.updates),
      'fix-ledger-imbalances': () => {
        // Usually handled by bulk update, or directly in UI
        if(details?.imbalances) {
          toast.info('Fixing imbalances');
        }
      },
      'export': () => txActions.handleExport(useLedgerStore.getState().transactions),
      'reset-workspace': () => txActions.handleResetWorkspace(),
      'analyze-trends': () => aiActions.handleAnalyzeTrends(),
      'select-architecture': () => setTemplateSelectorOpen(true),
      'settings': () => setActiveTab('settings'),
      'reports': () => setActiveTab('reports'),
      'switch-tab': () => {
        setActiveTab(details?.tab);
        if (details?.channel) {
           useUIStore.getState().setActiveIntelChannel(details.channel);
        }
        if (details?.subTab) {
           useUIStore.getState().setActiveSettingsTab(details.subTab);
        }
      },
      'drill-down': () => {
        setFilterCriteria(details);
        if (activeTab !== 'intelligence' && activeTab !== 'situation' && activeTab !== 'forecaster') {
          setActiveTab('transactions');
        }
      },
      'start-reconciliation': () => setActiveTab('reconciliation'),
      'paste-statement': () => setImporterOpen(true),
      'import_bank_csv': () => txActions.handleImportTransactions(details),
      'open-command-center': () => setCommandCenterOpen(true),
      'toggle-focus-mode': () => useUIStore.getState().toggleFocusMode(),
    };

    if (action.startsWith('select-template:')) {
       // Currently delegated inside App or via specific component. We will handle select template as a specific callback separately or inject it.
      return;
    }

    if (actionMap[action]) {
      actionMap[action]();
    } else if (VIEW_COMPONENTS[action] || APP_TABS.some(t => t.id === action)) {
      setActiveTab(action as any);
      if (details?.channel) {
        useUIStore.getState().setActiveIntelChannel(details.channel);
      }
    } else if (action === 'print') {
      window.print();
    } else if (action === 'generate') {
      toast.success('Report updated successfully.');
    } else if (action === 'filter_project') {
      if (details?.projectId) {
        useAuthStore.setState({ currentProjectId: details.projectId });
        toast.info('Filtered view by selected project');
      }
    } else {
      console.warn(`Unmapped command received: ${action}`);
    }
  }, [
    setConverterOpen, setIntegrityOpen, setGuideOpen, setCommandPaletteOpen, 
    setQuickEntryOpen, txActions, aiActions, setTemplateSelectorOpen, 
    setActiveTab, setFilterCriteria, activeTab, setImporterOpen, setCommandCenterOpen, 
  ]);

  return { handleAction };
}

