    },
    handleReconcileMatch,
    handleReconcileIgnore,
    handleReconcileCreate,
    handleReconcileUndo,
    handleAutoReconcile,
    handleAddRule,
    handleDeleteRule,
    handleDeleteAccount,
    handleUpdateRule,
    handleApplyRules,
    handleBulkRepair,
    handleIntegrityAction,
    handleToggleFlag,
    handleProcessDueRecurring: async () => {
      if (!user || !currentWorkspaceId) return { count: 0 };
      const recurringList = useLedgerStore.getState().recurring || [];
      const { dueTemplates, generatedTransactions } = findDueRecurring(recurringList);

      if (generatedTransactions.length === 0) {
        toast.info('No recurring transactions due at this time.');
        return { count: 0 };
      }

      const loader = toast.loading(`Processing ${generatedTransactions.length} due recurring transaction(s)...`);
      try {
        const batch = writeBatch(db);
        for (const item of generatedTransactions) {
          const txRef = doc(collection(db, 'transactions'));
          const balancedLines = balanceTransactionLines(item.transaction.lines || [], item.transaction.totalAmountCents || 0);
          batch.set(txRef, {
            ...item.transaction,
            lines: balancedLines,
            id: txRef.id,
            uid: user.uid,
            workspaceId: currentWorkspaceId,
            createdAt: new Date().toISOString()
          });

          const recRef = doc(db, 'recurring', item.templateId);
          batch.update(recRef, {
            nextOccurrence: item.updatedNextOccurrence
          });
        }

        await batch.commit();
        toast.success(`Successfully posted ${generatedTransactions.length} recurring transaction(s).`, { id: loader });
        return { count: generatedTransactions.length };
      } catch (err) {
        console.error('Failed to process recurring transactions:', err);
        toast.error('Failed to process recurring transactions.', { id: loader });
        throw err;
      }
    },
    handleSmartCluster: async () => {
      if (!user || !currentWorkspaceId) return;
      const loader = toast.loading('Calculating transaction clusters...');
      try {
        const txs = useLedgerStore.getState().transactions;
        const uncategorized = txs.filter(t => t.lines?.[0]?.accountId === 'uncategorized');

        if (uncategorized.length < 5) {
          toast.info('Insufficient data for statistical clustering.', { id: loader });
          return;
        }

        // Feature Engineering: Normalized Amount and Normalized Time
        const maxAmount = txs.reduce((max, t) => {
          const amt = Math.abs(t.totalAmountCents);
          return amt > max ? amt : max;
        }, 0);

        const minTime = txs.reduce((min, t) => {
          const time = parseLocalDate(t.date).getTime();
          return time < min ? time : min;
        }, Infinity);

        const maxTime = txs.reduce((max, t) => {
          const time = parseLocalDate(t.date).getTime();
          return time > max ? time : max;
        }, 0);

        const timeRange = maxTime - minTime || 1;

        const clusterData = uncategorized.map(t => ({
          id: t.id,
          x: Math.abs(t.totalAmountCents) / (maxAmount || 1),
          y: (parseLocalDate(t.date).getTime() - minTime) / timeRange
        }));

        const k = Math.min(5, Math.ceil(uncategorized.length / 10));
        const clusters = kMeans(clusterData, k);

        toast.success(`Discovered ${k} distinct spending patterns.`, { id: loader });
        return clusters;
      } catch (e) {
        toast.error('Cluster analysis failed.', { id: loader });
      }
    }
  }), [user, currentWorkspaceId, accounts, analyticalPatternCache, getCurrentWorkspace, setIsSyncing]);
}

import { auth } from '../../firebase';
import { 
  onAuthStateChanged, 
  signInWithPopup, 
  GoogleAuthProvider, 
  signOut as firebaseSignOut 
} from 'firebase/auth';
import { AuthAdapter, AuthUser } from '../../services/auth/types';

export class FirebaseAuthAdapter implements AuthAdapter {
  private mapUser(user: any): AuthUser | null {
    if (!user) return null;
    return {
      uid: user.uid,
      email: user.email,
      displayName: user.displayName,
      photoURL: user.photoURL
    };
  }

  getCurrentUser(): AuthUser | null {
    return this.mapUser(auth.currentUser);
  }

  onAuthStateChanged(callback: (user: AuthUser | null) => void): () => void {
    return onAuthStateChanged(auth, (user) => {
      callback(this.mapUser(user));
    });
  }

  async signInWithGoogle(): Promise<AuthUser> {
    const provider = new GoogleAuthProvider();
    const result = await signInWithPopup(auth, provider);
    return this.mapUser(result.user)!;
  }

  async signOut(): Promise<void> {
