  }
}

import { db } from '../../firebase';
import { 
  collection, doc, getDoc, getDocs, addDoc, setDoc, updateDoc, deleteDoc, 
  onSnapshot, query, where, writeBatch, DocumentData, QuerySnapshot, DocumentSnapshot,
  orderBy, limit
} from 'firebase/firestore';
import { DatabaseAdapter, QueryFilter, BatchOperation, QueryOptions } from '../../services/storage/types';

export class FirebaseAdapter implements DatabaseAdapter {
  async getDoc<T>(collectionPath: string, id: string): Promise<T | null> {
    const docRef = doc(db, collectionPath, id);
    const snap = await getDoc(docRef);
    return snap.exists() ? { id: snap.id, ...(snap.data() as object) } as T : null;
  }

  private buildQuery(collectionPath: string, options?: QueryOptions) {
    let q: any = collection(db, collectionPath);
    if (options) {
      if (options.filters) {
        for (const filter of options.filters) {
          q = query(q, where(filter.field, filter.operator as any, filter.value));
        }
      }
      if (options.orderBy) {
        for (const order of options.orderBy) {
          q = query(q, orderBy(order.field, order.direction || 'asc'));
        }
      }
      if (options.limit) {
        q = query(q, limit(options.limit));
      }
    }
    return q;
  }

  async getDocs<T>(collectionPath: string, options?: QueryOptions): Promise<T[]> {
    const q = this.buildQuery(collectionPath, options);
    const snap = await getDocs(q);
    return snap.docs.map((d: any) => ({ id: d.id, ...(d.data() as object) } as T));
  }

  async createDoc<T>(collectionPath: string, data: any, id?: string): Promise<string> {
    if (id) {
      await setDoc(doc(db, collectionPath, id), data);
      return id;
    } else {
      const docRef = await addDoc(collection(db, collectionPath), data);
      return docRef.id;
    }
  }

  async updateDoc(collectionPath: string, id: string, data: any): Promise<void> {
    await updateDoc(doc(db, collectionPath, id), data);
  }

  async deleteDoc(collectionPath: string, id: string): Promise<void> {
    await deleteDoc(doc(db, collectionPath, id));
  }

  subscribeToDoc<T>(collectionPath: string, id: string, callback: (data: T | null, hasPendingWrites?: boolean) => void): () => void {
    const docRef = doc(db, collectionPath, id);
    return onSnapshot(docRef, (snap: DocumentSnapshot) => {
      callback(
        snap.exists() ? { id: snap.id, ...(snap.data() as object) } as T : null,
        snap.metadata.hasPendingWrites
      );
    });
  }

  subscribeToCollection<T>(collectionPath: string, callback: (data: T[], hasPendingWrites?: boolean) => void, options?: QueryOptions): () => void {
    const q = this.buildQuery(collectionPath, options);
    return onSnapshot(q, (snap: QuerySnapshot) => {
      callback(
        snap.docs.map((d: any) => ({ id: d.id, ...(d.data() as object) } as T)),
        snap.metadata.hasPendingWrites
      );
    });
  }

  async executeBatch(operations: BatchOperation[]): Promise<void> {
    const batch = writeBatch(db);
    for (const op of operations) {
      const docRef = doc(db, op.collectionPath, op.docId);
      if (op.type === 'set') {
        batch.set(docRef, op.data!);
      } else if (op.type === 'update') {
        batch.update(docRef, op.data!);
      } else if (op.type === 'delete') {
        batch.delete(docRef);
      }
    }
    await batch.commit();
  }
}

import { ChartAccount, Transaction, JournalEntry } from '../../types';
import { isPostable } from '../../lib/txFilters';
import { allocateCents } from '../../lib/Allocation';

export class LedgerEngine {
  /**
   * Validates if a transaction satisfies the fundamental double-entry invariant.
   */
  static isBalanced(tx: Transaction): boolean {
    if (!tx.lines || tx.lines.length === 0) return false;
    // We use integer cents, so sum must be exactly zero
    const sum = tx.lines.reduce((acc, line) => acc + (line.amountCents || 0), 0);
    return sum === 0;
  }

  private static normalizationCache = new Map<string, any>();
  private static MAX_CACHE_SIZE = 150000;

  private static CACHED_SANITIZE_REGEX_CORP = /\b(inc|ltd|corp|co|llc|plc|gmbh|sa|bv|nv|ag|sas)\b/g;
  private static CACHED_SANITIZE_REGEX_CHARS = /[^a-z0-9]/g;

  private static sanitizeText(s: string) {
    return (s || '').toLowerCase()
        .replace(LedgerEngine.CACHED_SANITIZE_REGEX_CORP, '')
        .replace(LedgerEngine.CACHED_SANITIZE_REGEX_CHARS, ' ')
        .trim();
  }

  static normalize(transactions: Transaction[]) {
    // Basic high-speed eviction if cache grows too large
    if (this.normalizationCache.size > this.MAX_CACHE_SIZE) {
      this.normalizationCache.clear();
    }

    return transactions.map(t => {
      // Robust Deterministic Cache Key
      // We hash the lines to keep the key length manageable while ensuring any line change invalidates the cache
      const linesSignature = (t.lines || []).map(l => `${l.accountId}:${l.amountCents}`).join('|');
      const cacheKey = `${t.id}-${t.totalAmountCents}-${t.date}-${t.status}-${t.isCleared ? 1 : 0}-${t.tags?.join(',')}-${t.project || ''}-${linesSignature}`;

      if (this.normalizationCache.has(cacheKey)) {
        return this.normalizationCache.get(cacheKey);
      }

      const absAmount = Math.abs(t.totalAmountCents || 0) / 100;
      const tDate = t.date || '';

      const norm = {
        ...t,
        _normalized: {
          searchStr: `${t.description || ''} ${absAmount} ${tDate} ${t.isCleared ? 'cleared' : 'pending'} ${t.tags?.join(' ') || ''} ${t.project || ''} ${t.classId || ''} ${t.locationId || ''} ${t.dimensions ? Object.values(t.dimensions).join(' ') : ''} ${t.metadata ? JSON.stringify(t.metadata) : ''} ${t.lines?.map(l => `${l.accountName} ${l.description || ''} ${l.tags?.join(' ') || ''} ${l.class || ''} ${l.location || ''} ${l.project || ''} ${l.dimensions ? Object.values(l.dimensions).join(' ') : ''}`).join(' ')}`.toLowerCase()
            .normalize("NFD").replace(/[\u0300-\u036f]/g, ""),
          month: tDate.length >= 7 ? tDate.substring(0, 7) : '',
          absAmount,
          sanitizedDescription: this.sanitizeText(t.description || ''),
          year: tDate.length >= 4 ? tDate.substring(0, 4) : '',
          isLarge: absAmount > 5000,
          isTiny: absAmount < 1.00,
          isBalanced: (t.lines?.reduce((acc, line) => acc + (line.amountCents || 0), 0) || 0) === 0
        }
      };

      this.normalizationCache.set(cacheKey, norm);
      return norm;
    });
  }

  /**
   * Detects "Zombie" transactions - entries that passed balance check but contain 
   * orphaned accounts or zero-value non-offsetting lines.
   */
  static auditTransaction(tx: Transaction, accounts: ChartAccount[] | Set<string>): string[] {
    const errors: string[] = [];
    if (!this.isBalanced(tx)) errors.push('Mathematical imbalance');

    const isSet = accounts instanceof Set;

    if (tx.lines) {
      tx.lines.forEach((line, idx) => {
        const found = isSet ? (accounts as Set<string>).has(line.accountId) : (accounts as ChartAccount[]).some(a => a.id === line.accountId);
        if (!found) {
          errors.push(`Line ${idx + 1}: Account "${line.accountName}" not found in chart`);
        }
        if (line.amountCents === 0) {
          errors.push(`Line ${idx + 1}: Zero-value entries skew audit trails`);
        }
      });
    }

    return errors;
  }

  /**
   * Calculates multidimensional balances (by project, tag, etc).
   * Moved from lib/ledger-engine to kernel/ledger.
   */
  static computeDimensionalBalances(
    accounts: ChartAccount[],
    transactions: Transaction[],
    journalEntries: JournalEntry[] = []
  ): Map<string, { total: number, projects: Map<string, number> }> {
    const balances = new Map<string, { total: number, projects: Map<string, number> }>();

    // Initialize map
    accounts.forEach(acc => {
      const isDebit = acc.type === 'asset' || acc.type === 'expense' || acc.type === 'cost_of_goods';
      const opening = acc.openingBalanceCents || 0;
      balances.set(acc.id, { total: isDebit ? opening : -opening, projects: new Map() });
    });

    // We no longer loop UI transactions manually without Fx rates, etc.
    // For now, doing a basic translation.

    if (Array.isArray(transactions)) {
      transactions.forEach(tx => {
        if (!tx || typeof tx !== 'object') return;
        if (!isPostable(tx)) return;

        if (Array.isArray(tx.lines)) {
          const convertedLines = tx.lines.map(line => {
            if (!line || typeof line !== 'object') return { line, amount: 0, rawAmount: 0, rate: 1 };
            const rawAmount = typeof line.amountCents === 'number' && Number.isSafeInteger(line.amountCents) ? line.amountCents : 0;
            const rate = (typeof (line as any).exchangeRate === 'number' && (line as any).exchangeRate > 0 && Number.isFinite((line as any).exchangeRate))
              ? (line as any).exchangeRate
              : ((typeof tx.exchangeRate === 'number' && tx.exchangeRate > 0 && Number.isFinite(tx.exchangeRate)) ? tx.exchangeRate : 1);

            // #90: Enforce Number.isSafeInteger after FX conversion - fail closed on overflow
            const rawConverted = Math.round(rawAmount * rate);
            if (!Number.isSafeInteger(rawConverted)) {
              throw new Error(`Monetary overflow: Converted FX amount ${rawConverted} exceeds safe integer bounds for transaction ${tx.id || 'unknown'}.`);
            }
            const amount = rawConverted;
            return { line, amount, rawAmount, rate };
          });

          // Fix rounding errors for balanced transactions
          const sumRaw = convertedLines.reduce((acc, curr) => acc + curr.rawAmount, 0);
          if (sumRaw === 0 && convertedLines.length > 0) {
            const sumConverted = convertedLines.reduce((acc, curr) => acc + curr.amount, 0);
            if (sumConverted !== 0) {
              // Find the leg with the largest absolute converted amount to absorb the difference
              let largestIdx = 0;
              let maxAbs = -1;
              convertedLines.forEach((item, idx) => {
                const absAmt = Math.abs(item.amount);
                if (absAmt > maxAbs) {
                  maxAbs = absAmt;
                  largestIdx = idx;
                }
              });
              convertedLines[largestIdx].amount -= sumConverted;
            }
          }

          convertedLines.forEach(({ line, amount }) => {
            if (!line || typeof line !== 'object') return;
            const accId = typeof line.accountId === 'string' ? line.accountId : '';
            // #89: Strict ID resolution - no silent guessing by code or name fallback
            const accData = balances.get(accId);

            if (accData) {
              accData.total += amount;

              if (line.splitAllocations && Array.isArray(line.splitAllocations) && line.splitAllocations.length > 0) {
                const allocs = line.splitAllocations;
                const weights = allocs.map(a => a.weight || 0);
                const calculatedAmounts = allocateCents(amount, weights);

                allocs.forEach((alloc, idx) => {
                  const allocAmount = calculatedAmounts[idx];
                  const proj = alloc.dimensions?.project || alloc.dimensions?.projectId || alloc.dimensions?.property || alloc.dimensions?.world || alloc.dimensions?.classId;
                  if (proj) {
                    accData.projects.set(proj, (accData.projects.get(proj) || 0) + allocAmount);
                  }
                });
              } else {
                const proj = (typeof line.project === 'string' && line.project) || (typeof tx.projectId === 'string' && tx.projectId);
                if (proj) {
                  accData.projects.set(proj, (accData.projects.get(proj) || 0) + amount);
                }
              }
            }
          });
        }
      });
    }

    if (Array.isArray(journalEntries)) {
      journalEntries.forEach(je => {
        if (!je || typeof je !== 'object') return;
        if (je.deletedAt) return; // Journal entries only have deletedAt, not status
        if ((je as any).transactionId || (je as any).parentEventId) return; // Skip journal entries originating from transactions to prevent double-counting
        if (Array.isArray(je.lines)) {
          je.lines.forEach(line => {
            if (!line || typeof line !== 'object') return;
            const accId = typeof line.accountId === 'string' ? line.accountId : '';
            const accData = balances.get(accId);
            if (accData) {
              const debit = typeof line.debit === 'number' ? line.debit : ((line as any).debitCents || 0);
              const credit = typeof line.credit === 'number' ? line.credit : ((line as any).creditCents || 0);
              accData.total += debit - credit;
            }
          });
        }
      });
    }

    return balances;
  }

  /**
   * Recomputes ChartAccount array with live calculated balanceCents
   */
  static recomputeAccountBalances(
    accounts: ChartAccount[],
    transactions: Transaction[],
    journalEntries: JournalEntry[] = []
  ): ChartAccount[] {
    const map = this.computeDimensionalBalances(accounts, transactions, journalEntries);
    return accounts.map(acc => {
      const data = map.get(acc.id);
      const isDebit = acc.type === 'asset' || acc.type === 'expense' || acc.type === 'cost_of_goods';
      const net = data ? data.total : (isDebit ? (acc.openingBalanceCents || 0) : -(acc.openingBalanceCents || 0));
      // Convert signed balance to natural account balance
      const balanceCents = isDebit ? net : -net;
      return {
        ...acc,
        balanceCents
      };
    });
  }

  /**
   * Verifies double-entry zero-sum across all computed accounts
   */
  static verifyZeroSum(accounts: ChartAccount[]): boolean {
    let totalNet = 0;
    accounts.forEach(acc => {
      const isDebit = acc.type === 'asset' || acc.type === 'expense' || acc.type === 'cost_of_goods';
      const signed = isDebit ? (acc.balanceCents || 0) : -(acc.balanceCents || 0);
      totalNet += signed;
    });
    return Math.abs(totalNet) === 0;
  }

  /**
   * Validates that the sum of all balances across all accounts is zero.
   * Useful for ensuring the ledger is balanced at a global level.
   */
  static calculateTrialBalance(balances: Map<string, { total: number }>): { debitTotal: number, creditTotal: number, isBalanced: boolean, difference: number } {
    let debitTotal = 0;
    let creditTotal = 0;

    balances.forEach((data) => {
      if (data.total > 0) {
        debitTotal += data.total;
      } else {
        creditTotal += Math.abs(data.total);
      }
    });

    const difference = Math.abs(debitTotal - creditTotal);

    return {
      debitTotal,
      creditTotal,
      isBalanced: difference === 0,
      difference
    };
  }
}

import { Transaction } from '../../types';
import { DoubleEntryValidator } from './DoubleEntryValidator';
import { getDb } from '../../server/db/firestore';
import { TransactionSchema } from '../../schemas';
import { getAbsoluteTotal } from '../../lib/txFilters';
import { SecurityService } from '../../services/securityService';

export interface ValidationContext {
  workspaceId: string;
  user: { uid: string; admin?: boolean };
  wsData: any;
  accountsMap?: Map<string, any>;
}

export class TransactionValidator {

  static validateTransactionState(existingTx: Transaction, context: ValidationContext) {
    // 1. Period Lock
    if (context.wsData?.lockDate && existingTx.date && existingTx.date <= context.wsData.lockDate) {
      throw new Error(`Period Locked: Cannot modify transaction on ${existingTx.date} before lock date ${context.wsData.lockDate}.`);
    }

    // 2. Status Locks
    if ((existingTx.status === 'certified' || existingTx.status === 'void') && !context.user.admin) {
      throw new Error(`Forbidden: Transaction ${existingTx.id} status is locked.`);
    }

    // 3. Ownership
    if (existingTx.workspaceId !== context.workspaceId) {
      throw new Error(`Forbidden: Transaction does not belong to authorized workspace.`);
    }
  }

  static async validateAndPrepare(
    transaction: any,
    context: ValidationContext,
    existingTx?: Transaction,
    t?: any
  ): Promise<Transaction> {
    const db = getDb();

    // Ensure ownership & workspace (N14: Unconditionally enforce ownership)
    transaction.workspaceId = context.workspaceId;
    transaction.uid = context.user.uid;

    // N9: Prevent ghost simulation IDs from persisting as regular ledger transactions
    if (transaction.id && typeof transaction.id === 'string' && transaction.id.startsWith('ghost-') && transaction.type !== 'forecast') {
      throw new Error("Invalid transaction ID: 'ghost-' prefix is reserved for ephemeral client simulations.");
    }

    // #88 & N15 - Semantic contract: totalAmountCents is ALWAYS absolute positive safe integer, using FX-aware line amounts
    if (Array.isArray(transaction.lines) && transaction.lines.length > 0) {
      const calculatedTotal = getAbsoluteTotal(transaction);
      if (!Number.isSafeInteger(calculatedTotal)) {
        throw new Error(`Validation Failed: totalAmountCents exceeds safe integer bounds.`);
      }
      transaction.totalAmountCents = calculatedTotal;
    } else if (transaction.totalAmountCents !== undefined && transaction.totalAmountCents !== null) {
      const absVal = Math.abs(Math.round(transaction.totalAmountCents));
      if (!Number.isSafeInteger(absVal)) {
        throw new Error(`Validation Failed: totalAmountCents exceeds safe integer bounds.`);
      }
      transaction.totalAmountCents = absVal;
    }

    // Full Schema Validation
    const parsed = TransactionSchema.safeParse(transaction);
    if (!parsed.success) {
      const errMsgs = parsed.error.issues.map(i => `${i.path.join('.')}: ${i.message}`).join(', ');
      throw new Error(`Schema validation failed: ${errMsgs}`);
    }

    const validatedTx = {
      ...parsed.data,
      id: parsed.data.id || transaction.id || db.collection("transactions").doc().id,
      totalAmountCents: transaction.totalAmountCents ?? 0
    } as Transaction;

    // 1. Period Lock
    if (context.wsData?.lockDate && validatedTx.date && validatedTx.date <= context.wsData.lockDate) {
      throw new Error(`Period Locked: Cannot post/modify transaction on ${validatedTx.date} before lock date ${context.wsData.lockDate}.`);
    }

    // 2. Status Locks
    if (existingTx && (existingTx.status === 'certified' || existingTx.status === 'void') && !context.user.admin) {
      throw new Error(`Forbidden: Transaction ${existingTx.id} status is locked.`);
    }

    // 3. Ownership / Immutability
    if (existingTx && existingTx.workspaceId !== context.workspaceId) {
      throw new Error(`Forbidden: Transaction does not belong to authorized workspace.`);
    }

    // 4. Account Verification
    if (validatedTx.lines) {
      const accountIds = Array.from(new Set<string>(validatedTx.lines.map((l: any) => l.accountId).filter(Boolean)));
      if (accountIds.length > 0) {
        let accMap = context.accountsMap;
        if (!accMap) {
          const accRefs = accountIds.map(id => db.collection('chartAccounts').doc(id));
          const accSnaps = t ? await t.getAll(...accRefs) : await db.getAll(...accRefs);
          accMap = new Map<string, any>();
          for (const snap of accSnaps) {
            accMap.set(snap.id, snap.data());
          }
        }
        for (const id of accountIds) {
          const accData = accMap.get(id);
          if (!accData || accData.workspaceId !== context.workspaceId) {
            throw new Error(`Account ${id} does not exist or does not belong to authorized workspace.`);
          }
        }
        for (const line of validatedTx.lines) {
          if (!line.accountName && accMap.has(line.accountId)) {
            line.accountName = accMap.get(line.accountId)?.name || 'Account';
          }
        }
      }
    }

    // 5. Double Entry
    DoubleEntryValidator.validateJournalEntry(validatedTx);

    // 6. Server-Authoritative Forensic Hash Stamping
    if (!process.env.SYSTEM_SALT && process.env.NODE_ENV !== 'test') {
      throw new Error("SYSTEM_SALT environment variable is required for forensic stamping.");
    }
    const forensicHash = SecurityService.generateForensicHash(validatedTx);
    validatedTx.verification = {
      ...validatedTx.verification,
      status: 'verified',
      verifiedAt: new Date().toISOString(),
      verifiedBy: 'server-vault',
      timestamp: new Date().toISOString(),
      hash: forensicHash
    };

    return validatedTx;
  }
}

import { AhoCorasick, lexicalSimilarity, optimizedTransactionSimilarity, BayesianClassifier, SpellChecker } from './algorithms';
import { Transaction, AutoRule, DimensionNode } from '../types';
import { extractMultiDimensionalLabels, expandDeepLabels, decomposeHierarchicalLabel } from './dimensionUtils';

export interface MatchingClaim {
  accountName: string;
  confidence: number;
  status: 'AUTO_POSTED' | 'REVIEW_REQUIRED';
  provenance: {
    layer: string;
    description: string;
    evidence: string;
  };
  tags?: string[];
  dimensions?: Record<string, string>;
}

/**
 * Deterministic Entity Resolution & Matching Engine
 * Implements Layer 2 of the LedgerFlow Architecture.
 * Uses Aho-Corasick for O(N) multi-pattern matching and Levenshtein for fuzzy resolution.
 */
export class MatchingEngine {
  private ac: AhoCorasick | null = null;
  private dimAc: AhoCorasick | null = null;
  private rules: AutoRule[] = [];
  private analyticalCache: Record<string, any> = {};
  private bayes: BayesianClassifier;
  private spellChecker: SpellChecker;
  private analyticalSalt: string;
  private threshold: number;
  private dimensionNodes: DimensionNode[] = [];

  constructor(rules: AutoRule[], analyticalCache: Record<string, any> = {}, analyticalSalt = '', threshold = 0.85, allTransactions?: Transaction[], dimensionNodes?: DimensionNode[]) {
    this.rules = rules;
    this.analyticalCache = analyticalCache;
    this.analyticalSalt = analyticalSalt;
    this.threshold = threshold;
    this.dimensionNodes = dimensionNodes || [];

    this.bayes = new BayesianClassifier();
    this.spellChecker = new SpellChecker(Object.keys(analyticalCache));

    // 1. Initialize AC Trie for high-speed deterministic matching
    if (rules.length > 0) {
      const patterns = rules.flatMap(r => {
        const patternsToMatch = [];
        if (r.condition.vendor) patternsToMatch.push(r.condition.vendor);
        if (r.condition.descriptionContains) patternsToMatch.push(r.condition.descriptionContains);
        return patternsToMatch.map(p => ({ pattern: p, ruleId: r.id }));
      });

      if (patterns.length > 0) {
        this.ac = new AhoCorasick(patterns);
      }
    }

    // 1.5. Initialize AC Trie for dimension nodes
    if (this.dimensionNodes.length > 0) {
      const dimPatterns = this.dimensionNodes.flatMap(node => {
        const patterns = [...(node.aliases || [])];
        // Also use the description and ID as patterns if they are substantial
        if (node.description && node.description.length > 3) patterns.push(node.description);
        patterns.push(node.id); // e.g. "P1"
        return patterns.map(p => ({ pattern: p, ruleId: node.id }));
      });

      if (dimPatterns.length > 0) {
        this.dimAc = new AhoCorasick(dimPatterns);
      }
    }

    // 2. Seed Bayesian Network with Analytical Cache patterns (Google-Style Pre-training)
    Object.entries(analyticalCache).forEach(([description, data]: [string, any]) => {
      if (data.accountName) {
        this.bayes.train(description, data.accountName);
      }
    });

    // 3. Dynamic Auto-Learning on Finished Historical Transactions (3x accuracy improvements)
    if (allTransactions && allTransactions.length > 0) {
      allTransactions.forEach(t => {
        if (!t.deletedAt && t.status !== 'void' && t.lines && t.lines.length > 0) {
          t.lines.forEach(line => {
            if (line.accountName && line.accountName !== 'Uncategorized' && line.accountName !== 'Manual Review') {
              this.bayes.train(t.description, line.accountName);
            }
          });
        }
      });
    }
  }

  /**
   * Resolves category based on description patterns with multi-layer fallback.
   * Fully supports deep and multi-dimensional labeling (nested tags, coordinate paths, sub-labels).
   */
  resolveCategory(description: string): { accountName: string, tags?: string[], dimensions?: Record<string, string> } | null {
    const lowerDesc = (description || '').toLowerCase().trim();
    if (!lowerDesc) return null;

    // Extract deep multi-dimensional coordinates and tags from description (e.g. [Project:Apollo/Phase1] or #dept/eng)
    const extractedLabels = extractMultiDimensionalLabels(description);
    const baseDimensions: Record<string, string> = { ...extractedLabels.dimensions };
    const baseTags: string[] = [...extractedLabels.tags];

    const packageResult = (
      accountName: string, 
      extraTags?: string[], 
      extraDims?: Record<string, string>
    ) => {
      const dec = decomposeHierarchicalLabel(accountName);
      if (dec.depth > 1) {
        baseDimensions['category'] = dec.fullPath;
        baseTags.push(dec.fullPath);
      }
      const combinedDims = { ...baseDimensions, ...(extraDims || {}) };
      const combinedTags = expandDeepLabels([...baseTags, ...(extraTags || [])]);
      return {
        accountName,
        tags: combinedTags.length > 0 ? combinedTags : undefined,
        dimensions: Object.keys(combinedDims).length > 0 ? combinedDims : undefined
      };
    };

    // LAYER 0.5: Dimension Node resolution
    if (this.dimAc) {
      const dimMatches = this.dimAc.search(description);
      if (dimMatches.length > 0) {
        for (const matchId of dimMatches) {
          const node = this.dimensionNodes.find(n => n.id === matchId);
          if (node && !baseDimensions[node.dimensionId]) {
            baseDimensions[node.dimensionId] = node.id;
          }
        }
      }
    }

    // LAYER 1: Hardened Deterministic Rules (Aho-Corasick Trie) - O(N)
    if (this.ac) {
      const matches = this.ac.search(description);
      if (matches.length > 0) {
        const matchId = matches[0];
        const rule = this.rules.find(r => r.id === matchId);
        if (rule?.action.targetCategory) {
          return packageResult(
            rule.action.targetCategory,
            rule.action.targetTags,
            rule.action.targetDimensions
          );
        }
      }
    }

    // LAYER 2: Analytical Memory (Exact Match)
    const exactCache = this.analyticalCache[lowerDesc];
    if (exactCache) {
      return packageResult(exactCache.accountName, exactCache.tags, exactCache.dimensions);
    }

    // LAYER 3: Analytical Memory (Partial Word Match) - Pick longest matching pattern
    const partialMatches = Object.entries(this.analyticalCache)
      .filter(([key]) => key.length >= 4 && lowerDesc.includes(key))
      .sort((a, b) => b[0].length - a[0].length);
    if (partialMatches.length > 0) {
      const best = partialMatches[0][1];
      return packageResult(best.accountName, best.tags, best.dimensions);
    }

    // LAYER 4: Analytical Similarity (Jaro-Winkler + Semantic Overlap)
    if (lowerDesc.length > 3) {
      let bestFuzzy = { accountName: null as string | null, tags: [] as string[] | undefined, dimensions: undefined as Record<string, string> | undefined, score: 0 };
      const descWords = new Set(lowerDesc.split(/\s+/).filter(w => w.length > 2));

      for (const [key, val] of Object.entries(this.analyticalCache)) {
        if (key.length < 3) continue;

        const similarity = optimizedTransactionSimilarity(lowerDesc, key);
        const keyWords = key.split(/\s+/).filter((w: string) => w.length > 2);
        const overlapCount = keyWords.filter((w: string) => descWords.has(w)).length;
        const overlapScore = keyWords.length > 0 ? overlapCount / (keyWords.length || 1) : 0;

        const score = (similarity * 0.7) + (overlapScore * 0.3);

        if (score > this.threshold && score > bestFuzzy.score) {
          bestFuzzy = { accountName: val.accountName, tags: val.tags, dimensions: val.dimensions, score };
        }
      }
      if (bestFuzzy.accountName) {
        return packageResult(bestFuzzy.accountName, bestFuzzy.tags, bestFuzzy.dimensions);
      }
    }

    // LAYER 5: Statistical Inference (Probabilistic Models with Hierarchical Deep Categories)
    if (lowerDesc.length > 5) {
      const prediction = this.bayes.classifyHierarchical(lowerDesc);
      // Use configured threshold
      if (prediction && prediction.confidence > this.threshold) {
        return packageResult(prediction.category);
      }
    }

    // LAYER 6: Spell Correction (Typo Resistance)
    const typoCorrection = this.spellChecker.findClosest(lowerDesc, 2);
    if (typoCorrection) {
      const match = this.analyticalCache[typoCorrection];
      if (match) return packageResult(match.accountName, match.tags, match.dimensions);
    }

    // LAYER 7: Fail-safe to Manual Review
    return packageResult('Manual Review', ['UNRESOLVED_ENTRY']);
  }

  /**
   * Explains and debugs which mathematical layer matched a description
   */
  debugResolveCategory(description: string): { accountName: string; layer: string; confidence?: number; dimensions?: Record<string, string> } {
    const lowerDesc = (description || '').toLowerCase().trim();
    if (!lowerDesc) return { accountName: 'Manual Review', layer: 'Empty Input' };

    let dimensionReason = '';
    const extractedLabels = extractMultiDimensionalLabels(description);
    const baseDimensions: Record<string, string> = { ...extractedLabels.dimensions };
    if (extractedLabels.deepPaths.length > 0) {
      dimensionReason = ` (Deep Labels: ${extractedLabels.deepPaths.join(', ')})`;
    }

    // LAYER 0.5: Dimension Node resolution
    if (this.dimAc) {
      const dimMatches = this.dimAc.search(description);
      if (dimMatches.length > 0) {
        const foundAliases: string[] = [];
        for (const matchId of dimMatches) {
          const node = this.dimensionNodes.find(n => n.id === matchId);
          if (node) {
            if (!baseDimensions[node.dimensionId]) {
              baseDimensions[node.dimensionId] = node.id;
            }
            if (!foundAliases.includes(node.id)) {
              foundAliases.push(node.id);
            }
          }
        }
        if (foundAliases.length > 0) {
          dimensionReason += ` (Matched alias: ${foundAliases.join(', ')})`;
        }
      }
    }

    const packageDebug = (accountName: string, layer: string, confidence?: number, extraDims?: Record<string, string>) => {
      const dec = decomposeHierarchicalLabel(accountName);
      if (dec.depth > 1) {
        baseDimensions['category'] = dec.fullPath;
      }
      const combined = { ...baseDimensions, ...(extraDims || {}) };
      return {
        accountName,
        layer: layer + dimensionReason,
        confidence,
        dimensions: Object.keys(combined).length > 0 ? combined : undefined
      };
    };

    // LAYER 1: Hardened Deterministic Rules (Aho-Corasick Trie) - O(N)
    if (this.ac) {
      const matches = this.ac.search(description);
      if (matches.length > 0) {
        const matchId = matches[0];
        const rule = this.rules.find(r => r.id === matchId);
        if (rule?.action.targetCategory) {
          const ruleName = rule.condition.vendor || rule.condition.descriptionContains || rule.id;
          return packageDebug(rule.action.targetCategory, 'Rule: ' + ruleName, 1.0, rule.action.targetDimensions);
        }
      }
    }

    // LAYER 2: Analytical Memory (Exact Match)
    const exactCache = this.analyticalCache[lowerDesc];
    if (exactCache) {
      return packageDebug(exactCache.accountName, 'Exact Cache Pattern Match', 1.0, exactCache.dimensions);
    }

    // LAYER 3: Analytical Memory (Partial Word Match) - Pick longest matching pattern
    const partialMatches = Object.entries(this.analyticalCache)
      .filter(([key]) => key.length >= 4 && lowerDesc.includes(key))
      .sort((a, b) => b[0].length - a[0].length);
    if (partialMatches.length > 0) {
      const best = partialMatches[0][1];
      return packageDebug(best.accountName, 'Partial Cache Pattern', 0.95, best.dimensions);
    }

    // LAYER 4: Analytical Similarity (Jaro-Winkler + Semantic Overlap)
    if (lowerDesc.length > 3) {
      let bestFuzzy = { accountName: null as string | null, dimensions: undefined as Record<string, string> | undefined, score: 0 };
      const descWords = new Set(lowerDesc.split(/\s+/).filter(w => w.length > 2));

      for (const [key, val] of Object.entries(this.analyticalCache)) {
        if (key.length < 3) continue;

        const similarity = optimizedTransactionSimilarity(lowerDesc, key);
        const keyWords = key.split(/\s+/).filter((w: string) => w.length > 2);
        const overlapCount = keyWords.filter((w: string) => descWords.has(w)).length;
        const overlapScore = keyWords.length > 0 ? overlapCount / (keyWords.length || 1) : 0;

        const score = (similarity * 0.7) + (overlapScore * 0.3);

        if (score > this.threshold && score > bestFuzzy.score) {
          bestFuzzy = { accountName: val.accountName, dimensions: val.dimensions, score };
        }
      }
      if (bestFuzzy.accountName) {
        return packageDebug(bestFuzzy.accountName, 'Fuzzy Jaro-Winkler Metric', Number(bestFuzzy.score.toFixed(2)), bestFuzzy.dimensions);
      }
    }

    // LAYER 5: Statistical Inference (Probabilistic Models with Hierarchical Deep Categories)
    if (lowerDesc.length > 5) {
      const prediction = this.bayes.classifyHierarchical(lowerDesc);
      if (prediction && prediction.confidence > this.threshold) {
        return packageDebug(prediction.category, 'Bayesian Auto-Learning Model', Number(prediction.confidence.toFixed(2)));
      }
    }

    // LAYER 6: Spell Correction (Typo Resistance)
    const typoCorrection = this.spellChecker.findClosest(lowerDesc, 2);
    if (typoCorrection) {
      const match = this.analyticalCache[typoCorrection];
      if (match) {
        return packageDebug(match.accountName, `Typo Correction: ${typoCorrection}`, 0.8, match.dimensions);
      }
    }

    return packageDebug('Manual Review', 'Fallback Manual Intervention');
  }

  /**
   * Resolves a "normalized" merchant ID from a raw description.
   * Useful for grouping similar transactions from different banks.
   * This uses a hybrid Lexical-Jaro-Winkler scoring system for maximum precision.
   * Includes specific heuristics for stripping transaction metadata (The Google Way).
   */
  resolveMerchant(description: string, knownMerchants: { id: string, name: string }[]): string {
    const cleanDesc = (description || '').toLowerCase()
      .replace(/\b(sq \*|visa|pos|purchase|txn|val|int|ext|csh)\b/g, '') // Strip common bank metadata
      .replace(/[^a-z0-9 \u0590-\u05FF]/g, ' ')
      .trim();

    if (cleanDesc.length === 0) return description;

    let bestMatch = { id: description, score: 0 };

    for (const merchant of knownMerchants) {
      const merchantName = merchant.name.toLowerCase();

      // 1. Direct Pattern Intersection (High Confidence for partial matches)
      if (cleanDesc.includes(merchantName) || merchantName.includes(cleanDesc)) {
        const intersectionRatio = Math.min(cleanDesc.length, merchantName.length) / Math.max(cleanDesc.length, merchantName.length);
        if (intersectionRatio > 0.8) return merchant.id;
      }

      // 2. Statistical Similarity Scoring
      const levScore = lexicalSimilarity(cleanDesc, merchantName, this.analyticalSalt);
      const compositeScore = optimizedTransactionSimilarity(cleanDesc, merchantName);

      if (compositeScore > 0.88 && compositeScore > bestMatch.score) {
        bestMatch = { id: merchant.id, score: compositeScore };
      }
    }

    return bestMatch.id;
  }

  /**
   * Global Matching Analysis (Stability Matcher)
   * Groups a batch of raw transactions into clusters based on resolved merchants.
   */
  groupTransactions(transactions: any[]): Map<string, any[]> {
    const groups = new Map<string, any[]>();

    transactions.forEach(tx => {
      const merchantId = this.resolveMerchant(tx.description, []); // Context-free for now
      if (!groups.has(merchantId)) groups.set(merchantId, []);
      groups.get(merchantId)!.push(tx);
    });

    return groups;
  }

  /**
   * Suggests categories for a batch of transactions asynchronously in time-sliced chunks.
   * Prevents UI thread blocking when running massive classification on tons of info.
   */
  async suggestCategoriesAsync(transactions: Transaction[], onProgress?: (pct: number) => void): Promise<Map<string, { accountName: string, dimensions?: Record<string, string> }>> {
    const suggestions = new Map<string, { accountName: string, dimensions?: Record<string, string> }>();
    const chunkSize = 200; // Optimal yielding threshold for React/Vite loop constraints

    for (let i = 0; i < transactions.length; i += chunkSize) {
      // 1. Process Chunk
      const chunk = transactions.slice(i, i + chunkSize);
      chunk.forEach(tx => {
        const ruleMatch = this.resolveCategory(tx.description);
        if (ruleMatch) {
          suggestions.set(tx.id, {
            accountName: ruleMatch.accountName,
            dimensions: ruleMatch.dimensions
          });
        }
      });

      // 2. Report Progress
      if (onProgress) {
        onProgress(Math.min(100, Math.round(((i + chunk.length) / (transactions.length || 1)) * 100)));
      }

      // 3. Yield to Event Loop mathematically cleanly (prevents browser lockups)
      await new Promise(resolve => setTimeout(resolve, 0));
    }

    return suggestions;
  }

  /**
   * Evaluates input description and returns an explicit AI Claim carrying provenance and evidence.
   */
  resolveClaim(description: string): MatchingClaim {
    const debug = this.debugResolveCategory(description);
    const confidence = debug.confidence ?? (debug.layer.startsWith('Rule') || debug.layer.startsWith('Exact') ? 1.0 : 0.7);
    const isHighConfidence = confidence >= this.threshold && (debug.layer.startsWith('Rule') || debug.layer.startsWith('Exact'));

    return {
      accountName: debug.accountName,
      confidence,
      status: isHighConfidence ? 'AUTO_POSTED' : 'REVIEW_REQUIRED',
      provenance: {
        layer: debug.layer,
        description,
        evidence: `Matched via ${debug.layer} (confidence: ${(confidence * 100).toFixed(0)}%)`
      },
      dimensions: debug.dimensions
    };
  }

  /**
   * Suggests categories for a batch of transactions by cross-referencing
   * existing rules and merchant similarity. (Synchronous legacy wrapper)
   */
  suggestCategories(transactions: Transaction[]): Map<string, string> {
    const suggestions = new Map<string, string>();

    transactions.forEach(tx => {
      // 1. Try direct rule match
      const ruleMatch = this.resolveCategory(tx.description);
      if (ruleMatch) {
        suggestions.set(tx.id, ruleMatch.accountName);
        return;
      }
    });

    return suggestions;
  }
}

import { Transaction, FilterCriteria, ChartAccount } from '../types';
import { LedgerEngine } from '../kernel/ledger/LedgerEngine';
import { jaroWinklerSimilarity } from '../lib/algorithms';
import { TruthEngine } from '../modules/integrity/TruthEngine';
import { format } from 'date-fns';
import { parseLocalDate, resolveAccountName } from '../lib/utils';
import { isSimulationTransaction } from './txFilters';

// RULES PATTERN ENGINE: Pre-compiled static regex for maximum pipeline throughput
export const PATTERNS = {
  OP: /(>=|<=|[><=])\s*([\d,]+(?:\.\d+)?)/,
  TEXT_OP: /(greater than|more than|over|above|less than|under|below|at least|at most|around|about|approx|approximately)\s*([\d,]+(?:\.\d+)?)/,
  RANGE: /between\s*([\d,]+(?:\.\d+)?)\s*and\s*([\d,]+(?:\.\d+)?)/,
  PERCENTILE: /\b(top|bottom)\s*(10|25|50)\s*%?\b/,
  MONTH: /\b(january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)\b/,
  YEAR: /\b(20\d{2})\b/,
  RELATIVE: /\b(last month|this month|last week|this week|yesterday|today|last year|this year|last 7 days|last 30 days|ytd)\b/,
  QUARTER: /\b(q[1-4])\b/,
  DATE_RANGE: /(\d{4}-\d{2}-\d{2})\s*(?:to|and)\s*(\d{4}-\d{2}-\d{2})/,
  SINCE_DATE: /\b(since|after)\s*(\d{4}-\d{2}-\d{2})\b/,
  BEFORE_DATE: /\b(before|until)\s*(\d{4}-\d{2}-\d{2})\b/,
  CATEGORY: /(category|type|account):\s*([a-zA-Z\s]+)/,
  PROJECT: /(project|initiative|tag):\s*([a-zA-Z\s]+)/,
  CLASS: /(class|segment):\s*([a-zA-Z\s]+)/,
  LOCATION: /(location|office|site):\s*([a-zA-Z\s]+)/,
  STARTS_WITH: /starts\s+with\s+([a-zA-Z0-9\s]+)/,
  ENDS_WITH: /ends\s+with\s+([a-zA-Z0-9\s]+)/,
  CONTAINS: /contains\s+([a-zA-Z0-9\s]+)/,
  ERROR: /\b(error|mismatch|conflict|audit|review|unbalanced)\b/,
  AVERAGE: /\b(above|below)\s+average\b/,
};

export interface QueryEngineOptions {
  normalized: any[];
  filterCriteria: FilterCriteria | null;
  searchTerm: string;
  accounts: ChartAccount[];
  activeView: any;
  dimensionNodes: any[];
  reverseDimensionIndex: Map<string, Set<string>>;
  thresholds: {
    avg: number;
    totalVolume: number;
    percentiles: {
      top10: number;
      top25: number;
      bottom10: number;
    };
  };
  userUid?: string;
}

export class TransactionQueryEngine {
  static query(options: QueryEngineOptions): any[] {
    const {
      normalized,
      filterCriteria,
      searchTerm,
      accounts,
      activeView,
      dimensionNodes,
      reverseDimensionIndex,
      thresholds,
      userUid
    } = options;

    const hasFilter = filterCriteria && Object.keys(filterCriteria).length > 0;

    // Determine effective search term from component props AND active view
    const viewSearch = activeView?.filter?.searchTerm;
    const effectiveSearchTerm = (searchTerm.trim().length > 0) 
      ? (viewSearch ? `${viewSearch} ${searchTerm}` : searchTerm) 
      : (viewSearch || '');
    const hasSearch = effectiveSearchTerm.trim().length > 0;

    const allowSimulations = Boolean(filterCriteria?.includeSimulations || (activeView?.filter as any)?.includeSimulations);
    if (!hasFilter && !hasSearch && !activeView) {
      return allowSimulations ? normalized : normalized.filter(t => !isSimulationTransaction(t));
    }

    const lowerSearch = effectiveSearchTerm.toLowerCase().trim();

    // Parse Key-Value directives, amount operators, temporal context, and free-text terms
    const keyValues: Record<string, string> = {};
    let queryText = lowerSearch;

    // Extract key:value filters (e.g., category:Meals, account:Checking, type:expense, status:pending, payee:Apple, is:pending, min:100, max:500)
    const kvRegex = /\b(category|account|project|type|status|class|location|payee|vendor|customer|tag|code|id|min|max|is):\s*([a-zA-Z0-9_.-]+)/gi;
    let kvMatch;
    while ((kvMatch = kvRegex.exec(lowerSearch)) !== null) {
      const key = kvMatch[1].toLowerCase();
      const val = kvMatch[2].toLowerCase();
      keyValues[key] = val;
    }
    queryText = queryText.replace(kvRegex, ' ');

    // 1. Precise Amount Operators
    const opMatch = queryText.match(PATTERNS.OP);
    if (opMatch) queryText = queryText.replace(PATTERNS.OP, ' ');

    const textOpMatch = queryText.match(PATTERNS.TEXT_OP);
    if (textOpMatch) queryText = queryText.replace(PATTERNS.TEXT_OP, ' ');

    const rangeMatch = queryText.match(PATTERNS.RANGE);
    if (rangeMatch) queryText = queryText.replace(PATTERNS.RANGE, ' ');

    const percentileMatch = queryText.match(PATTERNS.PERCENTILE);
    if (percentileMatch) queryText = queryText.replace(PATTERNS.PERCENTILE, ' ');

    const averageMatch = queryText.match(PATTERNS.AVERAGE);
    if (averageMatch) queryText = queryText.replace(PATTERNS.AVERAGE, ' ');

    // 2. Temporal Context Parsers (Most specific first)
    const dateRangeMatch = queryText.match(PATTERNS.DATE_RANGE);
    if (dateRangeMatch) queryText = queryText.replace(PATTERNS.DATE_RANGE, ' ');

    const sinceDateMatch = queryText.match(PATTERNS.SINCE_DATE);
    if (sinceDateMatch) queryText = queryText.replace(PATTERNS.SINCE_DATE, ' ');

    const beforeDateMatch = queryText.match(PATTERNS.BEFORE_DATE);
    if (beforeDateMatch) queryText = queryText.replace(PATTERNS.BEFORE_DATE, ' ');

    const relativeTimeMatch = queryText.match(PATTERNS.RELATIVE);
    if (relativeTimeMatch) queryText = queryText.replace(PATTERNS.RELATIVE, ' ');

    const quarterMatch = queryText.match(PATTERNS.QUARTER);
    if (quarterMatch) queryText = queryText.replace(PATTERNS.QUARTER, ' ');

    const monthMatch = queryText.match(PATTERNS.MONTH);
    if (monthMatch) queryText = queryText.replace(PATTERNS.MONTH, ' ');

    const yearMatch = queryText.match(PATTERNS.YEAR);
    if (yearMatch) queryText = queryText.replace(PATTERNS.YEAR, ' ');

    // 3. Entity & Advanced String Tags
    const categoryMatch = queryText.match(PATTERNS.CATEGORY);
    if (categoryMatch) queryText = queryText.replace(PATTERNS.CATEGORY, ' ');

    const projectMatch = queryText.match(PATTERNS.PROJECT);
    if (projectMatch) queryText = queryText.replace(PATTERNS.PROJECT, ' ');

    const classMatch = queryText.match(PATTERNS.CLASS);
    if (classMatch) queryText = queryText.replace(PATTERNS.CLASS, ' ');

    const locationMatch = queryText.match(PATTERNS.LOCATION);
    if (locationMatch) queryText = queryText.replace(PATTERNS.LOCATION, ' ');

    const startsWithMatch = queryText.match(PATTERNS.STARTS_WITH);
    if (startsWithMatch) queryText = queryText.replace(PATTERNS.STARTS_WITH, ' ');

    const endsWithMatch = queryText.match(PATTERNS.ENDS_WITH);
    if (endsWithMatch) queryText = queryText.replace(PATTERNS.ENDS_WITH, ' ');

    const containsMatch = queryText.match(PATTERNS.CONTAINS);
    if (containsMatch) queryText = queryText.replace(PATTERNS.CONTAINS, ' ');

    const errorMatch = queryText.match(PATTERNS.ERROR);
    if (errorMatch) queryText = queryText.replace(PATTERNS.ERROR, ' ');

    // 4. Negative Terms (-term or NOT term)
    const negativeTerms: string[] = [];
    const negRegex = /(?:^|\s)-(?:[a-zA-Z0-9_.-]+)|(?:^|\s)NOT\s+([a-zA-Z0-9_.-]+)/gi;
    let negMatch;
    while ((negMatch = negRegex.exec(queryText)) !== null) {
      const rawMatch = negMatch[0].trim();
      if (rawMatch.startsWith('-')) {
        negativeTerms.push(rawMatch.substring(1).toLowerCase());
      } else if (negMatch[1]) {
        negativeTerms.push(negMatch[1].toLowerCase());
      }
    }
    queryText = queryText.replace(negRegex, ' ');

    // 5. Remaining Free-Text Words
    const freeTextKeywords = queryText
      .toLowerCase()
      .split(/\s+/)
      .map((w: string) => w.trim())
      .filter((w: string) => w.length > 0 && w !== 'and' && w !== 'or');

    // 6. Entity Intent Resolver (Heuristic categorization without prefixes)
    const possibleEntityMatch = freeTextKeywords.length > 0 && !Object.values(PATTERNS).some(p => lowerSearch.match(p));
    const recognizedAccountNames = possibleEntityMatch ? accounts.filter((a: any) => 
      freeTextKeywords.some((kw: string) => (a.name || '').toLowerCase().includes(kw) || (a.category || '').toLowerCase().includes(kw)) ||
      freeTextKeywords.some((kw: string) => jaroWinklerSimilarity(kw, (a.name || '').toLowerCase()) > 0.88)
    ).map((a: any) => a.name) : [];

    // Convert to Set for O(1) lookup inside the 100k hot-loop
    const recognizedAccountNamesSet = new Set(recognizedAccountNames);
    const accountMap = new Set(accounts.map(a => a.id));

    // Dimension Node Intent Resolver
    const recognizedDimensionNodeIds = possibleEntityMatch ? dimensionNodes.filter((n: any) => 
      freeTextKeywords.some((kw: string) => (n.id || '').toLowerCase() === kw || (n.description || '').toLowerCase().includes(kw)) ||
      freeTextKeywords.some((kw: string) => n.aliases?.some((a: string) => a.toLowerCase().includes(kw))) ||
      freeTextKeywords.some((kw: string) => jaroWinklerSimilarity(kw, (n.description || '').toLowerCase()) > 0.88)
    ).map((n: any) => n.id) : [];

    // Pull directly from O(1) reverse index for dimension matches to avoid scanning dimensions in loop
    const matchedByDimensionTxIds = new Set<string>();
    if (recognizedDimensionNodeIds.length > 0) {
       recognizedDimensionNodeIds.forEach(nId => {
          const txs = reverseDimensionIndex.get(nId);
          if (txs) txs.forEach(tId => matchedByDimensionTxIds.add(tId));
       });
    }

    // Helper function to test keyword presence across all searchable transaction fields
    const checkKeywordMatch = (t: any, kw: string): boolean => {
      if (!kw) return true;
      if ((t.description || '').toLowerCase().includes(kw)) return true;
      if (t._normalized?.sanitizedDescription?.toLowerCase().includes(kw)) return true;
      if ((t.payee || '').toLowerCase().includes(kw)) return true;
      if ((t.project || '').toLowerCase().includes(kw)) return true;
      if ((t.id || '').toLowerCase().includes(kw)) return true;
      if ((t.type || '').toLowerCase().includes(kw)) return true;
      if ((t.status || '').toLowerCase().includes(kw)) return true;
      if (t.tags && t.tags.some((tag: string) => tag.toLowerCase().includes(kw))) return true;

      if (t.lines) {
        for (const l of t.lines) {
          if ((l.description || '').toLowerCase().includes(kw)) return true;
          if ((l.accountName || '').toLowerCase().includes(kw)) return true;
          if ((l.memo || '').toLowerCase().includes(kw)) return true;
          if ((l.class || '').toLowerCase().includes(kw)) return true;
          if ((l.location || '').toLowerCase().includes(kw)) return true;
          if (l.tags && l.tags.some((tg: string) => tg.toLowerCase().includes(kw))) return true;
        }
      }

      const firstAccountId = t.lines?.[0]?.accountId;
      if (firstAccountId) {
        const acc = accounts.find(a => a.id === firstAccountId);
        if (acc) {
          if ((acc.name || '').toLowerCase().includes(kw)) return true;
          if ((acc.code || '').toLowerCase().includes(kw)) return true;
          if ((acc.category || '').toLowerCase().includes(kw)) return true;
        }
      }

      if (recognizedAccountNamesSet.has(t.lines?.[0]?.accountName || '') || matchedByDimensionTxIds.has(t.id)) {
        return true;
      }

      if (kw.length >= 3) {
        const similarity = jaroWinklerSimilarity(kw, (t.description || '').toLowerCase(), userUid, t._normalized?.sanitizedDescription);
        if (similarity >= 0.85) return true;
      }

      return false;
    };

    // Intent Resolution & Sub-Hot-Loop Pre-computation (CRITICAL FOR PERFORMANCE AT 100k RECORDS)
    const opVal = opMatch ? { op: opMatch[1], val: TruthEngine.parseAmountToCents(opMatch[2]) / 100 } : null;
    let textOp = null;
    if (textOpMatch) {
      const phrase = textOpMatch[1];
      const val = TruthEngine.parseAmountToCents(textOpMatch[2]) / 100;
      if (phrase.includes('greater') || phrase.includes('more') || phrase.includes('over') || phrase.includes('above')) textOp = { op: '>', val };
      else if (phrase.includes('less') || phrase.includes('under') || phrase.includes('below')) textOp = { op: '<', val };
      else if (phrase.includes('least')) textOp = { op: '>=', val };
      else if (phrase.includes('most')) textOp = { op: '<=', val };
      else if (phrase.includes('around') || phrase.includes('about') || phrase.includes('approx')) textOp = { op: '~', val };
    }

    // Precalculate parsed parameters for Range Logic
    const rangeMin = rangeMatch ? TruthEngine.parseAmountToCents(rangeMatch[1]) / 100 : 0;
    const rangeMax = rangeMatch ? TruthEngine.parseAmountToCents(rangeMatch[2]) / 100 : 0;

    // Precalculate Month Logic
    const parsedMonthIdx = (() => {
      if (!monthMatch) return -1;
      const mNames = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december", "jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
      return mNames.indexOf(monthMatch[1].toLowerCase()) % 12;
    })();
    const parsedMonthStr = parsedMonthIdx !== -1 ? (parsedMonthIdx + 1).toString().padStart(2, '0') : '';

    // Precalculate Relative Date thresholds and state variables
    const parsedRelativeRel = relativeTimeMatch ? relativeTimeMatch[1].toLowerCase() : '';
    const parsedNow = new Date();
    const parsedNowMonth = parsedNow.getMonth();
    const parsedNowYear = parsedNow.getFullYear();
    const parsedNowTime = parsedNow.getTime();
    const parsedTodayStr = format(parsedNow, 'yyyy-MM-dd');

    // Precalculate prefix filter parameters
    const queryCategory = categoryMatch ? categoryMatch[2].trim().toLowerCase() : '';
    const queryProject = projectMatch ? projectMatch[2].trim().toLowerCase() : '';
    const queryClass = classMatch ? classMatch[2].trim().toLowerCase() : '';
    const queryLocation = locationMatch ? locationMatch[2].trim().toLowerCase() : '';
    const queryStartsWith = startsWithMatch ? startsWithMatch[1].trim().toLowerCase() : '';
    const queryEndsWith = endsWithMatch ? endsWithMatch[1].trim().toLowerCase() : '';
    const queryContains = containsMatch ? containsMatch[1].trim().toLowerCase() : '';

    return normalized.filter(t => {
      // Identity Consistency Guard
      if (!t.id || !t._normalized) return false;

      // #100: Ghost / simulation / forecast isolation from normal queries unless explicitly requested
      const allowSimulations = Boolean(filterCriteria?.includeSimulations || (activeView?.filter as any)?.includeSimulations);
      if (!allowSimulations && isSimulationTransaction(t)) {
        return false;
      }

      // Active View (Saved Search & Filters)
      if (activeView) {
        const vFilter = activeView.filter;

        if (vFilter.accountTypes && vFilter.accountTypes.length > 0) {
          const mainLineAccount = accounts.find(a => a.id === t.lines?.[0]?.accountId) || { type: 'expense' };
          if (!vFilter.accountTypes.includes(mainLineAccount.type)) return false;
        }

        if (vFilter.accountIds && vFilter.accountIds.length > 0) {
          if (!vFilter.accountIds.includes(t.lines?.[0]?.accountId || '')) return false;
        }

        if (vFilter.minAmountCents !== undefined && t.totalAmountCents < vFilter.minAmountCents) return false;
        if (vFilter.maxAmountCents !== undefined && t.totalAmountCents > vFilter.maxAmountCents) return false;
        if (vFilter.type && vFilter.type !== 'all' && t.type !== vFilter.type) return false;
        if (vFilter.status && vFilter.status !== 'all' && t.status !== vFilter.status) return false;
        if (vFilter.projectId && t.project !== vFilter.projectId) return false;
      }

      // Filter Criteria (UI Overrides) - Optimized Procedural Filtering
      if (filterCriteria) {
        if ((filterCriteria.selectedCategories?.length ?? 0) > 0) {
          const account = resolveAccountName(accounts, t.lines?.[0]?.accountId, t.lines?.[0]?.accountName);
          if (!filterCriteria.selectedCategories?.includes(account || '')) return false;
        }
        if ((filterCriteria.selectedProjects?.length ?? 0) > 0) {
          if (!filterCriteria.selectedProjects?.includes(t.project || '')) return false;
        }
        if ((filterCriteria.selectedClasses?.length ?? 0) > 0) {
          const txClass = t.lines?.[0]?.class;
          if (!filterCriteria.selectedClasses?.includes(txClass || '')) return false;
        }
        if ((filterCriteria.selectedStatuses?.length ?? 0) > 0) {
          if (!filterCriteria.selectedStatuses?.includes(t.status || '')) return false;
        }
        if ((filterCriteria.selectedTypes?.length ?? 0) > 0) {
          if (!filterCriteria.selectedTypes?.includes(t.type || '')) return false;
        }

        const categoryName = resolveAccountName(accounts, t.lines?.[0]?.accountId, t.lines?.[0]?.accountName);
        if (filterCriteria.category && filterCriteria.category !== 'All' && categoryName !== filterCriteria.category) return false;
        if (filterCriteria.project && filterCriteria.project !== 'All' && t.project !== filterCriteria.project) return false;
        if (filterCriteria.type && filterCriteria.type !== 'All' && t.type !== filterCriteria.type) return false;

        if (filterCriteria.startDate && t.date < filterCriteria.startDate) return false;
        if (filterCriteria.endDate && t.date > filterCriteria.endDate) return false;
        if (filterCriteria.minAmount !== undefined && t._normalized.absAmount < filterCriteria.minAmount) return false;
        if (filterCriteria.maxAmount !== undefined && t._normalized.absAmount > filterCriteria.maxAmount) return false;

        // Class and Location arrays
        if (filterCriteria.selectedClasses && filterCriteria.selectedClasses.length > 0) {
          const match = t.lines?.some((l: any) => filterCriteria.selectedClasses?.includes(l.class || 'Unspecified'));
          if (!match) return false;
        }
        if (filterCriteria.selectedLocations && filterCriteria.selectedLocations.length > 0) {
          const match = t.lines?.some((l: any) => filterCriteria.selectedLocations?.includes(l.location || 'Unspecified'));
          if (!match) return false;
        }
      }

      // Smart Multi-Token Search Logic (Conjunctive & Precision Engine)
      if (hasSearch) {
        let isMatch = true;

        // A. Key-Value & Directive Filters (category, account, project, type, status, class, location, payee, vendor, tag, min, max, is)
        if (keyValues['category'] || keyValues['account']) {
          const target = keyValues['category'] || keyValues['account'];
          const catName = resolveAccountName(accounts, t.lines?.[0]?.accountId, t.lines?.[0]?.accountName).toLowerCase();
          const mainLineAcc = accounts.find(a => a.id === t.lines?.[0]?.accountId);
          const accName = (mainLineAcc?.name || '').toLowerCase();
          const accCode = (mainLineAcc?.code || '').toLowerCase();
          if (!catName.includes(target) && !accName.includes(target) && !accCode.includes(target)) {
            isMatch = false;
          }
        }

        if (isMatch && keyValues['project']) {
          const proj = (t.project || '').toLowerCase();
          if (!proj.includes(keyValues['project'])) isMatch = false;
        }

        if (isMatch && keyValues['type']) {
          const tType = (t.type || '').toLowerCase();
          if (tType !== keyValues['type']) isMatch = false;
        }

        if (isMatch && keyValues['status']) {
          const tStatus = (t.status || '').toLowerCase();
          if (tStatus !== keyValues['status']) isMatch = false;
        }

        if (isMatch && keyValues['class']) {
          const hasClass = t.lines?.some((l: any) => (l.class || '').toLowerCase().includes(keyValues['class']));
          if (!hasClass) isMatch = false;
        }

        if (isMatch && keyValues['location']) {
          const hasLoc = t.lines?.some((l: any) => (l.location || '').toLowerCase().includes(keyValues['location']));
          if (!hasLoc) isMatch = false;
        }

        if (isMatch && (keyValues['payee'] || keyValues['vendor'] || keyValues['customer'])) {
          const targetPayee = keyValues['payee'] || keyValues['vendor'] || keyValues['customer'];
          const p = (t.payee || '').toLowerCase();
          if (!p.includes(targetPayee)) isMatch = false;
        }

        if (isMatch && keyValues['tag']) {
          const targetTag = keyValues['tag'];
          const hasTag = (t.tags && t.tags.some((tg: string) => tg.toLowerCase().includes(targetTag))) ||
            t.lines?.some((l: any) => l.tags && l.tags.some((tg: string) => tg.toLowerCase().includes(targetTag)));
          if (!hasTag) isMatch = false;
        }

        if (isMatch && keyValues['code']) {
          const targetCode = keyValues['code'];
          const mainLineAcc = accounts.find(a => a.id === t.lines?.[0]?.accountId);
          if (mainLineAcc?.code?.toLowerCase() !== targetCode && !(t.lines || []).some((l: any) => l.accountId?.toLowerCase().includes(targetCode))) {
            isMatch = false;
          }
        }

        if (isMatch && keyValues['id']) {
          if (!t.id.toLowerCase().includes(keyValues['id'])) isMatch = false;
        }

        if (isMatch && keyValues['min']) {
          const minVal = parseFloat(keyValues['min']);
          if (!isNaN(minVal) && t._normalized.absAmount < minVal) isMatch = false;
        }

        if (isMatch && keyValues['max']) {
          const maxVal = parseFloat(keyValues['max']);
          if (!isNaN(maxVal) && t._normalized.absAmount > maxVal) isMatch = false;
        }

        // Boolean 'is:' directives
        if (isMatch && keyValues['is']) {
          const isDirective = keyValues['is'];
          if (isDirective === 'pending' && t.status !== 'pending') isMatch = false;
          else if (isDirective === 'posted' && t.status !== 'completed' && (t.status as string) !== 'posted') isMatch = false;
          else if (isDirective === 'cleared' && !t.isCleared) isMatch = false;
          else if (isDirective === 'reconciled' && t.status !== 'reconciled' && !t.isCleared) isMatch = false;
          else if (isDirective === 'unbalanced') {
            const isUnbalanced = LedgerEngine.auditTransaction(t, accountMap).some((err: string) => err.toLowerCase().includes('unbalanced') || err.toLowerCase().includes('imbalance'));
            if (!isUnbalanced) isMatch = false;
          }
          else if (isDirective === 'error') {
            const auditErrors = LedgerEngine.auditTransaction(t, accountMap);
            if (auditErrors.length === 0) isMatch = false;
          }
          else if (isDirective === 'ghost' || isDirective === 'forecast') {
            if (t.type !== 'forecast' && !t.metadata?.isGhost) isMatch = false;
          }
          else if (isDirective === 'split') {
            if (!t.lines || t.lines.length <= 2) isMatch = false;
          }
        }

        // B. Amount Heuristics
        if (isMatch && opVal) {
          const amt = t._normalized.absAmount;
          if (opVal.op === '>' && !(amt > opVal.val)) isMatch = false;
          else if (opVal.op === '>=' && !(amt >= opVal.val)) isMatch = false;
          else if (opVal.op === '<' && !(amt < opVal.val)) isMatch = false;
          else if (opVal.op === '<=' && !(amt <= opVal.val)) isMatch = false;
          else if (opVal.op === '=' && !(Math.abs(amt - opVal.val) < 0.01)) isMatch = false;
        } 
        else if (isMatch && textOp) {
          const actualAmt = t._normalized.absAmount;
          if (textOp.op === '>') { if (!(actualAmt > textOp.val)) isMatch = false; }
          else if (textOp.op === '>=') { if (!(actualAmt >= textOp.val)) isMatch = false; }
          else if (textOp.op === '<') { if (!(actualAmt < textOp.val)) isMatch = false; }
          else if (textOp.op === '<=') { if (!(actualAmt <= textOp.val)) isMatch = false; }
          else if (textOp.op === '~') { if (!(actualAmt >= textOp.val * 0.9 && actualAmt <= textOp.val * 1.1)) isMatch = false; }
        }
        else if (isMatch && rangeMatch) {
          const amt = t._normalized.absAmount;
          if (amt < rangeMin || amt > rangeMax) isMatch = false;
        }

        // C. Statistical Anchors
        if (isMatch && averageMatch) {
          const rel = averageMatch[1].toLowerCase();
          if (rel === 'above' && t._normalized.absAmount <= thresholds.avg) isMatch = false;
          if (rel === 'below' && t._normalized.absAmount >= thresholds.avg) isMatch = false;
        }
        if (isMatch && percentileMatch) {
          const side = percentileMatch[1].toLowerCase();
          const pct = percentileMatch[2];
          const amt = t._normalized.absAmount;
          if (side === 'top') {
            const threshold = pct === '10' ? thresholds.percentiles.top10 : pct === '25' ? thresholds.percentiles.top25 : (thresholds.percentiles.top25 * 0.5);
            if (amt < threshold) isMatch = false;
          } else if (side === 'bottom') {
            const threshold = pct === '10' ? thresholds.percentiles.bottom10 : pct === '25' ? (thresholds.percentiles.bottom10 * 2) : (thresholds.percentiles.bottom10 * 3);
            if (amt > threshold) isMatch = false;
          }
        }

        // D. Temporal Vectoring
        if (isMatch && monthMatch) {
          if (!(t.date || '').includes(`-${parsedMonthStr}-`)) isMatch = false;
        }
        if (isMatch && yearMatch) {
          if (!(t.date || '').startsWith(yearMatch[1])) isMatch = false;
        }
        if (isMatch && relativeTimeMatch) {
          const tDateStr = t.date || '';
          if (parsedRelativeRel === 'this month') {
             const tYear = parseInt(tDateStr.substring(0, 4), 10);
             const tMonth = parseInt(tDateStr.substring(5, 7), 10) - 1;
             if (tMonth !== parsedNowMonth || tYear !== parsedNowYear) isMatch = false;
          } else if (parsedRelativeRel === 'last month') {
             const lm = parsedNowMonth === 0 ? 11 : parsedNowMonth - 1;
             const lmy = parsedNowMonth === 0 ? parsedNowYear - 1 : parsedNowYear;
             const tYear = parseInt(tDateStr.substring(0, 4), 10);
             const tMonth = parseInt(tDateStr.substring(5, 7), 10) - 1;
             if (tMonth !== lm || tYear !== lmy) isMatch = false;
          } else if (parsedRelativeRel === 'this year') {
             const tYear = parseInt(tDateStr.substring(0, 4), 10);
             if (tYear !== parsedNowYear) isMatch = false;
          } else if (parsedRelativeRel === 'last year') {
             const tYear = parseInt(tDateStr.substring(0, 4), 10);
             if (tYear !== parsedNowYear - 1) isMatch = false;
          } else if (parsedRelativeRel === 'last 30 days') {
             const tTime = parseLocalDate(tDateStr).getTime();
             const diffDays = Math.floor((parsedNowTime - tTime) / (1000 * 60 * 60 * 24));
             if (diffDays < 0 || diffDays > 30) isMatch = false;
          } else if (parsedRelativeRel === 'last 7 days') {
             const tTime = parseLocalDate(tDateStr).getTime();
             const diffDays = Math.floor((parsedNowTime - tTime) / (1000 * 60 * 60 * 24));
             if (diffDays < 0 || diffDays > 7) isMatch = false;
          } else if (parsedRelativeRel === 'yesterday') {
             const yesterday = new Date(parsedNow);
             yesterday.setDate(yesterday.getDate() - 1);
             if (tDateStr !== format(yesterday, 'yyyy-MM-dd')) isMatch = false;
          } else if (parsedRelativeRel === 'this week') {
             const tDateObj = parseLocalDate(tDateStr);
             const dayOfWeek = parsedNow.getDay() || 7;
             const startOfWeek = new Date(parsedNow);
             startOfWeek.setDate(parsedNow.getDate() - dayOfWeek + 1);
             startOfWeek.setHours(0,0,0,0);
             if (tDateObj < startOfWeek || tDateObj > parsedNow) isMatch = false;
          } else if (parsedRelativeRel === 'last week') {
             const tDateObj = parseLocalDate(tDateStr);
             const dayOfWeek = parsedNow.getDay() || 7;
             const startOfThisWeek = new Date(parsedNow);
             startOfThisWeek.setDate(parsedNow.getDate() - dayOfWeek + 1);
             startOfThisWeek.setHours(0,0,0,0);
             const startOfLastWeek = new Date(startOfThisWeek);
             startOfLastWeek.setDate(startOfLastWeek.getDate() - 7);
             if (tDateObj < startOfLastWeek || tDateObj >= startOfThisWeek) isMatch = false;
          } else if (parsedRelativeRel === 'ytd') {
             const tYear = parseInt(tDateStr.substring(0, 4), 10);
             const tDateObj = parseLocalDate(tDateStr);
             if (tYear !== parsedNowYear || tDateObj > parsedNow) isMatch = false;
          } else if (parsedRelativeRel === 'today') {
             if (tDateStr !== parsedTodayStr) isMatch = false;
          }
        }
        if (isMatch && quarterMatch) {
          const q = quarterMatch[1].toLowerCase();
          const tDateStr = t.date || '';
          const tMonth = parseInt(tDateStr.substring(5, 7), 10) - 1;
          if (q === 'q1' && tMonth > 2) isMatch = false;
          else if (q === 'q2' && (tMonth < 3 || tMonth > 5)) isMatch = false;
          else if (q === 'q3' && (tMonth < 6 || tMonth > 8)) isMatch = false;
          else if (q === 'q4' && tMonth < 9) isMatch = false;
        }
        if (isMatch && dateRangeMatch) {
          const start = dateRangeMatch[1];
          const end = dateRangeMatch[2];
          if (t.date < start || t.date > end) isMatch = false;
        }
        if (isMatch && sinceDateMatch) {
          const start = sinceDateMatch[2];
          if (t.date < start) isMatch = false;
        }
        if (isMatch && beforeDateMatch) {
          const end = beforeDateMatch[2];
          if (t.date > end) isMatch = false;
        }

        // E. String Directives
        if (isMatch && startsWithMatch) {
            if (!(t.description || '').toLowerCase().startsWith(queryStartsWith)) isMatch = false;
        }
        if (isMatch && endsWithMatch) {
            if (!(t.description || '').toLowerCase().endsWith(queryEndsWith)) isMatch = false;
        }
        if (isMatch && containsMatch) {
            if (!(t.description || '').toLowerCase().includes(queryContains)) isMatch = false;
        }
        if (isMatch && errorMatch) {
           const auditErrors = LedgerEngine.auditTransaction(t, accountMap);
           if (auditErrors.length === 0) isMatch = false;
        }

        // F. Negative Terms (-term or NOT term)
        if (isMatch && negativeTerms.length > 0) {
          for (const negKw of negativeTerms) {
            if (checkKeywordMatch(t, negKw)) {
              isMatch = false;
              break;
            }
          }
        }

        // G. Free-Text Keywords (All must match)
        if (isMatch && freeTextKeywords.length > 0) {
          for (const kw of freeTextKeywords) {
            if (!checkKeywordMatch(t, kw)) {
              isMatch = false;
              break;
            }
          }
        }

        return isMatch;
      }

      return true;
    });
  }
}

import { ChartAccount } from '../types';

export type AccountRole = 'cash' | 'ar' | 'ap' | 'inventory' | 'revenue' | 'expense' | 'cogs' | 'equity' | 'liability' | 'asset' | 'unknown';

export function resolveAccountRole(account: ChartAccount | undefined | null): AccountRole {
  if (!account) return 'unknown';

  const type = (account.type || '').toLowerCase();
  const category = (account.category || '').toLowerCase();
  const name = (account.name || '').toLowerCase();
  const subtype = (account.subtype || '').toLowerCase();

  // Handle COGS first (could be type: cost_of_goods or type: expense with category: cogs / direct costs)
  if (type === 'cost_of_goods' || category === 'cogs' || category === 'direct costs' || name.includes('cost of goods') || name.includes('cogs')) {
    return 'cogs';
  }

  if (type === 'asset') {
    if (
      category === 'cash' ||
      category.includes('cash') ||
      category.includes('bank') ||
      subtype === 'cash' ||
      subtype === 'bank' ||
      subtype === 'checking' ||
      subtype === 'savings' ||
      name.includes('checking') ||
      name.includes('bank') ||
      name.includes('petty cash') ||
      name.includes('operating cash') ||
      name.includes('cash') ||
      (account as any).role === 'cash'
    ) {
      return 'cash';
    }
    if (category === 'receivables' || category === 'accounts receivable' || category === 'receivable' || subtype.includes('receivable') || name.includes('receivable')) {
      return 'ar';
    }
    if (category === 'inventory' || subtype === 'inventory' || name.includes('inventory')) {
      return 'inventory';
    }
    return 'asset';
  }

  if (type === 'liability') {
    if (category === 'payables' || category === 'accounts payable' || category === 'payable' || subtype.includes('payable') || name.includes('payable')) {
      return 'ap';
    }
    return 'liability';
  }

  if (type === 'revenue' || type === 'income' || category === 'sales' || category === 'revenue') return 'revenue';
  if (type === 'expense') return 'expense';
  if (type === 'equity' || category === 'equity') return 'equity';

  return 'unknown';
}

