export const BUDGET_VS_ACTUAL_ALGO: AlgorithmDefinition = {
  id: 'budget-vs-actual',
  name: 'Budget vs Actual Variance',
  domain: 'planning',
  tags: ['Reporting', 'Planning', 'Variance'],
  description: 'Compares budgeted amounts against actual posted ledger activity, computing variance and percentage completion.',
  requires: ['transactions', 'budgets', 'accounts'],
  inputs: [
    {
      kind: 'select',
      key: 'period',
      label: 'Budget Period',
      options: [
        { value: '2027', label: '2027 Annual' },
        { value: '2026', label: '2026 Annual' },
        { value: '2025', label: '2025 Annual' },
        { value: '2026-03', label: 'March 2026' }
      ],
      defaultValue: '2026'
    }
  ],
  compute: (ctx, inputs): AlgoResult => {
    const { transactions, accounts, accounting } = ctx;
    const budgets = ctx.entities?.budgets || [];
    const targetPeriod = inputs['period'] || '2026';

    // Filter budgets for the period
    const activeBudgets = budgets.filter((b: any) => b.period === targetPeriod && b.targetType === 'account');

    if (activeBudgets.length === 0) {
      return {
        metrics: [],
        charts: [],
        insights: [`No account-level budgets found for period "${targetPeriod}".`],
        rows: []
      };
    }

    const rows: any[] = [];
    const sourceTransactionIds = new Set<string>();
    let totalBudget = 0;
    let totalActual = 0;

    activeBudgets.forEach((budget: any) => {
      const accountId = budget.targetId;
      const account = accounts.find(a => a.id === accountId);

      // Calculate actuals
      let actualCents = 0;

      transactions.forEach(tx => {
        if (!isPostable(tx)) return;

        // Very rough period check: if budget is YYYY, match year. If YYYY-MM, match month.
        if (!tx.date.startsWith(targetPeriod)) return;

        tx.lines.forEach(e => {
          if (e.accountId === accountId) {
            const isDebitNormal = account ? (accounting.isAsset(account.id) || accounting.isExpense(account.id) || accounting.isCOGS(account.id)) : true;
            const debit = e.amountCents > 0 ? e.amountCents : 0;
            const credit = e.amountCents < 0 ? Math.abs(e.amountCents) : 0;

            actualCents += isDebitNormal ? (debit - credit) : (credit - debit);
            sourceTransactionIds.add(tx.id);
          }
        });
      });

      const budgetAmount = budget.amountCents;
      const variance = budgetAmount - actualCents;
      const variancePct = budgetAmount !== 0 ? (variance / budgetAmount) * 100 : 0;

      totalBudget += budgetAmount;
      totalActual += actualCents;

      rows.push({
        id: budget.id,
        account: account ? `${account.code} - ${account.name}` : accountId,
        budget: formatCurrency(budgetAmount),
        actual: formatCurrency(actualCents),
        variance: formatCurrency(variance),
        variancePct: `${variancePct > 0 ? '+' : ''}${variancePct.toFixed(1)}%`
      });
    });

    const totalVariance = totalBudget - totalActual;
    const totalVariancePct = totalBudget !== 0 ? (totalVariance / totalBudget) * 100 : 0;

    return {
      metrics: [
        { label: 'Total Budget', value: formatCurrency(totalBudget), color: 'text-indigo-400' },
        { label: 'Total Actuals', value: formatCurrency(totalActual), color: 'text-emerald-400' },
        { label: 'Net Variance', value: formatCurrency(totalVariance), color: totalVariance >= 0 ? 'text-emerald-500' : 'text-rose-500' }
      ],
      charts: [
        {
          config: {
            xKey: 'account',
            yKeys: [
              { key: 'budget', name: 'Budget', color: '#6366f1', type: 'bar' },
              { key: 'actual', name: 'Actual', color: '#10b981', type: 'bar' }
            ]
          },
          data: rows.map(r => ({
            account: r.account,
            budget: parseFloat(r.budget.replace(/[^0-9.-]+/g,"")),
            actual: parseFloat(r.actual.replace(/[^0-9.-]+/g,""))
          }))
        }
      ],
      insights: [
        `Overall budget completion is ${totalBudget > 0 ? ((totalActual / totalBudget) * 100).toFixed(1) : 0}%.`,
        totalVariance >= 0 ? 'Currently operating within budget.' : 'Warning: Total actuals exceed budget.'
      ],
      rows,
      sourceTransactionIds: Array.from(sourceTransactionIds)
    };
  }
};

import { AlgorithmDefinition, AlgoResult } from './types';
import { calculateNPV, calculateIRR } from './math';
import { isPostable, lineAmount } from '../../lib/txFilters';

export const CAPITAL_BUDGETING_ALGO: AlgorithmDefinition = {
  id: 'valuation_1',
  name: 'WACC & Capital Budgeting Analysis',
  domain: 'finance',
  tags: ['Valuation', 'NPV', 'IRR', 'WACC', 'Payback'],
  description: 'Computes Weighted Average Cost of Capital (WACC) and evaluates project viability using NPV, IRR, Profitability Index, and Discounted Payback Period.',
  inputs: [
    { key: 'initialInvestment', label: 'Initial Outlay ($)', min: 0, max: 10000000, step: 5000, defaultValue: 0 },
    { key: 'costOfEquityPct', label: 'Cost of Equity (%)', min: 1, max: 30, step: 0.5, defaultValue: 10 },
    { key: 'costOfDebtPct', label: 'Cost of Debt (%)', min: 1, max: 20, step: 0.5, defaultValue: 5 },
    { key: 'taxRatePct', label: 'Corporate Tax Rate (%)', min: 0, max: 50, step: 1, defaultValue: 21 },
    { key: 'equityDebtRatio', label: 'Equity Weight (%)', min: 0, max: 100, step: 5, defaultValue: 70 }
  ],
  compute: (ctx, inputs): AlgoResult => {
    const { transactions, accounts, accounting } = ctx;
    const ke = (inputs['costOfEquityPct'] ?? 10) / 100;
    const kd = (inputs['costOfDebtPct'] ?? 5) / 100;
    const tax = (inputs['taxRatePct'] ?? 21) / 100;
    const equityPct = (inputs['equityDebtRatio'] ?? 70) / 100;
    const debtPct = 1 - equityPct;

    // WACC = (E/V * Ke) + (D/V * Kd * (1 - Tax))
    const wacc = (equityPct * ke) + (debtPct * kd * (1 - tax));
    const waccPct = (wacc * 100).toFixed(2);

    // Group transaction cash flows by year
    const yearlyFlows: Record<string, number> = {};

    transactions.forEach(tx => {
      if (!isPostable(tx)) return;
      const year = tx.date.substring(0, 4);
      if (!yearlyFlows[year]) yearlyFlows[year] = 0;

      // Calculate net cash flow impact based on cash accounts
      let netImpact = 0;
      let hasCashAccount = false;

      tx.lines.forEach(l => {
         const amt = lineAmount(l, tx);
         if (accounting.isCash(l.accountId)) {
             hasCashAccount = true;
             netImpact += amt; // Inflows positive, outflows negative
         }
      });

      // If no explicit cash account was touched, compute Operating Net Income impact
      if (!hasCashAccount) {
        tx.lines.forEach(l => {
          const amt = lineAmount(l, tx);
          if (accounting.isRevenue(l.accountId)) {
            netImpact += Math.abs(amt);
          } else if (accounting.isExpense(l.accountId) || accounting.isCOGS(l.accountId)) {
            netImpact -= Math.abs(amt);
          }
        });
      }

      yearlyFlows[year] += (netImpact / 100);
    });

    const sortedYears = Object.keys(yearlyFlows).sort();
    let cashFlowArray = sortedYears.map(y => yearlyFlows[y]);

    // Determine Initial Investment (Capex): User explicit input takes strict precedence
    let initialInvestment = inputs['initialInvestment'] ?? 0;
    if (initialInvestment === 0 && cashFlowArray.length > 0 && cashFlowArray[0] < 0) {
      initialInvestment = Math.abs(cashFlowArray[0]);
      cashFlowArray = cashFlowArray.slice(1);
    }

    if (cashFlowArray.length === 0 && initialInvestment === 0) {
      return {
        metrics: [
          { label: 'WACC (Hurdle Rate)', value: `${waccPct}%`, color: 'blue' },
          { label: 'Internal Rate of Return (IRR)', value: 'N/A', color: 'gray' },
          { label: 'Net Present Value', value: '$0', color: 'gray' },
          { label: 'Profitability Index', value: '0.00', color: 'gray' },
          { label: 'Discounted Payback', value: 'N/A', color: 'gray' }
        ],
        charts: [],
        insights: [
          `The enterprise hurdle rate (WACC) is calculated at ${waccPct}%.`,
          'No transaction cash flows or initial project outlay specified in ledger or inputs. Provide an initial outlay or record project transactions to evaluate NPV/IRR.'
        ]
      };
    }

    const npv = calculateNPV(wacc, initialInvestment, cashFlowArray);
    const irr = calculateIRR(initialInvestment, cashFlowArray);

    // Profitability Index = (NPV + Initial Investment) / Initial Investment
    const profitabilityIndex = initialInvestment > 0 ? (npv + initialInvestment) / initialInvestment : 0;

    // Discounted Payback Period
    let discountedPayback = -1;
    let cumulativeDCF = -initialInvestment;

    const dcfChartData: any[] = [];

    for (let i = 0; i < cashFlowArray.length; i++) {
       const dcf = cashFlowArray[i] / Math.pow(1 + wacc, i + 1);
       cumulativeDCF += dcf;

       dcfChartData.push({
         Year: `Yr ${i+1}`,
         'Nominal Cash Flow': cashFlowArray[i],
         'Discounted Cash Flow': dcf,
         'Cumulative DCF': cumulativeDCF
       });

       if (cumulativeDCF >= 0 && discountedPayback === -1) {
         // Interpolate exact year fraction
         const prevCumulative = cumulativeDCF - dcf;
         discountedPayback = i + (dcf === 0 ? 0 : Math.abs(prevCumulative) / dcf);
       }
    }

    const chartData = [
      { Parameter: 'Cost of Equity', 'Rate (%)': parseFloat((ke * 100).toFixed(2)) },
      { Parameter: 'Cost of Debt (After-Tax)', 'Rate (%)': parseFloat((kd * (1 - tax) * 100).toFixed(2)) },
      { Parameter: 'Blended WACC', 'Rate (%)': parseFloat(waccPct) }
    ];

    const irrFormatted = !isNaN(irr) ? `${(irr * 100).toFixed(2)}%` : 'N/A';
    const isIrrViable = !isNaN(irr) && irr >= wacc;

    const insights = [
      `The enterprise hurdle rate (WACC) is calculated at ${waccPct}%, factoring an equity weight of ${inputs['equityDebtRatio']}% and a tax shield on debt of ${inputs['taxRatePct']}%.`,
      `The projected NPV stands at $${npv.toLocaleString(undefined, { maximumFractionDigits: 0, minimumFractionDigits: 0 })} against an initial capital outlay of $${initialInvestment.toLocaleString()}.`,
      !isNaN(irr) 
        ? (isIrrViable ? `The Internal Rate of Return (IRR) is ${irrFormatted}, clearing the ${waccPct}% WACC hurdle rate and indicating a value-accretive investment.` : `The Internal Rate of Return (IRR) is ${irrFormatted}, failing to meet the ${waccPct}% hurdle rate.`)
        : 'Internal Rate of Return (IRR) could not be calculated due to non-standard cash flow pattern.',
      profitabilityIndex >= 1 
        ? `Profitability Index is ${profitabilityIndex.toFixed(2)} (> 1.0), indicating the present value of future cash flows exceeds the initial investment.`
        : `Profitability Index is ${profitabilityIndex.toFixed(2)} (< 1.0), signaling wealth destruction. Project should be rejected.`,
    ];

    if (discountedPayback !== -1) {
       insights.push(`The Discounted Payback Period is ${discountedPayback.toFixed(1)} years.`);
    } else {
       insights.push(`The project does not reach discounted payback within the modeled ${cashFlowArray.length}-year horizon.`);
    }

    return {
      metrics: [
        { label: 'WACC (Hurdle Rate)', value: `${waccPct}%`, color: 'blue' },
        { label: 'Internal Rate of Return (IRR)', value: irrFormatted, color: isIrrViable ? 'green' : !isNaN(irr) ? 'red' : 'gray' },
        { label: 'Net Present Value', value: `$${Math.round(npv).toLocaleString()}`, color: npv >= 0 ? 'green' : 'red' },
        { label: 'Profitability Index', value: profitabilityIndex.toFixed(2), color: profitabilityIndex >= 1 ? 'green' : 'red' },
        { label: 'Discounted Payback', value: discountedPayback !== -1 ? `${discountedPayback.toFixed(1)} Yrs` : 'Never', color: discountedPayback !== -1 ? 'green' : 'red' }
      ],
      charts: [
        {
          config: {
            xKey: 'Year',
            yKeys: [
              { key: 'Nominal Cash Flow', name: 'Nominal CF', color: '#94a3b8', type: 'bar' },
              { key: 'Discounted Cash Flow', name: 'Discounted CF', color: '#6366f1', type: 'bar' },
              { key: 'Cumulative DCF', name: 'Cumulative NPV', color: '#10b981', type: 'line' }
            ]
          },
          data: dcfChartData
        },
        {
          config: {
            xKey: 'Parameter',
            yKeys: [
              { key: 'Rate (%)', name: 'Discount Rate %', color: '#8b5cf6', type: 'bar' }
            ]
          },
          data: chartData
        }
      ],
      insights
    };
  }
};

import { Transaction, ChartAccount } from '../../types';
import { AlgorithmDefinition } from './types';

function normalize(description: string): string {
  return description
    .toUpperCase()
    .replace(/\d+/g, "")
    .replace(/[^A-Z\s]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function tokens(description: string): Set<string> {
  return new Set(normalize(description).split(" ").filter((t) => t.length > 2));
}

export const CATEGORIZATION_CONSISTENCY_ALGO: AlgorithmDefinition = {
  id: 'forensics_categorization_consistency',
  name: 'Categorization Consistency Checker',
  domain: 'forensics',
  tags: ['audit', 'categorization', 'consistency', 'nlp'],
  description: 'Analyzes historical categorization patterns and flags transactions that deviate from highly consistent historical routing.',
  inputs: [
    { key: 'consistencyThreshold', label: 'Minimum Consistency Ratio', min: 0.5, max: 0.95, step: 0.05, defaultValue: 0.8 }
  ],
  compute: (ctx, inputs) => {
    const { transactions, accounts } = ctx;
    const consistencyThreshold = inputs['consistencyThreshold'] ?? 0.8;
    const targetDomain = 'expense'; // default to only analyzing expenses

    // Create a fast lookup for accounts
    const accountMap = new Map<string, ChartAccount>();
    for (const a of accounts) accountMap.set(a.id, a);

    // Extract history
    const history: { description: string; accountId: string; txId: string; amountCents: number; date: string }[] = [];

    for (const tx of transactions) {
      if (!tx.description) continue;
      // Assume the most significant line in the target domain is the categorization target
      // e.g., finding the first expense line for an expense transaction
      const targetLine = tx.lines.find(l => {
        const acc = accountMap.get(l.accountId);
        return acc && (acc.type as string) === targetDomain;
      });

      if (targetLine) {
        history.push({
          description: tx.description,
          accountId: targetLine.accountId,
          txId: tx.id,
          amountCents: tx.totalAmountCents,
          date: tx.date
        });
      }
    }

    // 1. Find Exact Match Consistency Issues
    // Group by normalized description
    const groups = new Map<string, typeof history>();
    for (const h of history) {
      const norm = normalize(h.description);
      if (!norm) continue;
      const group = groups.get(norm) ?? [];
      group.push(h);
      groups.set(norm, group);
    }

    const exactMatchAnomalies = [];
    let wellCategorizedGroups = 0;

    for (const [norm, items] of groups.entries()) {
      if (items.length < 3) continue; // Not enough history to judge consistency

      // Count categorizations for this exact normalized description
      const counts = new Map<string, number>();
      for (const item of items) {
        counts.set(item.accountId, (counts.get(item.accountId) ?? 0) + 1);
      }

      // Find the dominant category
      let dominantAcc = '';
      let maxCount = 0;
      for (const [acc, count] of counts.entries()) {
        if (count > maxCount) {
          maxCount = count;
          dominantAcc = acc;
        }
      }

      const consistency = maxCount / items.length;

      if (consistency >= consistencyThreshold && consistency < 1.0) {
        // Flag the minority items as potential anomalies
        for (const item of items) {
          if (item.accountId !== dominantAcc) {
            exactMatchAnomalies.push({
              ...item,
              dominantAccountId: dominantAcc,
              dominantAccountName: accountMap.get(dominantAcc)?.name ?? 'Unknown',
              currentAccountName: accountMap.get(item.accountId)?.name ?? 'Unknown',
              consistency: consistency,
              totalSeen: items.length
            });
          }
        }
      } else if (consistency === 1.0) {
        wellCategorizedGroups++;
      }
    }

    const metrics = [
      { 
        label: "Categorization Anomalies", 
        value: exactMatchAnomalies.length, 
        color: exactMatchAnomalies.length > 0 ? "text-amber-500" : "text-emerald-500" 
      },
      {
        label: "Analyzed Patterns",
        value: groups.size
      },
      {
        label: "Highly Consistent Patterns",
        value: wellCategorizedGroups,
        color: "text-emerald-500"
      }
    ];

    const insights: string[] = [];
    if (exactMatchAnomalies.length > 0) {
      insights.push(`Found ${exactMatchAnomalies.length} transactions that violate established categorization patterns.`);
    } else {
      insights.push("All recurring transaction patterns appear to be consistently categorized.");
    }

    const charts = [];
    if (exactMatchAnomalies.length > 0) {
      // Create a chart showing anomalies by account
      const anomaliesByAcc = new Map<string, number>();
      for (const a of exactMatchAnomalies) {
        const name = a.currentAccountName;
        anomaliesByAcc.set(name, (anomaliesByAcc.get(name) ?? 0) + 1);
      }

      charts.push({
        data: Array.from(anomaliesByAcc.entries()).map(([name, count]) => ({
          account: name,
          anomalies: count
        })),
        config: {
          xKey: 'account',
          yKeys: [{ key: 'anomalies', color: '#ef4444', name: 'Anomalies', type: 'bar' as const }]
        }
      });
    }

    return {
      metrics,
      charts,
      insights
    };
  }
};

