export const CUSTOMER_CHURN_ALGO: AlgorithmDefinition = {
  id: 'intelligence_6',
  name: 'Customer Churn & Attrition Analysis',
  domain: 'operations',
  tags: ['Sales', 'Customers', 'Churn', 'Retention'],
  description: 'Identifies previously active revenue-generating customers who have stopped purchasing, flagging them as churned or at-risk.',
  inputs: [
    { key: 'churnThresholdDays', label: 'Churn Threshold (Days)', min: 30, max: 365, step: 30, defaultValue: 90 }
  ],
  compute: (ctx, inputs): AlgoResult => {
    const { transactions, accounts, accounting } = ctx;
    const thresholdDays = inputs.churnThresholdDays ?? 90;

    // Identification of customers from transaction data based on income/revenue
    const customerLastSeen: Record<string, number> = {};
    const customerValue: Record<string, number> = {};

    let maxTxDate = 0;

    transactions.forEach(tx => {
       if (!isPostable(tx)) return;
       if (tx.date) {
          const d = parseLocalDate(tx.date).getTime();
          if (d > maxTxDate) maxTxDate = d;
       }

       let isRevenue = false;
       let txAmount = 0;
       tx.lines.forEach(l => {
          if (accounting.isRevenue(l.accountId)) {
             isRevenue = true;
             txAmount += Math.abs(lineAmount(l, tx));
          }
       });

       if (isRevenue && txAmount > 0) {
          const payee = (tx.payee || tx.description || 'Unknown Customer').toUpperCase().trim();
          const txDate = parseLocalDate(tx.date).getTime();

          if (!customerLastSeen[payee] || txDate > customerLastSeen[payee]) {
             customerLastSeen[payee] = txDate;
          }
          if (!customerValue[payee]) customerValue[payee] = 0;
          customerValue[payee] += txAmount;
       }
    });

    const now = maxTxDate > 0 ? maxTxDate : new Date().getTime();
    let totalCustomers = 0;
    let churnedCustomers = 0;
    let atRiskCustomers = 0;
    let activeCustomers = 0;

    let lostRevenue = 0;
    const chartData: any[] = [];

    Object.entries(customerLastSeen).forEach(([customer, lastSeen]) => {
       totalCustomers++;
       const daysSinceLastTx = (now - lastSeen) / (1000 * 60 * 60 * 24);

       if (daysSinceLastTx > thresholdDays) {
          churnedCustomers++;
          lostRevenue += customerValue[customer];
          chartData.push({
             Customer: customer,
             Status: 'Churned',
             DaysSinceActive: Math.round(daysSinceLastTx)
          });
       } else if (daysSinceLastTx > thresholdDays * 0.7) {
          atRiskCustomers++;
          chartData.push({
             Customer: customer,
             Status: 'At Risk',
             DaysSinceActive: Math.round(daysSinceLastTx)
          });
       } else {
          activeCustomers++;
       }
    });

    if (totalCustomers === 0) {
      return {
        metrics: [{ label: 'Status', value: 'No Customer Data' }],
        charts: [],
        insights: ['No recognizable revenue/customer transactions found to analyze churn.']
      };
    }

    const churnRate = totalCustomers === 0 ? 0 : (churnedCustomers / totalCustomers) * 100;

    // Sort chart data
    chartData.sort((a, b) => b.DaysSinceActive - a.DaysSinceActive);
    const topChartData = chartData.slice(0, 15);

    let churnColor = 'green';
    let churnTrend = 'positive';
    if (churnRate > 15) { churnColor = 'red'; churnTrend = 'negative'; }
    else if (churnRate > 5) { churnColor = 'orange'; churnTrend = 'neutral'; }

    return {
      metrics: [
        { label: 'Overall Churn Rate', value: `${churnRate.toFixed(1)}%`, color: churnColor, trend: churnTrend },
        { label: 'Total Customers', value: totalCustomers.toString() },
        { label: 'Active', value: activeCustomers.toString(), color: 'green' },
        { label: 'At Risk', value: atRiskCustomers.toString(), color: 'orange' },
        { label: 'Churned', value: churnedCustomers.toString(), color: 'red' }
      ],
      charts: [
        {
          config: {
            xKey: 'Customer',
            yKeys: [{ key: 'DaysSinceActive', name: 'Days Inactive', color: '#f43f5e', type: 'bar' }]
          },
          data: topChartData
        }
      ],
      insights: [
        `Of ${totalCustomers} historically active customers, ${churnedCustomers} have not purchased in over ${inputs.churnThresholdDays} days (Churn Rate: ${churnRate.toFixed(1)}%).`,
        `There are ${atRiskCustomers} customers currently "At Risk" (approaching the threshold). Targeted retention campaigns recommended.`,
        lostRevenue > 0 ? `The historical lifetime value associated with currently churned customers is $${(lostRevenue/100).toLocaleString()}.` : ''
      ]
    };
  }
};

import { AlgorithmDefinition, AlgoResult } from './types';
import { isPostable, lineAmount } from '../../lib/txFilters';

export const DUPONT_ANALYSIS_ALGO: AlgorithmDefinition = {
  id: 'valuation_3',
  name: 'DuPont ROE Decomposition',
  domain: 'valuation',
  tags: ['DuPont', 'ROE', 'Profitability', 'Efficiency', 'Leverage'],
  description: 'Deconstructs Return on Equity (ROE) into Profit Margin, Asset Turnover, and Financial Leverage to identify the core drivers of shareholder return.',
  inputs: [],
  compute: (ctx, inputs): AlgoResult => {
    const { transactions, accounts, accounting } = ctx;
    let revenue = 0;
    let netIncome = 0;
    let totalAssets = 0;
    let equity = 0;

    // Use accounts for assets and equity
    accounts.forEach(acc => {
      const bal = acc.balanceCents || 0;

      if (accounting.isAsset(acc.id)) {
        totalAssets += bal;
      } else if (accounting.isEquity(acc.id)) {
        equity -= bal;
      }
    });

    // Approximate revenue and net income from transactions
    transactions.forEach(tx => {
       if (!isPostable(tx)) return;
       tx.lines.forEach(l => {
          const amt = lineAmount(l, tx);
          if (accounting.isRevenue(l.accountId)) {
             const absAmt = Math.abs(amt);
             revenue += absAmt;
             netIncome += absAmt;
          } else if (accounting.isExpense(l.accountId) || accounting.isCOGS(l.accountId)) {
             netIncome -= Math.abs(amt);
          }
       });
    });

    if (equity === 0 || totalAssets === 0) {
      return {
        metrics: [{ label: 'Status', value: 'Insufficient Balance Sheet' }],
        charts: [],
        insights: ['DuPont analysis requires non-zero Total Assets and Equity balances to compute leverage and turnover.']
      };
    }

    // DuPont Factors
    const profitMargin = revenue > 0 ? (netIncome / revenue) : 0;
    const assetTurnover = totalAssets > 0 ? (revenue / totalAssets) : 0;
    const equityMultiplier = equity > 0 ? (totalAssets / equity) : 0;

    // ROE = Profit Margin * Asset Turnover * Equity Multiplier
    const roe = profitMargin * assetTurnover * equityMultiplier;

    const chartData = [
       { Component: 'Profit Margin', Value: parseFloat((profitMargin * 100).toFixed(2)) },
       { Component: 'Asset Turnover', Value: parseFloat((assetTurnover * 100).toFixed(2)) },
       { Component: 'Equity Multiplier', Value: parseFloat((equityMultiplier * 100).toFixed(2)) }
    ];

    let roeColor: string;
    let roeTrend = 'neutral';
    if (roe > 0.15) { roeColor = 'text-green-500'; roeTrend = 'positive'; }
    else if (roe < 0.05) { roeColor = 'text-red-500'; roeTrend = 'negative'; }
    else { roeColor = 'text-blue-500'; }

    return {
      metrics: [
        { label: 'Return on Equity (ROE)', value: `${(roe * 100).toFixed(2)}%`, color: roeColor, trend: roeTrend },
        { label: 'Net Profit Margin', value: `${(profitMargin * 100).toFixed(2)}%` },
        { label: 'Asset Turnover', value: `${assetTurnover.toFixed(2)}x` },
        { label: 'Equity Multiplier (Leverage)', value: `${equityMultiplier.toFixed(2)}x` }
      ],
      charts: [
        {
          config: {
            xKey: 'Component',
            yKeys: [{ key: 'Value', name: 'Driver Magnitude', color: '#10b981', type: 'bar' }]
          },
          data: chartData
        }
      ],
      insights: [
        `Return on Equity (ROE) stands at ${(roe * 100).toFixed(2)}%.`,
        `Decomposition shows a Profit Margin of ${(profitMargin * 100).toFixed(2)}%, Asset Turnover of ${assetTurnover.toFixed(2)}x, and Financial Leverage of ${equityMultiplier.toFixed(2)}x.`,
        equityMultiplier > 2 ? 'Note: High Equity Multiplier (>2.0x) indicates significant reliance on debt financing to drive ROE.' : 'Leverage is conservative, suggesting ROE is driven primarily by operational efficiency rather than debt.'
      ]
    };
  }
};

