export const EXPENSE_POLICY_ALGO: AlgorithmDefinition = {
  id: 'forensics_policy',
  name: 'Policy Violator (Weekend & Round Numbers)',
  domain: 'forensics',
  tags: ['Audit', 'Compliance', 'Risk', 'T&E'],
  description: 'Flags suspicious expenses that occur on weekends or are perfectly round numbers, which often indicate unapproved out-of-policy spending or artificial entries.',
  inputs: [
    {
      key: 'minRoundAmount',
      label: 'Min Round Amount ($)',
      min: 10,
      max: 1000,
      step: 10,
      defaultValue: 100
    }
  ],
  compute: (ctx, inputs): AlgoResult => {
    const { transactions, accounts, accounting } = ctx;
    const minRoundAmount = (inputs['minRoundAmount'] ?? 100) * 100; // in cents

    let weekendCount = 0;
    let roundNumberCount = 0;
    let totalRiskAmount = 0;

    const riskByDay: Record<string, number> = {
      'Monday': 0, 'Tuesday': 0, 'Wednesday': 0, 'Thursday': 0, 'Friday': 0, 'Saturday': 0, 'Sunday': 0
    };
    const daysOfWeek = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

    transactions.forEach(tx => {
      // Look at expense/liability accounts or general spending
      if (!isOutflow(tx, accounts as any)) return;

      const absAmount = Math.abs(tx.totalAmountCents);
      if (absAmount < 500) return; // Skip tiny transactions

      let isRisk = false;
      const dateObj = parseLocalDate(tx.date);
      const dayName = daysOfWeek[dateObj.getUTCDay()];

      // Check Weekend
      if (dayName === 'Saturday' || dayName === 'Sunday') {
        weekendCount++;
        isRisk = true;
      }

      // Check Round Number (e.g., $100.00, $500.00)
      if (absAmount >= minRoundAmount && absAmount % 10000 === 0) { // Divisible by $100.00
        roundNumberCount++;
        isRisk = true;
      }

      if (isRisk) {
        totalRiskAmount += absAmount;
        riskByDay[dayName] += (absAmount / 100);
      }
    });

    const chartData = Object.keys(riskByDay).map(day => ({
      Day: day.substring(0, 3), // Mon, Tue
      'Risk Volume': parseFloat(riskByDay[day].toFixed(2))
    }));

    const insights = [];
    if (weekendCount === 0 && roundNumberCount === 0) {
      insights.push('No significant policy violations detected. Expenses appear natural and within standard operating days.');
    } else {
      insights.push(`Detected ${weekendCount} transactions occurring on weekends.`);
      insights.push(`Detected ${roundNumberCount} round-number transactions (multiples of $100) over the threshold.`);
      insights.push(`Total potential out-of-policy spending at risk: $${(totalRiskAmount / 100).toLocaleString()}`);
    }

    return {
      metrics: [
        { label: 'Weekend Tx', value: weekendCount, color: weekendCount > 0 ? 'text-amber-500' : 'text-slate-500' },
        { label: 'Round Number Tx', value: roundNumberCount, color: roundNumberCount > 0 ? 'text-amber-500' : 'text-slate-500' },
        { label: 'At-Risk Volume', value: `$${(totalRiskAmount / 100).toLocaleString()}`, color: totalRiskAmount > 0 ? 'text-rose-500' : 'text-slate-500' }
      ],
      charts: [
        {
          config: {
            xKey: 'Day',
            yKeys: [
              { key: 'Risk Volume', name: 'Anomalous Volume ($)', color: '#f59e0b', type: 'bar' }
            ]
          },
          data: chartData
        }
      ],
      insights
    };
  }
};

import { AlgorithmDefinition, AlgoResult } from './types';
import { isPostable, lineAmount } from '../txFilters';

export const EXPENSE_VELOCITY_ALGO: AlgorithmDefinition = {
  id: 'ops_velocity',
  name: 'Expense Velocity (Spike Detector)',
  domain: 'operations',
  tags: ['Cash', 'Spikes', 'Operations', 'Monitoring'],
  description: 'Calculates the trailing moving average of true operational expenses to detect sudden spikes in outflow velocity before the end-of-month reporting cycle.',
  inputs: [
    {
      key: 'spikeThresholdPct',
      label: 'Spike Alert Threshold (%)',
      min: 10,
      max: 300,
      step: 10,
      defaultValue: 50
    },
    {
      key: 'movingAverageDays',
      label: 'Moving Avg (Days)',
      min: 3,
      max: 30,
      step: 1,
      defaultValue: 7
    }
  ],
  compute: (ctx, inputs): AlgoResult => {
    const { transactions, accounts, accounting } = ctx;
    const threshold = (inputs['spikeThresholdPct'] ?? 50) / 100;
    const windowDays = Math.max(1, inputs['movingAverageDays'] ?? 7);

    const accountMap = new Map(accounts.map(a => [a.id, a]));
    const dailyExpenses: Record<string, number> = {};
    const dailyTxIds: Record<string, string[]> = {};
    const sourceTransactionIds = new Set<string>();

    transactions.forEach(tx => {
      if (!isPostable(tx)) return;
      if (!tx.date) return;

      const dateKey = tx.date.substring(0, 10);
      let txExpenseCents = 0;

      if (Array.isArray(tx.lines) && tx.lines.length > 0) {
        tx.lines.forEach(l => {
          const acc = accountMap.get(l.accountId);
          const isExp = acc ? (accounting.isExpense(acc.id) || accounting.isCOGS(acc.id)) : false;
          if (isExp) {
            const amt = lineAmount(l, tx);
            if (amt > 0) txExpenseCents += amt; // Debits to expense accounts are positive
          }
        });
      }

      // If no dedicated expense accounts identified, fallback to explicit expense transaction types
      if (txExpenseCents === 0 && (tx.type === 'expense' || (tx.type as any) === 'cost_of_goods')) {
        txExpenseCents = Math.abs(tx.totalAmountCents || 0);
      }

      if (txExpenseCents > 0) {
        if (!dailyExpenses[dateKey]) {
          dailyExpenses[dateKey] = 0;
          dailyTxIds[dateKey] = [];
        }
        dailyExpenses[dateKey] += txExpenseCents;
        dailyTxIds[dateKey].push(tx.id);
        sourceTransactionIds.add(tx.id);
      }
    });

    // Sort dates
    const rawDates = Object.keys(dailyExpenses).sort();
    if (rawDates.length < 2) {
       return {
          metrics: [
            { label: 'Recent Spikes', value: 0, color: 'text-slate-500' },
            { label: 'Status', value: 'Insufficient Data' }
          ],
          charts: [],
          insights: ['Not enough expense transaction history to establish a baseline moving average.']
       };
    }

    // Build contiguous calendar days from min date to max date
    const startDate = new Date(rawDates[0]);
    const endDate = new Date(rawDates[rawDates.length - 1]);
    const contiguousDates: string[] = [];

    const curr = new Date(startDate);
    while (curr <= endDate) {
      contiguousDates.push(curr.toISOString().slice(0, 10));
      curr.setDate(curr.getDate() + 1);
    }

    if (contiguousDates.length < windowDays) {
      return {
        metrics: [],
        charts: [],
        insights: ['Date range is shorter than the configured moving average window.']
      };
    }

    // Calculate moving average and spikes
    const chartData = [];
    let recentSpikes = 0;
    let maxVelocity = 0;
    let currentVelocity = 0;
    const spikedTxIds: string[] = [];

    // Start from the window end
    for (let i = windowDays; i < contiguousDates.length; i++) {
      const targetDate = contiguousDates[i];
      const targetVolume = dailyExpenses[targetDate] || 0;

      // Calculate average of previous `windowDays` (strictly previous days)
      let sum = 0;
      for (let j = 1; j <= windowDays; j++) {
        sum += dailyExpenses[contiguousDates[i - j]] || 0;
      }
      const movingAvg = sum / windowDays;

      const velocityRatio = movingAvg > 0 ? (targetVolume - movingAvg) / movingAvg : (targetVolume > 0 ? 1 : 0);

      if (velocityRatio > threshold && targetVolume > 0) {
        recentSpikes++;
        if (dailyTxIds[targetDate]) {
          spikedTxIds.push(...dailyTxIds[targetDate]);
        }
      }

      if (targetVolume > maxVelocity) {
        maxVelocity = targetVolume;
      }

      currentVelocity = targetVolume;

      chartData.push({
        Date: targetDate.substring(5), // MM-DD
        'Daily Volume': parseFloat((targetVolume / 100).toFixed(2)),
        'Avg': parseFloat((movingAvg / 100).toFixed(2))
      });
    }

    const insights = [];
    insights.push(`Analyzed daily operational expense velocity across ${contiguousDates.length} calendar days.`);
    if (recentSpikes > 0) {
      insights.push(`Detected ${recentSpikes} day(s) where expense outflow spiked more than ${inputs['spikeThresholdPct'] ?? 50}% above the trailing ${windowDays}-day moving average.`);
    } else {
      insights.push(`Expense velocity is within normal bounds. No anomalous spikes detected above the ${inputs['spikeThresholdPct'] ?? 50}% threshold.`);
    }

    return {
      metrics: [
        { label: 'Recent Spikes', value: recentSpikes, color: recentSpikes > 0 ? 'text-amber-500' : 'text-slate-500' },
        { label: 'Max Daily Velocity', value: `$${(maxVelocity / 100).toLocaleString()}` },
        { label: 'Latest Daily Velocity', value: `$${(currentVelocity / 100).toLocaleString()}` }
      ],
      charts: [
        {
          config: {
            xKey: 'Date',
            yKeys: [
              { key: 'Daily Volume', name: 'Actual Daily Expenses ($)', color: '#94a3b8', type: 'bar' },
              { key: 'Avg', name: `${windowDays}-Day Trailing Avg ($)`, color: '#6366f1', type: 'line' }
            ]
          },
          data: chartData
        }
      ],
      insights,
      sourceTransactionIds: spikedTxIds.length > 0 ? spikedTxIds : Array.from(sourceTransactionIds)
    };
  }
};

import { Transaction } from '../../types';
import { AlgorithmDefinition } from './types';

// A Fenwick Tree (Binary Indexed Tree) for O(log n) prefix sums
// Allows instant "Balance as of Date" queries even with out-of-order amendments
export class FenwickTree {
    private tree: number[];
    private size: number;

    constructor(size: number) {
        this.size = size;
        this.tree = new Array(size + 1).fill(0);
    }

    // Add value to index i (1-based index)
    add(i: number, delta: number) {
        const intDelta = Math.round(delta);
        while (i <= this.size) {
            this.tree[i] += intDelta;
            i += i & (-i);
        }
    }

    // Get sum from 1 to i
    query(i: number): number {
        let sum = 0;
        while (i > 0) {
            sum += this.tree[i];
            i -= i & (-i);
        }
        return sum;
    }
}

export function buildTimeTravelLedger(transactions: readonly Transaction[], targetAccountId?: string) {
    // 0. Chronologically sort transactions to prevent out-of-order corruption
    const sortedTxs = [...transactions].sort((a, b) => {
        if (a.date > b.date) return 1;
        if (a.date < b.date) return -1;
        const aTime = a.createdAt || '';
        const bTime = b.createdAt || '';
        if (aTime > bTime) return 1;
        if (aTime < bTime) return -1;
        return 0;
    });

    // 1. Map dates to 1-based indices (compress the timeline)
    const dates = new Set<string>();
    sortedTxs.forEach(t => dates.add(t.date));
    const sortedDates = Array.from(dates).sort();

    const dateToIndex = new Map<string, number>();
    sortedDates.forEach((d, i) => dateToIndex.set(d, i + 1));

    const tree = new FenwickTree(sortedDates.length);

    // 2. Populate tree
    sortedTxs.forEach(t => {
        const idx = dateToIndex.get(t.date)!;
        let delta = 0;

        if (targetAccountId) {
            // Filter to specific account
            t.lines?.forEach(l => {
                if (l.accountId === targetAccountId || l.accountName === targetAccountId) {
                    delta += l.amountCents;
                }
            });
        } else {
            // Net cashflow for the day
            delta += t.totalAmountCents;
        }

        if (delta !== 0) {
            tree.add(idx, delta);
        }
    });

    return { tree, sortedDates, dateToIndex };
}

export const FENWICK_TIME_TRAVEL_ALGO: AlgorithmDefinition = {
  id: 'fenwick_time_travel',
  domain: 'system',
  name: 'O(log n) Time Travel Ledger (Fenwick Tree)',
  description: 'Uses a Binary Indexed Tree to compute "Balance As Of Date" in logarithmic time, enabling instant timeline scrubbing and Git-style branches.',
  inputs: [
    { key: 'targetDayIndex', label: 'Timeline Scrub (Days from Start)', min: 1, max: 365, step: 1, defaultValue: 90 }
  ],
  compute: (ctx, inputs) => {
    const { transactions } = ctx;
    const start = performance.now();

    // Build tree
    const { tree, sortedDates, dateToIndex } = buildTimeTravelLedger(transactions);

    // Query
    const maxIdx = sortedDates.length;
    const targetDayIndex = typeof inputs?.targetDayIndex === 'number' ? inputs.targetDayIndex : Math.max(1, Math.floor(maxIdx / 2));
    const queryIdx = maxIdx > 0 ? Math.min(Math.max(1, targetDayIndex), maxIdx) : 0;

    const balanceAsOf = maxIdx > 0 ? tree.query(queryIdx) : 0;

    const ms = performance.now() - start;

    // Generate chart data: sample every 10th day to show prefix sum curve
    const chartData = [];
    for (let i = 1; i <= maxIdx; i += Math.ceil(maxIdx / 20) || 1) {
        chartData.push({
            day: i,
            date: sortedDates[i-1],
            balance: tree.query(i) / 100
        });
    }

    return {
      metrics: [
        { label: 'Execution Time', value: `${ms.toFixed(2)} ms` },
        { label: 'Timeline Span', value: `${sortedDates.length} days` },
        { label: `Balance on Day ${queryIdx}`, value: `$${(balanceAsOf/100).toFixed(2)}`, color: 'text-indigo-400' }
      ],
      charts: [
         {
             data: chartData,
             config: {
                 xKey: 'date',
                 yKeys: [
                     { key: 'balance', color: '#8b5cf6', name: 'Cumulative Balance', type: 'line' }
                 ]
             }
         }
      ],
      insights: [
        `Constructed Binary Indexed Tree over ${sortedDates.length} distinct days.`,
        'Queries take O(log n) time. A query over 10,000 days touches at most 14 nodes.',
        'Updates (like an out-of-order amendment) also take O(log n) time, avoiding full recalculations.',
        'This provides the mathematical engine for the "Git-for-Books" Time Machine.'
      ]
    };
  }
};

import { AlgorithmDefinition, AlgoResult } from './types';
import { Transaction } from '../../types';
import { parseLocalDate, formatCurrency } from '../../lib/utils';
import { isPostable, lineAmount } from '../../lib/txFilters';
import { format, isWithinInterval } from 'date-fns';

export const GL_DETAIL_ALGO: AlgorithmDefinition = {
  id: 'gl-detail',
  name: 'General Ledger Detail',
  domain: 'operations',
  tags: ['Audit', 'Reconciliation', 'Reporting', 'Month-End'],
  description: 'Line-by-line detail of all transactions hitting a selected account, with debits, credits, and a running balance.',
  requires: ['transactions', 'accounts'],
  inputs: [
    {
      kind: 'dateRange',
      key: 'period',
      label: 'Reporting Period',
      defaultValue: { start: '', end: '' }
    },
    {
      kind: 'account',
      key: 'accountId',
      label: 'Filter by Account (Leave blank for all)',
      defaultValue: ''
    }
  ],
  compute: (ctx, inputs): AlgoResult => {
    const { transactions, accounts, accounting } = ctx;
    const period = inputs['period'];
    const accountId = inputs['accountId'];

    let startDate: Date | null = null;
    let endDate: Date | null = null;

    if (period && period.start && period.end) {
      startDate = parseLocalDate(period.start);
      endDate = parseLocalDate(period.end);
      endDate.setHours(23, 59, 59, 999);
    }

    // 1. Filter by date and account
    let relevantTxs = transactions.filter(t => isPostable(t));

    if (startDate && endDate) {
      relevantTxs = relevantTxs.filter(t => {
        const txDate = parseLocalDate(t.date);
        return isWithinInterval(txDate, { start: startDate as Date, end: endDate as Date });
      });
    }

    if (accountId) {
      relevantTxs = relevantTxs.filter(t => t.lines.some(e => e.accountId === accountId));
    }

    // 2. Sort by date ascending
    relevantTxs.sort((a, b) => parseLocalDate(a.date).getTime() - parseLocalDate(b.date).getTime());

    // 3. Flatten into rows (one row per matching entry)
    let runningBalance = 0;

    // If filtered to a specific account and period has a start date, calculate starting balance
    if (accountId && startDate) {
      transactions.forEach(t => {
        if (!isPostable(t)) return;
        const txDate = parseLocalDate(t.date);
        if (txDate < (startDate as Date)) {
          t.lines.forEach(e => {
            if (e.accountId === accountId) {
              const account = accounts.find(a => a.id === e.accountId);
              const isDebitNormal = account ? (accounting.isAsset(account.id) || accounting.isExpense(account.id) || accounting.isCOGS(account.id)) : true;
              const amt = lineAmount(e, t);
              const debit = amt > 0 ? amt : 0;
              const credit = amt < 0 ? Math.abs(amt) : 0;
              const impact = isDebitNormal ? (debit - credit) : (credit - debit);
              runningBalance += impact;
            }
          });
        }
      });
    }

    const rows: any[] = [];
    const sourceTransactionIds = new Set<string>();
    let totalDebits = 0;
    let totalCredits = 0;

    relevantTxs.forEach(t => {
      t.lines.forEach((e, idx) => {
        if (accountId && e.accountId !== accountId) return; // Skip entries not for this account if filtered

        const account = accounts.find(a => a.id === e.accountId);
        const isDebitNormal = account ? (accounting.isAsset(account.id) || accounting.isExpense(account.id) || accounting.isCOGS(account.id)) : true;

        const amt = lineAmount(e, t);
        const debit = amt > 0 ? amt : 0;
        const credit = amt < 0 ? Math.abs(amt) : 0;

        totalDebits += debit;
        totalCredits += credit;

        const impact = isDebitNormal ? (debit - credit) : (credit - debit);
        runningBalance += impact;

        rows.push({
          id: `${t.id}_${(e as any).id || idx}`,
          date: t.date,
          account: account ? `${account.code ? `${account.code} - ` : ''}${account.name}` : e.accountId,
          description: e.description || t.description || 'No description',
          debit: debit > 0 ? formatCurrency(debit) : '',
          credit: credit > 0 ? formatCurrency(credit) : '',
          balance: accountId ? formatCurrency(runningBalance) : '-',
          sourceIds: [t.id]
        });
        sourceTransactionIds.add(t.id);
      });
    });

    return {
      metrics: [
        { label: 'Transactions', value: sourceTransactionIds.size, color: 'text-indigo-400' },
        { label: 'Total Debits', value: formatCurrency(totalDebits), color: 'text-emerald-400' },
        { label: 'Total Credits', value: formatCurrency(totalCredits), color: 'text-emerald-400' },
        { label: 'Net Change', value: formatCurrency(totalDebits - totalCredits), color: 'text-white' }
      ],
      charts: [],
      insights: [
        `Generated ledger detail spanning ${rows.length} entries.`,
        accountId ? `Filtered specifically to account: ${accounts.find(a => a.id === accountId)?.name || accountId}` : 'Showing all accounts.'
      ],
      rows,
      sourceTransactionIds: Array.from(sourceTransactionIds)
    };
  }
};

import { resolveAccountRole } from '../accountUtils';
import { AlgorithmDefinition, AlgoResult } from './types';

export const INTEREST_RATE_SENSITIVITY_ALGO: AlgorithmDefinition = {
  id: 'treasury_2',
  name: 'Interest Rate Sensitivity (Gap Analysis)',
  domain: 'treasury',
  tags: ['Interest', 'Rates', 'Treasury', 'Risk', 'Debt'],
  description: 'Evaluates the impact of a sudden change in interest rates on net interest income based on variable-rate assets and liabilities.',
  inputs: [
    { key: 'rateShockBps', label: 'Rate Shock (Basis Points)', min: -500, max: 500, step: 25, defaultValue: 100 }
  ],
  compute: (ctx, inputs): AlgoResult => {
    const { transactions, accounts } = ctx;
    const rateShock = (inputs.rateShockBps ?? 100) / 10000;

    // For this simple simulation, we look for accounts that might be rate-sensitive
    let rsa = 0; // Rate Sensitive Assets
    let rsl = 0; // Rate Sensitive Liabilities

    accounts.forEach(acc => {
      const type = (acc.type || '').toLowerCase();
      const name = (acc.name || '').toLowerCase();
      const bal = acc.balanceCents || 0;

      // Simplistic identification of variable rate items
      const role = resolveAccountRole(acc);
      if (type === 'asset' && (role === 'cash' || name.includes('market') || name.includes('variable'))) {
         rsa += bal;
      } else if (type === 'liability' && (name.includes('variable') || name.includes('line of credit') || name.includes('revolver'))) {
         rsl += Math.abs(bal);
      }
    });

    if (rsa === 0 && rsl === 0) {
      return {
        metrics: [{ label: 'Status', value: 'No Rate-Sensitive Items Found' }],
        charts: [],
        insights: ['No variable-rate assets (e.g., cash sweeps) or liabilities (e.g., revolvers) were identified on the balance sheet.']
      };
    }

    const gap = rsa - rsl;
    const nmiImpact = gap * rateShock;

    const chartData = [
       { Category: 'Rate Sensitive Assets', Balance: rsa / 100 },
       { Category: 'Rate Sensitive Liab', Balance: -rsl / 100 },
       { Category: 'Net Gap', Balance: gap / 100 }
    ];

    let impactColor = 'gray';
    let impactTrend = 'neutral';
    if (nmiImpact > 0) { impactColor = 'green'; impactTrend = 'positive'; }
    else if (nmiImpact < 0) { impactColor = 'red'; impactTrend = 'negative'; }

    return {
      metrics: [
        { label: 'Net Interest Gap', value: `$${(gap / 100).toLocaleString()}` },
        { label: 'Net Income Impact (Annualized)', value: `$${(nmiImpact / 100).toLocaleString()}`, color: impactColor, trend: impactTrend }
      ],
      charts: [
        {
          config: {
            xKey: 'Category',
            yKeys: [{ key: 'Balance', name: 'Balance ($)', color: '#6366f1', type: 'bar' }]
          },
          data: chartData
        }
      ],
      insights: [
        `The entity has a Net Interest Gap of $${(gap / 100).toLocaleString()}, meaning it is ${gap > 0 ? 'asset-sensitive' : 'liability-sensitive'}.`,
        `A ${inputs.rateShockBps} bps (${rateShock * 100}%) parallel shift in interest rates would impact annualized Net Interest Income by $${(nmiImpact / 100).toLocaleString()}.`,
        nmiImpact < 0 ? 'Consider entering interest rate swaps or caps to hedge against rising rates on variable debt.' : 'Entity is positioned to benefit from this rate movement.'
      ]
    };
  }
};

import { AlgorithmDefinition } from './types';
import { Transaction } from '../../types';

export interface LocalizedAnomalyNode {
  coordinatePath: string;
  type: 'project' | 'vendor' | 'person' | 'property';
  score: number; // 0 to 100
  benfordScore: number;
  zScoreSpike: number;
  roundNumDensity: number;
  budgetDriftPercent: number;
  flaggedReason: string;
  sampleTxIds: string[];
}

export function computeLocalizedForensics(transactions: readonly Transaction[]): LocalizedAnomalyNode[] {
  const nodesMap: Record<string, {
    path: string;
    type: 'project' | 'vendor' | 'person' | 'property';
    amounts: number[];
    roundCount: number;
    payees: Set<string>;
    txIds: string[];
  }> = {};

  transactions.forEach(tx => {
    const amt = Math.abs(tx.totalAmountCents / 100);
    const payee = tx.payee || 'Unspecified Payee';

    // Group by Payee/Vendor
    const vendorKey = `vendor:${payee}`;
    if (!nodesMap[vendorKey]) {
      nodesMap[vendorKey] = { path: `vendor/${payee.toLowerCase().replace(/\s+/g, '-')}`, type: 'vendor', amounts: [], roundCount: 0, payees: new Set([payee]), txIds: [] };
    }
    nodesMap[vendorKey].amounts.push(amt);
    nodesMap[vendorKey].txIds.push(tx.id);
    if (amt > 0 && amt % 10 === 0) nodesMap[vendorKey].roundCount++;

    // Group by Project
    const project = tx.projectId || 'general';
    const projKey = `project:${project}`;
    if (!nodesMap[projKey]) {
      nodesMap[projKey] = { path: `project/${project}`, type: 'project', amounts: [], roundCount: 0, payees: new Set([payee]), txIds: [] };
    }
    nodesMap[projKey].amounts.push(amt);
    nodesMap[projKey].txIds.push(tx.id);
    if (amt > 0 && amt % 10 === 0) nodesMap[projKey].roundCount++;
  });

  const results: LocalizedAnomalyNode[] = [];

  Object.values(nodesMap).forEach(node => {
    if (node.amounts.length < 2) return;

    // 1. Benford's Law Chi-Square check on first digits
    const firstDigits = node.amounts.map(a => parseInt(String(a).replace(/^0+/, '').charAt(0), 10)).filter(d => d >= 1 && d <= 9);
    let benfordChiSquare = 0;
    if (firstDigits.length >= 3) {
      const counts = Array(10).fill(0);
      firstDigits.forEach(d => counts[d]++);
      const expectedProportions = [0, 0.301, 0.176, 0.125, 0.097, 0.079, 0.067, 0.058, 0.051, 0.046];
      for (let d = 1; d <= 9; d++) {
        const obs = counts[d];
        const exp = firstDigits.length * expectedProportions[d];
        if (exp > 0) benfordChiSquare += Math.pow(obs - exp, 2) / exp;
      }
    }

    // 2. Z-Score Velocity
    const mean = node.amounts.reduce((a, b) => a + b, 0) / node.amounts.length;
    const variance = node.amounts.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / node.amounts.length;
    const stdDev = Math.sqrt(variance) || 1;
    const maxAmt = Math.max(...node.amounts);
    const zScoreSpike = stdDev === 0 ? 0 : (maxAmt - mean) / stdDev;

    // 3. Round-number density
    const roundNumDensity = node.roundCount / node.amounts.length;

    // Composite Anomaly Score (0 - 100)
    const score = Math.min(100, Math.round(
      (benfordChiSquare > 15 ? 40 : benfordChiSquare * 2) +
      (zScoreSpike > 2.5 ? 35 : zScoreSpike * 10) +
      (roundNumDensity > 0.5 ? 25 : roundNumDensity * 30)
    ));

    if (score >= 25) {
      const reasons: string[] = [];
      if (benfordChiSquare > 12) reasons.push(`First digits fail Benford (χ²=${benfordChiSquare.toFixed(1)})`);
      if (zScoreSpike > 2.0) reasons.push(`Reimbursements/spend spiked ${zScoreSpike.toFixed(1)}σ above mean`);
      if (roundNumDensity > 0.4) reasons.push(`${Math.round(roundNumDensity * 100)}% round-number invoices`);

      results.push({
        coordinatePath: node.path,
        type: node.type,
        score,
        benfordScore: parseFloat(benfordChiSquare.toFixed(1)),
        zScoreSpike: parseFloat(zScoreSpike.toFixed(1)),
        roundNumDensity: parseFloat(roundNumDensity.toFixed(2)),
        budgetDriftPercent: Math.round(score * 0.8),
        flaggedReason: reasons.join('; ') || 'Statistical variance detected across node transactions',
        sampleTxIds: node.txIds.slice(0, 3)
      });
    }
  });

  return results.sort((a, b) => b.score - a.score);
}

