import { AlgorithmDefinition, AlgoResult } from './types';
import { standardDeviation, mean } from './math';
import { isPostable, isCashAccount, lineAmount } from '../txFilters';

export const MONTE_CARLO_ALGO: AlgorithmDefinition = {
  id: 'planning_4',
  name: 'Monte Carlo Cash Flow Simulation',
  domain: 'planning',
  tags: ['Forecasting', 'Stochastic', 'Probability', 'Risk'],
  description: 'Simulates 10,000 potential financial futures using geometric Brownian motion based on historical transaction variance to predict the probability of cash exhaustion.',
  inputs: [
    {
      key: 'simulationDays',
      label: 'Simulation Horizon (Days)',
      min: 30,
      max: 365,
      step: 15,
      defaultValue: 90
    },
    {
      key: 'iterations',
      label: 'Simulations (x100)',
      min: 10,
      max: 100,
      step: 10,
      defaultValue: 50 // 5000 iterations
    }
  ],
  compute: (ctx, inputs) => {
    const { transactions, accounts } = ctx;
    const horizon = inputs.simulationDays ?? 90;
    const runs = (inputs.iterations ?? 50) * 100;

    // Group historical transactions by day
    const dailyNet: Record<string, number> = {};
    let currentCashCents = 0;

    // Isolate authentic Cash and Cash Equivalent accounts
    accounts.forEach(acc => {
      if (resolveAccountRole(acc) === 'cash' || isCashAccount(acc)) {
        currentCashCents += acc.balanceCents || 0;
      }
    });

    transactions.forEach(t => {
      if (!isPostable(t)) return;
      const dateKey = t.date.split('T')[0];

      // Net cash flow is strictly the movement in Cash accounts
      let netImpact = 0;
      let hasCashMovement = false;
      t.lines.forEach(l => {
        const acc = accounts.find(a => a.id === l.accountId);
        if (acc && (resolveAccountRole(acc) === 'cash' || isCashAccount(acc))) {
          hasCashMovement = true;
          netImpact += lineAmount(l, t); // Debits increase cash (positive), credits decrease cash (negative)
        }
      });

      // Non-cash transactions (e.g. depreciation, equity swaps) have exactly zero cash impact
      if (hasCashMovement) {
        if (dailyNet[dateKey] === undefined) dailyNet[dateKey] = 0;
        dailyNet[dateKey] += netImpact;
      }
    });

    const historicalDailyFlows = Object.values(dailyNet);

    if (historicalDailyFlows.length < 5) {
      return {
        metrics: [
          { label: 'Status', value: 'Insufficient Data', color: 'red' }
        ],
        charts: [],
        insights: [
          'The Monte Carlo engine requires at least 5 days of transaction history to establish drift and volatility.'
        ]
      };
    }

    const muCents = mean(historicalDailyFlows);
    const sigmaCents = standardDeviation(historicalDailyFlows);

    let exhaustionCount = 0;
    const endBalances: number[] = [];
    const chartPercentiles: { day: number; p10: number; p50: number; p90: number }[] = [];

    // Pre-allocate matrix for charting
    const dayMatrix: number[][] = Array(horizon).fill(0).map(() => []);

    for (let run = 0; run < runs; run++) {
      let runCash = currentCashCents;
      let exhausted = false;
      for (let day = 0; day < horizon; day++) {
        // Box-Muller transform for normal distribution
        let u = 0, v = 0;
        while(u === 0) u = Math.random();
        while(v === 0) v = Math.random();
        const z = Math.sqrt( -2.0 * Math.log( u ) ) * Math.cos( 2.0 * Math.PI * v );

        const dailyShock = muCents + (sigmaCents * z);
        runCash += dailyShock;

        if (runCash <= 0 && !exhausted) {
          exhausted = true;
          exhaustionCount++;
        }
        dayMatrix[day].push(runCash);
      }
      endBalances.push(runCash);
    }

    const sortFn = (a: number, b: number) => a - b;

    for (let day = 0; day < horizon; day++) {
      const sorted = dayMatrix[day].sort(sortFn);
      chartPercentiles.push({
        day,
        p10: sorted[Math.floor(runs * 0.1)] / 100,
        p50: sorted[Math.floor(runs * 0.5)] / 100,
        p90: sorted[Math.floor(runs * 0.9)] / 100
      });
    }

    endBalances.sort(sortFn);
    const medianEnd = endBalances[Math.floor(runs * 0.5)] / 100;
    const p10End = endBalances[Math.floor(runs * 0.1)] / 100;
    const probabilityOfRuin = (exhaustionCount / runs) * 100;

    return {
      metrics: [
        { label: 'Risk of Exhaustion (Ruin %)', value: `${probabilityOfRuin.toFixed(2)}%`, trend: probabilityOfRuin < 10 ? 'positive' : 'negative', color: probabilityOfRuin < 10 ? 'green' : 'red' },
        { label: 'Median Ending Cash', value: `$${medianEnd.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` },
        { label: '10th Percentile (Worst Case)', value: `$${p10End.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` }
      ],
      charts: [
        {
          config: {
            xKey: 'day',
            yKeys: [
              { key: 'p90', color: '#10b981', name: 'Optimistic (90th)' },
              { key: 'p50', color: '#6366f1', name: 'Expected (50th)' },
              { key: 'p10', color: '#ef4444', name: 'Pessimistic (10th)' }
            ]
          },
          data: chartPercentiles
        }
      ],
      insights: [
        `Running ${runs.toLocaleString()} probabilistic futures, there is a ${probabilityOfRuin.toFixed(1)}% chance of cash exhaustion within ${horizon} days.`,
        `Historical daily drift is ${muCents > 0 ? 'positive' : 'negative'} at $${(Math.abs(muCents)/100).toFixed(2)}/day with a volatility (1σ) of $${(sigmaCents/100).toFixed(2)}.`,
        probabilityOfRuin > 20 ? 'URGENT: Structural cash flow deficit detected. High risk of insolvency without intervention.' : 'Cash reserves appear resilient against standard historical volatility shocks.'
      ]
    };
  }
};

import { Transaction } from '../../types';
import { AlgorithmDefinition } from './types';

// The Dimensional Ledger Engine (In-Memory OLAP Cube)
// Parses "dimension:path/to/node" tags to build dynamic pivot tables.
export function buildOLAPCube(transactions: readonly Transaction[], rowDim: string, colDim: string) {
    const matrix = new Map<string, Map<string, number>>();
    const rowTotals = new Map<string, number>();
    const colTotals = new Map<string, number>();
    let grandTotal = 0;

    transactions.forEach(t => {
        t.lines?.forEach(line => {
            // Extract dimensions for this line
            const dims = new Map<string, string>();

            // Native dimensions
            if (line.accountName) dims.set('category', line.accountName);
            if (t.type) dims.set('type', t.type);

            // Tag-based dimensions (e.g., "property:house-1/unit-a", "client:acme")
            const allTags = [...(t.tags || []), ...(line.tags || [])];
            allTags.forEach(tag => {
                const parts = tag.split(':');
                if (parts.length >= 2) {
                    const dimName = parts[0].trim().toLowerCase();
                    const dimPath = parts.slice(1).join(':').trim();
                    dims.set(dimName, dimPath);
                } else {
                    dims.set('label', tag.trim());
                }
            });

            // If a dimension is missing for this line, we use "Unassigned"
            const rowValue = dims.get(rowDim) || 'Unassigned';
            const colValue = dims.get(colDim) || 'Unassigned';

            const amount = line.amountCents;

            // Add to matrix
            if (!matrix.has(rowValue)) matrix.set(rowValue, new Map());
            const rowMap = matrix.get(rowValue)!;
            rowMap.set(colValue, (rowMap.get(colValue) || 0) + amount);

            // Update totals
            rowTotals.set(rowValue, (rowTotals.get(rowValue) || 0) + amount);
            colTotals.set(colValue, (colTotals.get(colValue) || 0) + amount);
            grandTotal += amount;
        });
    });

    return { matrix, rowTotals, colTotals, grandTotal };
}

export const MULTIDIMENSIONAL_MATRIX: AlgorithmDefinition = {
  id: 'dimensional_ledger',
  domain: 'finance',
  name: 'Dimensional Ledger (OLAP Cube Engine)',
  description: 'Evaluates coordinates instead of categories. Groups transactions by dynamic dimensions (e.g., property vs. category) without rigid charts of accounts.',
  inputs: [
    { key: 'minVolume', label: 'Minimum Volume Filter ($)', min: 0, max: 10000, step: 100, defaultValue: 500 }
  ],
  compute: (ctx, inputs) => {
    const { transactions } = ctx;
    // Process real transactions directly
    const processedTxs = transactions.map(t => {
      // If no explicit tags exist, check project, location, or class as dynamic dimensions
      if ((!t.tags || t.tags.length === 0) && (!t.lines || !t.lines.some(l => l.tags && l.tags.length > 0))) {
        const derivedTags: string[] = [];
        if (t.project || (t as any).projectId) derivedTags.push(`project:${t.project || (t as any).projectId}`);
        if ((t as any).location) derivedTags.push(`location:${(t as any).location}`);
        if ((t as any).class) derivedTags.push(`class:${(t as any).class}`);
        if (derivedTags.length > 0) {
          return { ...t, tags: derivedTags };
        }
      }
      return t;
    });

    const start = performance.now();

    // Pivot: Property/Dimension (Row) x Category (Col)
    const { matrix, rowTotals, colTotals } = buildOLAPCube(processedTxs, 'property', 'category');

    const ms = performance.now() - start;

    // Build chart data
    const chartData = [];
    for (const [property, total] of rowTotals.entries()) {
        if (property === 'Unassigned') continue;
        if (Math.abs(total) < inputs.minVolume * 100) continue;

        chartData.push({
            name: property,
            volume: Math.abs(total) / 100
        });
    }

    return {
      metrics: [
        { label: 'Execution Time', value: `${ms.toFixed(2)} ms` },
        { label: 'Properties Analyzed', value: rowTotals.size },
        { label: 'Categories Intersected', value: colTotals.size },
        { label: 'Dimensional Nodes', value: rowTotals.size * colTotals.size }
      ],
      charts: [
         {
             data: chartData,
             config: {
                 xKey: 'name',
                 yKeys: [
                     { key: 'volume', color: '#10b981', name: 'Total Volume ($)', type: 'bar' }
                 ]
             }
         }
      ],
      insights: [
        `Sliced ${transactions.length} transactions across 'property' and 'category' dimensions.`,
        'Transactions exist at coordinates (e.g., house-1/energy) rather than just linear categories.',
        'Supports infinite dynamic dimensions. Just tag a transaction "campaign:summer25" and pivot by it instantly.'
      ]
    };
  }
};

