export const VENDOR_CHURN_ALGO: AlgorithmDefinition = {
  id: 'ops_vendor_churn',
  name: 'Vendor Churn & Ghosting',
  domain: 'operations',
  tags: ['Vendors', 'AP', 'Operations', 'Risk'],
  description: 'Identifies vendors that were previously paid on a regular basis but have unexpectedly stopped billing, which may indicate cancelled SaaS, ghost vendors, or service interruption.',
  inputs: [
    {
      key: 'inactivityDays',
      label: 'Inactivity Threshold (Days)',
      min: 30,
      max: 180,
      step: 15,
      defaultValue: 90
    }
  ],
  compute: (ctx, inputs): AlgoResult => {
    const { transactions } = ctx;
    const inactivityDays = inputs['inactivityDays'] ?? 90;
    const inactivityMs = inactivityDays * 24 * 60 * 60 * 1000;
    const now = new Date().getTime();

    // Group transactions by Payee/Description
    const vendorHistory: Record<string, number[]> = {};

    transactions.forEach(tx => {
      // Look for outgoing payments (negative net amount, or just filter on expenses)
      // We will look at payee or description
      const name = (tx.payee || tx.description || 'Unknown').trim();
      if (!name || name.toLowerCase() === 'unknown') return;

      const txTime = parseLocalDate(tx.date).getTime();

      if (!vendorHistory[name]) {
        vendorHistory[name] = [];
      }
      vendorHistory[name].push(txTime);
    });

    let activeVendors = 0;
    let churnedVendors = 0;
    let singleUseVendors = 0;

    // Determine the status of each vendor
    const churnRiskScores: Array<{name: string, daysSince: number, txCount: number}> = [];

    Object.keys(vendorHistory).forEach(name => {
      const history = vendorHistory[name].sort((a, b) => a - b);

      if (history.length <= 2) {
        singleUseVendors++;
        return; // Need a history to establish a pattern
      }

      const lastTxTime = history[history.length - 1];
      const daysSinceLast = (now - lastTxTime) / (1000 * 60 * 60 * 24);

      // Was there a regular cadence?
      // Find average gap
      let totalGap = 0;
      for (let i = 1; i < history.length; i++) {
        totalGap += (history[i] - history[i-1]);
      }
      const avgGapMs = totalGap / (history.length - 1);
      const avgGapDays = avgGapMs / (1000 * 60 * 60 * 24);

      // If the vendor usually bills every ~30 days, and it's been > 90 days
      if (daysSinceLast > Math.max(avgGapDays * 2, inactivityDays)) {
        churnedVendors++;
        churnRiskScores.push({
          name,
          daysSince: daysSinceLast,
          txCount: history.length
        });
      } else {
        activeVendors++;
      }
    });

    // Sort churned by txCount (highest history first)
    churnRiskScores.sort((a, b) => b.txCount - a.txCount);

    const insights = [];
    insights.push(`Analyzed ${Object.keys(vendorHistory).length} unique payees/vendors.`);

    if (churnedVendors > 0) {
      insights.push(`Detected ${churnedVendors} vendors that established a recurring billing pattern but have gone silent for >${inactivityDays} days.`);
      const topChurn = churnRiskScores.slice(0, 3);
      insights.push(`Top silent vendors: ${topChurn.map(v => `"${v.name}" (${Math.round(v.daysSince)} days ago)`).join(', ')}.`);
    } else {
      insights.push(`No regular vendors have exceeded the ${inactivityDays}-day inactivity threshold.`);
    }

    const chartData = [
      { Category: 'Active Recurring', Count: activeVendors },
      { Category: 'Silent / Churned', Count: churnedVendors },
      { Category: 'One-off / Irregular', Count: singleUseVendors }
    ];

    return {
      metrics: [
        { label: 'Active Vendors', value: activeVendors },
        { label: 'Silent Vendors', value: churnedVendors, color: churnedVendors > 0 ? 'text-amber-500' : 'text-slate-500' },
        { label: 'Top Silent Gap', value: churnRiskScores.length > 0 ? `${Math.round(churnRiskScores[0].daysSince)}d` : '0d' }
      ],
      charts: [
        {
          config: {
            xKey: 'Category',
            yKeys: [
              { key: 'Count', name: 'Vendor Count', color: '#8b5cf6', type: 'bar' }
            ]
          },
          data: chartData
        }
      ],
      insights
    };
  }
};

import { AlgorithmDefinition, AlgoResult } from './types';
import { isPostable, isOutflow } from '../../lib/txFilters';

export const VENDOR_CONCENTRATION_ALGO: AlgorithmDefinition = {
  id: 'intelligence_4',
  name: 'Vendor Concentration Risk',
  domain: 'operations',
  tags: ['Risk', 'Supply Chain', 'Vendor', 'Concentration'],
  description: 'Calculates the Herfindahl-Hirschman Index (HHI) and top-vendor reliance to identify dangerous supply chain or operational dependencies.',
  inputs: [
    { key: 'topN', label: 'Top N Vendors to Analyze', min: 3, max: 20, step: 1, defaultValue: 5 }
  ],
  compute: (ctx, inputs): AlgoResult => {
    const { transactions, accounts } = ctx;
    const topN = inputs.topN ?? 5;
    const vendorSpend: Record<string, number> = {};
    let totalSpend = 0;

    transactions.forEach(tx => {
      if (!isPostable(tx)) return;

      // Look at expenses
      const isExpense = tx.lines.some(l => {
         const acc = accounts.find(a => a.id === l.accountId);
         if (!acc) return false;
         const catLower = (acc.category || '').toLowerCase();
         return acc.type === 'expense' || acc.type === 'cost_of_goods' || catLower === 'cogs' || catLower === 'expense' || catLower === 'direct costs';
      });

      if (isExpense || isOutflow(tx, accounts as any)) {
         const payee = (tx.payee || tx.description || 'Unknown Vendor').toUpperCase().trim();
         if (!vendorSpend[payee]) vendorSpend[payee] = 0;

         const rate = tx.exchangeRate || 1;
         const expCents = tx.lines
           .filter(l => {
             const acc = accounts.find(a => a.id === l.accountId);
             if (!acc) return false;
             const catLower = (acc.category || '').toLowerCase();
             return acc.type === 'expense' || acc.type === 'cost_of_goods' || catLower === 'cogs' || catLower === 'expense';
           })
           .reduce((s, l) => s + Math.abs(l.amountCents), 0) || Math.abs(tx.totalAmountCents);

         const convertedAmt = Math.round(expCents * rate);
         vendorSpend[payee] += convertedAmt;
         totalSpend += convertedAmt;
      }
    });

    if (totalSpend === 0) {
      return {
        metrics: [{ label: 'Status', value: 'Insufficient Expense Data' }],
        charts: [],
        insights: ['Not enough outgoing transactions to calculate vendor concentration.']
      };
    }

    const sortedVendors = Object.entries(vendorSpend).sort((a, b) => b[1] - a[1]);
    const topVendors = sortedVendors.slice(0, topN);

    // Calculate HHI
    let hhi = 0;
    const chartData = [];
    let topNSpend = 0;

    sortedVendors.forEach(([vendor, spend], index) => {
      const marketShare = (spend / totalSpend) * 100;
      hhi += (marketShare * marketShare);

      if (index < topN) {
        chartData.push({
          Vendor: vendor,
          'Share %': parseFloat(marketShare.toFixed(1)),
          Spend: spend / 100
        });
        topNSpend += spend;
      }
    });

    // Remainder
    if (sortedVendors.length > topN) {
      chartData.push({
        Vendor: 'All Others',
        'Share %': parseFloat(((totalSpend - topNSpend) / totalSpend * 100).toFixed(1)),
        Spend: (totalSpend - topNSpend) / 100
      });
    }

    const topVendorReliance = topVendors.length > 0 ? (topVendors[0][1] / totalSpend) * 100 : 0;

    let hhiStatus = 'Low Risk';
    let hhiColor = 'green';
    if (hhi > 2500) {
      hhiStatus = 'High Concentration Risk';
      hhiColor = 'red';
    } else if (hhi > 1500) {
      hhiStatus = 'Moderate Concentration';
      hhiColor = 'orange';
    }

    return {
      metrics: [
        { label: 'HHI Score (Out of 10,000)', value: Math.round(hhi).toString(), color: hhiColor },
        { label: 'Risk Level', value: hhiStatus, color: hhiColor },
        { label: 'Top Vendor Reliance', value: `${topVendorReliance.toFixed(1)}%`, color: topVendorReliance > 30 ? 'red' : 'green' }
      ],
      charts: [
        {
          config: {
            xKey: 'Vendor',
            yKeys: [{ key: 'Share %', name: 'Wallet Share %', color: '#8b5cf6', type: 'bar' }]
          },
          data: chartData
        }
      ],
      insights: [
        `The Herfindahl-Hirschman Index (HHI) for operating expenses is ${Math.round(hhi)}.`,
        hhi > 2500 ? 'CRITICAL: The index exceeds 2,500, indicating a highly concentrated and risky supply chain.' : 'The supply chain shows a healthy distribution of vendor dependencies.',
        `The largest single vendor (${topVendors[0]?.[0] || 'N/A'}) accounts for ${topVendorReliance.toFixed(1)}% of all operating expenditures.`
      ]
    };
  }
};

import { parseLocalDate } from '../../lib/utils';
import { AlgorithmDefinition, AlgoResult } from './types';
import { resolveAccountRole } from '../accountUtils';

export const WORKING_CAPITAL_AGING_ALGO: AlgorithmDefinition = {
  id: 'ops_2',
  name: 'Working Capital & Invoice Aging',
  domain: 'operations',
  tags: ['Working Capital', 'Receivables', 'Payables', 'Aging', 'Cash Flow'],
  description: 'Analyzes unpaid invoices and bills to identify late payments and assess short-term liquidity bottlenecks based on due dates.',
  inputs: [
    { key: 'lateThresholdDays', label: 'Overdue Warning (Days)', min: 1, max: 120, step: 5, defaultValue: 30 }
  ],
  compute: (ctx, inputs): AlgoResult => {
    const { transactions, accounts } = ctx;
    let arPending = 0;
    let apPending = 0;
    let arOverdue = 0;
    let apOverdue = 0;
    const thresholdDays = inputs.lateThresholdDays ?? 30;
    const now = new Date().getTime();
    const chartData = [
       { Bucket: 'Current', AR: 0, AP: 0 },
       { Bucket: '1-30 Days Late', AR: 0, AP: 0 },
       { Bucket: '31-60 Days Late', AR: 0, AP: 0 },
       { Bucket: '60+ Days Late', AR: 0, AP: 0 }
    ];

    let hasProcessedData = false;

    // 1. Process explicit Invoices from context
    if (ctx.entities?.invoices && ctx.entities.invoices.length > 0) {
      ctx.entities.invoices.forEach(inv => {
        if (inv.status === 'paid' || inv.status === 'void' || inv.status === 'draft') return;
        hasProcessedData = true;
        const dueDateStr = inv.dueDate || inv.date;
        const dueDate = dueDateStr ? parseLocalDate(dueDateStr).getTime() : now;
        const daysOverdue = Math.floor((now - dueDate) / (1000 * 60 * 60 * 24));
        const amount = Math.abs(inv.amountCents || inv.totalCents || 0);

        arPending += amount;
        if (daysOverdue > thresholdDays) arOverdue += amount;

        if (daysOverdue <= 0) chartData[0].AR += (amount / 100);
        else if (daysOverdue <= 30) chartData[1].AR += (amount / 100);
        else if (daysOverdue <= 60) chartData[2].AR += (amount / 100);
        else chartData[3].AR += (amount / 100);
      });
    }

    // 2. Process explicit Bills from context
    if (ctx.entities?.bills && ctx.entities.bills.length > 0) {
      ctx.entities.bills.forEach(bill => {
        if (bill.status === 'paid' || bill.status === 'void' || bill.status === 'draft') return;
        hasProcessedData = true;
        const dueDateStr = bill.dueDate || bill.date;
        const dueDate = dueDateStr ? parseLocalDate(dueDateStr).getTime() : now;
        const daysOverdue = Math.floor((now - dueDate) / (1000 * 60 * 60 * 24));
        const amount = Math.abs(bill.amountCents || 0);

        apPending += amount;
        if (daysOverdue > thresholdDays) apOverdue += amount;

        if (daysOverdue <= 0) chartData[0].AP += (amount / 100);
        else if (daysOverdue <= 30) chartData[1].AP += (amount / 100);
        else if (daysOverdue <= 60) chartData[2].AP += (amount / 100);
        else chartData[3].AP += (amount / 100);
      });
    }

    // 3. Fallback: If no explicit invoices or bills in context, analyze transactions array
    if (!hasProcessedData && transactions && transactions.length > 0) {
      const arIncreases: { amount: number, dueDate: number }[] = [];
      const apIncreases: { amount: number, dueDate: number }[] = [];
      let arDecreases = 0;
      let apDecreases = 0;

      transactions.forEach(tx => {
        if (tx.status === 'void' || tx.status === 'reconciled') return;

        const dueDateStr = tx.metadata?.dueDate || tx.date;
        const dueDate = dueDateStr ? parseLocalDate(dueDateStr).getTime() : now;

        tx.lines?.forEach(l => {
          const acc = accounts.find(a => a.id === l.accountId);
          if (acc) {
            const role = resolveAccountRole(acc);
            if (role === 'ar') {
              if (l.amountCents > 0) {
                arIncreases.push({ amount: l.amountCents, dueDate });
              } else {
                arDecreases += Math.abs(l.amountCents);
              }
            } else if (role === 'ap') {
              if (l.amountCents < 0) {
                apIncreases.push({ amount: Math.abs(l.amountCents), dueDate });
              } else {
                apDecreases += Math.abs(l.amountCents);
              }
            }
          }
        });
      });

      // Sort oldest first
      arIncreases.sort((a, b) => a.dueDate - b.dueDate);
      apIncreases.sort((a, b) => a.dueDate - b.dueDate);

      // FIFO AR
      arIncreases.forEach(inv => {
        let remaining = inv.amount;
        if (arDecreases >= remaining) {
          arDecreases -= remaining;
          remaining = 0;
        } else if (arDecreases > 0) {
          remaining -= arDecreases;
          arDecreases = 0;
        }

        if (remaining > 0) {
          const daysOverdue = Math.floor((now - inv.dueDate) / (1000 * 60 * 60 * 24));
          arPending += remaining;
          if (daysOverdue > thresholdDays) arOverdue += remaining;

          if (daysOverdue <= 0) chartData[0].AR += (remaining / 100);
          else if (daysOverdue <= 30) chartData[1].AR += (remaining / 100);
          else if (daysOverdue <= 60) chartData[2].AR += (remaining / 100);
          else chartData[3].AR += (remaining / 100);
        }
      });

      // FIFO AP
      apIncreases.forEach(bill => {
        let remaining = bill.amount;
        if (apDecreases >= remaining) {
          apDecreases -= remaining;
          remaining = 0;
        } else if (apDecreases > 0) {
          remaining -= apDecreases;
          apDecreases = 0;
        }

        if (remaining > 0) {
          const daysOverdue = Math.floor((now - bill.dueDate) / (1000 * 60 * 60 * 24));
          apPending += remaining;
          if (daysOverdue > thresholdDays) apOverdue += remaining;

          if (daysOverdue <= 0) chartData[0].AP += (remaining / 100);
          else if (daysOverdue <= 30) chartData[1].AP += (remaining / 100);
          else if (daysOverdue <= 60) chartData[2].AP += (remaining / 100);
          else chartData[3].AP += (remaining / 100);
        }
      });
    }

    if (arPending === 0 && apPending === 0) {
      return {
        metrics: [{ label: 'Status', value: 'No Pending Invoices' }],
        charts: [],
        insights: ['No open customer invoices or supplier bills were found in the system.']
      };
    }

    const netPending = arPending - apPending;

    let arHealth = 'green';
    if (arOverdue > (arPending * 0.3)) arHealth = 'red';
    else if (arOverdue > 0) arHealth = 'orange';

    return {
      metrics: [
        { label: 'Total Pending AR', value: `$${(arPending / 100).toLocaleString()}` },
        { label: 'Total Pending AP', value: `$${(apPending / 100).toLocaleString()}` },
        { label: 'Severely Overdue AR', value: `$${(arOverdue / 100).toLocaleString()}`, color: arHealth },
        { label: 'Net Working Capital (Pending)', value: `$${(netPending / 100).toLocaleString()}`, color: netPending >= 0 ? 'green' : 'orange' }
      ],
      charts: [
        {
          config: {
            xKey: 'Bucket',
            yKeys: [
               { key: 'AR', name: 'Accounts Receivable ($)', color: '#3b82f6', type: 'bar' },
               { key: 'AP', name: 'Accounts Payable ($)', color: '#f43f5e', type: 'bar' }
            ]
          },
          data: chartData
        }
      ],
      insights: [
        `There is $${(arPending / 100).toLocaleString()} tied up in unpaid customer invoices (AR) and $${(apPending / 100).toLocaleString()} outstanding in supplier bills (AP).`,
        arOverdue > 0 ? `WARNING: $${(arOverdue / 100).toLocaleString()} of Accounts Receivable is significantly overdue (> ${inputs.lateThresholdDays} days past due date). Immediate collection efforts recommended.` : 'Receivables collection is healthy with no severely overdue invoices.',
        netPending < 0 ? 'Short-term liquidity crunch: Pending payables exceed pending receivables.' : 'Working capital structure is positive.'
      ]
    };
  }
};

import { TransactionLine, Transaction, DimensionDefinition, SplitAllocation, DimensionNode } from '../types';

export const DEFAULT_WORKSPACE_DIMENSIONS: DimensionDefinition[] = [
  { id: 'category', name: 'Category', systemDefault: true, sortOrder: 0 },
  { id: 'world', name: 'World / Entity', isWorld: true, sortOrder: 1 },
  { id: 'class', name: 'Class', sortOrder: 2 },
  { id: 'location', name: 'Location', sortOrder: 3 },
  { id: 'project', name: 'Project', sortOrder: 4 }
];

/**
 * Suggests the next short code for a dimension (e.g. 'P6' for 'property') based on existing nodes.
 */
export function suggestNextDimensionNodeId(dimensionId: string, nodes: DimensionNode[] | undefined): string {
  const prefix = dimensionId.substring(0, 1).toUpperCase();
  if (!nodes || nodes.length === 0) return `${prefix}1`;

  const existingIds = nodes
    .filter(n => n.dimensionId === dimensionId && n.id.startsWith(prefix))
    .map(n => parseInt(n.id.substring(1), 10))
    .filter(n => !isNaN(n));

  if (existingIds.length === 0) return `${prefix}1`;
  const max = Math.max(...existingIds);
  return `${prefix}${max + 1}`;
}

/**
 * Gets the string value of a specified dimension for a transaction line.
 * Resolution priority:
 * 1. Line-level `dimensions[dimId]`
 * 2. Legacy line fields (`class`, `location`, `project`, `department`, `category`, `accountName`)
 * 3. Line/Transaction tags formatted as `dimId:value` or `dimId/value`
 * 4. Transaction-level `dimensions[dimId]` or legacy fields
 * 5. Default fallback: 'Unassigned'
 */
export function getLineDimension(
  line: TransactionLine,
  tx: Transaction | undefined,
  dimensionId: string
): string {
  const normDim = (dimensionId || '').toLowerCase().trim();

  // 1. Check line.dimensions map
  if (line.dimensions && line.dimensions[normDim]) {
    return line.dimensions[normDim];
  }

  // 2. Legacy alias fallback on line
  if (normDim === 'class' && line.class) return line.class;
  if (normDim === 'location' && line.location) return line.location;
  if (normDim === 'project' && line.project) return line.project;
  if (normDim === 'department' && line.department) return line.department;
  if (normDim === 'category') {
    if (line.category) return line.category;
    if (line.accountName) return line.accountName;
  }

  // 3. Check line tags or tx tags for `dimension:value` format
  const allTags = [...(line.tags || []), ...(tx?.tags || [])];
  for (const tag of allTags) {
    if (!tag) continue;
    if (tag.includes(':')) {
      const [key, ...valParts] = tag.split(':');
      if (key.trim().toLowerCase() === normDim) {
        return valParts.join(':').trim();
      }
    }
  }

  // 4. Transaction-level dimensions & legacy aliases
  if (tx?.dimensions && tx.dimensions[normDim]) {
    return tx.dimensions[normDim];
  }
  if (tx) {
    if (normDim === 'project' && tx.projectId) return tx.projectId;
    if (normDim === 'class' && (tx as any).classId) return (tx as any).classId;
    if (normDim === 'location' && (tx as any).locationId) return (tx as any).locationId;
  }

  return 'Unassigned';
}

/**
 * Updates a transaction line with a dynamic dimension coordinate while keeping legacy aliases in sync.
 */
export function setLineDimension(
  line: TransactionLine,
  dimensionId: string,
  value: string
): TransactionLine {
  const normDim = dimensionId.toLowerCase().trim();
  const updatedDimensions = { ...(line.dimensions || {}), [normDim]: value };

  const updatedLine: TransactionLine = {
    ...line,
    dimensions: updatedDimensions
  };

  // Keep backward-compatible legacy fields in sync
  if (normDim === 'class') updatedLine.class = value;
  if (normDim === 'location') updatedLine.location = value;
  if (normDim === 'project') updatedLine.project = value;
  if (normDim === 'department') updatedLine.department = value;
  if (normDim === 'category') updatedLine.category = value;

  return updatedLine;
}

/**
 * Checks if a coordinate path matches or sits under a target parent path (hierarchical subtree match).
 * e.g., 'homes/maui/unit1' matches under 'homes' or 'homes/maui'.
 */
export function isPathSubtreeMatch(path: string, parentPath: string): boolean {
  if (!path || !parentPath) return false;
  const p = path.toLowerCase().trim();
  const target = parentPath.toLowerCase().trim();
  if (p === target) return true;
  return p.startsWith(target + '/');
}

/**
 * Validates split weight allocations for a line.
 * Weights across split allocations must sum to 1.0 (100%).
 */
export function validateSplitAllocations(splits?: SplitAllocation[]): { valid: boolean; sum: number; error?: string } {
  if (!splits || splits.length === 0) {
    return { valid: true, sum: 1.0 };
  }

  const hasInvalidWeight = splits.some(s => typeof s.weight !== 'number' || s.weight < 0 || s.weight > 1.0);
  if (hasInvalidWeight) {
    return {
      valid: false,
      sum: splits.reduce((acc, s) => acc + (s.weight || 0), 0),
      error: 'Individual split weight allocations must be between 0% (0.0) and 100% (1.0).'
    };
  }

  const sum = splits.reduce((acc, s) => acc + (s.weight || 0), 0);
  const roundedSum = Math.round(sum * 1000) / 1000; // allow small JS float precision

  if (Math.abs(roundedSum - 1.0) > 0.001) {
    return {
      valid: false,
      sum: roundedSum,
      error: `Split weights sum to ${(roundedSum * 100).toFixed(1)}%, but must total exactly 100%.`
    };
  }

  return { valid: true, sum: roundedSum };
}

/**
 * Extracts all unique hierarchical paths present in a dataset for autocomplete trie/dropdowns.
 */
export function extractUniqueDimensionPaths(
  transactions: Transaction[],
  dimensionId: string
): string[] {
  const pathSet = new Set<string>();

  transactions.forEach(tx => {
    tx.lines?.forEach(line => {
      const val = getLineDimension(line, tx, dimensionId);
      if (val && val !== 'Unassigned') {
        pathSet.add(val);
        // Also add parent path steps (e.g. homes/maui -> add homes)
        const parts = val.split('/');
        let current = '';
        for (let i = 0; i < parts.length - 1; i++) {
          current = current ? `${current}/${parts[i]}` : parts[i];
          if (current) pathSet.add(current);
        }
      }
    });
  });

  return Array.from(pathSet).sort();
}

/**
 * Deep Labeling & Multi-Dimensional Hierarchical Decomposition
 */
export interface DecomposedLabel {
  root: string;
  segments: string[];
  depth: number;
  parentPath: string | null;
  fullPath: string;
}

/**
 * Decomposes a multi-dimensional / nested label into its constituent hierarchy.
 * Supports delimiters: '/', ' > ', or ':'.
 * e.g. "Marketing / Digital / PPC" -> segments: ["Marketing", "Digital", "PPC"]
 */
export function decomposeHierarchicalLabel(label: string): DecomposedLabel {
  if (!label || typeof label !== 'string') {
    return { root: '', segments: [], depth: 0, parentPath: null, fullPath: '' };
  }

  const trimmed = label.trim();
  let segments: string[];

  if (trimmed.includes('>')) {
    segments = trimmed.split('>').map(s => s.trim()).filter(Boolean);
  } else if (trimmed.includes('/')) {
    segments = trimmed.split('/').map(s => s.trim()).filter(Boolean);
  } else if (trimmed.includes(':')) {
    segments = trimmed.split(':').map(s => s.trim()).filter(Boolean);
  } else {
    segments = [trimmed];
  }

  const root = segments[0] || '';
  const depth = segments.length;
  const parentPath = depth > 1 ? segments.slice(0, depth - 1).join('/') : null;
  const fullPath = segments.join('/');

  return { root, segments, depth, parentPath, fullPath };
}

/**
 * Matches a deep label against a target query pattern.
 * If matchAncestors is true, 'Dept/Engineering/Backend' matches a query for 'Dept/Engineering' or 'Dept'.
 */
export function matchDeepLabel(assigned: string, target: string, matchAncestors = true): boolean {
  if (!assigned || !target) return false;
  const a = assigned.toLowerCase().trim();
  const t = target.toLowerCase().trim();
  if (a === t) return true;

  const aDec = decomposeHierarchicalLabel(a);
  const tDec = decomposeHierarchicalLabel(t);

  // Exact normalized path match
  if (aDec.fullPath.toLowerCase() === tDec.fullPath.toLowerCase()) return true;

  if (matchAncestors) {
    // Child matches ancestor (e.g. 'engineering/backend' matches 'engineering')
    if (aDec.fullPath.toLowerCase().startsWith(tDec.fullPath.toLowerCase() + '/')) return true;
    // Ancestor matches child if desired
    if (tDec.fullPath.toLowerCase().startsWith(aDec.fullPath.toLowerCase() + '/')) return true;
  }

  return false;
}

/**
 * Expands hierarchical deep tags so that querying on any parent tier works seamlessly.
 * e.g. ["marketing/digital/ppc", "dept:ops:warehouse"]
 * -> ["marketing", "marketing/digital", "marketing/digital/ppc", "dept:ops", "dept:ops:warehouse"]
 */
export function expandDeepLabels(labels: string[]): string[] {
  if (!labels || labels.length === 0) return [];
  const resultSet = new Set<string>();

  for (const raw of labels) {
    if (!raw || typeof raw !== 'string') continue;
    const clean = raw.trim();
    resultSet.add(clean);

    // If label uses ':', expand colon prefixes (e.g. dept:ops:warehouse -> dept:ops, dept)
    if (clean.includes(':')) {
      const parts = clean.split(':').map(p => p.trim()).filter(Boolean);
      let cumulative = '';
      for (let i = 0; i < parts.length; i++) {
        cumulative = cumulative ? `${cumulative}:${parts[i]}` : parts[i];
        resultSet.add(cumulative);
      }
    }

    // If label uses '/' or '>', expand slash paths
    const dec = decomposeHierarchicalLabel(clean);
    if (dec.depth > 1) {
      let cumulativePath = '';
      for (let i = 0; i < dec.segments.length; i++) {
        cumulativePath = cumulativePath ? `${cumulativePath}/${dec.segments[i]}` : dec.segments[i];
        resultSet.add(cumulativePath);
      }
    }
  }

  return Array.from(resultSet);
}

/**
 * Extracts deep multi-dimensional coordinates and labels from free text (memos, descriptions).
 * Looks for patterns like [Dimension:Value/SubValue] or #tag/subtag
 */
export function extractMultiDimensionalLabels(
  text: string,
  existingDimensions?: Record<string, string>,
  existingTags?: string[]
): { dimensions: Record<string, string>; tags: string[]; deepPaths: string[] } {
  const dimensions: Record<string, string> = { ...(existingDimensions || {}) };
  const tagSet = new Set<string>(existingTags || []);
  const deepPaths: string[] = [];

  if (!text) return { dimensions, tags: Array.from(tagSet), deepPaths };

  // 1. Match bracketed dimensions: [Key:Value] or [Key:Value/SubValue]
  const bracketRegex = /\[([a-zA-Z0-9_-]+)\s*[:=]\s*([^\]]+)\]/g;
  let bMatch;
  while ((bMatch = bracketRegex.exec(text)) !== null) {
    const dimKey = bMatch[1].toLowerCase().trim();
    const dimVal = bMatch[2].trim();
    dimensions[dimKey] = dimVal;
    deepPaths.push(`${dimKey}:${dimVal}`);
    tagSet.add(`${dimKey}:${dimVal}`);
  }

  // 2. Match hashtag deep paths: #project/apollo/subphase or #dept/eng
  const hashRegex = /#([a-zA-Z0-9_/: -]+)/g;
  let hMatch;
  while ((hMatch = hashRegex.exec(text)) !== null) {
    const tag = hMatch[1].trim();
    tagSet.add(tag);
    if (tag.includes('/') || tag.includes(':')) {
      deepPaths.push(tag);
    }
  }

  const expandedTags = expandDeepLabels(Array.from(tagSet));
  return { dimensions, tags: expandedTags, deepPaths };
}

type SubscriptionCallback<T = any> = (data: T) => void;

class EventBus {
  private listeners: Record<string, SubscriptionCallback[]> = {};

  /**
   * Register a subscriber for an event. Returns a function to unsubscribe.
   */
  public subscribe<T = any>(event: string, callback: SubscriptionCallback<T>): () => void {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);

    return () => {
      this.listeners[event] = this.listeners[event].filter(cb => cb !== callback);
    };
  }

  /**
   * Broadcast/Publish an event with structured data.
   */
  public publish<T = any>(event: string, data: T): void {
    if (!this.listeners[event]) return;
    this.listeners[event].forEach(callback => {
      try {
        callback(data);
      } catch (err) {
        console.error(`Error executing event listener for event "${event}":`, err);
      }
    });
  }
}

export const globalEventBus = new EventBus();

import { format, startOfMonth, endOfMonth, startOfYear, subMonths, subDays } from 'date-fns';
import { TruthEngine } from '../modules/integrity/TruthEngine';

export const PATTERNS = {
  OP: /([><=])\s*([\d,]+(\.\d+)?)/,
  TEXT_OP: /(greater than|more than|over|above|at least|at most|less than|under|below|around|about|approx|approximately)\s*([\d,]+(\.\d+)?)/,
  RANGE: /between\s*([\d,]+(\.\d+)?)\s*and\s*([\d,]+(\.\d+)?)/,
  PERCENTILE: /\b(top|bottom)\s*(10|25|50)\s*%?\b/,
  MONTH: /(january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)/,
  YEAR: /\b(20\d{2})\b/,
  RELATIVE: /\b(last (?:month|week|year)|this (?:month|week|year)|yesterday|today|last \d+ days|ytd)\b/,
  QUARTER: /\b(q[1-4])\b/,
  DATE_RANGE: /(\d{4}-\d{2}-\d{2})\s*(?:to|until|through|-)\s*(\d{4}-\d{2}-\d{2})/,
  CATEGORY: /(category|type|account|sector):\s*([a-zA-Z\s]+)/,
  PROJECT: /(project|initiative|tag|venture):\s*([a-zA-Z\s]+)/,
  ERROR: /\b(error|mismatch|conflict|audit|review|unbalanced|weird|anomaly|fix)\b/,
};

const SEMANTIC_MAP: Record<string, string[]> = {
  'revenue': ['income', 'sales', 'earnings', 'deposits', 'inflow'],
  'expense': ['burn', 'spending', 'costs', 'bills', 'outflow', 'payments'],
  'marketing': ['ads', 'growth', 'social', 'campaign'],
  'infrastructure': ['cloud', 'aws', 'server', 'hosting', 'compute'],
  'payroll': ['salary', 'wages', 'team', 'staff', 'compensation', 'payroll'],
  'tax': ['irs', 'levy', 'tax', 'deductible', 'vat', 'gst'],
  'travel': ['uber', 'flight', 'airline', 'hotel', 'airbnb', 'commute'],
};

export interface ResolvedIntent {
  searchTerm: string;
  category?: string;
  project?: string;
  minAmountCents?: number;
  maxAmountCents?: number;
  startDate?: string;
  endDate?: string;
  percentile?: { side: 'top' | 'bottom', value: number };
  isAuditQuery?: boolean;
}

export class IntentResolver {
  static resolve(query: string, categories: string[] = [], projects: string[] = []): ResolvedIntent {
    const lowerQuery = query.toLowerCase().trim();
    const result: ResolvedIntent = { searchTerm: query };

    // 1. Semantic Mapping & Intent Steering
    for (const [canonical, aliases] of Object.entries(SEMANTIC_MAP)) {
      if (aliases.some(a => lowerQuery.includes(a)) || lowerQuery.includes(canonical)) {
          // If the query mentions a broad category like "expense", we often don't want to 
          // force a single category yet, but we allow the search term to capture it.
      }
    }

    // 2. Fuzzy Entity Detection (Smart Matching)
    const findEntity = (entities: string[], query: string) => {
        // Direct containment check (greedy)
        const direct = entities.find(e => query.includes(e.toLowerCase()));
        if (direct) return direct;

        // Sub-word check (e.g. "advertising" matches "ads")
        const sub = entities.find(e => e.split(' ').some(word => word.length > 3 && query.includes(word.toLowerCase())));
        return sub;
    };

    result.category = findEntity(categories, lowerQuery);
    result.project = findEntity(projects, lowerQuery);

    // 3. Precision Pattern Extraction
    const parseAmt = (valStr: string) => {
        let val = TruthEngine.parseAmountToCents(valStr) / 100;
        if (lowerQuery.includes('grand') || lowerQuery.includes('thousand') || lowerQuery.includes(' k ')) val *= 1000;
        if (lowerQuery.includes('mil') || lowerQuery.includes('million') || lowerQuery.includes(' m ')) val *= 1000000;
        return val * 100;
    };

    const opMatch = lowerQuery.match(/([><=])\s*([\d,]+(\.\d+)?)/);
    const textOpMatch = lowerQuery.match(/(greater than|more than|over|above|at least|at most|less than|under|below|around|about|approx|approximately)\s*([\d,]+(\.\d+)?)/);
    const rangeMatch = lowerQuery.match(/between\s*([\d,]+(\.\d+)?)\s*and\s*([\d,]+(\.\d+)?)/);

    if (opMatch) {
        const val = parseAmt(opMatch[2]);
        if (opMatch[1] === '>') result.minAmountCents = val;
        else if (opMatch[1] === '<') result.maxAmountCents = val;
    } else if (textOpMatch) {
        const val = parseAmt(textOpMatch[2]);
        const phrase = textOpMatch[1];
        if (/greater|more|over|above|at least/.test(phrase)) result.minAmountCents = val;
        else if (/less|under|below|at most/.test(phrase)) result.maxAmountCents = val;
    } else if (rangeMatch) {
        result.minAmountCents = parseAmt(rangeMatch[1]);
        result.maxAmountCents = parseAmt(rangeMatch[4]);
    }

    // 4. Enhanced Temporal Logic
    const monthMatch = lowerQuery.match(PATTERNS.MONTH);
    const yearMatch = lowerQuery.match(PATTERNS.YEAR);
    const relativeTimeMatch = lowerQuery.match(PATTERNS.RELATIVE);
    const quarterMatch = lowerQuery.match(PATTERNS.QUARTER);
    const dateRangeMatch = lowerQuery.match(PATTERNS.DATE_RANGE);
    const now = new Date();

    if (dateRangeMatch) {
        result.startDate = dateRangeMatch[1];
        result.endDate = dateRangeMatch[2];
    } else if (monthMatch) {
        const mNames = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december", "jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
        const monthIdx = mNames.indexOf(monthMatch[1].toLowerCase()) % 12;
        const year = yearMatch ? parseInt(yearMatch[1]) : now.getFullYear();
        result.startDate = format(new Date(year, monthIdx, 1), 'yyyy-MM-dd');
        result.endDate = format(new Date(year, monthIdx + 1, 0), 'yyyy-MM-dd');
    } else if (relativeTimeMatch) {
        const rel = relativeTimeMatch[1].toLowerCase();
        if (rel.includes('last 7 days')) {
          result.startDate = format(subDays(now, 7), 'yyyy-MM-dd');
          result.endDate = format(now, 'yyyy-MM-dd');
        } else if (rel.includes('last 30 days')) {
          result.startDate = format(subDays(now, 30), 'yyyy-MM-dd');
          result.endDate = format(now, 'yyyy-MM-dd');
        } else if (rel === 'this month') {
          result.startDate = format(startOfMonth(now), 'yyyy-MM-dd');
          result.endDate = format(endOfMonth(now), 'yyyy-MM-dd');
        } else if (rel === 'last month') {
          const lm = subMonths(now, 1);
          result.startDate = format(startOfMonth(lm), 'yyyy-MM-dd');
          result.endDate = format(endOfMonth(lm), 'yyyy-MM-dd');
        } else if (rel === 'ytd') {
          result.startDate = format(startOfYear(now), 'yyyy-MM-dd');
          result.endDate = format(now, 'yyyy-MM-dd');
        }
    } else if (yearMatch && !monthMatch) {
        const year = parseInt(yearMatch[1]);
        result.startDate = `${year}-01-01`;
        result.endDate = `${year}-12-31`;
    }

    if (lowerQuery.match(PATTERNS.ERROR)) result.isAuditQuery = true;

    return result;
  }

  static resolveEntry(input: string, options?: { rules?: any[], accounts?: any[], ruleCache?: Record<string, any> }): any[] | null {
    const lines = input.split(/\n+/).filter(line => line.trim().length > 0);
    const results: any[] = [];

    for (const line of lines) {
        const lowerInput = line.toLowerCase().trim();
        let learnedCategory: string | null = null;
        const learnedAccount: string | null = null;
        let isRuleConfirmed = false;

        // 0. High-Confidence Rule Mapping (Hardened User Rules)
        if (options?.rules) {
            const matchingRule = options.rules.find(r => 
                (r.condition.descriptionContains && lowerInput.includes(r.condition.descriptionContains.toLowerCase())) ||
                (r.condition.vendor && lowerInput.includes(r.condition.vendor.toLowerCase()))
            );

            if (matchingRule) {
                learnedCategory = matchingRule.action.targetCategory || null;
                isRuleConfirmed = true;
            }
        }

        // 0.1 Autonomous Rule Cache (Soft Learning from History)
        if (!learnedCategory && options?.ruleCache) {
            const cacheMatch = Object.entries(options.ruleCache).find(([key]) => lowerInput.includes(key));
            if (cacheMatch) {
                learnedCategory = cacheMatch[1].accountName;
                isRuleConfirmed = true; // Still counts as learned, but soft
            }
        }

        // 1. Check for Split Patterns: "Walmart $100 ($40 Groceries, $60 Electronics)"
        const splitMatch = lowerInput.match(/([a-zA-Z0-9\s.]+)\s*\$?([\d,]+(?:\.\d+)?[km]?)\s*\(([^)]+)\)/i);

        if (splitMatch) {
            const store = splitMatch[1].trim();
            const totalAmtStr = splitMatch[2];
            const itemsStr = splitMatch[3];

            const cleanedAmtStr = totalAmtStr.replace(/[km]/i, '');
            let totalAmt = TruthEngine.parseAmountToCents(cleanedAmtStr) / 100;
            if (totalAmtStr.endsWith('k')) totalAmt *= 1000;
            if (totalAmtStr.endsWith('m')) totalAmt *= 1000000;
            totalAmt *= 100;

            const splitLines = itemsStr.split(',').map(item => {
                const itemMatch = item.trim().match(/\$?([\d,]+(?:\.\d+)?[km]?)\s*([a-zA-Z\s]+)/i);
                if (itemMatch) {
                    const cleanedItemAmtStr = itemMatch[1].replace(/[km]/i, '');
                    let itemAmt = TruthEngine.parseAmountToCents(cleanedItemAmtStr) / 100;
                    if (itemMatch[1].endsWith('k')) itemAmt *= 1000;
                    if (itemMatch[1].endsWith('m')) itemAmt *= 1000000;
                    return {
                        accountName: itemMatch[2].trim().charAt(0).toUpperCase() + itemMatch[2].trim().slice(1),
                        amountCents: Math.round(itemAmt * 100)
                    };
                }
                return null;
            }).filter(Boolean);

            if (splitLines.length > 0) {
                results.push({
                    amountCents: -totalAmt,
                    description: store.charAt(0).toUpperCase() + store.slice(1),
                    dimensions: {
                        category: splitLines[0]!.accountName,
                        account: "Default Bank"
                    },
                    lines: splitLines.map(l => ({
                        accountName: l!.accountName,
                        amountCents: l!.amountCents
                    })),
                    date: format(new Date(), 'yyyy-MM-dd'),
                    type: "actual"
                });
                continue;
            }
        }

        // 2. Standard Pattern Matching
        const amountRegex = /(?:spent|paid|received|deposited)?\s*\$?([\d,]+(?:\.\d+)?[km]?)\s*(?:for|on|at|from)?\s*([a-zA-Z0-9\s.]+)/i;
        const amountSuffixRegex = /([a-zA-Z0-9\s.]+)\s*\$?([\d,]+(?:\.\d+)?[km]?)/i;

        let match = lowerInput.match(amountRegex);
        let desc = '';
        let amtStr = '';
        const isIncome = lowerInput.includes('received') || lowerInput.includes('deposited') || lowerInput.includes('income') || lowerInput.includes('sale') || lowerInput.includes('plus') || lowerInput.includes('+');

        if (match) {
            amtStr = match[1];
            desc = match[2].trim();
        } else {
            match = lowerInput.match(amountSuffixRegex);
            if (match) {
                desc = match[1].trim();
                amtStr = match[2];
            }
        }

        if (amtStr && desc) {
            const cleanedAmtStr = amtStr.replace(/[km]/i, '');
            let amt = TruthEngine.parseAmountToCents(cleanedAmtStr) / 100;
            if (amtStr.endsWith('k')) amt *= 1000;
            if (amtStr.endsWith('m')) amt *= 1000000;
            amt *= 100; // to cents

            // Deterministic Category Mapping (Hardware logic)
            let category = learnedCategory || "Uncategorized";
            if (!learnedCategory) {
                const dLower = desc.toLowerCase();

                // Check provided accounts first (dynamic learning)
                if (options?.accounts) {
                    const dynamicMatch = options.accounts.find(acc => {
                        const name = typeof acc === 'string' ? acc : (acc as any).name;
                        return dLower.includes(name.toLowerCase());
                    });
                    if (dynamicMatch) {
                        category = typeof dynamicMatch === 'string' ? dynamicMatch : (dynamicMatch as any).name;
                    }
                }

                if (category === "Uncategorized") {
                    for (const [cat, keywords] of Object.entries(SEMANTIC_MAP)) {
                      if (keywords.some(k => dLower.includes(k)) || dLower.includes(cat)) {
                        category = cat.charAt(0).toUpperCase() + cat.slice(1);
                        break;
                      }
                    }
                }
            }

            // 3. Date Detection
            let txDate = format(new Date(), 'yyyy-MM-dd');
            const yesterdayMatch = lowerInput.match(/yesterday/i);
            const dateMatch = lowerInput.match(/(\d{1,2})(?:st|nd|rd|th)?\s+(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)/i);

            if (yesterdayMatch) {
                txDate = format(subDays(new Date(), 1), 'yyyy-MM-dd');
            } else if (dateMatch) {
                const day = parseInt(dateMatch[1]);
                const monthName = dateMatch[2].toLowerCase();
                const months = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];
                const monthIdx = months.indexOf(monthName);
                if (monthIdx !== -1) {
                    const d = new Date();
                    d.setMonth(monthIdx);
                    d.setDate(day);
                    txDate = format(d, 'yyyy-MM-dd');
                }
            }

            results.push({
                amountCents: isIncome ? amt : -amt,
                description: desc.charAt(0)?.toUpperCase() + desc.slice(1),
                isLearned: isRuleConfirmed,
                dimensions: {
                    category: category,
                    account: "Default Bank"
                },
                date: txDate,
                type: "actual"
            });
        }
    }

    return results.length > 0 ? results : null;
  }
}

