  const html = `
    <html>
    <head>
      <title>Invoice ${invoice.number}</title>
      <style>
        body { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; padding: 40px; color: #333; }
        .header { display: flex; justify-content: space-between; border-bottom: 2px solid #eee; padding-bottom: 20px; }
        .header-left h1 { margin: 0; font-size: 32px; color: #111; }
        .header-right { text-align: right; }
        .header-right h2 { margin: 0; font-size: 24px; color: #555; }
        .info-section { display: flex; justify-content: space-between; margin-top: 40px; }
        .bill-to h3 { margin-top: 0; color: #666; font-size: 14px; text-transform: uppercase; }
        .meta-table { border-collapse: collapse; }
        .meta-table td { padding: 5px 15px; text-align: right; }
        .meta-table td:first-child { font-weight: bold; color: #666; text-align: left; }
        .items-table { width: 100%; border-collapse: collapse; margin-top: 40px; }
        .items-table th { background: #f9f9f9; padding: 12px; text-align: left; border-bottom: 1px solid #ddd; }
        .items-table td { padding: 12px; border-bottom: 1px solid #eee; }
        .items-table th.right, .items-table td.right { text-align: right; }
        .totals-section { margin-top: 40px; display: flex; justify-content: flex-end; }
        .totals-table { width: 300px; border-collapse: collapse; }
        .totals-table td { padding: 10px; text-align: right; border-bottom: 1px solid #eee; }
        .totals-table td:first-child { font-weight: bold; text-align: left; }
        .totals-table .total-row { font-size: 18px; font-weight: bold; border-top: 2px solid #333; border-bottom: none; }
        .status-badge { display: inline-block; padding: 4px 10px; border-radius: 4px; font-weight: bold; font-size: 12px; text-transform: uppercase; border: 1px solid currentColor; color: ${statusColor}; margin-top: 10px; }
        .notes { margin-top: 40px; color: #666; font-size: 14px; }
      </style>
    </head>
    <body>
      <div class="header">
        <div class="header-left">
          <h1>${workspaceName}</h1>
        </div>
        <div class="header-right">
          <h2>INVOICE</h2>
          <div># ${invoice.number}</div>
          <div class="status-badge">${invoice.status}</div>
        </div>
      </div>

      <div class="info-section">
        <div class="bill-to">
          <h3>Bill To</h3>
          <strong>${customer?.name || 'Unknown Customer'}</strong><br/>
          ${customer?.email ? customer.email + '<br/>' : ''}
          ${customer?.phone ? customer.phone + '<br/>' : ''}
        </div>
        <div>
          <table class="meta-table">
            <tr><td>Date:</td><td>${invoice.date}</td></tr>
            <tr><td>Due Date:</td><td>${invoice.dueDate || invoice.date}</td></tr>
          </table>
        </div>
      </div>

      <table class="items-table">
        <thead>
          <tr>
            <th>Description</th>
            <th class="right">Qty</th>
            <th class="right">Rate</th>
            <th class="right">Amount</th>
          </tr>
        </thead>
        <tbody>
          ${((invoice.metadata && invoice.metadata.lines) || []).map((item: any) => `
            <tr>
              <td>${item.description || 'Item'}</td>
              <td class="right">${item.quantity || 1}</td>
              <td class="right">${formatCurrency(item.rateCents ?? item.amountCents ?? 0)}</td>
              <td class="right">${formatCurrency(item.amountCents)}</td>
            </tr>
          `).join('')}
        </tbody>
      </table>

      <div class="totals-section">
        <table class="totals-table">
          <tr><td>Subtotal</td><td>${formatCurrency(invoice.totalCents)}</td></tr>
          ${(invoice.metadata && invoice.metadata.amountPaidCents) ? `<tr><td>Amount Paid</td><td>-${formatCurrency((invoice.metadata && invoice.metadata.amountPaidCents))}</td></tr>` : ''}
          <tr class="total-row"><td>Amount Due</td><td>${formatCurrency(amountDue)}</td></tr>
        </table>
      </div>

      ${(invoice.metadata && invoice.metadata.notes) ? `<div class="notes"><strong>Notes:</strong><br/>${(invoice.metadata && invoice.metadata.notes)}</div>` : ''}

      <script>
        window.onload = function() { window.print(); };
      </script>
    </body>
    </html>
  `;

  const printWindow = window.open('', '_blank');
  if (printWindow) {
    printWindow.document.write(html);
    printWindow.document.close();
  }
}

import { RecurringTransaction, Transaction } from '../types';
import { parseLocalDate } from './utils';

export function calculateNextOccurrence(currentDateStr: string, frequency: RecurringTransaction['frequency']): string {
  const date = parseLocalDate(currentDateStr || new Date().toISOString().slice(0, 10));
  if (isNaN(date.getTime())) {
    const now = new Date();
    return now.toISOString().slice(0, 10);
  }

  switch (frequency) {
    case 'daily':
      date.setDate(date.getDate() + 1);
      break;
    case 'weekly':
      date.setDate(date.getDate() + 7);
      break;
    case 'monthly':
      date.setMonth(date.getMonth() + 1);
      break;
    case 'quarterly':
      date.setMonth(date.getMonth() + 3);
      break;
    case 'yearly':
      date.setFullYear(date.getFullYear() + 1);
      break;
    default:
      date.setMonth(date.getMonth() + 1);
  }

  const yyyy = date.getFullYear();
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

export interface DueRecurringResult {
  dueTemplates: RecurringTransaction[];
  generatedTransactions: Array<{
    transaction: Partial<Transaction>;
    templateId: string;
    updatedNextOccurrence: string;
  }>;
}

export function findDueRecurring(recurringList: RecurringTransaction[], asOfDateStr?: string): DueRecurringResult {
  const todayStr = asOfDateStr || new Date().toISOString().slice(0, 10);
  const asOfTime = parseLocalDate(todayStr).getTime();

  const dueTemplates: RecurringTransaction[] = [];
  const generatedTransactions: DueRecurringResult['generatedTransactions'] = [];

  for (const item of recurringList) {
    if (!item.isActive) continue;

    const currentNextOccStr = item.nextOccurrence || item.createdAt.slice(0, 10);
    let nextOccTime = parseLocalDate(currentNextOccStr).getTime();

    if (!isNaN(nextOccTime) && nextOccTime <= asOfTime) {
      dueTemplates.push(item);

      const template = (item.template || {}) as Partial<Transaction>;
      const amount = item.amountCents || template.totalAmountCents || 0;
      const currency = template.currency || 'USD';

      let lines = template.lines;
      if (!lines || lines.length === 0) {
        const primaryAccountId = (template as any).accountId || '';
        const primaryAccountName = (template as any).accountName || 'Operating Expense';
        const offsetAccountId = (template as any).offsetAccountId || '';
        const offsetAccountName = (template as any).offsetAccountName || 'Operating Cash';

        lines = [
          {
            accountId: primaryAccountId,
            accountName: primaryAccountName,
            amountCents: amount,
            description: item.description
          },
          {
            accountId: offsetAccountId,
            accountName: offsetAccountName,
            amountCents: -amount,
            description: item.description
          }
        ];
      }

      // Handle catch-up loop if overdue
      let latestNextOccStr = currentNextOccStr;
      while (nextOccTime <= asOfTime) {
        const newTx: Partial<Transaction> = {
          description: item.description,
          totalAmountCents: amount,
          currency,
          date: latestNextOccStr,
          status: 'completed',
          type: 'actual',
          tags: [...(template.tags || []), 'recurring'],
          lines,
          projectId: template.projectId,
          metadata: {
            recurringTemplateId: item.id,
            generatedAt: new Date().toISOString(),
            ...(template.metadata || {})
          }
        };

        latestNextOccStr = calculateNextOccurrence(latestNextOccStr, item.frequency);
        nextOccTime = parseLocalDate(latestNextOccStr).getTime();

        generatedTransactions.push({
          transaction: newTx,
          templateId: item.id,
          updatedNextOccurrence: latestNextOccStr
        });
      }
    }
  }

  return { dueTemplates, generatedTransactions };
}

/**
 * LedgerFlow High-Precision Telemetry System
 * Tracks micro-timing for component 'opens', module imports, and mathematical execution.
 */

export class PerformanceTelemetry {
  private static markers: Map<string, number> = new Map();

  static start(label: string) {
    this.markers.set(label, performance.now());
  }

  static end(label: string) {
    const startTime = this.markers.get(label);
    if (!startTime) return null;

    const duration = performance.now() - startTime;
    this.markers.delete(label);
    return duration;
  }

  /**
   * Specifically for tracking component "opening" (mount time)
   */
  static traceComponent(name: string) {
    const start = performance.now();
    let captured = false;

    return () => {
      if (captured) return;
      captured = true;
      const duration = performance.now() - start;
      return duration;
    };
  }
}

import { Transaction, TransactionLine, ChartAccount } from '../types';

/**
 * Checks if a transaction is a simulation/ghost transaction created for scenario forecasting
 */
export function isSimulationTransaction(t: Transaction): boolean {
  if (!t) return false;
  return Boolean(
    t.metadata?.isGhost || 
    t.type === 'forecast' || 
    (typeof t.id === 'string' && t.id.startsWith('ghost-')) || 
    t.workspaceId === 'simulation' ||
    t.workspaceId === 'ghost-workspace'
  );
}

/**
 * Predicate to determine if a transaction is postable / active
 * Filters out void, failed, draft, soft-deleted, and by default simulation/ghost transactions.
 */
export function isPostable(t: Transaction): boolean;
export function isPostable(t: Transaction, options: { includeSimulations?: boolean }): boolean;
export function isPostable(t: Transaction, options?: any): boolean {
  if (!t) return false;
  if (t.status === 'void' || t.status === 'failed' || (t as any).status === 'draft' || t.deletedAt) {
    return false;
  }
  const includeSimulations = typeof options === 'object' && options !== null && Boolean(options.includeSimulations);
  if (!includeSimulations && isSimulationTransaction(t)) {
    return false;
  }
  return true;
}

/**
 * Normalizes a ledger date to its calendar-day representation. Transactions may
 * be stored as either `YYYY-MM-DD` or a full ISO timestamp, while report
 * controls use date-only values. Comparing those strings directly excludes
 * timestamped transactions that occur on an inclusive end date.
 */
export function transactionDate(t: Pick<Transaction, 'date'>): string {
  return typeof t.date === 'string' ? t.date.slice(0, 10) : '';
}

/** Returns true when a transaction falls within an inclusive calendar-date range. */
export function isTransactionInDateRange(t: Pick<Transaction, 'date'>, start?: string, end?: string): boolean {
  const date = transactionDate(t);
  if (!date) return false;
  const startDate = start?.slice(0, 10);
  const endDate = end?.slice(0, 10);
  return (!startDate || date >= startDate) && (!endDate || date <= endDate);
}

/**
 * Calculates the base-currency amount in cents for a line item,
 * incorporating line or transaction-level FX exchange rates.
 */
export function lineAmount(l: TransactionLine, t?: Transaction): number {
  if (!l) return 0;
  const raw = l.amountCents || 0;
  const rate = l.exchangeRate ?? t?.exchangeRate ?? 1;
  return Math.round(raw * rate);
}

/**
 * Checks if an account is an income/revenue account
 */
export function isRevenueAccount(account?: ChartAccount): boolean {
  if (!account) return false;
  const type = (account.type || '').toLowerCase();
  return type === 'revenue' || type === 'income';
}

/**
 * Checks if an account is an expense/cost-of-goods account
 */
export function isExpenseAccount(account?: ChartAccount): boolean {
  if (!account) return false;
  const type = (account.type || '').toLowerCase();
  return type === 'expense' || type === 'cost_of_goods' || type === 'cogs';
}

/**
 * Checks if an account is a cash or cash equivalent asset
 */
export function isCashAccount(account?: ChartAccount): boolean {
  if (!account) return false;
  const category = (account.category || '').toLowerCase();
  const subType = (account.subtype || (account as any).subType || '').toLowerCase();
  const name = (account.name || '').toLowerCase();
  const role = ((account as any).role || '').toLowerCase();
  return (
    role === 'cash' ||
    category.includes('cash') ||
    category.includes('bank') ||
    subType.includes('cash') ||
    subType.includes('bank') ||
    subType.includes('checking') ||
    subType.includes('savings') ||
    name.includes('checking') ||
    name.includes('savings') ||
    name.includes('operating cash') ||
    name.includes('petty cash') ||
    name.includes('cash') ||
    name.includes('bank')
  );
}

/**
 * Determines whether a transaction is predominantly an Income transaction
 */
export function isIncomeTransaction(tx: Transaction, accountMap?: Map<string, ChartAccount>): boolean {
  if (!isPostable(tx)) return false;
  if (tx.type === 'income') return true;
  if (tx.type === 'expense') return false;

  // If lines are present, check if any line credits a revenue account
  if (Array.isArray(tx.lines) && tx.lines.length > 0) {
    for (const line of tx.lines) {
      const acc = accountMap?.get(line.accountId);
      if (acc && isRevenueAccount(acc) && line.amountCents < 0) {
        return true;
      }
    }
  }
  return false;
}

/**
 * Determines whether a transaction is predominantly an Expense transaction
 */
export function isExpenseTransaction(tx: Transaction, accountMap?: Map<string, ChartAccount>): boolean {
  if (!isPostable(tx)) return false;
  if (tx.type === 'expense') return true;
  if (tx.type === 'income') return false;

  if (Array.isArray(tx.lines) && tx.lines.length > 0) {
    for (const line of tx.lines) {
      const acc = accountMap?.get(line.accountId);
      if (acc && isExpenseAccount(acc) && line.amountCents > 0) {
        return true;
      }
    }
  }
  return false;
}

/**
 * Determines whether a transaction represents an outflow / expense
 */
export function isOutflow(t: Transaction, accounts?: ChartAccount[] | Map<string, ChartAccount>): boolean {
  if (!isPostable(t)) return false;
  if (t.type === 'expense' || (t.type as string) === 'cost_of_goods') return true;
  if (t.type === 'income' || (t.type as string) === 'revenue') return false;

  const map = Array.isArray(accounts) 
    ? new Map(accounts.map(a => [a.id, a])) 
    : accounts;

  if (t.lines && t.lines.length > 0) {
    const hasExpenseLine = t.lines.some(l => {
      const acc = map?.get(l.accountId);
      return acc ? isExpenseAccount(acc) : false;
    });
    if (hasExpenseLine) return true;
  }
  return false;
}

/**
 * Determines whether a transaction represents an inflow / income
 */
export function isInflow(t: Transaction, accounts?: ChartAccount[] | Map<string, ChartAccount>): boolean {
  if (!isPostable(t)) return false;
  if (t.type === 'income' || (t.type as string) === 'revenue') return true;
  if (t.type === 'expense' || (t.type as string) === 'cost_of_goods') return false;

  const map = Array.isArray(accounts) 
    ? new Map(accounts.map(a => [a.id, a])) 
    : accounts;

  if (t.lines && t.lines.length > 0) {
    return t.lines.some(l => {
      const acc = map?.get(l.accountId);
      return acc ? (isRevenueAccount(acc) && (l.amountCents || 0) < 0) : false;
    });
  }
  return false;
}

/**
 * Calculates the net income-statement impact (Inflow - Outflow) of a transaction.
 * This is the canonical way to determine the "value" of a transaction for reports.
 * Returns (Sum of Revenue credits) - (Sum of Expense/COGS debits).
 */
export function calculateTransactionImpact(t: Transaction, accountMap?: Map<string, ChartAccount>): number {
  if (!isPostable(t)) return 0;
  let impact = 0;
  const lines = t.lines || [];

  for (let i = 0; i < lines.length; i++) {
    const l = lines[i];
    const acc = accountMap?.get(l.accountId);
    const amt = lineAmount(l, t);

    if (isRevenueAccount(acc)) {
      impact -= amt; // Revenue is credit (negative), so subtract to get positive impact
    } else if (isExpenseAccount(acc)) {
      impact -= amt; // Expense is debit (positive), so subtract to get negative impact
    }
  }

  return impact;
}

/**
 * Predicate to determine if an invoice is open/unpaid
 */
export function isOpenInvoice(item: any): boolean {
  if (!item) return false;
  return item.status !== 'paid' && item.status !== 'void' && item.status !== 'draft' && item.status !== 'rejected';
}

/**
 * Predicate to determine if a bill is open/unpaid
 */
export function isOpenBill(item: any): boolean {
  if (!item) return false;
  return item.status !== 'paid' && item.status !== 'void' && item.status !== 'draft' && item.status !== 'rejected';
}

/**
 * Pure math P&L & Net Income calculator
 */
export function calculateNetIncome(
  transactions: Transaction[],
  accounts: ChartAccount[],
  startDate?: string,
  endDate?: string
): { income: number; cogs: number; expense: number; grossProfit: number; netIncome: number } {
  const start = startDate || "1970-01-01";
  const end = endDate || "2099-12-31";

  let income = 0;
  let cogs = 0;
  let expense = 0;

  const accountMap = new Map<string, ChartAccount>();
  for (let i = 0; i < accounts.length; i++) {
    accountMap.set(accounts[i].id, accounts[i]);
  }

  for (let i = 0; i < transactions.length; i++) {
    const t = transactions[i];
    if (!isPostable(t)) continue;
    if (!isTransactionInDateRange(t, start, end)) continue;

    const lines = t.lines || [];
    for (let j = 0; j < lines.length; j++) {
      const l = lines[j];
      const acc = accountMap.get(l.accountId);
      if (!acc) continue;

      const amt = lineAmount(l, t);

      const isCogs = acc.type === 'cost_of_goods' || acc.category === 'COGS' || acc.category === 'Direct Costs' || (acc as any).role === 'cogs';

      if (acc.type === 'income' || acc.type === 'revenue') {
        income += -amt;
      } else if (isCogs) {
        cogs += amt;
      } else if (acc.type === 'expense') {
        expense += amt;
      }
    }
  }

  const grossProfit = income - cogs;
  const netIncome = grossProfit - expense;

  return { income, cogs, expense, grossProfit, netIncome };
}

/**
 * Computes the absolute total of a transaction (sum of all positive line amounts).
 * This replaces scattered manual absolute-total calculation loops across the codebase.
 */
export function getAbsoluteTotal(tx: Transaction): number {
  if (!tx || !Array.isArray(tx.lines)) return 0;
  return tx.lines
    .filter(l => (l.amountCents || 0) > 0)
    .reduce((sum, l) => sum + lineAmount(l, tx), 0);
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';
import { toast } from 'sonner';

/**
 * Specialized financial rounding to prevent decimal loss in tax calculations
 */
export function roundCents(cents: number): number {
  return Math.sign(cents) * Math.round(Math.abs(cents));
}

/**
 * Safely parses string or numeric monetary inputs into integer cents without floating point precision errors.
 */
export function parseAmountToCents(val: string | number | undefined | null): number {
  if (val === undefined || val === null || val === '') return 0;
  if (typeof val === 'number') {
    if (isNaN(val)) return 0;
    return Math.round(val * 100);
  }
  const cleanStr = String(val).replace(/[^0-9.-]/g, '');
  const parsed = parseFloat(cleanStr);
  if (isNaN(parsed)) return 0;
  return Math.round(parsed * 100);
}

/**
 * Safe currency formatter with fallback
 */
export function formatCurrency(cents: number | undefined | null, currency?: string): string {
  let targetCurrency = currency;
  if (!targetCurrency) {
    try {
      targetCurrency = (typeof window !== 'undefined' && (window as any).__ledgerBaseCurrency) || 'USD';
    } catch {
      targetCurrency = 'USD';
    }
  }

  const safeCents = (cents === undefined || cents === null || isNaN(cents)) ? 0 : cents;

  let divisor = 100;
  try {
    const formatter = new Intl.NumberFormat(undefined, { style: 'currency', currency: targetCurrency });
    if (formatter.resolvedOptions().maximumFractionDigits === 0) {
      divisor = 1;
    }
  } catch (_e) {
    // Unsupported currency fallback
  }

  return new Intl.NumberFormat(undefined, {
    style: 'currency',
    currency: targetCurrency,
  }).format(safeCents / divisor);
}

/**
 * Safe currency formatter for amounts already in dollars
 */
export function formatDollars(dollars: number | undefined | null, currency?: string): string {
  const safeDollars = (dollars === undefined || dollars === null || isNaN(dollars)) ? 0 : dollars;
  return formatCurrency(safeDollars * 100, currency);
}

/**
 * Masks sensitive PII (Personally Identifiable Information) for Display
 */
export function maskPII(text: string | undefined | null): string {
  if (!text) return "";
  if (text.includes('@')) {
    const parts = text.split('@');
    if (parts.length >= 2) {
      const user = parts[0];
      const domain = parts.slice(1).join('@');
      return `${user.slice(0, 2)}***@${domain}`;
    }
  }
  // Mask potential account numbers
  const digitsOnly = text.replace(/[\s-]/g, '');
  if (/^\d{8,20}$/.test(digitsOnly)) {
    return `****${digitsOnly.slice(-4)}`;
  }
  return text;
}

/**
 * Accurately formats a cents value into a string representing decimal dollars without binary float issues.
 * Used for CSV exports. Example: 1005 -> "10.05"
 */
export function formatDecimal(cents: number): string {
  if (cents === null || cents === undefined || isNaN(cents)) return "0.00";
  const isNegative = cents < 0;
  const absCents = Math.abs(Math.round(cents));
  const dollars = Math.floor(absCents / 100);
  const remainder = absCents % 100;
  return `${isNegative && absCents > 0 ? '-' : ''}${dollars}.${remainder.toString().padStart(2, '0')}`;
}

/**
 * Returns YYYY-MM-DD string in local user timezone to prevent UTC shift off-by-one errors
 */
export function getLocalDateISO(d: Date = new Date()): string {
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/**
 * Parses a YYYY-MM-DD string into a local midnight Date object
 * Prevents UTC off-by-one errors from standard new Date('YYYY-MM-DD')
 */
export function parseLocalDate(s: string): Date {
  if (!s) return new Date();
  if (s.includes('T')) return new Date(s); // Handle full ISO strings if they somehow appear
  const parts = s.split('-');
  if (parts.length === 3) {
    const [y, m, d] = parts.map(Number);
    return new Date(y, m - 1, d);
  }
  return new Date(s);
}

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Sanitizes a string value against CSV/Formula injection attacks.
 * Prevents execution of spreadsheet formulas starting with =, +, -, @, \t, \r
 */
export function sanitizeCsvCell(value: any): string {
  if (value === null || value === undefined) return '""';
  if (typeof value === 'number') return String(value);

  let str = String(value);

  // Purely formatted numbers (like -1,000.00 or -$50.00) are safe from formula injection
  const isSafeNumber = /^-?\$?\s*\d{1,3}(,?\d{3})*(\.\d+)?$/.test(str);

  if (!isSafeNumber && /^[=+\-@\t\r]/.test(str)) {
    str = "'" + str;
  }

  return `"${str.replace(/"/g, '""')}"`;
}

export enum OperationType {
  CREATE = 'create',
  UPDATE = 'update',
  DELETE = 'delete',
  LIST = 'list',
  GET = 'get',
  WRITE = 'write',
  AUTH = 'auth',
  SYNC = 'sync'
}

export interface AppErrorInfo {
  error: string;
  operationType: OperationType;
  path: string | null;
  timestamp: string;
  context?: Record<string, any>;
  stack?: string;
}

/**
 * Enhanced Error Logger
 * Captures deep context for forensic debugging
 */
export function reportError(error: unknown, operationType: OperationType, path: string | null = null, context?: Record<string, any>) {
  const message = error instanceof Error ? error.message : String(error);
  const stack = error instanceof Error ? error.stack : undefined;

  const errInfo: AppErrorInfo = {
    error: message,
    operationType,
    path,
    timestamp: new Date().toISOString(),
    context,
    stack
  };

  console.error(`[FORENSIC ERROR] ${(operationType || 'UNKNOWN').toUpperCase()}:`, JSON.stringify(errInfo, null, 2));

  // UI Feedback
  toast.error(`SYSTEM ERROR: ${(operationType || 'UNKNOWN').toUpperCase()}`, {
    description: message.length > 100 ? message.slice(0, 100) + '...' : message
  });

  return errInfo;
}

/**
 * Async Safety Wrapper
 * Automatically handles errors and reports them
 */
export async function safeAsync<T>(
  promise: Promise<T>, 
  operationType: OperationType, 
  path: string | null = null,
  context?: Record<string, any>
): Promise<[T | null, AppErrorInfo | null]> {
  try {
    const result = await promise;
    return [result, null];
  } catch (error) {
    const errInfo = reportError(error, operationType, path, context);
    return [null, errInfo];
  }
}

/**
 * Safe confirmation modal dialog helper.
 * Degrades gracefully inside sandboxed browser iframes where window.confirm causes SecurityError.
 * Fails closed (returns false) to prevent accidental execution of destructive actions.
 */
export function safeConfirm(message: string): boolean {
  try {
    if (typeof window !== 'undefined' && typeof window.confirm === 'function') {
      return window.confirm(message);
    }
    return false;
  } catch (error) {
    console.warn('[SANDBOX CAUGHT] window.confirm execution prevented by environment. Refusing destructive action for safety.', error);
    return false;
  }
}

/**
 * Resolves account name dynamically from chart of accounts using accountId first,
 * falling back to line.accountName or line.accountId if deleted/archived.
 */
export function resolveAccountName(accounts: any[], accountId?: string, fallbackName?: string): string {
  if (!accountId && !fallbackName) return 'Uncategorized';
  if (accountId && Array.isArray(accounts)) {
    const matched = accounts.find(a => a.id === accountId);
    if (matched?.name) return matched.name;
  }
  return fallbackName || accountId || 'Uncategorized';
}

