import { parseLocalDate } from '../../lib/utils';
// Architecture: Core Integrity Engine
// Enforces that numbers, facts, and validations are strictly correct. No false info.
import { TemporalValidity } from '../../types';
import Decimal from 'decimal.js';

export class TruthEngine {
  static resolveEffectiveValue(timeSeries: TemporalValidity[], targetDateStr: string): number {
    const targetTime = parseLocalDate(targetDateStr).getTime();
    if (isNaN(targetTime)) {
      throw new Error(`Integrity Violation: Invalid target date format -> ${targetDateStr}`);
    }

    const sortedSeries = [...timeSeries].sort((a, b) => parseLocalDate(b.validFrom).getTime() - parseLocalDate(a.validFrom).getTime());

    for (const record of sortedSeries) {
      const fromTime = parseLocalDate(record.validFrom).getTime();
      const toTime = record.validTo ? parseLocalDate(record.validTo).getTime() : Infinity;

      if (targetTime >= fromTime && targetTime <= toTime) {
        return record.value;
      }
    }

    throw new Error(`Integrity Violation: No effective temporal value found for date ${targetDateStr}. System refuses to guess rates.`);
  }

  static evaluateHistoricalConversion(amountCents: number, exchangeRatesTimeline: TemporalValidity[], transactionDate: string): number {
    const exchangeRate = this.resolveEffectiveValue(exchangeRatesTimeline, transactionDate);
    if (exchangeRate <= 0) throw new Error('Integrity Violation: Exchange rate must be strictly positive.');
    return new Decimal(amountCents).mul(exchangeRate).round().toNumber();
  }

  static evaluateHistoricalTaxLiability(amountCents: number, taxRatesTimeline: TemporalValidity[], transactionDate: string): number {
    const taxRate = this.resolveEffectiveValue(taxRatesTimeline, transactionDate);
    if (taxRate < 0) throw new Error('Integrity Violation: Tax rate cannot be negative.');
    return new Decimal(amountCents).mul(taxRate).round().toNumber();
  }

  static deriveSignedTotal(lines: any[], accounts?: any[]): number {
    if (!lines || lines.length === 0) return 0;

    if (accounts && accounts.length > 0) {
      const assetLines = lines.filter(l => {
        const acc = accounts.find(a => a.id === l.accountId);
        return acc && acc.type === 'asset';
      });
      if (assetLines.length > 0) {
        return assetLines.reduce((sum, l) => sum + (l.amountCents || 0), 0);
      }

      const liabilityLines = lines.filter(l => {
        const acc = accounts.find(a => a.id === l.accountId);
        return acc && acc.type === 'liability';
      });
      if (liabilityLines.length > 0) {
        // Liability increasing (credit/negative) means inflow of cash
        return -liabilityLines.reduce((sum, l) => sum + (l.amountCents || 0), 0);
      }
    }

    // Fallback when accounts context is absent: sum of debit legs
    const debitSum = lines
      .filter(l => (l.amountCents || 0) > 0)
      .reduce((sum, l) => sum + (l.amountCents || 0), 0);
    return debitSum || Math.abs(lines[0]?.amountCents || 0);
  }

  static parseAmountToCents(amountString: string | number | null | undefined): number {
    if (amountString === null || amountString === undefined) {
      throw new Error('Integrity Violation: Amount cannot be empty');
    }
    let s = String(amountString).trim();
    if (!s) throw new Error('Integrity Violation: Amount cannot be empty');

    // Handle unicode minus, currency symbols, commas, and whitespace
    s = s.replace(/\u2212/g, '-').replace(/[$€£¥]/g, '').replace(/,/g, '').trim();

    // Handle parenthesized negatives: (123.45) -> -123.45
    if (s.startsWith('(') && s.endsWith(')')) {
      s = '-' + s.slice(1, -1).trim();
    }

    // Handle trailing CR (credit / negative) / DR (debit / positive)
    let isCR = false;
    let isDR = false;
    if (/[\s]?(CR|cr)$/i.test(s)) {
      isCR = true;
      s = s.replace(/[\s]?(CR|cr)$/i, '').trim();
    } else if (/[\s]?(DR|dr)$/i.test(s)) {
      isDR = true;
      s = s.replace(/[\s]?(DR|dr)$/i, '').trim();
    }

    try {
      let val = new Decimal(s).mul(100).round().toNumber();
      if (isNaN(val)) throw new Error('Integrity Violation: Parsed amount is NaN');
      if (isCR) val = -Math.abs(val);
      if (isDR) val = Math.abs(val);
      return val;
    } catch (e) {
      throw new Error(`Integrity Violation: Invalid amount format: ${amountString}`, { cause: e });
    }
  }

  static parseAmountToCentsOrZero(amountString: string | number | null | undefined): number {
    if (amountString === null || amountString === undefined) return 0;
    const s = String(amountString).trim();
    if (!s) return 0;
    try {
      return TruthEngine.parseAmountToCents(s);
    } catch {
      return 0;
    }
  }

  static validateAccountingIntegrity(entries: Array<{ amount: number, type: 'debit' | 'credit' }>): boolean {
    let balance = new Decimal(0);
    for (const entry of entries) {
      if (typeof entry.amount !== 'number' || isNaN(entry.amount)) {
        throw new Error('Integrity Violation: Financial amounts must be precise numbers.');
      }
      const val = new Decimal(Math.abs(entry.amount));
      balance = entry.type === 'debit' ? balance.plus(val) : balance.minus(val);
    }

    return balance.abs().lessThan(0.01);
  }

  static assertImmutabilityId(recordId: string | null | undefined): void {
    if (!recordId) {
       throw new Error('Integrity Violation: All integrity records must carry a cryptographic or system identifier.');
    }
  }

  static sanitizeFact(input: string): string {
    return input.trim();
  }

  static calculateStraightLineDepreciation(costCents: number, salvageValueCents: number, usefulLifePeriods: number): number {
    if (usefulLifePeriods <= 0) throw new Error('Integrity Violation: Useful life must be strictly positive.');
    if (salvageValueCents > costCents) throw new Error('Integrity Violation: Salvage value cannot exceed initial cost.');
    return new Decimal(costCents).minus(salvageValueCents).div(usefulLifePeriods).round().toNumber();
  }

  static calculateDecliningBalanceDepreciation(bookValueCents: number, depreciationRate: number): number {
    if (depreciationRate <= 0 || depreciationRate > 1) throw new Error('Integrity Violation: Rate must be between 0 and 1.');
    return new Decimal(bookValueCents).mul(depreciationRate).round().toNumber();
  }

  static calculateLoanAmortizationPayment(principalCents: number, annualInterestRate: number, totalPeriods: number, paymentsPerYear: number = 12): number {
    if (totalPeriods <= 0) throw new Error('Integrity Violation: Periods must be strictly positive.');
    if (paymentsPerYear <= 0) throw new Error('Integrity Violation: Payments per year must be strictly positive.');
    if (annualInterestRate === 0) return new Decimal(principalCents).div(totalPeriods).round().toNumber();

    const ratePerPeriod = new Decimal(annualInterestRate).div(paymentsPerYear);
    const p = new Decimal(principalCents);
    const onePlusRToN = ratePerPeriod.plus(1).pow(totalPeriods);

    const pmt = p.mul(ratePerPeriod).mul(onePlusRToN).div(onePlusRToN.minus(1));
    return pmt.round().toNumber();
  }

  static calculateWACInventoryCost(currentQuantity: number, currentTotalValueCents: number, incomingQuantity: number, incomingValueCents: number): number {
    const totalQuantity = new Decimal(currentQuantity).plus(incomingQuantity);
    if (totalQuantity.lessThanOrEqualTo(0)) return 0;
    const totalValueCents = new Decimal(currentTotalValueCents).plus(incomingValueCents);
    return totalValueCents.div(totalQuantity).round().toNumber();
  }

  static analyzeBudgetVariance(actualCents: number, budgetedCents: number, isRevenue: boolean = false): { varianceCents: number, variancePercentage: number, isFavorable: boolean } {
    const a = new Decimal(actualCents);
    const b = new Decimal(budgetedCents);
    const varianceCents = isRevenue ? a.minus(b) : b.minus(a);
    const variancePercentage = b.greaterThan(0) ? varianceCents.abs().div(b).mul(100).toNumber() : 0;
    return {
      varianceCents: varianceCents.toNumber(),
      variancePercentage,
      isFavorable: varianceCents.greaterThanOrEqualTo(0)
    };
  }

  static calculateDoubleDecliningBalanceDepreciation(bookValueCents: number, usefulLifePeriods: number, multiplier: number = 2): number {
    if (usefulLifePeriods <= 0) throw new Error('Integrity Violation: Useful life must be strictly positive.');
    const depreciationRate = new Decimal(multiplier).div(usefulLifePeriods);
    return new Decimal(bookValueCents).mul(depreciationRate).round().toNumber();
  }

  static calculateSumOfTheYearsDigitsDepreciation(costCents: number, salvageValueCents: number, usefulLifePeriods: number, currentPeriod: number): number {
    if (usefulLifePeriods <= 0) throw new Error('Integrity Violation: Useful life must be strictly positive.');
    if (currentPeriod <= 0 || currentPeriod > usefulLifePeriods) throw new Error('Integrity Violation: Current period is out of bounds.');

    const n = new Decimal(usefulLifePeriods);
    const sumOfDigits = n.mul(n.plus(1)).div(2);
    const remainingLife = n.minus(currentPeriod).plus(1);
    const depreciationBase = new Decimal(costCents).minus(salvageValueCents);

    return depreciationBase.mul(remainingLife.div(sumOfDigits)).round().toNumber();
  }

  static calculateEconomicOrderQuantity(annualDemand: number, costPerOrderCents: number, holdingCostPerUnitCents: number): number {
    if (holdingCostPerUnitCents <= 0) throw new Error('Integrity Violation: Holding cost must be positive.');
    const d = new Decimal(annualDemand);
    const s = new Decimal(costPerOrderCents);
    const h = new Decimal(holdingCostPerUnitCents);
    return d.mul(s).mul(2).div(h).sqrt().round().toNumber();
  }

  static calculateROI(netProfitCents: number, investmentCostCents: number): number {
    if (investmentCostCents === 0) return 0;
    return new Decimal(netProfitCents).div(investmentCostCents).mul(100).toNumber();
  }

  static calculateWACC(
    equityValueCents: number,
    debtValueCents: number,
    costOfEquity: number,
    costOfDebt: number,
    corporateTaxRate: number
  ): number {
    const e = new Decimal(equityValueCents);
    const d = new Decimal(debtValueCents);
    const totalCapital = e.plus(d);
    if (totalCapital.lessThanOrEqualTo(0)) return 0;

    // Normalize percentage inputs (> 1 assumed to be e.g. 21% or 10%)
    const normKe = costOfEquity > 1 ? new Decimal(costOfEquity).div(100) : new Decimal(costOfEquity);
    const normKd = costOfDebt > 1 ? new Decimal(costOfDebt).div(100) : new Decimal(costOfDebt);
    const normTax = corporateTaxRate > 1 ? new Decimal(corporateTaxRate).div(100) : new Decimal(corporateTaxRate);

    const equityWeight = e.div(totalCapital);
    const debtWeight = d.div(totalCapital);

    const equityComponent = equityWeight.mul(normKe);
    const debtComponent = debtWeight.mul(normKd).mul(new Decimal(1).minus(normTax));

    return equityComponent.plus(debtComponent).toNumber();
  }

  static calculateCAGR(beginningValueCents: number, endingValueCents: number, numYears: number): number {
    if (beginningValueCents <= 0 || endingValueCents <= 0 || numYears <= 0) return 0;
    const b = new Decimal(beginningValueCents);
    const e = new Decimal(endingValueCents);
    return e.div(b).pow(new Decimal(1).div(numYears)).minus(1).toNumber();
  }

  static calculateMACRSDepreciation(costCents: number, yearIdx: number, assetClassYears: number): number {
      const tables: Record<number, number[]> = {
          3: [0.3333, 0.4445, 0.1481, 0.0741],
          5: [0.2000, 0.3200, 0.1920, 0.1152, 0.1152, 0.0576],
          7: [0.1429, 0.2449, 0.1749, 0.1249, 0.0893, 0.0892, 0.0893, 0.0446]
      };
      const table = tables[assetClassYears] || [];
      const rate = table[yearIdx] || 0;
      return new Decimal(costCents).mul(rate).round().toNumber();
  }

  static calculateNPV(discountRate: number, initialInvestmentCents: number, cashFlowsCents: number[]): number {
    let npv = new Decimal(initialInvestmentCents).neg();
    const r = new Decimal(1).plus(discountRate);
    for (let t = 0; t < cashFlowsCents.length; t++) {
      npv = npv.plus(new Decimal(cashFlowsCents[t]).div(r.pow(t + 1)));
    }
    return npv.round().toNumber();
  }

  static calculateGrossProfitMargin(revenueCents: number, cogsCents: number): number {
    if (revenueCents === 0) return 0;
    const r = new Decimal(revenueCents);
    return r.minus(cogsCents).div(r).mul(100).toNumber();
  }

  static calculateBreakEvenUnits(fixedCostsCents: number, variableCostPerUnitCents: number, pricePerUnitCents: number): number {
    const contributionMargin = new Decimal(pricePerUnitCents).minus(variableCostPerUnitCents);
    if (contributionMargin.lessThanOrEqualTo(0)) throw new Error('Integrity Violation: Contribution margin must be positive to break even.');
    return new Decimal(fixedCostsCents).div(contributionMargin).ceil().toNumber();
  }

  static calculateCurrentRatio(currentAssetsCents: number, currentLiabilitiesCents: number): number {
    if (currentLiabilitiesCents === 0) return 0;
    return new Decimal(currentAssetsCents).div(currentLiabilitiesCents).toNumber();
  }

  static calculateQuickRatio(currentAssetsCents: number, inventoryCents: number, currentLiabilitiesCents: number): number {
    if (currentLiabilitiesCents === 0) return 0;
    return new Decimal(currentAssetsCents).minus(inventoryCents).div(currentLiabilitiesCents).toNumber();
  }

  static calculateDebtToEquityRatio(totalLiabilitiesCents: number, totalEquityCents: number): number {
    if (totalEquityCents === 0) return 0;
    return new Decimal(totalLiabilitiesCents).div(totalEquityCents).toNumber();
  }

  // Fallback for typed arrays
  static generateVectorizedDCF(
    forecastsLen: number,
    baseFCFsCents: Float64Array,
    waccOptions: Float64Array, 
    growthOptions: Float64Array
  ): Float64Array {
    const totalScenarios = waccOptions.length * growthOptions.length;
    const results = new Float64Array(totalScenarios);

    let scenarioIdx = 0;

    for (let w = 0; w < waccOptions.length; w++) {
       const waccNum = waccOptions[w];
       const wacc = new Decimal(waccNum);
       for (let g = 0; g < growthOptions.length; g++) {
          const growthNum = growthOptions[g];
          const growth = new Decimal(growthNum);

          if (wacc.lessThanOrEqualTo(growth)) {
             results[scenarioIdx++] = 0; 
             continue;
          }

          let npv = new Decimal(0);
          for (let t = 0; t < forecastsLen; t++) {
             npv = npv.plus(new Decimal(baseFCFsCents[t]).div(wacc.plus(1).pow(t + 1)));
          }

          const finalFCF = new Decimal(baseFCFsCents[forecastsLen - 1]);
          const terminalValue = finalFCF.mul(growth.plus(1)).div(wacc.minus(growth));
          npv = npv.plus(terminalValue.div(wacc.plus(1).pow(forecastsLen)));

          results[scenarioIdx++] = npv.round().toNumber();
       }
    }

    return results;
  }

  static evaluateAltmanZScore(
    workingCapital: number, retainedEarnings: number,
    ebit: number, mktValueEquity: number, totalLiabilities: number,
    totalAssets: number, sales: number
  ): number {
    if (totalAssets === 0 || totalLiabilities === 0) return 0;
    const X1 = new Decimal(workingCapital).div(totalAssets);
    const X2 = new Decimal(retainedEarnings).div(totalAssets);
    const X3 = new Decimal(ebit).div(totalAssets);
    const X4 = new Decimal(mktValueEquity).div(totalLiabilities);
    const X5 = new Decimal(sales).div(totalAssets);

    return X1.mul(1.2).plus(X2.mul(1.4)).plus(X3.mul(3.3)).plus(X4.mul(0.6)).plus(X5.mul(0.999)).toNumber();
  }

  static calculateFCFF(ebit: number, taxRate: number, depreciation: number, capitalExpenditure: number, changeInNWC: number): number {
    return new Decimal(ebit).mul(new Decimal(1).minus(taxRate))
            .plus(depreciation).minus(capitalExpenditure).minus(changeInNWC).toNumber();
  }

  static calculateFCFE(netIncome: number, depreciation: number, capitalExpenditure: number, changeInNWC: number, netBorrowing: number): number {
    return new Decimal(netIncome).plus(depreciation).minus(capitalExpenditure).minus(changeInNWC).plus(netBorrowing).toNumber();
  }

  static calculateDCFValuation(
    forecastedFCFF: number[],
    wacc: number,
    terminalGrowthRate: number
  ): number {
    if (wacc <= terminalGrowthRate) throw new Error("Integrity Violation: WACC must be strictly greater than Terminal Growth Rate to avoid infinite valuation.");
    let impliedValue = new Decimal(0);
    const w = new Decimal(wacc);
    const tgr = new Decimal(terminalGrowthRate);

    for (let t = 0; t < forecastedFCFF.length; t++) {
      impliedValue = impliedValue.plus(new Decimal(forecastedFCFF[t]).div(w.plus(1).pow(t + 1)));
    }
    const finalYearFCFF = new Decimal(forecastedFCFF[forecastedFCFF.length - 1]);
    const terminalValue = finalYearFCFF.mul(tgr.plus(1)).div(w.minus(tgr));
    impliedValue = impliedValue.plus(terminalValue.div(w.plus(1).pow(forecastedFCFF.length)));
    return impliedValue.round().toNumber();
  }

  static calculateRuleOf40(growthRatePct: number, ebitdaMarginPct: number): number {
    return new Decimal(growthRatePct).plus(ebitdaMarginPct).toNumber();
  }

  static calculateCAC(totalMarketingAndSalesCostCents: number, newCustomersAcquired: number): number {
    if (newCustomersAcquired <= 0) return Infinity; // infinite CAC if no customers acquired
    return new Decimal(totalMarketingAndSalesCostCents).div(newCustomersAcquired).round().toNumber();
  }

  static calculateLTV(arpuCents: number, grossMarginPct: number, churnRatePct: number): number {
    if (churnRatePct <= 0 || churnRatePct > 100) return Infinity;
    const a = new Decimal(arpuCents);
    const g = new Decimal(grossMarginPct).div(100);
    const c = new Decimal(churnRatePct).div(100);
    return a.mul(g).div(c).round().toNumber();
  }

  static calculateLTVtoCAC(ltvCents: number, cacCents: number): number {
    if (cacCents === 0) return 0;
    return new Decimal(ltvCents).div(cacCents).toNumber();
  }

  static calculateMagicNumber(currentQtrARR: number, priorQtrARR: number, priorQtrSMCost: number): number {
    if (priorQtrSMCost === 0) return 0;
    return new Decimal(currentQtrARR).minus(priorQtrARR).div(priorQtrSMCost).toNumber();
  }

  static calculateDSO(accountsReceivableCents: number, totalCreditSalesCents: number, daysInPeriod: number): number {
    if (totalCreditSalesCents === 0) return 0;
    return new Decimal(accountsReceivableCents).div(totalCreditSalesCents).mul(daysInPeriod).toNumber();
  }

  static calculateDuPontROE(netIncome: number, sales: number, assets: number, equity: number): { roe: number, profitMargin: number, assetTurnover: number, equityMultiplier: number } {
    if (sales === 0 || assets === 0 || equity === 0) return { roe: 0, profitMargin: 0, assetTurnover: 0, equityMultiplier: 0 };

    const profitMargin = new Decimal(netIncome).div(sales);
    const assetTurnover = new Decimal(sales).div(assets);
    const equityMultiplier = new Decimal(assets).div(equity);

    return {
      profitMargin: profitMargin.toNumber(),
      assetTurnover: assetTurnover.toNumber(),
      equityMultiplier: equityMultiplier.toNumber(),
      roe: profitMargin.mul(assetTurnover).mul(equityMultiplier).toNumber()
    };
  }

  static calculateSharpeRatio(portfolioReturnPct: number, riskFreeRatePct: number, standardDeviationPct: number): number {
    if (standardDeviationPct === 0) return 0;
    return new Decimal(portfolioReturnPct).minus(riskFreeRatePct).div(standardDeviationPct).toNumber();
  }

  static calculateCAPM(riskFreeRatePct: number, beta: number, expectedMarketReturnPct: number): number {
    return new Decimal(riskFreeRatePct).plus(new Decimal(beta).mul(new Decimal(expectedMarketReturnPct).minus(riskFreeRatePct))).toNumber();
  }

  static calculateEVA(nopat: number, totalCapital: number, wacc: number): number {
    return new Decimal(nopat).minus(new Decimal(totalCapital).mul(wacc)).round().toNumber();
  }

  static evaluatePiotroskiFScore(
    roaS: boolean, cfoS: boolean, roaDeltaS: boolean, qualityOfEarningsS: boolean,
    leverageDeltaS: boolean, liquidityDeltaS: boolean, equityIssueS: boolean,
    marginDeltaS: boolean, turnoverDeltaS: boolean
  ): number {
    let score = 0;
    if (roaS) score++;
    if (cfoS) score++;
    if (roaDeltaS) score++;
    if (qualityOfEarningsS) score++;
    if (leverageDeltaS) score++;
    if (liquidityDeltaS) score++;
    if (equityIssueS) score++;
    if (marginDeltaS) score++;
    if (turnoverDeltaS) score++;
    return score;
  }
}

import admin from 'firebase-admin';
import { getFirestore, Firestore } from 'firebase-admin/firestore';
import path from 'path';
import fs from 'fs';

let firebaseConfig: Record<string, any> = {};
try {
  const configPath = path.resolve(process.cwd(), 'firebase-applet-config.json');
  if (fs.existsSync(configPath)) {
    firebaseConfig = JSON.parse(fs.readFileSync(configPath, 'utf8'));
  }
} catch (error) {
  console.warn('[Firebase Admin] Warning: Could not read firebase-applet-config.json:', error);
}

const activeFirebaseProjectId = process.env.FIREBASE_PROJECT_ID || firebaseConfig.projectId;

if (admin.apps.length === 0 && activeFirebaseProjectId) {
  admin.initializeApp({
    projectId: activeFirebaseProjectId,
  });
}

export const getDb = (): Firestore => {
  const dbId = process.env.FIRESTORE_DATABASE_ID || firebaseConfig.firestoreDatabaseId || '(default)';
  if (dbId && dbId !== '(default)') {
    return getFirestore(admin.app(), dbId);
  }
  return getFirestore(admin.app());
};

export async function validateWorkspaceMember(db: Firestore, workspaceId: string, user: { uid: string; admin?: boolean; developerWorkspaceId?: string }) {
  if (!workspaceId) throw new Error('Workspace ID is required.');
  if (user.developerWorkspaceId && user.developerWorkspaceId !== workspaceId) {
    throw new Error(`Unauthorized: API key is scoped strictly to workspace ${user.developerWorkspaceId}`);
  }
  const wsDoc = await db.collection('workspaces').doc(workspaceId).get();
  if (!wsDoc.exists) throw new Error('Workspace not found.');
  const data = wsDoc.data() || {};
  const isMember = data.uid === user.uid || (Array.isArray(data.members) && data.members.includes(user.uid)) || (data.admins && data.admins[user.uid]) || user.admin;
  if (!isMember) {
    throw new Error('Unauthorized: You are not a member of this workspace.');
  }
  return { wsDoc, data };
}

export const assertWorkspaceAccess = validateWorkspaceMember;

export async function assertPeriodOpen(db: Firestore, workspaceId: string, date: string) {
  if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    throw new Error(`Invalid transaction date format: ${date}. Expected YYYY-MM-DD.`);
  }
  const wsDoc = await db.collection('workspaces').doc(workspaceId).get();
  const lockDate = wsDoc.data()?.lockDate;
  if (lockDate && date <= lockDate) {
    throw new Error(`Period Locked: Posting forbidden for transaction date ${date} on or prior to lock date ${lockDate}.`);
  }
}

export async function validateWorkspaceAccounts(db: Firestore, workspaceId: string, accountIds: string[]): Promise<Map<string, { id: string; name: string; type: string; category?: string }>> {
  const accountMap = new Map<string, { id: string; name: string; type: string; category?: string }>();
  const validIds = Array.from(new Set(accountIds.filter(Boolean)));
  if (validIds.length === 0) return accountMap;

  const refs = validIds.map(id => db.collection('chartAccounts').doc(id));
  const docs = await db.getAll(...refs);

  for (const accDoc of docs) {
    if (!accDoc.exists) {
      throw new Error(`Account ${accDoc.id} not found in chart of accounts.`);
    }
    const accData = accDoc.data() || {};
    if (accData.workspaceId !== workspaceId) {
      throw new Error(`Security Violation: Account ${accDoc.id} (${accData.name || 'unnamed'}) belongs to another workspace (${accData.workspaceId}). Cross-workspace ledger references are forbidden.`);
    }
    accountMap.set(accDoc.id, {
      id: accDoc.id,
      name: accData.name || 'Account',
      type: accData.type || 'asset',
      category: accData.category
    });
  }
  return accountMap;
}

import express from 'express';
import { getAuth } from 'firebase-admin/auth';

export const authenticate = async (req: express.Request, res: express.Response, next: express.NextFunction) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized: Missing or invalid Authorization header' });
  }

  const idToken = authHeader.split('Bearer ')[1];
  try {
    const decodedToken = await getAuth().verifyIdToken(idToken);
    (req as any).user = decodedToken;
    next();
  } catch (error) {
    console.error('Error verifying auth token', error);
    return res.status(401).json({ error: 'Unauthorized: Invalid token' });
  }
};

export const apiAuthenticate = authenticate;

import express from 'express';
import { FieldValue } from 'firebase-admin/firestore';
import Decimal from 'decimal.js';
import { DoubleEntryValidator } from '../../kernel/validation/DoubleEntryValidator';
import { TransactionValidator } from '../../kernel/validation/TransactionValidator';
import { getDb, validateWorkspaceMember, assertPeriodOpen, validateWorkspaceAccounts } from '../db/firestore';

export const inventoryRouter = express.Router();

/**
 * Recognizes COGS for a sale. Reduces quantity on hand.
 */
inventoryRouter.post('/cogs', async (req, res) => {
  try {
    const { workspaceId, itemId, quantitySold, inventoryAccountId, cogsAccountId, date } = req.body;
    const user = (req as any).user;
    const db = getDb();

    if (!workspaceId || !itemId || !quantitySold || !inventoryAccountId || !cogsAccountId) {
      return res.status(400).json({ error: "Missing required fields (workspaceId, itemId, quantitySold, inventoryAccountId, cogsAccountId)." });
    }

    if (!Number.isInteger(quantitySold) || quantitySold <= 0) {
      return res.status(400).json({ error: "quantitySold must be a positive integer." });
    }

    // 1. Validate workspace membership FIRST (#82)
    const { data: wsData } = await validateWorkspaceMember(db, workspaceId, user);

    const idempotencyKey = req.headers['idempotency-key'] as string;
    if (idempotencyKey) {
      const idempDoc = await db.collection('idempotencyKeys').doc(`${workspaceId}_inv_${idempotencyKey}`).get();
      if (idempDoc.exists) {
        return res.json(idempDoc.data()?.response);
      }
    }

    const txDate = date && /^\d{4}-\d{2}-\d{2}$/.test(date) ? date : new Date().toLocaleDateString('en-CA');

    // 2. Validate period lock
    await assertPeriodOpen(db, workspaceId, txDate);

    // 3. Validate accounts exist and belong to workspace
    const accountMap = await validateWorkspaceAccounts(db, workspaceId, [inventoryAccountId, cogsAccountId]);
    const inventoryAcc = accountMap.get(inventoryAccountId)!;
    const cogsAcc = accountMap.get(cogsAccountId)!;

    // 4. Fetch the real inventory item from Firestore
    const itemDoc = await db.collection('inventory').doc(itemId).get();
    if (!itemDoc.exists) {
      return res.status(404).json({ error: `Inventory item ${itemId} not found.` });
    }
    const itemData = itemDoc.data() || {};

    // Fail-closed ownership check
    if (!itemData.workspaceId || itemData.workspaceId !== workspaceId) {
      return res.status(403).json({ error: 'Security Violation: Item not found in workspace.' });
    }

    if (typeof itemData.unitCostCents !== 'number' || itemData.unitCostCents <= 0) {
      return res.status(400).json({ error: `Inventory item ${itemId} has no valid unitCostCents configured.` });
    }

    // #76 - Use Decimal for COGS precision
    const unitCostDec = new Decimal(itemData.unitCostCents);
    const totalCogsDec = unitCostDec.mul(quantitySold);
    const totalCogsCents = totalCogsDec.round().toNumber();

    const itemName = itemData.name || itemData.sku || itemId;

    const tx = {
      id: db.collection("transactions").doc().id,
      workspaceId,
      uid: user.uid,
      date: txDate,
      description: `Inventory COGS Recognition: ${itemName} (Qty: ${quantitySold})`,
      totalAmountCents: totalCogsCents,
      currency: 'USD',
      type: 'journal' as const,
      status: 'approved' as const,
      isCleared: true,
      createdAt: new Date().toISOString(),
      lines: [
        {
          id: `line-1`,
          accountId: cogsAccountId,
          accountName: cogsAcc.name,
          amountCents: totalCogsCents, // Debit Expense
          description: `Recognize COGS for ${quantitySold} units of ${itemName}`
        },
        {
          id: `line-2`,
          accountId: inventoryAccountId,
          accountName: inventoryAcc.name,
          amountCents: -totalCogsCents, // Credit Asset
          description: `Reduce inventory asset for ${quantitySold} units of ${itemName}`
        }
      ]
    };

    // Validate through canonical transaction validator (#102-R)
    const validatedTx = await TransactionValidator.validateAndPrepare(tx, {
      workspaceId,
      user: { uid: user.uid, admin: user.admin },
      wsData
    });

    const responsePayload = {
      status: 'ok',
      message: 'Inventory COGS recorded successfully.',
      transactionId: validatedTx.id,
      unitCostCents: itemData.unitCostCents,
      totalCogsCents
    };

    let resultResponse = responsePayload;

    await db.runTransaction(async (t: any) => {
      // Re-fetch item inside transaction for race-condition safety
      const itemSnap = await t.get(db.collection('inventory').doc(itemId));
      const currentItemData = itemSnap.data();
      const currentQty = typeof currentItemData?.quantityOnHand === 'number' ? currentItemData.quantityOnHand : 0;

      if (quantitySold > currentQty) {
        throw new Error(`Insufficient inventory stock. Requested ${quantitySold}, available ${currentQty}.`);
      }

      if (idempotencyKey) {
        const idempRef = db.collection('idempotencyKeys').doc(`${workspaceId}_inv_${idempotencyKey}`);
        const idempSnap = await t.get(idempRef);
        if (idempSnap.exists) {
          resultResponse = idempSnap.data()?.response || responsePayload;
          return;
        }
      }

      const txRef = db.collection('transactions').doc(validatedTx.id);
      t.set(txRef, { ...validatedTx, createdAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp() });

      // Reduce on-hand inventory quantity
      const itemRef = db.collection('inventory').doc(itemId);
      t.update(itemRef, {
        quantityOnHand: FieldValue.increment(-quantitySold),
        updatedAt: FieldValue.serverTimestamp()
      });

      if (idempotencyKey) {
        const idempRef = db.collection('idempotencyKeys').doc(`${workspaceId}_inv_${idempotencyKey}`);
        t.set(idempRef, {
          response: responsePayload,
          timestamp: new Date().toISOString(),
          workspaceId
        });
      }
    });

    res.json(resultResponse);
  } catch (e: any) {
    res.status(e.message?.includes('Unauthorized') ? 403 : 400).json({ error: e.message });
  }
});

/**
 * Purchases or Adjusts inventory. 
 * Implements Weighted Average Cost (WAC) logic if purchasing.
 */
inventoryRouter.post('/adjust', async (req, res) => {
  try {
    const { workspaceId, itemId, quantityChange, unitCostCents, inventoryAccountId, offsetAccountId, type, date } = req.body;
    const user = (req as any).user;
    const db = getDb();

    if (!workspaceId || !itemId || quantityChange === undefined || !inventoryAccountId || !offsetAccountId) {
      return res.status(400).json({ error: "Missing required fields." });
    }

    const { data: wsData } = await validateWorkspaceMember(db, workspaceId, user);
    const txDate = date && /^\d{4}-\d{2}-\d{2}$/.test(date) ? date : new Date().toLocaleDateString('en-CA');
    await assertPeriodOpen(db, workspaceId, txDate);

    // 1. Validate accounts exist and belong to workspace
    const accountMap = await validateWorkspaceAccounts(db, workspaceId, [inventoryAccountId, offsetAccountId]);
    const inventoryAcc = accountMap.get(inventoryAccountId)!;
    const offsetAcc = accountMap.get(offsetAccountId)!;

    await db.runTransaction(async (t: any) => {
      const itemRef = db.collection('inventory').doc(itemId);
      const itemSnap = await t.get(itemRef);
      if (!itemSnap.exists) throw new Error('Item not found');

      const itemData = itemSnap.data()!;
      // Fail-closed ownership check
      if (!itemData.workspaceId || itemData.workspaceId !== workspaceId) {
        throw new Error('Security Violation: Item not found in workspace.');
      }

      const oldQty = new Decimal(itemData.quantityOnHand || 0);
      const newQty = oldQty.plus(quantityChange);

      // Negative inventory check for adjustments
      if (newQty.lt(0)) {
        throw new Error(`Adjustment would result in negative inventory. Current: ${oldQty.toNumber()}, Change: ${quantityChange}.`);
      }

      const oldWAC = new Decimal(itemData.unitCostCents || 0);
      const deltaQty = new Decimal(quantityChange);
      const newPurchasePrice = new Decimal(unitCostCents || itemData.unitCostCents || 0);

      let newWAC = oldWAC;
      if (type === 'purchase' && deltaQty.gt(0)) {
        const totalOldValue = oldQty.mul(oldWAC);
        const totalNewValue = deltaQty.mul(newPurchasePrice);
        newWAC = totalOldValue.plus(totalNewValue).div(oldQty.plus(deltaQty));
      }

      const totalAdjustmentValue = deltaQty.mul(newPurchasePrice).round().toNumber();

      const tx = {
        id: db.collection("transactions").doc().id,
        workspaceId,
        uid: user.uid,
        date: txDate,
        description: `Inventory ${type || 'Adjustment'}: ${itemData.name || itemId} (Qty Δ: ${quantityChange})`,
        totalAmountCents: Math.abs(totalAdjustmentValue),
        currency: 'USD',
        type: 'journal' as const,
        status: 'approved' as const,
        isCleared: true,
        createdAt: new Date().toISOString(),
        lines: [
          {
            id: `line-1`,
            accountId: inventoryAccountId,
            accountName: inventoryAcc.name,
            amountCents: totalAdjustmentValue,
            description: `${type === 'purchase' ? 'Purchase' : 'Adjustment'} of ${quantityChange} units`
          },
          {
            id: `line-2`,
            accountId: offsetAccountId,
            accountName: offsetAcc.name,
            amountCents: -totalAdjustmentValue,
            description: `Offset for inventory ${type || 'adjustment'}`
          }
        ]
      };

      const validatedTx = await TransactionValidator.validateAndPrepare(tx, {
        workspaceId,
        user: { uid: user.uid, admin: user.admin },
        wsData
      }, undefined, t);

      t.set(db.collection('transactions').doc(validatedTx.id), { ...validatedTx, createdAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp() });

      t.update(itemRef, {
        quantityOnHand: newQty.toNumber(),
        unitCostCents: newWAC.round().toNumber(),
        updatedAt: FieldValue.serverTimestamp()
      });

      return { newWAC: newWAC.toNumber(), newQuantity: newQty.toNumber() };
    }).then(result => {
        res.json({ status: 'ok', ...result });
    });
  } catch (e: any) {
    res.status(400).json({ error: e.message });
  }
});

import express from 'express';
import crypto from 'crypto';
import { getDb } from '../db/firestore';
import { getTrustedAppUrl } from '../utils/urlHelper';
import { deliverInvoiceEmail } from '../services/emailService';

export const invoiceEmailRouter = express.Router();

invoiceEmailRouter.post('/:invoiceId/send', async (req, res) => {
  try {
    const { workspaceId, toEmail, subject, body } = req.body;
    const invoiceId = req.params.invoiceId;
    const user = (req as any).user;

    if (!workspaceId || !toEmail || typeof toEmail !== 'string') {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(toEmail.trim())) {
      return res.status(400).json({ error: 'Invalid recipient email format' });
    }

    if (subject && (typeof subject !== 'string' || subject.length > 200)) {
      return res.status(400).json({ error: 'Subject must be under 200 characters' });
    }
    if (body && (typeof body !== 'string' || body.length > 5000)) {
      return res.status(400).json({ error: 'Body must be under 5000 characters' });
    }

    const db = getDb();

    // Verify user is a member of the workspace
    const wsDoc = await db.collection('workspaces').doc(workspaceId).get();
    const wsData = wsDoc.data();
    if (!wsDoc.exists || (wsData?.uid !== user.uid && !wsData?.members?.includes(user.uid) && wsData?.admins?.[user.uid] !== true && !user.admin)) {
      return res.status(403).json({ error: 'Forbidden: You are not a member of this workspace.' });
    }

    // Invoices are stored in the canonical top-level 'invoices' collection
    const invoiceRef = db.collection('invoices').doc(invoiceId);

    const doc = await invoiceRef.get();
    if (!doc.exists) {
      return res.status(404).json({ error: 'Invoice not found' });
    }

    const invoice = doc.data() as any || {};
    if (invoice.workspaceId !== workspaceId) {
      return res.status(403).json({ error: 'Forbidden: Invoice does not belong to this workspace.' });
    }

    // Generate a cryptographically secure payment token if it doesn't have one
    let paymentToken = invoice.paymentToken;
    if (!paymentToken) {
      paymentToken = `pay_${crypto.randomBytes(32).toString('hex')}`;
      await invoiceRef.update({
        paymentToken,
        metadata: {
          ...invoice.metadata,
          tokenCreatedAt: new Date().toISOString()
        }
      });
    }

    // Resolve trusted URL without host-header poisoning (#85)
    const baseUrl = getTrustedAppUrl(req);
    const invoiceUrl = `${baseUrl}/i/${paymentToken}`;

    // #84 - Honest email delivery: check if an actual email service provider is configured
    const hasEmailService = Boolean(process.env.RESEND_API_KEY || process.env.POSTMARK_SERVER_TOKEN || process.env.SENDGRID_API_KEY);

    if (!hasEmailService) {
      return res.status(503).json({
        success: false,
        delivered: false,
        error: 'EMAIL_SERVICE_NOT_CONFIGURED',
        message: 'No external email delivery service (RESEND_API_KEY, POSTMARK_SERVER_TOKEN, or SENDGRID_API_KEY) is configured on this server.',
        paymentToken,
        invoiceUrl
      });
    }

    // Format amount for display if cents available
    const totalAmount = typeof invoice.totalCents === 'number'
      ? `$${(invoice.totalCents / 100).toFixed(2)}`
      : (typeof invoice.amountCents === 'number' ? `$${(invoice.amountCents / 100).toFixed(2)}` : undefined);

    // Dispatch real email delivery
    let deliveryResult;
    try {
      deliveryResult = await deliverInvoiceEmail({
        toEmail,
        subject: subject || `Invoice ${invoice.invoiceNumber || invoice.number || invoiceId} from ${wsData?.name || 'LedgerFlow'}`,
        invoiceNumber: invoice.invoiceNumber || invoice.number || invoiceId,
        customerName: invoice.customerName || invoice.customer?.name,
        totalFormatted: totalAmount,
        invoiceUrl,
        customBody: body
      });
    } catch (deliveryError: any) {
      console.error('[InvoiceEmail] Provider delivery failure:', deliveryError);
      return res.status(502).json({
        success: false,
        delivered: false,
        error: 'EMAIL_DELIVERY_FAILED',
        message: deliveryError.message || 'External email service rejected the dispatch request.',
        paymentToken,
        invoiceUrl
      });
    }

    // Update invoice status to 'sent' ONLY upon verified delivery success
    await invoiceRef.update({
      status: invoice.status === 'draft' || invoice.status === 'pending' ? 'sent' : invoice.status,
      metadata: {
        ...invoice.metadata,
        lastSentAt: new Date().toISOString(),
        sentTo: toEmail,
        emailProvider: deliveryResult.provider,
        emailMessageId: deliveryResult.messageId
      }
    });

    res.json({
      success: true,
      delivered: true,
      provider: deliveryResult.provider,
      messageId: deliveryResult.messageId,
      paymentToken,
      invoiceUrl
    });
  } catch (err) {
    console.error('Error sending invoice email:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

import express from 'express';
import { FieldValue } from 'firebase-admin/firestore';
import { TransactionValidator } from '../../kernel/validation/TransactionValidator';
import { getDb, assertPeriodOpen } from '../db/firestore';
import { Transaction } from '../../types';

export const leaseRouter = express.Router();

leaseRouter.post('/capitalize', async (req, res) => {
  try {
    const { workspaceId, leaseName, pvAmountCents, rouAssetAccountId, leaseLiabilityAccountId, date } = req.body;
    const user = (req as any).user;
    const db = getDb();

    if (!workspaceId || !pvAmountCents || !rouAssetAccountId || !leaseLiabilityAccountId) {
      return res.status(400).json({ error: "Missing required fields for ASC 842 capitalization." });
    }

    if (!Number.isInteger(pvAmountCents) || pvAmountCents <= 0) {
      return res.status(400).json({ error: "pvAmountCents must be a positive integer." });
    }

    // 1. Authorize workspace membership FIRST before checking idempotency (#82)
    const wsDoc = await db.collection('workspaces').doc(workspaceId).get();
    const wsData = wsDoc.data();
    if (!wsDoc.exists || (wsData?.uid !== user.uid && !wsData?.members?.includes(user.uid) && !user.admin)) {
      return res.status(403).json({ error: 'Not a member' });
    }

    // 2. Check idempotency record AFTER authorization (#82)
    const idempotencyKey = (req.headers['idempotency-key'] as string) || (leaseName ? `lease_${leaseName.toLowerCase().replace(/[^a-z0-9]/g, '_')}` : undefined);
    if (idempotencyKey) {
      const idempDoc = await db.collection('idempotencyKeys').doc(`${workspaceId}_lease_${idempotencyKey}`).get();
      if (idempDoc.exists) {
        return res.json(idempDoc.data()?.response);
      }
    }

    const txDate = date && /^\d{4}-\d{2}-\d{2}$/.test(date) ? date : new Date().toLocaleDateString('en-CA');

    // 3. Validate period lock
    await assertPeriodOpen(db, workspaceId, txDate);

    const tx = {
      id: db.collection("transactions").doc().id,
      workspaceId,
      uid: user.uid,
      date: txDate,
      description: `ASC 842 Initial Recognition: ${leaseName || 'Operating Lease'}`,
      totalAmountCents: pvAmountCents,
      currency: 'USD',
      type: 'journal' as const,
      status: 'approved' as const,
      isCleared: true,
      createdAt: new Date().toISOString(),
      lines: [
        {
          id: 'line-1',
          accountId: rouAssetAccountId,
          amountCents: pvAmountCents, // Debit Asset
          description: 'Capitalize PV of lease payments'
        },
        {
          id: 'line-2',
          accountId: leaseLiabilityAccountId,
          amountCents: -pvAmountCents, // Credit Liability
          description: 'Recognize lease liability'
        }
      ]
    };

    // 4. Validate through canonical validator (#102-R)
    const validatedTx = await TransactionValidator.validateAndPrepare(tx, {
      workspaceId,
      user: { uid: user.uid, admin: user.admin },
      wsData
    });

    const responsePayload = {
      status: 'ok',
      message: 'ASC 842 Lease capitalized successfully.',
      transactionId: validatedTx.id
    };

    let resultResponse = responsePayload;

    await db.runTransaction(async (t: any) => {
      if (idempotencyKey) {
        const idempRef = db.collection('idempotencyKeys').doc(`${workspaceId}_lease_${idempotencyKey}`);
        const idempSnap = await t.get(idempRef);
        if (idempSnap.exists) {
          resultResponse = idempSnap.data()?.response || responsePayload;
          return;
        }
      }

      const txRef = db.collection('transactions').doc(validatedTx.id);
      t.set(txRef, { ...validatedTx, createdAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp() });

      if (idempotencyKey) {
        const idempRef = db.collection('idempotencyKeys').doc(`${workspaceId}_lease_${idempotencyKey}`);
        t.set(idempRef, {
          response: responsePayload,
          timestamp: new Date().toISOString(),
          workspaceId
        });
      }
    });

    res.json(resultResponse);
  } catch (e: any) {
    res.status(e.message?.includes('Unauthorized') || e.message?.includes('Forbidden') ? 403 : 400).json({ error: e.message });
  }
});

import express from 'express';
import { getDb } from '../db/firestore';
import { getTrustedAppUrl } from '../utils/urlHelper';
import Stripe from 'stripe';

let stripeClient: Stripe | null = null;
function getStripe(): Stripe {
  if (!stripeClient) {
    const key = process.env.STRIPE_SECRET_KEY as string;
    stripeClient = new Stripe(key, { apiVersion: "2024-12-18.acacia" as any });
  }
  return stripeClient;
}

export const publicInvoiceRouter = express.Router();

publicInvoiceRouter.get('/:token', async (req, res) => {
  try {
    const token = req.params.token;
    if (!token || typeof token !== 'string' || !/^pay_[a-zA-Z0-9_-]{10,128}$/.test(token)) {
      return res.status(400).json({ error: 'Invalid token format' });
    }
    const db = getDb();

    // Check top-level collection first, with collectionGroup fallback
    let snapshot = await db.collection('invoices').where('paymentToken', '==', token).limit(1).get();
    if (snapshot.empty) {
      snapshot = await db.collectionGroup('invoices').where('paymentToken', '==', token).limit(1).get();
    }

    if (snapshot.empty) {
      return res.status(404).json({ error: 'Invoice not found' });
    }

    const doc = snapshot.docs[0];
    const invoice = doc.data();

    const lineTotal = Array.isArray(invoice.lines) 
      ? invoice.lines.reduce((sum: number, l: any) => {
          const lineAmt = typeof l.amountCents === 'number' 
            ? l.amountCents 
            : Math.round((Number(l.quantity) || 1) * (Number(l.unitPriceCents) || 0));
          return sum + lineAmt;
        }, 0)
      : 0;

    const totalInvoiceAmount = typeof invoice.totalCents === 'number'
      ? invoice.totalCents
      : (typeof invoice.amountCents === 'number' ? invoice.amountCents : lineTotal);
    const amountPaid = typeof invoice.amountPaidCents === 'number' 
      ? invoice.amountPaidCents 
      : (typeof invoice.paidAmountCents === 'number' ? invoice.paidAmountCents : 0);
    const remainingBalance = Math.max(0, totalInvoiceAmount - amountPaid);

    res.json({
      invoice: {
        id: invoice.id || doc.id,
        number: invoice.number,
        date: invoice.date,
        dueDate: invoice.dueDate,
        status: invoice.status,
        amountCents: totalInvoiceAmount,
        totalCents: totalInvoiceAmount,
        amountPaidCents: amountPaid,
        remainingBalanceCents: remainingBalance,
        currency: invoice.currency || 'USD',
        customerName: invoice.customerName,
        paymentToken: invoice.paymentToken,
        lines: Array.isArray(invoice.lines) ? invoice.lines.map((l: any) => ({
          description: l.description,
          quantity: l.quantity,
          unitPriceCents: l.unitPriceCents,
          amountCents: typeof l.amountCents === 'number' ? l.amountCents : Math.round((Number(l.quantity) || 1) * (Number(l.unitPriceCents) || 0))
        })) : []
      }
    });

  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

publicInvoiceRouter.post('/:token/pay', async (req, res) => {
  try {
    const token = req.params.token;
    if (!token || typeof token !== 'string' || !/^pay_[a-zA-Z0-9_-]{10,128}$/.test(token)) {
      return res.status(400).json({ error: 'Invalid token format' });
    }
    const db = getDb();

    let snapshot = await db.collection('invoices').where('paymentToken', '==', token).limit(1).get();
    if (snapshot.empty) {
      snapshot = await db.collectionGroup('invoices').where('paymentToken', '==', token).limit(1).get();
    }

    if (snapshot.empty) {
      return res.status(404).json({ error: 'Invoice not found' });
    }

    const doc = snapshot.docs[0];
    const invoice = doc.data();

    const payableStatuses = ['sent', 'unpaid', 'pending', 'overdue', 'approved', 'invoiced'];
    if (!payableStatuses.includes(invoice.status) || invoice.isLocked === true) {
      return res.status(400).json({ 
        error: `Invoice cannot be paid. Current status: ${invoice.status || 'unknown'}${invoice.isLocked ? ' (locked)' : ''}` 
      });
    }

    const stripe = getStripe();
    const lineTotal = Array.isArray(invoice.lines)
      ? invoice.lines.reduce((sum: number, l: any) => {
          const lineAmt = typeof l.amountCents === 'number' 
            ? l.amountCents 
            : Math.round((Number(l.quantity) || 1) * (Number(l.unitPriceCents) || 0));
          return sum + lineAmt;
        }, 0)
      : 0;

    const totalInvoiceAmount = typeof invoice.totalCents === 'number'
      ? invoice.totalCents
      : (typeof invoice.amountCents === 'number' ? invoice.amountCents : lineTotal);
    const amountPaid = typeof invoice.amountPaidCents === 'number' 
      ? invoice.amountPaidCents 
      : (typeof invoice.paidAmountCents === 'number' ? invoice.paidAmountCents : 0);
    const remainingBalance = totalInvoiceAmount - amountPaid;

    if (!Number.isInteger(remainingBalance) || remainingBalance <= 0) {
      return res.status(400).json({ error: 'Invoice has no outstanding unpaid balance or is already paid.' });
    }

    // Use configured trusted application URL to prevent host-header poisoning (#85)
    const origin = getTrustedAppUrl(req);

    const idempotencyKey = `checkout_${doc.id}_${remainingBalance}_${token.slice(-16)}`;

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card', 'us_bank_account'],
      line_items: [
        {
          price_data: {
            currency: (invoice.currency || 'usd').toLowerCase(),
            product_data: {
              name: `Invoice ${invoice.number || 'Payment'}`,
              description: `Payment for ${invoice.customerName || 'Services'}`
            },
            unit_amount: remainingBalance,
          },
          quantity: 1,
        },
      ],
      mode: 'payment',
      success_url: `${origin}/i/${token}?success=true`,
      cancel_url: `${origin}/i/${token}?canceled=true`,
      client_reference_id: doc.id,
      metadata: {
        invoiceId: doc.id,
        workspaceId: invoice.workspaceId,
        paymentToken: token
      }
    }, {
      idempotencyKey
    });

    res.json({ url: session.url });

  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to create payment session' });
  }
});

import express from "express";
import admin from "firebase-admin";
import { z } from "zod";
import { getDb, validateWorkspaceMember } from "../db/firestore";
import { calculateNetIncome, isPostable, isRevenueAccount, isExpenseAccount, lineAmount } from "../../lib/txFilters";
import { ReportRangeSchema, WorkspaceIdSchema } from "../../schemas";
import { parseLocalDate, getLocalDateISO } from "../../lib/utils";

export const reportRouter = express.Router();

interface AuthUser extends admin.auth.DecodedIdToken {
  email_verified: boolean;
}

interface AuthenticatedRequest extends express.Request {
  user: AuthUser;
}

function sendError(res: express.Response, message: string, status: number = 500, details?: any) {
  console.error(`[API Error] ${status}: ${message} (Path: ${res.req?.originalUrl || "unknown"})`, details || "");
  res.status(status).json({
    status: "error",
    message,
    ...(details && { details })
  });
}

async function authorizeWorkspace(req: AuthenticatedRequest, workspaceId: string) {
  const db = getDb();
  await validateWorkspaceMember(db, workspaceId, req.user);
}

async function getReportContext(req: AuthenticatedRequest, workspaceId: string) {
  const db = getDb();
  await authorizeWorkspace(req, workspaceId);
  const accountsSnap = await db.collection("chartAccounts").where("workspaceId", "==", workspaceId).get();

  const transactions: any[] = [];
  const txStream = db.collection("transactions").where("workspaceId", "==", workspaceId).stream();

  for await (const chunk of txStream as any) {
    transactions.push((chunk as any).data());
  }

  return {
    accounts: accountsSnap.docs.map((doc: any) => ({ id: doc.id, ...(doc.data() as any) })),
    transactions
  };
}

reportRouter.get("/profit-and-loss", async (req, res) => {
  const authReq = req as AuthenticatedRequest;
  const result = ReportRangeSchema.safeParse(req.query);
  if (!result.success) return sendError(res, "Invalid parameters", 400, result.error.issues);
  const { workspaceId, startDate, endDate } = result.data;
  try {
    const { accounts, transactions } = await getReportContext(authReq, workspaceId);
    const start = startDate || "1970-01-01";
    const end = endDate || "2099-12-31";
    const pl: any = {
      income: { total: 0, accounts: {} },
      expense: { total: 0, accounts: {} },
      grossProfit: 0,
      netIncome: 0
    };
    accounts.forEach((acc: any) => {
      if (isRevenueAccount(acc)) {
        pl.income.accounts[acc.id] = { name: acc.name, balance: 0, parentId: acc.parentId };
      } else if (isExpenseAccount(acc)) {
        pl.expense.accounts[acc.id] = { name: acc.name, balance: 0, parentId: acc.parentId };
      }
    });
    for (const tx of transactions) {
      if (!isPostable(tx)) continue;
      if (tx.date < start || tx.date > end) continue;
      tx.lines?.forEach((line: any) => {
        const amount = lineAmount(line, tx);
        if (pl.income.accounts[line.accountId]) {
          const val = -amount; 
          pl.income.accounts[line.accountId].balance += val;
          pl.income.total += val;
        } else if (pl.expense.accounts[line.accountId]) {
          const val = amount;
          pl.expense.accounts[line.accountId].balance += val;
          pl.expense.total += val;
        }
      });
    }
    const totals = calculateNetIncome(transactions, accounts, start, end);
    pl.grossProfit = totals.grossProfit;
    pl.netIncome = totals.netIncome;
    pl.income.total = totals.income;
    pl.expense.total = totals.expense;
    res.json(pl);
  } catch (error: any) {
    if (error.message === "FORBIDDEN") return sendError(res, "Forbidden", 403);
    if (error.message === "NOT_FOUND" || error.message?.includes("NOT_FOUND")) return sendError(res, "Workspace not found", 404);
    sendError(res, "Internal Reporting Error", 500, error.message);
  }
});

reportRouter.get("/balance-sheet", async (req, res) => {
  const authReq = req as AuthenticatedRequest;
  const result = ReportRangeSchema.safeParse(req.query);
  if (!result.success) return sendError(res, "Invalid parameters", 400, result.error.issues);
  const { workspaceId, endDate } = result.data;
  try {
    const { accounts, transactions } = await getReportContext(authReq, workspaceId);
    const end = endDate || "2099-12-31";

    const balances: Record<string, number> = {};
    accounts.forEach((acc: any) => {
      balances[acc.id] = acc.openingBalanceCents || 0;
    });

    for (const tx of transactions) {
      if (!isPostable(tx)) continue;
      if (tx.date > end) continue;
      tx.lines?.forEach((line: any) => {
        if (balances[line.accountId] !== undefined) {
          balances[line.accountId] += lineAmount(line, tx);
        }
      });
    }

    const { netIncome } = calculateNetIncome(transactions, accounts, "1970-01-01", end);

    const assets: Record<string, { name: string; balance: number; subtype?: string }> = {};
    const liabilities: Record<string, { name: string; balance: number; subtype?: string }> = {};
    const equity: Record<string, { name: string; balance: number; subtype?: string }> = {};

    let totalAssets = 0;
    let totalLiabilities = 0;
    let totalEquity = 0;

    accounts.forEach((acc: any) => {
      const bal = balances[acc.id] || 0;
      if (acc.type === 'asset') {
        assets[acc.id] = { name: acc.name, balance: bal, subtype: acc.subtype };
        totalAssets += bal;
      } else if (acc.type === 'liability') {
        const val = -bal;
        liabilities[acc.id] = { name: acc.name, balance: val, subtype: acc.subtype };
        totalLiabilities += val;
      } else if (acc.type === 'equity') {
        const val = -bal;
        equity[acc.id] = { name: acc.name, balance: val, subtype: acc.subtype };
        totalEquity += val;
      }
    });

    totalEquity += netIncome;

    res.json({
      assets: { total: totalAssets, accounts: assets },
      liabilities: { total: totalLiabilities, accounts: liabilities },
      equity: { total: totalEquity, accounts: equity, currentPeriodNetIncome: netIncome },
      totalAssets,
      totalLiabilitiesAndEquity: totalLiabilities + totalEquity,
      isBalanced: totalAssets === (totalLiabilities + totalEquity)
    });
  } catch (error: any) {
    if (error.message === "FORBIDDEN") return sendError(res, "Forbidden", 403);
    if (error.message === "NOT_FOUND" || error.message?.includes("NOT_FOUND")) return sendError(res, "Workspace not found", 404);
    sendError(res, "Internal Reporting Error", 500, error.message);
  }
});

reportRouter.get("/aging", async (req, res) => {
  const authReq = req as AuthenticatedRequest;
  const result = WorkspaceIdSchema.extend({ type: z.enum(['ar', 'ap']) }).safeParse(req.query);
  if (!result.success) return sendError(res, "Invalid parameters", 400, result.error.issues);
  const { workspaceId, type } = result.data;

  try {
    await authorizeWorkspace(authReq, workspaceId);
    const db = getDb();
    const collectionName = type === 'ar' ? 'invoices' : 'bills';
    const snap = await db.collection(collectionName)
      .where("workspaceId", "==", workspaceId)
      .get();

    let items = snap.docs.map((doc: any) => doc.data());

    const allowedStatuses = ["unpaid", "pending", "overdue", "sent", "partially_paid"];
    items = items.filter(item => allowedStatuses.includes(item.status));
    const today = parseLocalDate(getLocalDateISO());

    const aging = {
      current: 0,
      "1-30": 0,
      "31-60": 0,
      "61-90": 0,
      "90+": 0,
      total: 0
    };

    items.forEach((item: any) => {
      const rawTotal = item.amountCents || item.totalCents || item.amountTotalCents || 0;
      const rawPaid = item.amountPaidCents || item.paidAmountCents || 0;
      const outstanding = Math.max(0, rawTotal - rawPaid);
      if (outstanding <= 0) return;

      let diffDays = 0;
      const dateStr = item.dueDate || item.date;
      if (dateStr && typeof dateStr === 'string') {
        try {
          const parsed = parseLocalDate(dateStr);
          if (!isNaN(parsed.getTime())) {
            diffDays = Math.floor((today.getTime() - parsed.getTime()) / (1000 * 60 * 60 * 24));
          }
        } catch {
          diffDays = 0;
        }
      }

      if (diffDays <= 0) aging.current += outstanding;
      else if (diffDays <= 30) aging["1-30"] += outstanding;
      else if (diffDays <= 60) aging["31-60"] += outstanding;
      else if (diffDays <= 90) aging["61-90"] += outstanding;
      else aging["90+"] += outstanding;

      aging.total += outstanding;
    });

    res.json(aging);
  } catch (error: any) {
    if (error.message === "FORBIDDEN") return sendError(res, "Forbidden", 403);
    if (error.message === "NOT_FOUND" || error.message?.includes("NOT_FOUND")) return sendError(res, "Workspace not found", 404);
    sendError(res, "Failed to generate aging report", 500, error.message);
  }
});

reportRouter.get("/trial-balance", async (req, res) => {
  const authReq = req as AuthenticatedRequest;
  const result = WorkspaceIdSchema.safeParse(req.query);
  if (!result.success) return sendError(res, "Invalid parameters", 400, result.error.issues);
  const { workspaceId } = result.data;
  try {
    const { accounts, transactions } = await getReportContext(authReq, workspaceId);
    const trialBalance: Record<string, { name: string, debit: number, credit: number }> = {};
    accounts.forEach((acc: any) => {
      const opening = acc.openingBalanceCents || 0;
      trialBalance[acc.id] = {
        name: acc.name,
        debit: opening > 0 ? opening : 0,
        credit: opening < 0 ? Math.abs(opening) : 0
      };
    });
    for (const tx of transactions) {
      if (!isPostable(tx)) continue;
      tx.lines?.forEach((line: any) => {
        const amount = lineAmount(line, tx);
        if (trialBalance[line.accountId]) {
          if (amount > 0) trialBalance[line.accountId].debit += amount;
          else trialBalance[line.accountId].credit += Math.abs(amount);
        }
      });
    }
    const totalDebit = Object.values(trialBalance).reduce((sum, acc) => sum + acc.debit, 0);
    const totalCredit = Object.values(trialBalance).reduce((sum, acc) => sum + acc.credit, 0);
    res.json({ accounts: trialBalance, totalDebit, totalCredit, isBalanced: totalDebit === totalCredit });
  } catch (error: any) {
    if (error.message === "FORBIDDEN") return sendError(res, "Forbidden", 403);
    if (error.message === "NOT_FOUND" || error.message?.includes("NOT_FOUND")) return sendError(res, "Workspace not found", 404);
    sendError(res, "Trial Balance Failure", 500, error.message);
  }
});

reportRouter.get("/cash-flow", async (req, res) => {
  const authReq = req as AuthenticatedRequest;
  const result = ReportRangeSchema.safeParse(req.query);
  if (!result.success) return sendError(res, "Invalid parameters", 400, result.error.issues);
  const { workspaceId, startDate, endDate } = result.data;

  try {
    await authorizeWorkspace(authReq, workspaceId);
    const db = getDb();

    const [accountsSnap, transactionsSnap] = await Promise.all([
      db.collection("chartAccounts").where("workspaceId", "==", workspaceId).get(),
      db.collection("transactions").where("workspaceId", "==", workspaceId).get()
    ]);

    const accounts = accountsSnap.docs.map((doc: any) => ({ id: doc.id, ...doc.data() }));
    let transactions = transactionsSnap.docs.map((doc: any) => doc.data());

    if (startDate || endDate) {
      const start = startDate ? String(startDate) : "1970-01-01";
      const end = endDate ? String(endDate) : "2099-12-31";
      transactions = transactions.filter((tx: any) => tx.date >= start && tx.date <= end);
    }

    const cashFlow = {
      operating: { total: 0, items: [] as any[] },
      investing: { total: 0, items: [] as any[] },
      financing: { total: 0, items: [] as any[] },
      netChange: 0
    };

    transactions.forEach((tx: any) => {
      if (!isPostable(tx)) return;
      tx.lines?.forEach((line: any) => {
        const acc = accounts.find(a => a.id === line.accountId);
        if (!acc) return;
        const amount = lineAmount(line, tx);

        if (acc.type === 'income') cashFlow.operating.total -= amount;
        if (acc.type === 'expense') cashFlow.operating.total -= amount;

        if (acc.type === 'asset' && (acc.category === 'Receivables' || acc.category === 'Receivable' || acc.category === 'Accounts Receivable')) cashFlow.operating.total -= amount;
        if (acc.type === 'liability' && (acc.category === 'Payables' || acc.category === 'Payable' || acc.category === 'Accounts Payable')) cashFlow.operating.total -= amount;

        if (acc.type === 'asset' && (acc.category === 'Fixed Assets' || acc.category === 'Fixed Asset')) {
          cashFlow.investing.total -= amount;
          cashFlow.investing.items.push({ name: tx.description, amount: -amount });
        }

        if (acc.type === 'equity' || (acc.type === 'liability' && (acc.category === 'Long Term Liabilities' || acc.category === 'Long Term Liability'))) {
          cashFlow.financing.total -= amount;
          cashFlow.financing.items.push({ name: tx.description, amount: -amount });
        }
      });
    });

    cashFlow.netChange = cashFlow.operating.total + cashFlow.investing.total + cashFlow.financing.total;

    res.json(cashFlow);
  } catch (error: any) {
    if (error.message === "FORBIDDEN") return sendError(res, "Forbidden", 403);
    if (error.message === "NOT_FOUND" || error.message?.includes("NOT_FOUND")) return sendError(res, "Workspace not found", 404);
    sendError(res, "Failed to generate cash flow statement", 500, error.message);
  }
});

reportRouter.get("/budget-vs-actual", async (req, res) => {
  const authReq = req as AuthenticatedRequest;
  const result = WorkspaceIdSchema.extend({ month: z.string().optional() }).safeParse(req.query);
  if (!result.success) return sendError(res, "Invalid parameters", 400, result.error.issues);
  const { workspaceId, month } = result.data;

  try {
    await authorizeWorkspace(authReq, workspaceId);
    const db = getDb();
    const [budgetsSnap, transactionsSnap, accountsSnap] = await Promise.all([
      db.collection("budgets").where("workspaceId", "==", workspaceId).get(),
      db.collection("transactions").where("workspaceId", "==", workspaceId).get(),
      db.collection("chartAccounts").where("workspaceId", "==", workspaceId).get()
    ]);

    const budgets = budgetsSnap.docs.map((doc: any) => doc.data());
    let transactions = transactionsSnap.docs.map((doc: any) => doc.data());
    const accounts = accountsSnap.docs.map((doc: any) => ({ id: doc.id, ...doc.data() }));

    if (month) {
      const monthStr = String(month);
      transactions = transactions.filter(tx => tx.date && tx.date.startsWith(monthStr));
    }

    const report = budgets.map((b: any) => {
      const account = accounts.find(a => a.id === b.accountId);
      let actual = 0;
      transactions.forEach((tx: any) => {
        if (!isPostable(tx)) return;
        tx.lines?.forEach((line: any) => {
          if (line.accountId === b.accountId) {
            actual += Math.abs(line.amountCents);
          }
        });
      });

      return {
        accountName: account?.name || 'Unknown',
        budget: b.amountCents,
        actual,
        variance: b.amountCents - actual,
        percent: b.amountCents > 0 ? (actual / b.amountCents) * 100 : 0
      };
    });

    res.json(report);
  } catch (error: any) {
    if (error.message === "FORBIDDEN") return sendError(res, "Forbidden", 403);
    if (error.message === "NOT_FOUND" || error.message?.includes("NOT_FOUND")) return sendError(res, "Workspace not found", 404);
    sendError(res, "Failed to generate budget vs actual report", 500, error.message);
  }
});

