  }),
  removeSpeedDial: (key) => set((state) => {
    const { [key]: _, ...nextSpeedDials } = state.speedDials;
    try {
      localStorage.setItem('lf_speed_dials', JSON.stringify(nextSpeedDials));
    } catch (_e) {
      // Ignore storage error
    }
    return { speedDials: nextSpeedDials };
  })
}));

if (typeof window !== 'undefined') {
  window.addEventListener('hashchange', () => {
    const hash = window.location.hash.slice(1) as AppTab;
    if (hash && useUIStore.getState().activeTab !== hash) {
      useUIStore.setState({ activeTab: hash });
    }
  });

  window.addEventListener('online', () => {
    useUIStore.getState().setIsOnline(true);
  });
  window.addEventListener('offline', () => {
    useUIStore.getState().setIsOnline(false);
  });
}

import assert from 'node:assert/strict';
import { test, describe } from 'node:test';
import { CASH_CONVERSION_CYCLE_ALGO } from '../lib/algorithms/cash-conversion-cycle.js';
import { ALTMAN_Z_SCORE_ALGO } from '../lib/algorithms/altman-z-score.js';
import { EXPENSE_VELOCITY_ALGO } from '../lib/algorithms/expense-velocity.js';
import { MONTE_CARLO_ALGO } from '../lib/algorithms/monte-carlo.js';
import { assetAmortizer } from '../lib/algorithms/asset-amortizer.js';
import { ANOMALY_DETECTION_ALGO } from '../lib/algorithms/anomaly-detection.js';
import { parseNaturalLanguageEntry } from '../lib/algorithms/nl-parser.js';
import { buildAlgorithmContext } from '../lib/algorithms/types.js';
import { isPostable, isSimulationTransaction } from '../lib/txFilters.js';

describe('Financial Algorithms & Platform Semantics Test Suite', () => {
  test('Altman Z-Score computes correctly and avoids division by zero', () => {
    const computeFn = ALTMAN_Z_SCORE_ALGO.compute;
    const ctxEmpty = buildAlgorithmContext([], [], '2026-09-06', { start: '2026-01-01', end: '2026-12-31' });
    const resEmpty = computeFn(ctxEmpty, { publicCompany: 0 });
    assert.equal(resEmpty.metrics[0].value, 'N/A');

    const accounts = [
      { id: '1', type: 'asset', balanceCents: 100000 },
      { id: '2', type: 'asset', subtype: 'cash', balanceCents: 20000 },
      { id: '3', type: 'liability', subtype: 'current_liability', balanceCents: 30000 },
      { id: '4', type: 'liability', balanceCents: 40000 },
      { id: '5', type: 'equity', subtype: 'retained_earnings', balanceCents: 50000 },
    ];

    const transactions = [
      { id: 'tx1', status: 'completed', lines: [
        { accountId: '6', type: 'revenue', amountCents: -60000 },
        { accountId: '1', type: 'asset', amountCents: 60000 }
      ]}
    ];

    const ctx = buildAlgorithmContext(transactions as any, accounts as any, '2026-09-06', { start: '2026-01-01', end: '2026-12-31' });
    const res = computeFn(ctx, { publicCompany: 0 });
    assert.ok(res.metrics.length > 0);
  });

  test('Expense Velocity isolates true expenses and calculates trailing spikes', () => {
    const accounts = [
      { id: 'cash1', name: 'Operating Cash', type: 'asset', category: 'Cash' },
      { id: 'exp1', name: 'Rent Expense', type: 'expense', category: 'Rent' },
      { id: 'rev1', name: 'Product Revenue', type: 'revenue', category: 'Revenue' }
    ];

    // Create 10 days of base expenses ($100/day = 10000 cents) and a spike on day 10 ($1000 = 100000 cents)
    const txs: any[] = [];
    for (let day = 1; day <= 9; day++) {
      const dayStr = day < 10 ? `0${day}` : `${day}`;
      txs.push({
        id: `tx-exp-${day}`,
        date: `2026-06-${dayStr}T12:00:00.000Z`,
        status: 'completed',
        totalAmountCents: 10000,
        lines: [
          { accountId: 'exp1', amountCents: 10000 },
          { accountId: 'cash1', amountCents: -10000 }
        ]
      });
    }

    // Spike on day 10
    txs.push({
      id: 'tx-exp-10',
      date: '2026-06-10T12:00:00.000Z',
      status: 'completed',
      totalAmountCents: 100000,
      lines: [
        { accountId: 'exp1', amountCents: 100000 },
        { accountId: 'cash1', amountCents: -100000 }
      ]
    });

    // Also add an incoming revenue transaction of $500,000 which must NOT count as an expense spike!
    txs.push({
      id: 'tx-rev-10',
      date: '2026-06-10T14:00:00.000Z',
      status: 'completed',
      totalAmountCents: 50000000,
      lines: [
        { accountId: 'cash1', amountCents: 50000000 },
        { accountId: 'rev1', amountCents: -50000000 }
      ]
    });

    const ctx = buildAlgorithmContext(txs, accounts as any, '2026-06-11', { start: '2026-06-01', end: '2026-06-11' });
    const res = EXPENSE_VELOCITY_ALGO.compute(ctx, { spikeThresholdPct: 50, movingAverageDays: 7 });

    assert.ok(res.metrics.length >= 3);
    const spikeMetric = res.metrics.find(m => m.label === 'Recent Spikes');
    assert.ok(spikeMetric);
    assert.equal(spikeMetric.value, 1);
    assert.ok(res.sourceTransactionIds?.includes('tx-exp-10'));
    assert.ok(!res.sourceTransactionIds?.includes('tx-rev-10'));
  });

  test('Monte Carlo strictly isolates cash accounts and ignores non-cash transactions', () => {
    const accounts = [
      { id: 'bank1', name: 'JPMorgan Checking', type: 'asset', category: 'Cash', role: 'cash', balanceCents: 1000000 },
      { id: 'ar1', name: 'Accounts Receivable', type: 'asset', category: 'Receivables', balanceCents: 5000000 },
      { id: 'fa1', name: 'Office Machinery', type: 'asset', category: 'Fixed Assets', balanceCents: 8000000 },
      { id: 'exp1', name: 'Depreciation Expense', type: 'expense', balanceCents: 0 }
    ];

    const txs: any[] = [];
    // 10 days of cash transactions
    for (let day = 1; day <= 10; day++) {
      const dayStr = day < 10 ? `0${day}` : `${day}`;
      txs.push({
        id: `tx-cash-${day}`,
        date: `2026-05-${dayStr}`,
        status: 'completed',
        totalAmountCents: 20000,
        lines: [
          { accountId: 'bank1', amountCents: 20000 },
          { accountId: 'ar1', amountCents: -20000 }
        ]
      });
    }

    // Non-cash depreciation entry of $1,000,000
    txs.push({
      id: 'tx-deprec',
      date: '2026-05-11',
      status: 'completed',
      totalAmountCents: 100000000,
      lines: [
        { accountId: 'exp1', amountCents: 100000000 },
        { accountId: 'fa1', amountCents: -100000000 }
      ]
    });

    const ctx = buildAlgorithmContext(txs, accounts as any, '2026-05-12', { start: '2026-05-01', end: '2026-05-12' });
    const res = MONTE_CARLO_ALGO.compute(ctx, { simulationDays: 90, iterations: 10 });

    assert.ok(res.metrics.length > 0);
    // Baseline cash flows should isolate cash txs ($200/day) and ignore non-cash $1M depreciation
    assert.ok(res.insights[1].includes('$200.00/day'));
    const ruinMetric = res.metrics.find(m => m.label.includes('Risk of Exhaustion'));
    assert.ok(ruinMetric);
  });

  test('Fixed Asset Amortizer strictly filters out liquid cash/AR and models half-year convention', () => {
    const accounts = [
      { id: 'bank1', name: 'Operating Cash', type: 'asset', category: 'Cash', role: 'cash', balanceCents: 100000 },
      { id: 'fa1', name: 'CNC Milling Machine', type: 'asset', category: 'Fixed Assets', balanceCents: 10000000 }
    ];

    const ctx = buildAlgorithmContext([], accounts as any, '2026-01-01', { start: '2026-01-01', end: '2026-12-31' });
    const res = assetAmortizer.compute(ctx, { life: 5, salvageValuePct: 10, taxRate: 25, convention: 'half-year' });

    assert.ok(res.metrics.length > 0);
    // Depreciable base should be on $100,000 (10,000,000 cents), not $101,000
    const baseMetric = res.metrics.find(m => m.label === 'Identified Capital Base');
    assert.ok(baseMetric);
    assert.equal(baseMetric.value, '$100,000');

    // Half-year convention: 5-year asset produces 6 periods (Year 1 to Year 6)
    assert.equal(res.charts[0].data.length, 6);
    assert.ok(res.charts[0].data[0].year.includes('Half'));
  });

  test('Simulation / Ghost Transaction Isolation protects real reports', () => {
    const realTx: any = {
      id: 'tx-real-1',
      status: 'completed',
      date: '2026-01-15',
      totalAmountCents: 5000,
      lines: [{ accountId: 'cash', amountCents: 5000 }]
    };

    const ghostTx: any = {
      id: 'ghost-scenario-1-20260115',
      status: 'pending',
      type: 'forecast',
      date: '2026-01-15',
      totalAmountCents: 5000,
      metadata: { isGhost: true },
      lines: [{ accountId: 'ghost-acc', amountCents: 5000 }]
    };

    assert.equal(isPostable(realTx), true);
    assert.equal(isSimulationTransaction(realTx), false);

    assert.equal(isSimulationTransaction(ghostTx), true);
    // Real reports: default isPostable rejects ghost transactions
    assert.equal(isPostable(ghostTx), false);
    // Scenario reports: can explicitly opt-in
    assert.equal(isPostable(ghostTx, { includeSimulations: true }), true);
  });

  test('Deterministic NL Parser correctly resolves transaction, project, and query intents', () => {
    const txIntent = parseNaturalLanguageEntry('paid $45.50 gas cash yesterday');
    assert.equal(txIntent.type, 'transaction');
    assert.equal(txIntent.amountCents, 4550);
    assert.equal(txIntent.action, 'expense');
    assert.equal(txIntent.method, 'Cash');

    const projIntent = parseNaturalLanguageEntry('new project: Shakespeare Folio');
    assert.equal(projIntent.type, 'project');
    assert.equal(projIntent.projectName, 'Shakespeare Folio');

    const queryIntent = parseNaturalLanguageEntry('show maui repair expenses');
    assert.equal(queryIntent.type, 'query');
    assert.equal(queryIntent.queryText, 'maui repair expenses');
  });
});

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { TransactionValidator } from '../kernel/validation/TransactionValidator';
import { DoubleEntryValidator } from '../kernel/validation/DoubleEntryValidator';
import { getTrustedAppUrl } from '../server/utils/urlHelper';
import { calculateNetIncome, isPostable, getAbsoluteTotal, lineAmount } from '../lib/txFilters';
import { ChartAccount, Transaction } from '../types';

describe('Checkpoint 2 Regression & Security Hardening Suite (N1 - N18)', () => {

  test('N1 & N14: TransactionValidator enforces period lock and user ownership', async () => {
    const wsData = { lockDate: '2026-03-31' };
    const context = {
      workspaceId: 'ws-test-100',
      user: { uid: 'user-alice' },
      wsData
    };

    // 1. Locked date transaction should throw
    const lockedTx = {
      id: 'tx-locked-1',
      date: '2026-03-15',
      description: 'Historical adjustment',
      lines: [
        { accountId: 'acc-cash', amountCents: 1000 },
        { accountId: 'acc-rev', amountCents: -1000 }
      ]
    };

    await assert.rejects(
      async () => {
        await TransactionValidator.validateAndPrepare(lockedTx, context);
      },
      /Period Locked/
    );

    // 2. Open period transaction succeeds and enforces user UID
    const openTx = {
      id: 'tx-open-1',
      date: '2026-04-15',
      description: 'Current sales',
      uid: 'spoofed-uid-attacker', // should be overridden
      lines: [
        { accountId: 'acc-cash', amountCents: 5000 },
        { accountId: 'acc-rev', amountCents: -5000 }
      ]
    };

    const mockAccountsMap = new Map([
      ['acc-cash', { id: 'acc-cash', name: 'Cash', workspaceId: 'ws-test-100', type: 'asset' }],
      ['acc-rev', { id: 'acc-rev', name: 'Sales Revenue', workspaceId: 'ws-test-100', type: 'revenue' }]
    ]);

    const validated = await TransactionValidator.validateAndPrepare(openTx, {
      ...context,
      accountsMap: mockAccountsMap
    });

    assert.equal(validated.uid, 'user-alice', 'User UID must be strictly enforced');
    assert.equal(validated.workspaceId, 'ws-test-100', 'Workspace ID must be enforced');
    assert.equal(validated.totalAmountCents, 5000, 'Total amount must be absolute 5000 cents');
  });

  test('N9: TransactionValidator strictly rejects ghost simulation IDs for persistent writes', async () => {
    const context = {
      workspaceId: 'ws-test-100',
      user: { uid: 'user-alice' },
      wsData: { lockDate: null },
      accountsMap: new Map([
        ['acc-cash', { id: 'acc-cash', name: 'Cash', workspaceId: 'ws-test-100' }],
        ['acc-rev', { id: 'acc-rev', name: 'Sales', workspaceId: 'ws-test-100' }]
      ])
    };

    const ghostTx = {
      id: 'ghost-sim-12345',
      date: '2026-05-01',
      description: 'Simulated cashflow item',
      type: 'standard',
      lines: [
        { accountId: 'acc-cash', amountCents: 1000 },
        { accountId: 'acc-rev', amountCents: -1000 }
      ]
    };

    await assert.rejects(
      async () => {
        await TransactionValidator.validateAndPrepare(ghostTx, context);
      },
      /ghost-/
    );
  });

  test('N15 & #88: getAbsoluteTotal correctly computes absolute transaction total with FX support', () => {
    const multiLineTx = {
      id: 'tx-multi-1',
      workspaceId: 'ws-1',
      uid: 'user-1',
      date: '2026-06-01',
      description: 'Multi-line invoice',
      status: 'completed' as const,
      currency: 'USD',
      totalAmountCents: 0,
      lines: [
        { accountId: 'acc-ar', accountName: 'Receivables', amountCents: 12000 },
        { accountId: 'acc-tax', accountName: 'Tax Payable', amountCents: -2000 },
        { accountId: 'acc-rev', accountName: 'Revenue', amountCents: -10000 }
      ]
    } as Transaction;

    const total = getAbsoluteTotal(multiLineTx);
    assert.equal(total, 12000, 'Absolute total of $120 debit leg is 12000 cents');
  });

  test('N6: getTrustedAppUrl rejects open shared cloud domains and protects against Host header poisoning', () => {
    // 1. With APP_URL configured
    process.env.APP_URL = 'https://app.customcorp.com';
    assert.equal(getTrustedAppUrl(), 'https://app.customcorp.com');
    delete process.env.APP_URL;

    // 2. Mock request with malicious host header
    const maliciousReq: any = {
      get: (header: string) => {
        if (header.toLowerCase() === 'host') return 'evil-phishing.run.app';
        return null;
      },
      protocol: 'https'
    };

    const trusted = getTrustedAppUrl(maliciousReq);
    assert.notEqual(trusted, 'https://evil-phishing.run.app', 'Must not trust arbitrary run.app hosts');
  });

  test('N7 & N8: calculateNetIncome correctly accounts for COGS and revenue with isPostable filtering', () => {
    const accounts = [
      { id: 'acc-rev', uid: 'user-1', code: '4000', name: 'Software Sales', type: 'revenue' as const, balanceCents: 0, workspaceId: 'ws-1' },
      { id: 'acc-cogs', uid: 'user-1', code: '5000', name: 'Hosting Costs', type: 'cost_of_goods' as const, balanceCents: 0, workspaceId: 'ws-1' },
      { id: 'acc-exp', uid: 'user-1', code: '6000', name: 'Office Supplies', type: 'expense' as const, balanceCents: 0, workspaceId: 'ws-1' },
      { id: 'acc-cash', uid: 'user-1', code: '1000', name: 'Checking Account', type: 'asset' as const, balanceCents: 0, workspaceId: 'ws-1' }
    ] as ChartAccount[];

    const transactions = [
      // 1. Revenue of $10,000 (credit)
      {
        id: 'tx-1',
        workspaceId: 'ws-1',
        uid: 'user-1',
        date: '2026-06-01',
        description: 'Client sale',
        status: 'completed' as const,
        lines: [
          { accountId: 'acc-cash', accountName: 'Checking Account', amountCents: 1000000 },
          { accountId: 'acc-rev', accountName: 'Software Sales', amountCents: -1000000 }
        ]
      },
      // 2. COGS of $2,000 (debit)
      {
        id: 'tx-2',
        workspaceId: 'ws-1',
        uid: 'user-1',
        date: '2026-06-02',
        description: 'Server costs',
        status: 'completed' as const,
        lines: [
          { accountId: 'acc-cogs', accountName: 'Hosting Costs', amountCents: 200000 },
          { accountId: 'acc-cash', accountName: 'Checking Account', amountCents: -200000 }
        ]
      },
      // 3. OPEX of $1,000 (debit)
      {
        id: 'tx-3',
        workspaceId: 'ws-1',
        uid: 'user-1',
        date: '2026-06-03',
        description: 'Supplies',
        status: 'completed' as const,
        lines: [
          { accountId: 'acc-exp', accountName: 'Office Supplies', amountCents: 100000 },
          { accountId: 'acc-cash', accountName: 'Checking Account', amountCents: -100000 }
        ]
      },
      // 4. Voided transaction (should be ignored by isPostable)
      {
        id: 'tx-void',
        workspaceId: 'ws-1',
        uid: 'user-1',
        date: '2026-06-04',
        description: 'Cancelled deal',
        status: 'void' as const,
        lines: [
          { accountId: 'acc-cash', accountName: 'Checking Account', amountCents: 5000000 },
          { accountId: 'acc-rev', accountName: 'Software Sales', amountCents: -5000000 }
        ]
      }
    ] as Transaction[];

    const result = calculateNetIncome(transactions, accounts);
    // Net Income = Revenue ($10,000) - COGS ($2,000) - OPEX ($1,000) = $7,000 = 700000 cents
    assert.equal(result.income, 1000000, 'Income must equal $10,000.00');
    assert.equal(result.cogs, 200000, 'COGS must equal $2,000.00');
    assert.equal(result.expense, 100000, 'Expense must equal $1,000.00');
    assert.equal(result.grossProfit, 800000, 'Gross profit must equal $8,000.00');
    assert.equal(result.netIncome, 700000, 'Net income must equal $7,000.00');
  });

});

import test, { describe, it } from 'node:test';
import assert from 'node:assert';
import { 
  decomposeHierarchicalLabel, 
  matchDeepLabel, 
  expandDeepLabels, 
  extractMultiDimensionalLabels 
} from '../lib/dimensionUtils';
import { BayesianClassifier } from '../lib/algorithms';
import { MatchingEngine } from '../lib/MatchingEngine';
import { AutoRule } from '../types';

describe('Deep and Multi-Dimensional Labeling Engine', () => {
  it('correctly decomposes deep hierarchical labels with slashes, arrows, or colons', () => {
    const slashLabel = decomposeHierarchicalLabel('Marketing / Digital / PPC');
    assert.strictEqual(slashLabel.root, 'Marketing');
    assert.deepStrictEqual(slashLabel.segments, ['Marketing', 'Digital', 'PPC']);
    assert.strictEqual(slashLabel.depth, 3);
    assert.strictEqual(slashLabel.parentPath, 'Marketing/Digital');
    assert.strictEqual(slashLabel.fullPath, 'Marketing/Digital/PPC');

    const arrowLabel = decomposeHierarchicalLabel('Expenses > Software > DevTools');
    assert.strictEqual(arrowLabel.root, 'Expenses');
    assert.deepStrictEqual(arrowLabel.segments, ['Expenses', 'Software', 'DevTools']);
    assert.strictEqual(arrowLabel.parentPath, 'Expenses/Software');

    const colonLabel = decomposeHierarchicalLabel('Dept:Engineering:Infra');
    assert.strictEqual(colonLabel.root, 'Dept');
    assert.deepStrictEqual(colonLabel.segments, ['Dept', 'Engineering', 'Infra']);
  });

  it('accurately matches deep labels and subtree hierarchies', () => {
    // Child matches ancestor query
    assert.strictEqual(matchDeepLabel('Engineering/Backend/API', 'Engineering'), true);
    assert.strictEqual(matchDeepLabel('Engineering/Backend/API', 'Engineering/Backend'), true);
    // Ancestor matches child when matchAncestors is enabled
    assert.strictEqual(matchDeepLabel('Engineering', 'Engineering/Backend', true), true);
    // Unrelated branches do not match
    assert.strictEqual(matchDeepLabel('Marketing/SEO', 'Engineering/Backend'), false);
  });

  it('expands multi-tiered tags across every hierarchical level', () => {
    const rawTags = ['marketing/digital/sem', 'dept:ops:warehouse', 'project-apollo'];
    const expanded = expandDeepLabels(rawTags);

    // Checks all ancestor tiers are populated for fast indexing and filtering
    assert.ok(expanded.includes('marketing'));
    assert.ok(expanded.includes('marketing/digital'));
    assert.ok(expanded.includes('marketing/digital/sem'));
    assert.ok(expanded.includes('dept'));
    assert.ok(expanded.includes('dept:ops'));
    assert.ok(expanded.includes('dept:ops:warehouse'));
    assert.ok(expanded.includes('project-apollo'));
  });

  it('extracts multi-dimensional coordinates and hashtags from memo descriptions', () => {
    const memo = 'AWS Cloud Hosting Invoice [Dept:Engineering/Cloud] #project/titan/phase1';
    const extracted = extractMultiDimensionalLabels(memo);

    assert.strictEqual(extracted.dimensions['dept'], 'Engineering/Cloud');
    assert.ok(extracted.tags.includes('dept:Engineering/Cloud'));
    assert.ok(extracted.tags.includes('project/titan/phase1'));
    assert.ok(extracted.tags.includes('project/titan'));
    assert.ok(extracted.tags.includes('project'));
  });

  it('Bayesian classifier trains hierarchical categories and predicts deep labels', () => {
    const bayes = new BayesianClassifier();

    // Train with deep hierarchical categories
    bayes.train('Google Ads search campaign pay per click', 'Marketing / Advertising / PPC', 3.0);
    bayes.train('Facebook instagram social media boost', 'Marketing / Social / Paid', 3.0);
    bayes.train('GitHub Copilot annual developer subscription', 'Software / DevTools / AI', 3.0);

    const result = bayes.classifyHierarchical('Google Search adwords click invoice');
    assert.ok(result !== null);
    assert.strictEqual(result.rootCategory, 'Marketing');
    assert.ok(result.category.includes('Marketing'));
    assert.ok(result.depth >= 1);
  });

  it('MatchingEngine automatically assigns deep multi-dimensional tags and dimensions', () => {
    const rules: AutoRule[] = [
      {
        id: 'rule-slack',
        uid: 'test-user',
        workspaceId: 'ws-test',
        condition: { descriptionContains: 'Slack' },
        action: { 
          targetCategory: 'Software / Collaboration / Chat',
          targetDimensions: { department: 'Engineering/Operations' },
          targetTags: ['comms:internal']
        },
        confidence: 1,
        isHardened: true,
        priority: 10,
        isActive: true,
        createdAt: new Date().toISOString()
      }
    ];

    const engine = new MatchingEngine(rules);
    const resolved = engine.resolveCategory('Monthly Slack Team Subscription [Project:Moonshot/Core]');

    assert.ok(resolved !== null);
    assert.strictEqual(resolved.accountName, 'Software / Collaboration / Chat');
    assert.strictEqual(resolved.dimensions?.['category'], 'Software/Collaboration/Chat');
    assert.strictEqual(resolved.dimensions?.['department'], 'Engineering/Operations');
    assert.strictEqual(resolved.dimensions?.['project'], 'Moonshot/Core');
    assert.ok(resolved.tags?.includes('comms:internal'));
    assert.ok(resolved.tags?.includes('project:Moonshot/Core'));
  });
});

import assert from 'node:assert/strict';
import { test, describe } from 'node:test';
import { roundCents, formatCurrency, formatDollars, getLocalDateISO } from '../lib/utils.js';

describe('Financial Accounting Golden-Path Test Suite', () => {
  test('Local ISO Date helper generates YYYY-MM-DD in local time', () => {
    const fixedDate = new Date(2026, 6, 22); // July 22, 2026 local
    assert.equal(getLocalDateISO(fixedDate), '2026-07-22');
  });

  test('Currency formatting produces clean Intl representations', () => {
    assert.equal(formatCurrency(123456), '$1,234.56');
    assert.equal(formatCurrency(0), '$0.00');
    assert.equal(formatCurrency(null as any), '$0.00');
    assert.equal(formatDollars(1234.56), '$1,234.56');
  });

  test('Financial rounding prevents sub-cent rounding errors', () => {
    const rawCents = 12500.4;
    assert.equal(roundCents(rawCents), 12500);
    assert.equal(roundCents(12500.6), 12501);
  });

  test('Double-Entry Ledger Balancing: Debits must equal Credits', () => {
    const journalEntry = {
      id: 'tx_1',
      description: 'Consulting Revenue Received',
      lines: [
        { accountId: '1010', debitCents: 500000, creditCents: 0 },   // Operating Cash (Asset) +$5,000
        { accountId: '4010', debitCents: 0, creditCents: 500000 }    // Service Revenue +$5,000
      ]
    };

    const totalDebits = journalEntry.lines.reduce((sum, line) => sum + line.debitCents, 0);
    const totalCredits = journalEntry.lines.reduce((sum, line) => sum + line.creditCents, 0);

    assert.equal(totalDebits, totalCredits, 'Double-entry equation violated: Debits !== Credits');
    assert.equal(totalDebits, 500000);
  });

  test('Trial Balance Ties Out To Zero', () => {
    const accounts = [
      { id: '1010', type: 'asset', debitCents: 1000000, creditCents: 0 },
      { id: '2010', type: 'liability', debitCents: 0, creditCents: 200000 },
      { id: '3010', type: 'equity', debitCents: 0, creditCents: 300000 },
      { id: '4010', type: 'revenue', debitCents: 0, creditCents: 800000 },
      { id: '5010', type: 'expense', debitCents: 300000, creditCents: 0 },
    ];

    const sumDebits = accounts.reduce((acc, a) => acc + a.debitCents, 0);
    const sumCredits = accounts.reduce((acc, a) => acc + a.creditCents, 0);

    assert.equal(sumDebits, 1300000);
    assert.equal(sumCredits, 1300000);
    assert.equal(sumDebits - sumCredits, 0, 'Trial balance does not tie out to zero');
  });

  test('P&L & Balance Sheet Reconciliation Equation: Assets = Liabilities + Equity + Net Income', () => {
    // Financial numbers (in cents)
    const assets = 1000000;      // $10,000
    const liabilities = 200000;  // $2,000
    const initialEquity = 300000;// $3,000
    const revenue = 800000;      // $8,000
    const expenses = 300000;     // $3,000

    const netIncome = revenue - expenses; // $5,000
    const totalEndingEquity = initialEquity + netIncome; // $8,000

    assert.equal(netIncome, 500000, 'Net Income calculation error');
    assert.equal(assets, liabilities + totalEndingEquity, 'Accounting equation violated: Assets !== Liabilities + Equity');
  });
});

import assert from 'node:assert/strict';
