      await wsRef.set({
        id: 'ws-alice',
        uid: 'alice',
        name: 'Alice Corp',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      });
    });

    // Bob (non-member) tries to read Alice's workspace
    const wsBobRef = bobDb.doc('workspaces/ws-alice');
    await assert.rejects(async () => {
      await wsBobRef.get();
