      payFrequency: 'Monthly',
      status: 'Active',
      createdAt: '2026-01-01'
    };

    const breakdown = computePeriodPayroll(employee, 2026);
    assert.equal(
      breakdown.totalPeriodLiabilityCents,
      breakdown.grossPayCents + breakdown.totalEmployerTaxCents
    );
